INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tmdry4530/agent-poker/ws-protocol', 'community', 'tmdry4530', 'agent-poker', 'tmdry4530/agent-poker', 'ws-protocol', 0, 0, 23, '2026-02-23T11:15:44Z', '2026-03-07T03:42:23.572Z', 'b1a44a049518d5c9b8c551daf682777fbcb9a78af5c9bbaeaa1a0482a77f29ed', '{"id":"tmdry4530/agent-poker/ws-protocol","name":"ws-protocol","description":{"en":"The ws-protocol skill enables AI agents to establish robust WebSocket connections, ensuring efficient communication and data exchange. It benefits developers working with real-time web applications.","zh":"ws-protocol 是一种用于建立 WebSocket 连接的协议，包括消息封装、幂等性密钥和重放保护策略等技术细节。","ja":"ws-protocol は WebSocket 接続を確立するためのプロトコルであり、メッセージエンベロープ、イデンプォテントキー、リプレイ保護戦略などの技術的な詳細を含みます。","ko":"ws-protocol은 WebSocket 연결을 설정하는 데 사용되는 프로토콜로, 메시지封装, 멱등성 키 및 재생 보호 전략 등 기술적인 세부 정보를 포함합니다.","es":"El protocolo ws permite a los desarrolladores crear Agentes de IA con capacidades de mensajería y seguridad avanzadas","fr":"Le protocole ws permet aux développeurs de créer des Outils d''IA avec des capacités de messagerie et de sécurité avancées","de":"Das ws-protocol ermöglicht es Entwicklern, KI-Agents mit erweiterten Messaging- und Sicherheitsfunktionen zu erstellen","pt":"O ws-protocol é um protocolo de comunicação que permite a troca de mensagens entre clientes e servidores. Ele inclui recursos como protocolVersion e message envelope.","ru":"ИИ Агенты: ws-protocol - это протокол связи, позволяющий обмениваться сообщениями между клиентами и серверами. Он включает функции, такие как protocolVersion и message envelope.","ar":"بروتوكول ws-protocol هو بروتوكول اتصال يسمح بتبادل الرسائل بين العملاء والخوادم. يتضمن ميزات مثل protocolVersion و message envelope."},"seo":{"title":{"en":"ws-protocol: Implementation Guide for AI Agents | AI Agen...","zh":"ws-protocol 设置指南：消息封装和重放保护","ja":"ws-protocol のベストプラクティス：メッセージエンベロープとリプレイ保護","ko":"ws-protocol 설정 가이드: 메시지封装 및 재생 보호","es":"Guía de configuración de ws-protocol para Agentes de IA","fr":"Guide de mise en place du protocole ws pour les Outils d''IA","de":"Einrichtungsleitfaden für ws-protocol in KI-Agents","pt":"Guia de Configuração do ws-protocol para Desenvolvedores","ru":"ИИ Агенты: Настройка ws-protocol для Разработчиков","ar":"دليل إعداد بروتوكول ws-protocol للعاملين بالتطبيقات"},"description":{"en":"Unlock the full potential of ws-protocol with our expert guide. Learn how to implement protocolVersion, message envelope, and idempotency keys for seamless A...","zh":"了解 ws-protocol 的技术细节，包括协议版本、消息封装、幂等性密钥和重放保护策略，AIエージェント","ja":"ws-protocol の技術的な詳細について学習し、プロトコルバージョン、メッセージエンベロープ、イデンプォテントキー、リプレイ保護戦略などをマスターする、AIエージェント","ko":"ws-protocol의 기술적인 세부 정보를 알아보세요. 프로토콜 버전, 메시지封装, 멱등성 키 및 재생 보호 전략 등, AI Tools","es":"Aprende a configurar ws-protocol para desarrollar Agentes de IA con funcionalidades de mensajería y seguridad","fr":"Découvrez comment mettre en place le protocole ws pour créer des Outils d''IA avec des fonctionnalités de messagerie et de sécurité","de":"Erfahren Sie, wie Sie ws-protocol für die Entwicklung von KI-Agents mit Messaging- und Sicherheitsfunktionen einrichten","pt":"Aprenda a configurar o ws-protocol para desenvolvedores com nossa guia passo a passo, incluindo protocolVersion e message envelope.","ru":"Узнайте, как настроить ws-protocol для разработчиков с нашей пошаговой инструкцией, включая protocolVersion и message envelope.","ar":"تعرف على كيفية إعداد بروتوكول ws-protocol للعاملين بالتطبيقات بخطوات سهلة، بما في ذلك protocolVersion و message envelope."},"definition":{"en":"ws-protocol is a technical specification outlining the protocol version, message envelope, and idempotency keys for action submission, ensuring reliable and secure communication between AI agents and WebSocket servers.","zh":"ws-protocol 是一种用于 WebSocket 连接的协议，定义了消息封装和重放保护等技术细节。","ja":"ws-protocol は WebSocket 接続を確立するためのプロトコルであり、メッセージエンベロープとリプレイ保護などの技術的な詳細を定義します。","ko":"ws-protocol은 WebSocket 연결을 설정하는 데 사용되는 프로토콜로, 메시지封装 및 재생 보호 등의 기술적인 세부 정보를 정의합니다.","es":"ws-protocol es un protocolo de comunicación para Agentes de IA que proporciona funcionalidades de mensajería y seguridad","fr":"Le protocole ws est un protocole de communication pour les Outils d''IA qui offre des fonctionnalités de messagerie et de sécurité","de":"ws-protocol ist ein Kommunikationsprotokoll für KI-Agents, das Messaging- und Sicherheitsfunktionen bietet","pt":"O ws-protocol é um protocolo de comunicação que define como as mensagens são trocadas entre clientes e servidores.","ru":"ИИ Агенты: ws-protocol - это протокол связи, определяющий, как сообщения обмениваются между клиентами и серверами.","ar":"بروتوكول ws-protocol هو بروتوكول اتصال يحدد كيفية تبادل الرسائل بين العملاء والخوادم."},"features":{"en":["Supports protocolVersion specification for backward compatibility","Implements message envelope with type, ts, requestId, tableId, seatToken, and payload","Ensures idempotency keys for action submission and replay protection strategy","Provides error codes and retry rules for robust error handling","Includes full example flows for join, disconnect, and reconnect scenarios"],"zh":["协议版本（protocolVersion）","消息封装（message envelope）","幂等性密钥（idempotency keys）","重放保护策略（replay protection strategy）","错误代码和重试规则（error codes and retry rules）","完整的例子流程（full example flows）"],"ja":["プロトコルバージョン（protocolVersion）","メッセージエンベロープ（message envelope）","イデンプォテントキー（idempotency keys）","リプレイ保護戦略（replay protection strategy）","エラーコードとリトライルール（error codes and retry rules）","フルエクサンプルフロー（full example flows）"],"ko":["프로토콜 버전（protocolVersion）","메시지封装（message envelope）","멱등성 키（idempotency keys）","재생 보호 전략（replay protection strategy）","오류 코드 및 재시도 규칙（error codes and retry rules）","완전한 예제 흐름（full example flows）"],"es":["Soporte para protocolVersion","Envelope de mensaje con tipo, ts, requestId, tableId, seatToken y payload","Claves de idempotencia para la presentación de acciones","Estrategia de protección de reproducción con secuencia monótona por cliente o asiento","Códigos de error y reglas de reintento","Flujos de ejemplo completos para unir, conectar, iniciar y finalizar manos"],"fr":["Prise en charge de la protocolVersion","Enveloppe de message avec type, ts, requestId, tableId, seatToken et payload","Clés d''idempotence pour la soumission d''actions","Stratégie de protection de répétition avec séquence monotonique par client ou siège","Codes d''erreur et règles de réessai","Flux d''exemple complets pour rejoindre, se connecter, démarrer et terminer des mains"],"de":["Unterstützung für protocolVersion","Message-Envelope mit Typ, ts, requestId, tableId, seatToken und Payload","Idempotenz-Schlüssel für die Übermittlung von Aktionen","Wiederholungsschutzstrategie mit monotoner Sequenz pro Kunde oder Sitz","Fehlercodes und Wiederholungsregeln","Vollständige Beispiel-Flows zum Joinen, Verbinden, Starten und Beenden von Händen"],"pt":["Suporte a protocolVersion para controle de versão","Message envelope com tipo, ts, requestId, tableId, seatToken e payload","Chaves de idempotência para envio de ações","Estratégia de proteção contra replay com sequência monotônica por cliente ou assento","Códigos de erro e regras de retry","Fluxos de exemplo completos para join, ws connect, start hand, ações e end hand"],"ru":["Поддержка protocolVersion для контроля версии","Message envelope с tipo, ts, requestId, tableId, seatToken и payload","Ключи идемпотентности для отправки действий","Стратегия защиты от повторного воспроизведения с монотонной последовательностью по клиенту или месту","Коды ошибок и правила повторной попытки","Полные примеры потоков для join, ws connect, start hand, действий и end hand"],"ar":["دعم protocolVersion للتحكم في الإصدار","message envelope مع tipo و ts و requestId و tableId و seatToken و payload","مفاتيح للاستبدال ل gửi الأعمال","استراتيجية حماية ضد إعادة التشغيل مع تسلسل أحادي الاتجاه للعميل أو المقعد","رموز الخطأ وقواعد إعادة المحاولة","سلاسل مثال كاملة للانضمام و ws connect و start hand و الإجراءات و end hand"]},"keywords":{"en":["ws-protocol implementation guide","how to use ws-protocol with AI agents","ws-protocol vs WebSocket protocol","ws-protocol setup for real-time web applications","what is ws-protocol and its benefits","ws-protocol install and configuration","ws-protocol alternative for AI agent communication","ws-protocol best practices for developers","ws-protocol and idempotency keys","ws-protocol error handling and retry rules"],"zh":["ws-protocol","WebSocket 连接","消息封装","幂等性密钥","重放保护","AIエージェント","协议版本","错误代码","重试规则"],"ja":["ws-protocol","WebSocket 接続","メッセージエンベロープ","イデンプォテントキー","リプレイ保護","AIエージェント","プロトコルバージョン","エラーコード","リトライルール"],"ko":["ws-protocol","WebSocket 연결","메시지封装","멱등성 키","재생 보호","AI Tools","프로토콜 버전","오류 코드","재시도 규칙"],"es":["ws-protocol","Agentes de IA","mensajería","seguridad","protocolVersion","idempotencia","reproducción","códigos de error","reglas de reintento"],"fr":["protocole ws","Outils d''IA","messagerie","sécurité","protocolVersion","idempotence","répétition","codes d''erreur","règles de réessai"],"de":["ws-protocol","KI-Agents","Messaging","Sicherheit","protocolVersion","Idempotenz","Wiederholung","Fehlercodes","Wiederholungsregeln"],"pt":["ws-protocol configuração","protocolVersion explicação","message envelope exemplo","idempotência em ações","proteção contra replay em ws-protocol","códigos de erro ws-protocol","fluxos de exemplo ws-protocol","desenvolvimento de aplicativos com ws-protocol"],"ru":["настройка ws-protocol","protocolVersion объяснение","message envelope пример","идемпотентность в действиях","защита от повторного воспроизведения в ws-protocol","коды ошибок ws-protocol","полные примеры потоков ws-protocol","разработка приложений с ws-protocol"],"ar":["إعداد بروتوكول ws-protocol","شرح protocolVersion","مثال message envelope","الاستبدال في الإجراءات","حماية ضد إعادة التشغيل في بروتوكول ws-protocol","رموز الخطأ بروتوكول ws-protocol","سلاسل مثال كاملة بروتوكول ws-protocol","تطوير التطبيقات مع بروتوكول ws-protocol"]}},"owner":"tmdry4530","repo":"agent-poker","repoPath":"tmdry4530/agent-poker","stars":0,"forks":0,"updatedAt":"2026-02-23T11:15:44Z","topics":[],"category":"community","skillMd":{"name":"ws-protocol","description":"Define/update the WebSocket protocol spec: message types, schemas, idempotency, replay protection, reconnect flow.","bodyPreview":"Update docs/PROTOCOL_WS.md.\n\nInclude:\n- protocolVersion\n- message envelope (type, ts, requestId, tableId, seatToken, payload)\n- idempotency keys for action submission\n- replay protection strategy (monotonic seq per client or per seat)\n- error codes and retry rules\n- full example flows:\n  1) join -> ws connect -> start hand -> actions -> end hand\n  2) disconnect -> reconnect -> state resync","body":"Update docs/PROTOCOL_WS.md.\n\nInclude:\n- protocolVersion\n- message envelope (type, ts, requestId, tableId, seatToken, payload)\n- idempotency keys for action submission\n- replay protection strategy (monotonic seq per client or per seat)\n- error codes and retry rules\n- full example flows:\n  1) join -> ws connect -> start hand -> actions -> end hand\n  2) disconnect -> reconnect -> state resync\n"},"lastSynced":"2026-03-07T03:42:23.572Z","agentAnalysis":{"suitability":{"en":"Ideal for Real-Time Web Application Agents requiring robust WebSocket connections and efficient data exchange","zh":"适合需要强大的WebSocket连接和高效数据交换的实时Web应用程序代理","ja":"リアルタイムWebアプリケーションエージェントが強力なWebSocket接続と効率的なデータ交換を必要とする場合に適しています","ko":"실시간 웹 애플리케이션 에이전트가 강력한 WebSocket 연결과 효율적인 데이터 교환을 필요로 할 때 적합합니다","es":"Ideal para Agentes de Aplicaciones Web en Tiempo Real que requieren conexiones de WebSocket robustas y un intercambio de datos eficiente","fr":"Idéal pour les Agents d''Applications Web en Temps Réel nécessitant des connexions WebSocket robustes et un échange de données efficace","de":"Ideal für Echtzeit-Webanwendungsagenten, die robuste WebSocket-Verbindungen und einen effizienten Datenaustausch erfordern","pt":"Ideal para Agentes de Aplicativos Web em Tempo Real que requerem conexões WebSocket robustas e troca de dados eficiente","ru":"Идеально подходит для агентов веб-приложений в реальном времени, требующих надежных подключений WebSocket и эффективного обмена данными","ar":"مثالي للوكلاء التطبيقين الويب في الوقت الفعلي الذين يحتاجون إلى اتصالات WebSocket قوية وتبادل بيانات فعال"},"recommendation":{"en":"Empowers agents to establish secure WebSocket connections using protocolVersion, message envelopes, and idempotency keys, while implementing replay protection strategies and handling error codes with retry rules, all leveraging WebSocket protocols and message sequencing","zh":"赋予代理建立安全的WebSocket连接的能力，使用协议版本、消息封套和幂等性密钥，同时实现重放保护策略和处理错误代码的重试规则，所有这些都利用WebSocket协议和消息排序","ja":"エージェントがプロトコルバージョン、メッセージエンベロープ、および冪等性キーを使用して安全なWebSocket接続を確立し、リプレイ保護戦略を実装し、リトライルールでエラーコードを処理する能力を提供します。すべてこれらはWebSocketプロトコルとメッセージシーケンシングを利用しています","ko":"에이전트가 프로토콜 버전, 메시지 봉투 및 멱등성 키를 사용하여 안전한 WebSocket 연결을 설정하고, 재실행 보호 전략을 구현하고, 재시도 규칙으로 오류 코드를 처리할 수 있는 기능을 제공합니다. 모든 이러한 사항은 WebSocket 프로토콜과 메시지 시퀀싱을 활용합니다","es":"Habilita a los agentes a establecer conexiones de WebSocket seguras utilizando protocolVersion, sobres de mensaje y claves de idempotencia, mientras implementan estrategias de protección de reproducción y manejo de códigos de error con reglas de reintento, todo aprovechando los protocolos de WebSocket y la secuenciación de mensajes","fr":"Permet aux agents d''établir des connexions WebSocket sécurisées en utilisant protocolVersion, des enveloppes de message et des clés d''idempotence, tout en mettant en œuvre des stratégies de protection de relecture et en gérant les codes d''erreur avec des règles de réessai, le tout en exploitant les protocoles WebSocket et la séquenciation des messages","de":"Ermächtigt Agenten, sichere WebSocket-Verbindungen mit Hilfe von protocolVersion, Nachrichten-Umschlägen und Idempotenz-Schlüsseln herzustellen, während sie Strategien zum Schutz vor Wiedergabe und Fehlercode-Handhabung mit Wiederholungsregeln implementieren, alles unter Ausnutzung von WebSocket-Protokollen und Nachrichten-Sequenzierung","pt":"Habilita os agentes a estabelecer conexões WebSocket seguras usando protocolVersion, envelopes de mensagens e chaves de idempotência, enquanto implementam estratégias de proteção de reprodução e lidam com códigos de erro com regras de retry, tudo aproveitando os protocolos WebSocket e a sequenciação de mensagens","ru":"Предоставляет агентам возможность устанавливать безопасные подключения WebSocket с использованием protocolVersion, конвертов сообщений и ключей идемпотентности, реализуя при этом стратегии защиты от повторной передачи и обработку кодов ошибок с правилами повторной попытки, все это при помощи протоколов WebSocket и последовательности сообщений","ar":"تمكن الوكلاء من إنشاء اتصالات WebSocket آمنة باستخدام protocolVersion وأغلفة الرسائل والمفاتيح المتسقة، بينما تنفذ استراتيجيات حماية الإعادة والتعامل مع رموز الخطأ بقواعد إعادة المحاولة، وكل ذلك بالاستفادة من بروتوكولات WebSocket وترتيب الرسائل"},"useCases":{"en":["Establishing secure WebSocket connections for real-time data exchange","Implementing idempotency keys for action submission and replay protection","Handling error codes and retry rules for robust communication","Debugging WebSocket connection issues with full example flows","Resynchronizing state after disconnect and reconnect scenarios"],"zh":["为实时数据交换建立安全的WebSocket连接","为操作提交和重放保护实现幂等性密钥","处理错误代码和重试规则以实现强大的通信","使用完整的示例流调试WebSocket连接问题","在断开连接和重新连接场景后重新同步状态"],"ja":["リアルタイムデータ交換のための安全なWebSocket接続を確立する","操作の送信とリプレイ保護のための冪等性キーを実装する","エラーコードとリトライルールを処理して強力な通信を実現する","完全な例フローを使用してWebSocket接続の問題をデバッグする","切断と再接続シナリオ後に状態を再同期する"],"ko":["실시간 데이터 교환을 위한 안전한 WebSocket 연결을 설정하는 것","작업 제출 및 재실행 보호를 위한 멱등성 키를 구현하는 것","오류 코드 및 재시도 규칙을 처리하여 강력한 통신을 구현하는 것","완전한 예제 흐름을 사용하여 WebSocket 연결 문제를 디버깅하는 것","분리 및 재접속 시나리오 후 상태를 재동기화하는 것"],"es":["Establecer conexiones de WebSocket seguras para el intercambio de datos en tiempo real","Implementar claves de idempotencia para la presentación de acciones y la protección de reproducción","Manejar códigos de error y reglas de reintento para una comunicación robusta","Depurar problemas de conexión de WebSocket con flujos de ejemplo completos","Re sincronizar el estado después de escenarios de desconexión y reconexión"],"fr":["Établir des connexions WebSocket sécurisées pour l''échange de données en temps réel","Mettre en œuvre des clés d''idempotence pour la soumission d''actions et la protection de relecture","Gérer les codes d''erreur et les règles de réessai pour une communication robuste","Déboguer les problèmes de connexion WebSocket avec des flux d''exemple complets","Ré synchroniser l''état après des scénarios de déconnexion et de reconnexion"],"de":["Sichere WebSocket-Verbindungen für den Echtzeit-Datenaustausch herstellen","Idempotenz-Schlüssel für die Übermittlung von Aktionen und den Schutz vor Wiedergabe implementieren","Fehlercodes und Wiederholungsregeln für eine robuste Kommunikation handhaben","WebSocket-Verbindungsprobleme mit vollständigen Beispiel-Flows debuggen","Den Zustand nach Trennungs- und Wiederherstellungs-Szenarien neu synchronisieren"],"pt":["Estabelecendo conexões WebSocket seguras para troca de dados em tempo real","Implementando chaves de idempotência para envio de ações e proteção de reprodução","Lidando com códigos de erro e regras de retry para comunicação robusta","Depurando problemas de conexão WebSocket com fluxos de exemplo completos","Re-sincronizando o estado após cenários de desconexão e reconexão"],"ru":["Установка безопасных подключений WebSocket для обмена данными в реальном времени","Реализация ключей идемпотентности для отправки действий и защиты от повторной передачи","Обработка кодов ошибок и правил повторной попытки для надежной связи","Отладка проблем подключения WebSocket с полными примерами потоков","Пересинхронизация состояния после сценариев отключения и повторного подключения"],"ar":["إنشاء اتصالات WebSocket آمنة لتبادل البيانات في الوقت الفعلي","تنفيذ مفاتيح المتسقة لإرسال الإجراءات وحماية الإعادة","التعامل مع رموز الخطأ وقواعد إعادة المحاولة للاتصال المتين","تصحيح أخطاء الاتصال ببروتوكول WebSocket باستخدام تدفقات مثال كاملة","إعادة مزامنة الحالة بعد سيناريوهات الفصل وإعادة الاتصال"]},"limitations":{"en":["Requires WebSocket protocol support","Needs proper configuration of protocolVersion and message envelopes","Idempotency key management required for action submission"],"zh":["需要WebSocket协议支持","需要正确配置协议版本和消息封套","需要幂等性密钥管理用于操作提交"],"ja":["WebSocketプロトコルのサポートが必要","プロトコルバージョンとメッセージエンベロープの正しい構成が必要","操作の送信のための冪等性キーの管理が必要"],"ko":["WebSocket 프로토콜 지원이 필요합니다","프로토콜 버전 및 메시지 봉투의 올바른 구성이 필요합니다","작업 제출을 위한 멱등성 키 관리가 필요합니다"],"es":["Requiere soporte para el protocolo WebSocket","Necesita una configuración adecuada de protocolVersion y sobres de mensaje","Se requiere un manejo de claves de idempotencia para la presentación de acciones"],"fr":["Nécessite un support pour le protocole WebSocket","Nécessite une configuration appropriée de protocolVersion et d''enveloppes de message","Nécessite une gestion de clés d''idempotence pour la soumission d''actions"],"de":["Benötigt Unterstützung für das WebSocket-Protokoll","Benötigt eine ordnungsgemäße Konfiguration von protocolVersion und Nachrichten-Umschlägen","Benötigt eine Verwaltung von Idempotenz-Schlüsseln für die Übermittlung von Aktionen"],"pt":["Requer suporte ao protocolo WebSocket","Necessita de configuração adequada de protocolVersion e envelopes de mensagens","Gerenciamento de chaves de idempotência necessário para envio de ações"],"ru":["Требует поддержки протокола WebSocket","Требует правильной настройки protocolVersion и конвертов сообщений","Требуется управление ключами идемпотентности для отправки действий"],"ar":["يتطلب دعم بروتوكول WebSocket","يحتاج إلى تكوين مناسب لبروتوكول وversion وغلاف الرسائل","يتطلب إدارة مفاتيح المتسقة لإرسال الإجراءات"]},"version":4},"contentHash":"b1a44a049518d5c9b8c551daf682777fbcb9a78af5c9bbaeaa1a0482a77f29ed","qualityScore":23}');
