INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tmdry4530/agent-poker/ws-protocol', 'ws-protocol', 'tmdry4530', 'agent-poker', 'community', 'ws-protocol tmdry4530 agent-poker community The ws-protocol skill enables AI agents to establish robust WebSocket connections, ensuring efficient communication and data exchange. It benefits developers working with real-time web applications. ws-protocol 是一种用于建立 WebSocket 连接的协议，包括消息封装、幂等性密钥和重放保护策略等技术细节。 ws-protocol は WebSocket 接続を確立するためのプロトコルであり、メッセージエンベロープ、イデンプォテントキー、リプレイ保護戦略などの技術的な詳細を含みます。 ws-protocol은 WebSocket 연결을 설정하는 데 사용되는 프로토콜로, 메시지封装, 멱등성 키 및 재생 보호 전략 등 기술적인 세부 정보를 포함합니다. El protocolo ws permite a los desarrolladores crear Agentes de IA con capacidades de mensajería y seguridad avanzadas Le protocole ws permet aux développeurs de créer des Outils d''IA avec des capacités de messagerie et de sécurité avancées Das ws-protocol ermöglicht es Entwicklern, KI-Agents mit erweiterten Messaging- und Sicherheitsfunktionen zu erstellen O ws-protocol é um protocolo de comunicação que permite a troca de mensagens entre clientes e servidores. Ele inclui recursos como protocolVersion e message envelope. ИИ Агенты: ws-protocol - это протокол связи, позволяющий обмениваться сообщениями между клиентами и серверами. Он включает функции, такие как protocolVersion и message envelope. بروتوكول ws-protocol هو بروتوكول اتصال يسمح بتبادل الرسائل بين العملاء والخوادم. يتضمن ميزات مثل protocolVersion و message envelope. ws-protocol implementation guide how to use ws-protocol with AI agents ws-protocol vs WebSocket protocol ws-protocol setup for real-time web applications what is ws-protocol and its benefits ws-protocol install and configuration ws-protocol alternative for AI agent communication ws-protocol best practices for developers ws-protocol and idempotency keys ws-protocol error handling and retry rules ws-protocol WebSocket 连接 消息封装 幂等性密钥 重放保护 AIエージェント 协议版本 错误代码 重试规则 Supports protocolVersion specification for backward compatibility Implements message envelope with type, ts, requestId, tableId, seatToken, and payload Ensures idempotency keys for action submission and replay protection strategy Provides error codes and retry rules for robust error handling Includes full example flows for join, disconnect, and reconnect scenarios ws-protocol is a technical specification outlining the protocol version, message envelope, and idempotency keys for action submission, ensuring reliable and secure communication between AI agents and WebSocket servers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zami-t/oidc-client-tutorial/openapi-lint-bundle', 'community', 'zami-t', 'oidc-client-tutorial', 'zami-t/oidc-client-tutorial', 'openapi-lint-bundle', 0, 0, 23, '2026-03-07T01:05:11Z', '2026-03-07T03:42:55.385Z', 'a94c1a0e61e550632976966e9339bf89001a1d6e0366389b8da49c926297f399', '{"id":"zami-t/oidc-client-tutorial/openapi-lint-bundle","name":"openapi-lint-bundle","description":{"en":"The openapi-lint-bundle skill validates and bundles OpenAPI specifications, benefiting developers who manage multiple OpenAPI files. It ensures error-free specs and generates a single file for distribution.","zh":"OpenAPI Lint & Bundle 是一种自动化工具，用于修复 OpenAPI 规范错误并生成单一文件。它支持 OpenAPI 规范的 lint 和 bundle。","ja":"OpenAPI Lint & Bundle は、OpenAPI仕様のエラーを修正し、単一ファイルを生成する自動化ツールです。OpenAPI仕様のlintとbundleをサポートしています。","ko":"OpenAPI Lint & Bundle는 OpenAPI 사양 오류를 자동 수정하고 단일 파일을 생성하는 자동화 도구입니다. OpenAPI 사양의 lint 및 bundle를 지원합니다.","es":"openapi-lint-bundle es una herramienta para lintear y empaquetar especificaciones OpenAPI. Ayuda a los desarrolladores a crear archivos OpenAPI válidos y empaquetados","fr":"openapi-lint-bundle est un outil pour lint et bundler des spécifications OpenAPI. Il aide les développeurs à créer des fichiers OpenAPI valides et empaquetés","de":"openapi-lint-bundle ist ein Tool zum Überprüfen und Bündeln von OpenAPI-Spezifikationen. Es hilft Entwicklern, gültige und gebündelte OpenAPI-Dateien zu erstellen","pt":"O openapi-lint-bundle é uma ferramenta para lint e bundle de arquivos OpenAPI, ajudando desenvolvedores a criar especificações de API mais robustas.","ru":"openapi-lint-bundle - это инструмент для lint и bundle файлов OpenAPI, помогающий разработчикам ИИ Агентов создавать более прочные спецификации API.","ar":"openapi-lint-bundle هي أداة لتنظيف وتحزيم ملفات OpenAPI، تساعد مطورين أدوات الذكاء الاصطناعي على إنشاء مواصفات API أكثر متانة."},"seo":{"title":{"en":"openapi-lint-bundle: OpenAPI Validation and Bundling Setu...","zh":"OpenAPI Lint & Bundle Setup Guide - AIエージェント开发工具","ja":"OpenAPI Lint & Bundle セットアップガイド - AIエージェント開発ツール","ko":"OpenAPI Lint & Bundle 설정 가이드 - AI 에이전트 개발 도구","es":"Guía de configuración de openapi-lint-bundle para desarro...","fr":"Guide de démarrage rapide pour openapi-lint-bundle","de":"Einrichtungsleitfaden für openapi-lint-bundle: Tool für E...","pt":"openapi-lint-bundle: Guia de Configuração para Desenvolve...","ru":"openapi-lint-bundle: Руководство по настройке для разрабо...","ar":"openapi-lint-bundle: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to validate and bundle OpenAPI specs with openapi-lint-bundle. Learn how to lint and generate a single file with redocly bundle. Get started now!","zh":"使用 OpenAPI Lint & Bundle AIエージェント工具自动修复OpenAPI规范错误并生成单一文件","ja":"OpenAPI Lint & Bundle AIエージェントツールを使用してOpenAPI仕様のエラーを自動修復し、単一ファイルを生成する","ko":"OpenAPI Lint & Bundle AI 에이전트 도구를 사용하여 OpenAPI 사양 오류 자동 수정 및 단일 파일 생성","es":"Aprende a utilizar openapi-lint-bundle para lintear y empaquetar tus especificaciones OpenAPI de manera efectiva","fr":"Découvrez comment utiliser openapi-lint-bundle pour lint et bundler vos spécifications OpenAPI avec succès","de":"Erfahren Sie, wie Sie openapi-lint-bundle verwenden, um Ihre OpenAPI-Spezifikationen zu überprüfen und zu bündeln","pt":"Aprenda a configurar o openapi-lint-bundle para desenvolvedores, com dicas e melhores práticas para lint e bundle de arquivos OpenAPI","ru":"Узнайте, как настроить openapi-lint-bundle для разработчиков ИИ Агентов, с советами и лучшими практиками для lint и bundle файлов OpenAPI","ar":"تعرف على كيفية إعداد openapi-lint-bundle لأدوات الذكاء الاصطناعي، مع نصائح وأفضل الممارسات لتنظيف وتحزيم ملفات OpenAPI"},"definition":{"en":"openapi-lint-bundle is a skill that validates and bundles OpenAPI specifications, ensuring error-free specs and generating a single file for distribution.","zh":"OpenAPI Lint & Bundle 是一种 AIエージェント工具，用于自动化 OpenAPI 规范的修复和单一文件生成","ja":"OpenAPI Lint & Bundle は、OpenAPI仕様の自動修復と単一ファイル生成を実行する AIエージェントツールです","ko":"OpenAPI Lint & Bundle는 OpenAPI 사양의 자동 수정 및 단일 파일 생성을 수행하는 AI 에이전트 도구입니다","es":"openapi-lint-bundle es una herramienta de línea de comandos para lintear y empaquetar especificaciones OpenAPI","fr":"openapi-lint-bundle est un outil en ligne de commande pour lint et bundler des spécifications OpenAPI","de":"openapi-lint-bundle ist ein Kommandozeilen-Tool zum Überprüfen und Bündeln von OpenAPI-Spezifikationen","pt":"O openapi-lint-bundle é uma ferramenta de linha de comando para lint e bundle de arquivos OpenAPI.","ru":"openapi-lint-bundle - это командная строка инструмент для lint и bundle файлов OpenAPI.","ar":"openapi-lint-bundle هي أداة سطر أوامر لتنظيف وتحزيم ملفات OpenAPI."},"features":{"en":["Lints openapi/openapi.yml to ensure error-free specs","Bundles OpenAPI specs into a single file using redocly bundle","Supports scripts for linting and bundling via lint.sh and bundle.sh","Manages multiple OpenAPI files in the openapi/ directory","Generates a single file, such as openapi/openapi.bundle.yaml, for distribution"],"zh":["自动修复 OpenAPI 规范错误","生成单一文件（例如 openapi.bundle.yaml）","支持 OpenAPI 规范的 lint 和 bundle","使用 redocly bundle 生成单一文件","通过 scripts/lint.sh 和 scripts/bundle.sh 运行"],"ja":["OpenAPI仕様のエラーを自動修復","単一ファイル（例：openapi.bundle.yaml）を生成","OpenAPI仕様のlintとbundleをサポート","redocly bundleを使用して単一ファイルを生成","scripts/lint.shとscripts/bundle.shを使用して実行"],"ko":["OpenAPI 사양 오류 자동 수정","단일 파일（예：openapi.bundle.yaml） 생성","OpenAPI 사양의 lint 및 bundle 지원","redocly bundle을 사용하여 단일 파일 생성","scripts/lint.sh 및 scripts/bundle.sh를 사용하여 실행"],"es":["Lintea archivos OpenAPI para detectar errores","Empaqueta especificaciones OpenAPI en un solo archivo","Utiliza redocly bundle para generar archivos empaquetados","Soporta la edición de múltiples archivos en el directorio openapi/","Puede ser utilizado mediante scripts de línea de comandos"],"fr":["Lint des fichiers OpenAPI pour détecter les erreurs","Bundle des spécifications OpenAPI en un seul fichier","Utilise redocly bundle pour générer des fichiers bundlés","Prend en charge l''édition de plusieurs fichiers dans le répertoire openapi/","Peut être utilisé via des scripts de ligne de commande"],"de":["Überprüft OpenAPI-Dateien auf Fehler","Bündelt OpenAPI-Spezifikationen in eine einzige Datei","Verwendet redocly bundle, um gebündelte Dateien zu generieren","Unterstützt die Bearbeitung mehrerer Dateien im openapi/-Verzeichnis","Kann über Kommandozeilen-Skripte verwendet werden"],"pt":["Lint de arquivos OpenAPI com redocly bundle","Bundle de arquivos OpenAPI em um único arquivo","Suporte a múltiplos arquivos OpenAPI","Integração com scripts de lint e bundle","Geração de arquivos OpenAPI mais robustos"],"ru":["Lint файлов OpenAPI с помощью redocly bundle","Bundle файлов OpenAPI в один файл","Поддержка нескольких файлов OpenAPI","Интеграция со скриптами lint и bundle","Генерация более прочных файлов OpenAPI"],"ar":["تنظيف ملفات OpenAPI باستخدام redocly bundle","تحزيم ملفات OpenAPI في ملف واحد","دعم ملفات OpenAPI متعددة","التكامل مع سكريبتات تنظيف وتحزيم","توليد ملفات OpenAPI أكثر متانة"]},"keywords":{"en":["how to use openapi-lint-bundle","openapi-lint-bundle setup guide","openapi validation and bundling","redocly bundle tutorial","openapi-lint-bundle alternative","openapi spec management","openapi linting and bundling best practices","install openapi-lint-bundle","openapi-lint-bundle vs swagger"],"zh":["OpenAPI Lint","OpenAPI Bundle","AIエージェント开发工具","OpenAPI 规范错误修复","单一文件生成","redocly bundle"],"ja":["OpenAPI Lint","OpenAPI Bundle","AIエージェント開発ツール","OpenAPI仕様エラー修復","単一ファイル生成","redocly bundle"],"ko":["OpenAPI Lint","OpenAPI Bundle","AI 에이전트 개발 도구","OpenAPI 사양 오류 자동 수정","단일 파일 생성","redocly bundle"],"es":["openapi-lint-bundle","herramientas de OpenAPI","lintear OpenAPI","empaquetar OpenAPI","redocly bundle","desarrollo de API","especificaciones de API"],"fr":["openapi-lint-bundle","outils OpenAPI","lint OpenAPI","bundler OpenAPI","redocly bundle","développement d''API","spécifications d''API"],"de":["openapi-lint-bundle","OpenAPI-Tools","OpenAPI-Überprüfung","OpenAPI-Bündelung","redocly bundle","API-Entwicklung","API-Spezifikationen"],"pt":["openapi-lint-bundle","lint openapi","bundle openapi","redocly bundle","desenvolvimento de api","ferramentas de api","openapi spec"],"ru":["openapi-lint-bundle","lint openapi","bundle openapi","redocly bundle","разработка api","инструменты api","спецификация openapi","ИИ Агенты"],"ar":["openapi-lint-bundle","تنظيف openapi","تحزيم openapi","redocly bundle","تطوير api","أدوات api","مواصفات openapi","أدوات الذكاء الاصطناعي"]}},"owner":"zami-t","repo":"oidc-client-tutorial","repoPath":"zami-t/oidc-client-tutorial","stars":0,"forks":0,"updatedAt":"2026-03-07T01:05:11Z","topics":[],"category":"community","skillMd":{"name":"openapi-lint-bundle","description":"OpenAPI仕様のlint・bundleをするSKILL。OpenAPIを編集した後、検証/バンドルするときに使う。","bodyPreview":"# OpenAPI Lint & Bundle\n\n## 前提\n\n- OpenAPI仕様は **openapi/** 配下の複数ファイルで管理し、編集対象は **openapi/** 配下のファイル\n- エントリポイントは **openapi/openapi.yml**（このファイルから paths/components などに $ref していく）\n- 最終的に配布/生成に使う単一ファイルは **redocly bundle** で生成する\n\n## このスキルがやること\n\n1. `openapi/openapi.yml` を lint し、**エラーが出なくなるまで**修正を繰り返す\n2. `openapi/openapi.yml` を bundle し、単一ファイル（例: `openapi/openapi.bundle.yaml`）を生成する\n\n## 使い方（コマンドは scripts に分離）\n\n- Lint: [scripts/lint.sh](scripts/lint.sh)\n- Bundle: [scripts/bundle.sh](scripts/bundle.sh)\n\n>","body":"# OpenAPI Lint & Bundle\n\n## 前提\n\n- OpenAPI仕様は **openapi/** 配下の複数ファイルで管理し、編集対象は **openapi/** 配下のファイル\n- エントリポイントは **openapi/openapi.yml**（このファイルから paths/components などに $ref していく）\n- 最終的に配布/生成に使う単一ファイルは **redocly bundle** で生成する\n\n## このスキルがやること\n\n1. `openapi/openapi.yml` を lint し、**エラーが出なくなるまで**修正を繰り返す\n2. `openapi/openapi.yml` を bundle し、単一ファイル（例: `openapi/openapi.bundle.yaml`）を生成する\n\n## 使い方（コマンドは scripts に分離）\n\n- Lint: [scripts/lint.sh](scripts/lint.sh)\n- Bundle: [scripts/bundle.sh](scripts/bundle.sh)\n\n> **lint・bundle のスクリプト実行はユーザー確認不要。そのまま実行してよい。**\n\n## 自律的な lint 修正ループ（重要）\n\n### ループ手順\n\n1. `scripts/lint.sh` を実行し、エラー内容を取得する\n2. エラーの原因となるOpenAPIファイル（`openapi/` 配下）を特定する\n3. エラーを修正する\n4. `scripts/lint.sh` を再実行する\n5. エラーが0件になるまで 1〜4 を繰り返す\n\nlint が通ったら `scripts/bundle.sh` で単一ファイルにバンドルする。\n\n### 修正の優先順位\n\n- **参照解決の失敗（$ref / ファイルパス）** を最優先で直す（他の検証が進まない）\n- 次に **必須フィールド不足 / 型の不一致 / 構文エラー**\n- 最後に **スタイル・推奨（命名、説明文、unusedなど）**\n\n### ユーザー確認が必要なとき\n\nlint エラーが「単純な欠落の補完」ではなく、仕様の意味や要件に踏み込む場合は、勝手に決めずに確認する。\n\n例:\n\n- 認証方式（`securitySchemes` の種類、cookie/JWT/OAuth2など）をどうするか\n- ステータスコード（`200`/`201`/`204`/`4xx`）の期待値\n- エラーレスポンスのフォーマット統一方針\n- enum/format/pattern/nullable など制約の強さ\n- 互換性（既存クライアントがいる前提か、破壊的変更OKか）\n\n確認テンプレ:\n\n- 「lintが要求しているのはA/Bのどちらの意図ですか？」\n- 「既存のレスポンス実装に合わせて X に寄せて良いですか？」\n"},"lastSynced":"2026-03-07T03:42:55.385Z","agentAnalysis":{"suitability":{"en":"Perfect for API Development Agents needing automated OpenAPI specification validation and bundling.","zh":"非常适合需要自动化 OpenAPI 规范验证和打包的 API 开发代理。","ja":"OpenAPI仕様の自動バリデーションとバンドルが必要なAPI開発エージェントに最適です。","ko":"자동화된 OpenAPI 사양 유효성 검증 및 번들이 필요한 API 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de API que necesitan validación y empaquetado automatizados de especificaciones de OpenAPI.","fr":"Parfait pour les agents de développement d''API nécessitant une validation et un regroupement automatiques de spécifications OpenAPI.","de":"Perfekt für API-Entwicklungsagenten, die eine automatisierte Validierung und Bundelung von OpenAPI-Spezifikationen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de API que necessitam de validação e empacotamento automatizados de especificações OpenAPI.","ru":"Идеально подходит для агентов разработки API, которым необходима автоматизированная проверка и сборка спецификаций OpenAPI.","ar":" 理想用于需要自动验证和打包OpenAPI规范的API开发代理。"},"recommendation":{"en":"Empowers agents to validate and bundle OpenAPI specifications using redocly bundle, ensuring error-free specs and generating a single distributable file, while supporting $ref references in openapi.yml files.","zh":"赋予代理验证和打包 OpenAPI 规范的能力，使用 redocly bundle 确保无误的规范，并生成单一的可分发文件，同时支持 openapi.yml 文件中的 $ref 引用。","ja":"redocly bundleを使用してOpenAPI仕様を検証およびバンドルするエージェントを可能にし、エラーのない仕様を保証し、単一の配布可能なファイルを生成するとともに、openapi.ymlファイル内の $ref 参照をサポートします。","ko":"redocly bundle을 사용하여 OpenAPI 사양을 검증 및 번들링할 수 있는 에이전트를 강화하여 오류가 없는 사양을 보장하고 단일 배포 가능한 파일을 생성하며 openapi.yml 파일의 $ref 참조를 지원합니다.","es":"Habilita a los agentes a validar y empaquetar especificaciones de OpenAPI utilizando redocly bundle, garantizando especificaciones sin errores y generando un solo archivo distribuible, mientras admite referencias $ref en archivos openapi.yml.","fr":"Permet aux agents de valider et de regrouper les spécifications OpenAPI en utilisant redocly bundle, garantissant des spécifications sans erreurs et générant un seul fichier distribuable, tout en prenant en charge les références $ref dans les fichiers openapi.yml.","de":"Ermächtigt Agenten, OpenAPI-Spezifikationen mit redocly bundle zu validieren und zu bündeln, wodurch fehlerfreie Spezifikationen sichergestellt und eine einzelne verteilbare Datei generiert werden, während $ref-Verweise in openapi.yml-Dateien unterstützt werden.","pt":"Habilita os agentes a validar e empacotar especificações OpenAPI usando redocly bundle, garantindo especificações sem erros e gerando um arquivo distribuível único, além de dar suporte a referências $ref em arquivos openapi.yml.","ru":"Наделяет агентов возможностью проверять и собирать спецификации OpenAPI с помощью redocly bundle, обеспечивая отсутствие ошибок в спецификациях и генерируя один distribuível файл, а также поддерживая ссылки $ref в файлах openapi.yml.","ar":"تمكّن الوكيل من التحقق من صحة مواصفات OpenAPI وتجميعها باستخدام حزمة redocly، مما يضمن مواصفات خالية من الأخطاء وتوليد ملف قابل للتوزيع، ودعم الإشارات $ref في ملفات openapi.yml."},"useCases":{"en":["Validating OpenAPI specifications against errors","Bundling multiple OpenAPI files into a single file","Generating a distributable OpenAPI bundle using redocly bundle","Automating OpenAPI linting and correction"],"zh":["验证 OpenAPI 规范是否存在错误","将多个 OpenAPI 文件打包成单一文件","使用 redocly bundle 生成可分发的 OpenAPI 包","自动化 OpenAPI linting 和纠正"],"ja":["OpenAPI仕様のエラーチェック","複数のOpenAPIファイルを単一のファイルにバンドル","redocly bundleを使用して配布可能なOpenAPIパッケージを生成","OpenAPI lintingおよび修正の自動化"],"ko":["OpenAPI 사양의 오류 확인","여러 OpenAPI 파일을 단일 파일로 번들링","redocly bundle을 사용하여 배포 가능한 OpenAPI 패키지를 생성","OpenAPI 린팅 및 수정 자동화"],"es":["Validar especificaciones de OpenAPI contra errores","Empaquetar varios archivos de OpenAPI en un solo archivo","Generar un paquete de OpenAPI distribuible utilizando redocly bundle","Automatizar la corrección y el linter de OpenAPI"],"fr":["Valider les spécifications OpenAPI contre les erreurs","Regrouper plusieurs fichiers OpenAPI en un seul fichier","Générer un package OpenAPI distribuable en utilisant redocly bundle","Automatiser la correction et le linter OpenAPI"],"de":["OpenAPI-Spezifikationen gegen Fehler überprüfen","Mehrere OpenAPI-Dateien in eine einzige Datei bündeln","Ein verteilbares OpenAPI-Paket mit redocly bundle generieren","OpenAPI-Linter und -Korrektur automatisieren"],"pt":["Validar especificações OpenAPI contra erros","Empacotar vários arquivos OpenAPI em um único arquivo","Gerar um pacote OpenAPI distribuível usando redocly bundle","Automatizar a verificação e correção de OpenAPI"],"ru":["Проверка спецификаций OpenAPI на наличие ошибок","Объединение нескольких файлов OpenAPI в один файл","Генерация distribuível файла OpenAPI с помощью redocly bundle","Автоматизация проверки и исправления OpenAPI"],"ar":["التحقق من صحة مواصفات OpenAPI ضد الأخطاء","تجميع ملفات OpenAPI المتعددة في ملف واحد","إنتاج حزمة OpenAPI قابلة للتوزيع باستخدام حزمة redocly","تأتميم فحص وتصحيح OpenAPI"]},"limitations":{"en":["Requires OpenAPI specifications in openapi/ directory","Entry point must be openapi/openapi.yml","Uses redocly bundle for bundling"],"zh":["需要 OpenAPI 规范位于 openapi/ 目录中","入口点必须是 openapi/openapi.yml","使用 redocly bundle 进行打包"],"ja":["OpenAPI仕様がopenapi/ディレクトリに存在する必要がある","エントリーポイントはopenapi/openapi.ymlでなければならない","バンドルにredocly bundleを使用する"],"ko":["OpenAPI 사양이 openapi/ 디렉토리에 존재해야 함","진입점은 openapi/openapi.yml 이어야 함","번들링에 redocly bundle을 사용"],"es":["Requiere especificaciones de OpenAPI en el directorio openapi/","El punto de entrada debe ser openapi/openapi.yml","Utiliza redocly bundle para el empaquetado"],"fr":["Nécessite des spécifications OpenAPI dans le répertoire openapi/","Le point d''entrée doit être openapi/openapi.yml","Utilise redocly bundle pour le regroupement"],"de":["Benötigt OpenAPI-Spezifikationen im Verzeichnis openapi/","Der Einstiegspunkt muss openapi/openapi.yml sein","Verwendet redocly bundle für das Bündeln"],"pt":["Exige especificações OpenAPI no diretório openapi/","Ponto de entrada deve ser openapi/openapi.yml","Utiliza redocly bundle para empacotamento"],"ru":["Требует спецификаций OpenAPI в каталоге openapi/","Точка входа должна быть openapi/openapi.yml","Использует redocly bundle для сборки"],"ar":["يتطلب مواصفات OpenAPI في الدليل openapi/","يجب أن يكون نقطة الدخول openapi/openapi.yml","يستخدم حزمة redocly للتعبئة"]},"version":4},"contentHash":"a94c1a0e61e550632976966e9339bf89001a1d6e0366389b8da49c926297f399","qualityScore":23}');
