INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zami-t/oidc-client-tutorial/openapi-lint-bundle', 'openapi-lint-bundle', 'zami-t', 'oidc-client-tutorial', 'community', 'openapi-lint-bundle zami-t oidc-client-tutorial community The openapi-lint-bundle skill validates and bundles OpenAPI specifications, benefiting developers who manage multiple OpenAPI files. It ensures error-free specs and generates a single file for distribution. OpenAPI Lint & Bundle 是一种自动化工具，用于修复 OpenAPI 规范错误并生成单一文件。它支持 OpenAPI 规范的 lint 和 bundle。 OpenAPI Lint & Bundle は、OpenAPI仕様のエラーを修正し、単一ファイルを生成する自動化ツールです。OpenAPI仕様のlintとbundleをサポートしています。 OpenAPI Lint & Bundle는 OpenAPI 사양 오류를 자동 수정하고 단일 파일을 생성하는 자동화 도구입니다. OpenAPI 사양의 lint 및 bundle를 지원합니다. openapi-lint-bundle es una herramienta para lintear y empaquetar especificaciones OpenAPI. Ayuda a los desarrolladores a crear archivos OpenAPI válidos y empaquetados openapi-lint-bundle est un outil pour lint et bundler des spécifications OpenAPI. Il aide les développeurs à créer des fichiers OpenAPI valides et empaquetés openapi-lint-bundle ist ein Tool zum Überprüfen und Bündeln von OpenAPI-Spezifikationen. Es hilft Entwicklern, gültige und gebündelte OpenAPI-Dateien zu erstellen O openapi-lint-bundle é uma ferramenta para lint e bundle de arquivos OpenAPI, ajudando desenvolvedores a criar especificações de API mais robustas. openapi-lint-bundle - это инструмент для lint и bundle файлов OpenAPI, помогающий разработчикам ИИ Агентов создавать более прочные спецификации API. openapi-lint-bundle هي أداة لتنظيف وتحزيم ملفات OpenAPI، تساعد مطورين أدوات الذكاء الاصطناعي على إنشاء مواصفات API أكثر متانة. how to use openapi-lint-bundle openapi-lint-bundle setup guide openapi validation and bundling redocly bundle tutorial openapi-lint-bundle alternative openapi spec management openapi linting and bundling best practices install openapi-lint-bundle openapi-lint-bundle vs swagger OpenAPI Lint OpenAPI Bundle AIエージェント开发工具 OpenAPI 规范错误修复 单一文件生成 redocly bundle Lints openapi/openapi.yml to ensure error-free specs Bundles OpenAPI specs into a single file using redocly bundle Supports scripts for linting and bundling via lint.sh and bundle.sh Manages multiple OpenAPI files in the openapi/ directory Generates a single file, such as openapi/openapi.bundle.yaml, for distribution openapi-lint-bundle is a skill that validates and bundles OpenAPI specifications, ensuring error-free specs and generating a single file for distribution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pyronaur/oxlint-plugin-inhuman/publish', 'community', 'pyronaur', 'oxlint-plugin-inhuman', 'pyronaur/oxlint-plugin-inhuman', 'publish', 0, 0, 23, '2026-02-05T07:44:05Z', '2026-03-07T03:48:50.005Z', 'e782d4df186f1fdc2fda9245ff72172029c5c23a8473bb35f27a87cec00b4c45', '{"id":"pyronaur/oxlint-plugin-inhuman/publish","name":"publish","description":{"en":"The publish skill prepares your repository for npm publish by verifying status, updating documentation, bumping version, committing, tagging, and pushing. It benefits developers by streamlining the publishing process.","zh":"准备代码仓库以进行npm发布，包括验证状态、更新文档、版本升级和提交","ja":"npm公開のためにコードリポジトリを準備する方法。状態の検証、ドキュメントの更新、バージョンの昇格、コミット","ko":"npm 발행을 위해 코드 저장소를 준비하는 방법. 상태 확인, 문서 업데이트, 버전 업그레이드, 커밋","es":"El AI Agent ''publish'' prepara tu repositorio para publicar en npm. Verifica el estado, actualiza la documentación y realiza pruebas","fr":"L''outil AI Agent ''publish'' prépare votre référentiel pour publier sur npm. Vérifiez l''état, mettez à jour la documentation et effectuez des tests","de":"Das AI-Tool ''publish'' bereitet Ihr Repository für die Veröffentlichung in npm vor. Überprüfen Sie den Status, aktualisieren Sie die Dokumentation und führen Sie Tests durch","pt":"O publish é uma habilidade que prepara o repositório para npm publish, verificando o status e atualizando documentos se necessário. Ele executa make lint e npm test se o código foi alterado desde a última execução bem-sucedida","ru":"Publish - это навык, который готовит репозиторий для npm publish, проверяя статус и обновляя документацию при необходимости. Он выполняет make lint и npm test, если код был изменен с последнего успешного запуска с ИИ Агентами","ar":"Publish هو مهارة التي تحضير المستودع لنشر npm ، والتحقق من الحالة وتحديث الوثائق عند الحاجة. وهو يقوم بتنفيذ make lint و npm test إذا تم تعديل الشفرة منذ آخر تشغيل ناجح مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Publish: End-to-End Setup Guide for AI Agents","zh":"发布设置指南：准备npm发布","ja":"パブリッシュの設定方法：npm公開の準備","ko":"발행 설정 가이드: npm 발행 준비","es":"Guía de configuración para publicar en npm con AI Agent","fr":"Guide de publication npm avec l''outil AI Agent","de":"Einrichtungsleitfaden für die Veröffentlichung in npm mit...","pt":"Guia de Configuração do Publish: Preparando o Repositório...","ru":"Настройка Publish: Подготовка Репозитория для npm с ИИ Аг...","ar":"دليل إعداد Publish: إعداد المستودع لنpm مع أدوات الذكاء ا..."},"description":{"en":"Get ready to publish your repo with ease! Learn how to prepare your repository for npm publish, including verification, documentation updates, and version bu...","zh":"了解如何准备代码仓库以进行npm发布，包括验证状态、更新文档、版本升级和提交","ja":"npm公開のためにコードリポジトリを準備する方法を学びます。状態の検証、ドキュメントの更新、バージョンの昇格、コミットなど","ko":"npm 발행을 위해 코드 저장소를 준비하는 방법을 알아보세요. 상태 확인, 문서 업데이트, 버전 업그레이드, 커밋 등","es":"Aprende a preparar tu repositorio para publicar en npm con nuestro AI Agent. Verifica el estado, actualiza la documentación y más","fr":"Découvrez comment préparer votre référentiel pour publier sur npm avec notre outil AI Agent. Vérifiez l''état, mettez à jour la documentation et plus","de":"Erfahren Sie, wie Sie Ihr Repository mit unserem AI-Tool für die Veröffentlichung in npm vorbereiten. Überprüfen Sie den Status, aktualisieren Sie die Dokume...","pt":"Aprenda a preparar seu repositório para npm publish com nossa guia de configuração do publish, incluindo verificação de status e atualização de documentos","ru":"Узнайте, как подготовить ваш репозиторий для npm publish с нашей инструкцией по настройке publish, включая проверку статуса и обновление документации с ИИ Аг...","ar":"تعلم كيفية إعداد مستودعك لنشر npm مع دليلنا لإعداد Publish ، بما في ذلك التحقق من الحالة وتحديث الوثائق مع أدوات الذكاء الاصطناعي"},"definition":{"en":"Publish is a skill that automates the end-to-end process of preparing a repository for npm publish, including preflight checks, linting, and testing.","zh":"发布是指准备代码仓库以进行npm发布的过程","ja":"パブリッシュとは、npm公開のためにコードリポジトリを準備するプロセス","ko":"발행은 npm 발행을 위해 코드 저장소를 준비하는 과정","es":"El AI Agent ''publish'' es una herramienta que prepara un repositorio para su publicación en npm","fr":"L''outil AI Agent ''publish'' est un outil qui prépare un référentiel pour sa publication sur npm","de":"Das AI-Tool ''publish'' ist ein Werkzeug, das ein Repository für die Veröffentlichung in npm vorbereitet","pt":"O que é publish? É uma habilidade que prepara o repositório para npm publish, garantindo que o código esteja pronto para ser publicado","ru":"Что такое Publish? Это навык, который готовит репозиторий для npm publish, гарантируя, что код готов к публикации с ИИ Агентами","ar":"ما هي Publish؟ هي مهارة التي تحضير المستودع لنشر npm ، مما يضمن أن الشفرة تكون جاهزة للنشر مع أدوات الذكاء الاصطناعي"},"features":{"en":["Runs preflight checks using git status -sb and git diff","Executes make lint and npm test for code validation","Bumps version and commits changes","Creates tags and pushes updates to the repository","Verifies repository readiness for npm publish"],"zh":["验证代码仓库状态","更新文档","版本升级","运行make lint和npm test","提交代码更改","创建标签并推送"],"ja":["コードリポジトリの状態を検証","ドキュメントを更新","バージョンを昇格","make lintとnpm testを実行","コードの変更をコミット","タグを作成してプッシュ"],"ko":["코드 저장소 상태 확인","문서 업데이트","버전 업그레이드","make lint와 npm test 실행","코드 변경 커밋","태그 생성 및 푸시"],"es":["Verificación del estado del repositorio con git status","Ejecución de pruebas con npm test","Actualización de la documentación si es necesario","Incremento de la versión y commit","Creación de etiquetas y push al repositorio","Compatibilidad con npm publish"],"fr":["Vérification de l''état du référentiel avec git status","Exécution de tests avec npm test","Mise à jour de la documentation si nécessaire","Incrementation de la version et commit","Création d''étiquettes et push vers le référentiel","Compatibilité avec npm publish"],"de":["Überprüfung des Repository-Status mit git status","Ausführung von Tests mit npm test","Aktualisierung der Dokumentation wenn erforderlich","Versionsincrement und Commit","Erstellung von Tags und Push an das Repository","Kompatibilität mit npm publish"],"pt":["Verificação de status com git status -sb","Execução de make lint e npm test se o código foi alterado","Atualização de documentos se necessário","Preparação do repositório para npm publish","Execução de comandos CLI para garantir a integridade do código"],"ru":["Проверка статуса с git status -sb","Выполнение make lint и npm test, если код был изменен","Обновление документации при необходимости","Подготовка репозитория для npm publish с ИИ Агентами","Выполнение команд CLI для обеспечения целостности кода"],"ar":["التحقق من الحالة مع git status -sb","تنفيذ make lint و npm test إذا تم تعديل الشفرة","تحديث الوثائق عند الحاجة","إعداد المستودع لنشر npm مع أدوات الذكاء الاصطناعي","تنفيذ أوامر CLI لضمان صحة الشفرة"]},"keywords":{"en":["how to use publish","publish setup guide","npm publish workflow","publish vs npm","publish install","what is publish","publish alternative","end-to-end publishing"],"zh":["npm发布","代码仓库准备","版本升级","make lint","npm test","代码提交","AIエージェント工具","代码管理"],"ja":["npm公開","コードリポジトリの準備","バージョンの昇格","make lint","npm test","コードのコミット","AIエージェント","コード管理"],"ko":["npm 발행","코드 저장소 준비","버전 업그레이드","make lint","npm test","코드 커밋","AI 에이전트","코드 관리"],"es":["AI Agent de publicación","npm publish","preparar repositorio para publicación","verificar estado del repositorio","ejecutar pruebas con npm test","actualizar documentación","incrementar versión","crear etiquetas","push al repositorio"],"fr":["Outil AI Agent de publication","npm publish","préparer référentiel pour publication","vérifier état du référentiel","exécuter tests avec npm test","mettre à jour documentation","incrémenter version","créer étiquettes","push vers le référentiel"],"de":["AI-Tool für die Veröffentlichung","npm publish","Repository für Veröffentlichung vorbereiten","Überprüfung des Repository-Status","Ausführung von Tests mit npm test","Aktualisierung der Dokumentation","Versionsincrement","Erstellung von Tags","Push an das Repository"],"pt":["publish npm","guia de configuração do publish","preparar repositório para npm","verificar status com git","executar make lint e npm test","atualizar documentos","comandos CLI para npm"],"ru":["publish npm","настройка publish","подготовка репозитория для npm","проверка статуса с git","выполнение make lint и npm test","обновление документации","команды CLI для npm с ИИ Агентами"],"ar":["نشر npm","دليل إعداد Publish","إعداد المستودع لنشر npm","التحقق من الحالة مع git","تنفيذ make lint و npm test","تحديث الوثائق","أوامر CLI لنشر npm مع أدوات الذكاء الاصطناعي"]}},"owner":"pyronaur","repo":"oxlint-plugin-inhuman","repoPath":"pyronaur/oxlint-plugin-inhuman","stars":0,"forks":0,"updatedAt":"2026-02-05T07:44:05Z","topics":[],"category":"community","skillMd":{"name":"publish","description":"Prepare oxlint-plugin-inhuman for an npm publish release. Use when the user asks to publish, prep a release, bump version, update README, tag, or push for oxlint-plugin-inhuman.","bodyPreview":"# Publish\n\n## Overview\n\nPrepare this repo for `npm publish` end-to-end: verify status, update docs if needed, bump version, commit, tag, and push. Do not run `npm publish`; stop after confirming readiness.\n\n## Workflow\n\n1. Preflight\n- Ensure the cwd is `/Users/n14/Projects/Open-Source/oxlint-plugin-inhuman`.\n- Check `git status -sb` and `git diff` to understand what will be released.\n- Run `make lint` and `npm test` if code changed since last green run or if unsure; lint is mandatory after runti","body":"# Publish\n\n## Overview\n\nPrepare this repo for `npm publish` end-to-end: verify status, update docs if needed, bump version, commit, tag, and push. Do not run `npm publish`; stop after confirming readiness.\n\n## Workflow\n\n1. Preflight\n- Ensure the cwd is `/Users/n14/Projects/Open-Source/oxlint-plugin-inhuman`.\n- Check `git status -sb` and `git diff` to understand what will be released.\n- Run `make lint` and `npm test` if code changed since last green run or if unsure; lint is mandatory after runtime changes.\n\n2. Update docs\n- Review `README.md` for any rule changes or new fixtures and update if needed.\n\n3. Pick version\n- If the user provided a version, use it.\n- Otherwise infer:\n  - Patch for fixes or docs/fixtures only\n  - Minor for behavior changes or new capabilities\n  - Major for breaking changes\n- Apply with `npm version <x.y.z> --no-git-tag-version`.\n- Update `package-lock.json` only if it is tracked; do not add it if the repo doesn’t track it.\n\n4. Commit\n- Follow repo style: imperative subject, blank line, `-` bullets.\n- Split commits if code changes and docs should be separated, or if multiple concerns exist.\n- Use heredoc with `git commit -F - <<''EOF'' ... EOF`.\n\n5. Tag\n- Create `vX.Y.Z` tag.\n- Prefer lightweight tag unless the user asks for annotated.\n\n6. Push\n- Push commits to `origin`.\n- Push the tag: `git push origin vX.Y.Z`.\n\n7. Final response\n- Report version, commits, tag status, and confirm the repo is ready.\n- Tell the user they can now run `npm publish`.\n\n## Notes\n\n- Do not run `npm pack` unless asked.\n- If any tooling fails, fix and rerun before proceeding.\n"},"lastSynced":"2026-03-07T03:48:50.005Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined npm package publishing capabilities.","zh":"非常适合需要简化npm包发布功能的开发代理。","ja":"開発エージェントがnpmパッケージの公開機能をストリームライン化する必要がある場合に最適です。","ko":"npm 패키지 배포 기능을 간소화해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan capacidades de publicación de paquetes npm simplificadas.","fr":"Parfait pour les agents de développement ayant besoin de capacités de publication de packages npm simplifiées.","de":"Perfekt für Entwicklungsmittel, die eine vereinfachte Veröffentlichung von npm-Paketen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de capacidades de publicação de pacotes npm simplificadas.","ru":"Идеально для агентов разработки, которым необходимы упрощенные возможности публикации пакетов npm.","ar":"مثالي لعميل التطوير الذي يحتاج إلى إمكانيات نشر حزم npm مبسطة."},"recommendation":{"en":"Empowers agents to automate the publishing process using git status, npm test, and version bumping, ensuring a smooth and verified release workflow with protocols like npm publish.","zh":"赋予代理人使用git状态、npm测试和版本升级自动化发布过程的能力，确保使用npm publish等协议的平滑和已验证的发布工作流程。","ja":"gitの状態、npmのテスト、バージョン番号の自動インクリメントを使用して公開プロセスを自動化することで、エージェントに権限を与え、npm publishなどのプロトコルを使用したスムーズで検証されたリリースワークフローを保証します。","ko":"git 상태, npm 테스트, 버전 번호 자동 증가를 사용하여 배포 과정을 자동화하여 에이전트에게 권한을 부여하고 npm publish와 같은 프로토콜을 사용한 매끄러운 배포 워크플로우를 보장합니다.","es":"Habilita a los agentes a automatizar el proceso de publicación utilizando git status, npm test y aumento de versión, asegurando un flujo de trabajo de lanzamiento suave y verificado con protocolos como npm publish.","fr":"Permet aux agents d''automatiser le processus de publication en utilisant git status, npm test et incrémentation de version, assurant ainsi un flux de travail de publication fluide et vérifié avec des protocoles comme npm publish.","de":"Ermöglicht es den Agenten, den Veröffentlichungsprozess mithilfe von git-Status, npm-Test und Versionsnummern zu automatisieren und so einen reibungslosen und verifizierten Release-Workflow mit Protokollen wie npm publish sicherzustellen.","pt":"Habilita os agentes a automatizar o processo de publicação usando git status, npm test e incremento de versão, garantindo um fluxo de trabalho de lançamento suave e verificado com protocolos como npm publish.","ru":"Наделяет агентов возможностью автоматизировать процесс публикации с использованием git status, npm test и инкремента версии, обеспечивая гладкий и проверенный рабочий процесс выпуска с протоколами như npm publish.","ar":"يمنح الوكلاء القدرة على автоматизировать عملية النشر باستخدام git status و npm test وزيادة الإصدار ، مما يضمن تدفق عمل إصدار سلس وموثق ببروتوكولات مثل npm publish."},"useCases":{"en":["Automating npm package releases","Verifying repository status before publishing","Updating documentation and versioning for consistency"],"zh":["自动化npm包发布","在发布前验证仓库状态","更新文档和版本控制以保持一致性"],"ja":["npmパッケージのリリースの自動化","公開前にリポジトリの状態を確認","一貫性を保つためにドキュメントとバージョニングを更新"],"ko":["npm 패키지 배포 자동화","배포 전 리포지토리 상태 확인","일관성을 유지하기 위해 문서 및 버전 관리 업데이트"],"es":["Automatización de lanzamientos de paquetes npm","Verificación del estado del repositorio antes de la publicación","Actualización de la documentación y la versión para garantizar la coherencia"],"fr":["Automatisation des publications de packages npm","Vérification du statut du référentiel avant publication","Mise à jour de la documentation et de la version pour assurer la cohérence"],"de":["Automatisierung von npm-Paket-Veröffentlichungen","Überprüfung des Repository-Status vor der Veröffentlichung","Aktualisierung der Dokumentation und Versionierung für Konsistenz"],"pt":["Automatizar lançamentos de pacotes npm","Verificar status do repositório antes da publicação","Atualizar documentação e versionamento para consistência"],"ru":["Автоматизировать выпуск пакетов npm","Проверять статус репозитория перед публикацией","Обновлять документацию и версионирование для согласованности"],"ar":["توفير إصدارات حزم npm автоматически","التحقق من حالة المستودع قبل النشر","تحديث المستندات وتأريخ الإصدار من أجل الاتساق"]},"limitations":{"en":["Requires git and npm setup","Limited to npm package management","Does not execute the final npm publish command"],"zh":["需要git和npm设置","仅限npm包管理","不执行最终的npm publish命令"],"ja":["gitおよびnpmの設定が必要","npmパッケージ管理のみ","最終的なnpm publishコマンドは実行されません"],"ko":["git 및 npm 설정이 필요","npm 패키지 관리에만 국한","최종 npm publish 명령을 실행하지 않음"],"es":["Requiere configuración de git y npm","Limitado a la administración de paquetes npm","No ejecuta el comando final de npm publish"],"fr":["Nécessite une configuration git et npm","Limité à la gestion de packages npm","N''exécute pas la commande finale npm publish"],"de":["Benötigt git- und npm-Einrichtung","Begrenzt auf npm-Paketverwaltung","Führt den endgültigen npm publish-Befehl nicht aus"],"pt":["Requer configuração do git e npm","Limitado ao gerenciamento de pacotes npm","Não executa o comando npm publish final"],"ru":["Требует настройки git и npm","Ограничен только менеджментом пакетов npm","Не выполняет окончательную команду npm publish"],"ar":["يتطلب إعداد git و npm","محدود بإدارة حزم npm","لا ينفذ الأمر npm publish النهائي"]},"version":4},"contentHash":"e782d4df186f1fdc2fda9245ff72172029c5c23a8473bb35f27a87cec00b4c45","qualityScore":23}');
