INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pyronaur/oxlint-plugin-inhuman/publish', 'publish', 'pyronaur', 'oxlint-plugin-inhuman', 'community', 'publish pyronaur oxlint-plugin-inhuman community The publish skill prepares your repository for npm publish by verifying status, updating documentation, bumping version, committing, tagging, and pushing. It benefits developers by streamlining the publishing process. 准备代码仓库以进行npm发布，包括验证状态、更新文档、版本升级和提交 npm公開のためにコードリポジトリを準備する方法。状態の検証、ドキュメントの更新、バージョンの昇格、コミット npm 발행을 위해 코드 저장소를 준비하는 방법. 상태 확인, 문서 업데이트, 버전 업그레이드, 커밋 El AI Agent ''publish'' prepara tu repositorio para publicar en npm. Verifica el estado, actualiza la documentación y realiza pruebas L''outil AI Agent ''publish'' prépare votre référentiel pour publier sur npm. Vérifiez l''état, mettez à jour la documentation et effectuez des tests Das AI-Tool ''publish'' bereitet Ihr Repository für die Veröffentlichung in npm vor. Überprüfen Sie den Status, aktualisieren Sie die Dokumentation und führen Sie Tests durch O publish é uma habilidade que prepara o repositório para npm publish, verificando o status e atualizando documentos se necessário. Ele executa make lint e npm test se o código foi alterado desde a última execução bem-sucedida Publish - это навык, который готовит репозиторий для npm publish, проверяя статус и обновляя документацию при необходимости. Он выполняет make lint и npm test, если код был изменен с последнего успешного запуска с ИИ Агентами Publish هو مهارة التي تحضير المستودع لنشر npm ، والتحقق من الحالة وتحديث الوثائق عند الحاجة. وهو يقوم بتنفيذ make lint و npm test إذا تم تعديل الشفرة منذ آخر تشغيل ناجح مع أدوات الذكاء الاصطناعي how to use publish publish setup guide npm publish workflow publish vs npm publish install what is publish publish alternative end-to-end publishing npm发布 代码仓库准备 版本升级 make lint npm test 代码提交 AIエージェント工具 代码管理 Runs preflight checks using git status -sb and git diff Executes make lint and npm test for code validation Bumps version and commits changes Creates tags and pushes updates to the repository Verifies repository readiness for npm publish Publish is a skill that automates the end-to-end process of preparing a repository for npm publish, including preflight checks, linting, and testing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gw-ai-security/ats-cv-scorer/project-phase-planner', 'community', 'gw-ai-security', 'ats-cv-scorer', 'gw-ai-security/ats-cv-scorer', 'project-phase-planner', 0, 0, 23, '2026-03-06T12:59:22.227Z', '2026-03-06T14:13:25.358Z', '3202dd4dde5f464a8d66f911a387713857b48ff2bb5d666b525c4252be34fe0f', '{"id":"gw-ai-security/ats-cv-scorer/project-phase-planner","name":"project-phase-planner","description":{"en":"The project-phase-planner skill generates and updates phase-based project plans, including roles, tasks, and artifacts. It benefits project managers and team leads by streamlining project planning.","zh":"项目阶段规划器是一种自动化项目管理的工具，通过读取项目快照、更新阶段计划、分配任务和角色等功能，帮助开发者高效管理项目","ja":"プロジェクトフェーズプランナーは、プロジェクト管理を自動化するツールです。プロジェクトスナップショットの読み取り、フェーズプランの更新、タスクとロールの割り当てなどを通じて、開発者のプロジェクト管理を効率化します","ko":"프로젝트 단계 계획工具은 프로젝트 관리를 자동화하는 도구입니다. 프로젝트 스냅숏을 읽고, 단계 계획을 업데이트하고, 태스크와 역할을 할당하는 등 개발자의 프로젝트 관리를 효율화합니다","es":"Project-phase-planner es una herramienta para planificar y actualizar proyectos por fases, incluyendo roles, tareas y artefactos. Se utiliza para adaptar el plan a los cambios en el proyecto.","fr":"Project-phase-planner est un outil pour planifier et mettre à jour les projets par phases, incluant les rôles, les tâches et les artefacts. Il est utilisé pour adapter le plan aux changements dans le projet.","de":"Project-phase-planner ist ein Tool zur Planung und Aktualisierung von Projekten nach Phasen, einschließlich Rollen, Aufgaben und Artefakten. Es wird verwendet, um den Plan an die Änderungen im Projekt anzupassen.","pt":"O project-phase-planner é uma ferramenta para gerenciar fases, tarefas e papéis em projetos","ru":"ИИ Агент project-phase-planner помогает автоматизировать планирование проектов","ar":"project-phase-planner هو أداة لإنشاء وتحديث مراحل المشروع"},"seo":{"title":{"en":"project-phase-planner: Phase-Based Project Planning Setup...","zh":"项目阶段规划器 Setup Guide","ja":"プロジェクトフェーズプランナー ベストプラクティス","ko":"프로젝트 단계 계획工具 설정 가이드","es":"Guía de configuración de project-phase-planner para agent...","fr":"Guide de mise en œuvre de project-phase-planner pour les ...","de":"Einrichtungsleitfaden für project-phase-planner in der AI...","pt":"Guia de Configuração do project-phase-planner","ru":"ИИ Агент project-phase-planner: Руководство по Настройке","ar":"إعداد مراحل المشروع مع project-phase-planner"},"description":{"en":"Discover how to leverage project-phase-planner for adaptive project planning. Learn to update phase plans, roles, tasks, and artifacts with this AI agent skill.","zh":"了解项目阶段规划器的功能和优点，实现项目管理的自动化和高效化，使用AIエージェント技术","ja":"プロジェクトフェーズプランナーを使用して、プロジェクト管理を自動化し、高効率化する方法を紹介します。AIエージェントの活用を学びましょう","ko":"프로젝트 단계 계획工具을 사용하여 프로젝트 관리를 자동화하고 효율화하는 방법을 알아보세요. AI Tools 기술을 활용해 보세요","es":"Aprende a utilizar project-phase-planner para planificar fases de proyectos de manera eficiente con tecnologías como CLI y Python","fr":"Découvrez comment utiliser project-phase-planner pour planifier les phases de projets de manière efficace avec des technologies comme CLI et Python","de":"Erfahren Sie, wie Sie project-phase-planner nutzen, um Projektphasen effizient mit Technologien wie CLI und Python zu planen","pt":"Aprenda a configurar o project-phase-planner para gerenciar fases, tarefas e papéis em projetos","ru":"Настройте ИИ Агент project-phase-planner для автоматизации планирования проектов","ar":"تعرف على كيفية إعداد مراحل المشروع وتحديثها باستخدام project-phase-planner"},"definition":{"en":"project-phase-planner is a skill that automates the creation and updating of phase-based project plans, incorporating roles, tasks, artifacts, and completion criteria.","zh":"项目阶段规划器是一种使用AIエージェント技术的项目管理工具","ja":"プロジェクトフェーズプランナーは、AIエージェント技術を使用したプロジェクト管理ツールです","ko":"프로젝트 단계 계획工具은 AI Tools 기술을 사용하는 프로젝트 관리 도구입니다","es":"Project-phase-planner es una herramienta de planificación de proyectos que genera y actualiza planes de proyecto basados en fases","fr":"Project-phase-planner est un outil de planification de projets qui génère et met à jour les plans de projet basés sur les phases","de":"Project-phase-planner ist ein Projektplanungstool, das phasenbasierte Projektpläne generiert und aktualisiert","pt":"O project-phase-planner é uma ferramenta de planejamento de projetos","ru":"ИИ Агент project-phase-planner - это инструмент для планирования проектов","ar":"project-phase-planner هو أداة لتحديد المراحل والمتطلبات في المشاريع"},"features":{"en":["Reads the latest project snapshot from `docs/project_state/`","Derives phases, tasks, and status from the project snapshot","Updates the phase plan based on the current project snapshot","Supports dynamic adaptation of project plans to new phases or tasks","Integrates with project planning workflows to ensure consistency"],"zh":["读取项目快照","更新阶段计划","分配任务和角色","使用CLI进行项目管理","支持多阶段项目管理","自动化项目状态更新"],"ja":["プロジェクトスナップショットの読み取り","フェーズプランの更新","タスクとロールの割り当て","CLIを使用したプロジェクト管理","多段階プロジェクト管理のサポート","プロジェクト状態の自動更新"],"ko":["프로젝트 스냅숏을 읽기","단계 계획을 업데이트","태스크와 역할을 할당","CLI를 사용한 프로젝트 관리","多단계 프로젝트 관리 지원","프로젝트 상태 자동 업데이트"],"es":["Generación de planes de proyecto basados en fases","Actualización de planes de proyecto según el proyecto actual","Incorporación de roles, tareas y artefactos en el plan","Utilización de tecnologías como CLI y Python","Adaptación del plan a los cambios en el proyecto","Lectura del proyecto actual desde `docs/project_state/`"],"fr":["Génération de plans de projet basés sur les phases","Mise à jour des plans de projet en fonction du projet actuel","Intégration de rôles, de tâches et d''artefacts dans le plan","Utilisation de technologies comme CLI et Python","Adaptation du plan aux changements dans le projet","Lecture du projet actuel depuis `docs/project_state/`"],"de":["Generierung von phasenbasierten Projektplänen","Aktualisierung von Projektplänen gemäß dem aktuellen Projekt","Einbindung von Rollen, Aufgaben und Artefakten in den Plan","Verwendung von Technologien wie CLI und Python","Anpassung des Plans an die Änderungen im Projekt","Lesevorgang des aktuellen Projekts aus `docs/project_state/`"],"pt":["Leitura do arquivo de estado do projeto em `docs/project_state/`","Extração de fases, tarefas e status do projeto","Atualização do plano de fases do projeto","Gerenciamento de papéis e responsabilidades","Integração com ferramentas de gerenciamento de projetos","Suporte a atualizações em tempo real"],"ru":["Чтение файла состояния проекта в `docs/project_state/`","Извлечение фаз, задач и статуса проекта","Обновление фазового плана проекта","Управление ролями и ответственностью","Интеграция с инструментами управления проектами","Поддержка обновлений в реальном времени"],"ar":["قراءة ملف حالة المشروع في `docs/project_state/`","استخراج المراحل والمهام ووضع المشروع","تحديث خطة المراحل للمشروع","إدارة الأدوار والمسؤوليات","دمج أدوات إدارة المشاريع","دعم التحديثات في الوقت الفعلي"]},"keywords":{"en":["how to use project-phase-planner","project-phase-planner setup guide","project-phase-planner alternative","project-phase-planner vs traditional planning","project-phase-planner install","phase-based project planning with AI"],"zh":["项目阶段规划器","AIエージェント","项目管理工具","自动化项目管理","CLI项目管理","多阶段项目管理","项目状态更新","开发者工具","项目管理软件"],"ja":["プロジェクトフェーズプランナー","AIエージェント","プロジェクト管理ツール","自動化プロジェクト管理","CLIプロジェクト管理","多段階プロジェクト管理","プロジェクト状態更新","開発者ツール","プロジェクト管理ソフトウェア"],"ko":["프로젝트 단계 계획工具","AI Tools","프로젝트 관리 도구","자동화 프로젝트 관리","CLI 프로젝트 관리","多단계 프로젝트 관리","프로젝트 상태 업데이트","개발자 도구","프로젝트 관리 소프트웨어"],"es":["project-phase-planner","agentes de IA","planificación de proyectos","fases de proyecto","CLI","Python","desarrollo de herramientas de IA","planificación de proyectos por fases","herramientas de planificación de proyectos"],"fr":["project-phase-planner","outils d''IA","planification de projets","phases de projet","CLI","Python","développement d''outils d''IA","planification de projets par phases","outils de planification de projets"],"de":["project-phase-planner","AI-Tools","Projektplanung","Projektphasen","CLI","Python","Entwicklung von AI-Tools","Projektplanung nach Phasen","Projektplanungstools"],"pt":["project-phase-planner","planejamento de projetos","gerenciamento de fases","ferramentas de gerenciamento de projetos","integração com ferramentas de gerenciamento de projetos","atualizações em tempo real","leitura de arquivo de estado do projeto","extração de fases e tarefas"],"ru":["ИИ Агент project-phase-planner","планирование проектов","управление фазами","инструменты управления проектами","интеграция с инструментами управления проектами","обновления в реальном времени","чтение файла состояния проекта","извлечение фаз и задач"],"ar":["project-phase-planner","تخطيط المشاريع","إدارة المراحل","أدوات إدارة المشاريع","دمج أدوات إدارة المشاريع","التحديثات في الوقت الفعلي","قراءة ملف حالة المشروع","استخراج المراحل والمهام"]}},"owner":"gw-ai-security","repo":"ats-cv-scorer","repoPath":"gw-ai-security/ats-cv-scorer","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.227Z","topics":[],"category":"community","skillMd":{"name":"project-phase-planner","description":"Erstelle und pflege den phasenbasierten Projektplan fuer ATS CV Scorer; verwenden, wenn der Gesamtplan, Phasen oder Aufgaben aktualisiert werden muessen.","bodyPreview":"# Skill: project-phase-planner\n\n## Zweck\nErzeuge und aktualisiere den phasenbasierten Projektplan inklusive Rollen, Aufgaben, Artefakten und Abschlusskriterien.\n\n## Wann anwenden\n- Wenn neue Phasen, Aufgaben oder Rollen benoetigt werden.\n- Wenn der Plan an den aktuellen Project Snapshot angepasst werden muss.\n\n## Vorgehen (Schritt-fuer-Schritt)\n1) Lies den neuesten Project Snapshot unter `docs/project_state/`.\n2) Leite Phasen, Aufgaben und Status aus dem Snapshot ab.\n3) Aktualisiere den Phasenpl","body":"# Skill: project-phase-planner\n\n## Zweck\nErzeuge und aktualisiere den phasenbasierten Projektplan inklusive Rollen, Aufgaben, Artefakten und Abschlusskriterien.\n\n## Wann anwenden\n- Wenn neue Phasen, Aufgaben oder Rollen benoetigt werden.\n- Wenn der Plan an den aktuellen Project Snapshot angepasst werden muss.\n\n## Vorgehen (Schritt-fuer-Schritt)\n1) Lies den neuesten Project Snapshot unter `docs/project_state/`.\n2) Leite Phasen, Aufgaben und Status aus dem Snapshot ab.\n3) Aktualisiere den Phasenplan in `docs/codex_skills/PHASE_PLAN.md`.\n4) Stelle sicher, dass Phase 0 explizit als erledigt markiert ist.\n\n## Lernperspektive\n- Warum so? Ein phasenbasierter Plan macht Fortschritt messbar und auditierbar.\n- Alternativen: lose To-do-Listen ohne Status und Rollen.\n- Warum nicht hier? Ohne Phasenstruktur fehlen Lern- und Entscheidungsnachweise.\n\n## Repo-Referenzen\n- `docs/project_state/`\n- `docs/codex_skills/PHASE_PLAN.md`\n- `docs/00_overview/PROJECT_STATE.md`\n\n## Qualitaetscheck\n- Alle Phasen haben Ziele, Rollen, Aufgaben, Outputs und Abschlusskriterien.\n- Status basiert auf dem Project Snapshot.\n- Keine nicht belegten Annahmen.\n\n## Phasenbezug\n| Phase | Aufgabe | Status |\n|-------|---------|--------|\n| Phase 1 | Phasenplan aus Snapshot ableiten | offen |"},"lastSynced":"2026-03-06T14:13:25.358Z","agentAnalysis":{"suitability":{"en":"Ideal for Project Management Agents needing automated phase-based project planning and task management capabilities.","zh":"适用于需要自动化基于阶段的项目规划和任务管理能力的项目管理代理。","ja":"プロジェクト管理エージェントが自動化されたフェーズベースのプロジェクト計画とタスク管理機能を必要とする場合に適しています。","ko":"자동화된 단계 기반 프로젝트 계획 및 작업 관리 기능이 필요한 프로젝트 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Proyectos que necesitan planificación y gestión de tareas automatizadas basadas en fases.","fr":"Idéal pour les Agents de Gestion de Projet ayant besoin d''une planification et d''une gestion de tâches automatisées basées sur les phases.","de":"Ideal für Projektmanagement-Agenten, die automatisierte phasenbasierte Projektplanung und Aufgabenmanagementfunktionen benötigen.","pt":"Ideal para Agentes de Gerenciamento de Projetos que necessitam de planejamento de projeto automatizado baseado em fases e capacidades de gerenciamento de tarefas.","ru":"Идеально для Агентов Управления Проектами, требующих автоматизированного планирования проектов на основе фаз и возможностей управления задачами.","ar":"مثالي لعميل إدارة المشروع الذي يحتاج إلى تخطيط مشروع آلي مستند إلى المراحل وقدرات إدارة المهام."},"recommendation":{"en":"Empowers agents to generate and update comprehensive project plans, including roles, tasks, and artifacts, utilizing phase-based planning and adapting to current project snapshots stored in `docs/project_state/`.","zh":"赋予代理生成和更新综合项目计划的能力，包括角色、任务和文档，利用基于阶段的规划，并适应存储在 `docs/project_state/` 中的当前项目快照。","ja":"エージェントが包括的なプロジェクト計画を生成および更新する機能を提供します。ロール、タスク、成果物を含み、フェーズベースの計画を利用し、`docs/project_state/` に保存された現在のプロジェクトスナップショットに適応します。","ko":"에이전트가 포괄적인 프로젝트 계획을 생성 및 업데이트하는 기능을 제공합니다. 역할, 작업 및 아티팩트를 포함하며, 단계 기반 계획을 사용하고 `docs/project_state/`에 저장된 현재 프로젝트 스냅샷에 적응합니다.","es":"Habilita a los agentes a generar y actualizar planes de proyecto completos, incluyendo roles, tareas y artefactos, utilizando la planificación basada en fases y adaptándose a las instantáneas de proyecto actuales almacenadas en `docs/project_state/`.","fr":"Permet aux agents de générer et de mettre à jour des plans de projet complets, y compris les rôles, les tâches et les artefacts, en utilisant la planification basée sur les phases et en s''adaptant aux instantanés de projet actuels stockés dans `docs/project_state/`.","de":"Ermächtigt Agenten, umfassende Projektpläne zu generieren und zu aktualisieren, einschließlich Rollen, Aufgaben und Artefakten, unter Verwendung von phasenbasierter Planung und Anpassung an aktuelle Projekt-Snapshots, die in `docs/project_state/` gespeichert sind.","pt":"Permite que os agentes gerem e atualizem planos de projeto abrangentes, incluindo funções, tarefas e artefatos, utilizando planejamento baseado em fases e adaptando-se a instantâneos de projeto atuais armazenados em `docs/project_state/`.","ru":"Наделяет агентов возможностью создавать и обновлять комплексные планы проектов, включая роли, задачи и артефакты, используя планирование на основе фаз и адаптируясь к текущим снимкам проекта, хранящимся в `docs/project_state/`.","ar":"يمنح الوكيل khảية generar و تحديث خطط المشروع الشاملة، بما في ذلك الأدوار والمهام والمنقولات، باستخدام التخطيط المستند إلى المراحل والتكيف مع لقطات المشروع الحالية المخزنة في `docs/project_state/`."},"useCases":{"en":["Automating project plan updates based on new phases or tasks","Generating phase-based project schedules with assigned roles and tasks","Debugging project plan inconsistencies against the current project snapshot"],"zh":["基于新阶段或任务自动更新项目计划","生成具有分配角色和任务的基于阶段的项目时间表","调试项目计划不一致性与当前项目快照"],"ja":["新しいフェーズまたはタスクに基づいてプロジェクト計画を自動更新する","割り当てられたロールとタスクを持つフェーズベースのプロジェクトスケジュールを生成する","現在のプロジェクトスナップショットに対するプロジェクト計画の不一致をデバッグする"],"ko":["새로운 단계 또는 작업을 기반으로 프로젝트 계획을 자동으로 업데이트하는 것","할당된 역할 및 작업을 갖는 단계 기반 프로젝트 스케줄을 생성하는 것","현재 프로젝트 스냅샷에 대한 프로젝트 계획의 불일치를 디버깅하는 것"],"es":["Automatización de actualizaciones de planes de proyecto en función de nuevas fases o tareas","Generación de horarios de proyecto basados en fases con roles y tareas asignados","Depuración de inconsistencias en el plan de proyecto contra la instantánea de proyecto actual"],"fr":["Automatisation des mises à jour des plans de projet en fonction de nouvelles phases ou de tâches","Génération d''horaires de projet basés sur les phases avec des rôles et des tâches assignés","Débogage des incohérences dans le plan de projet par rapport à l''instantané de projet actuel"],"de":["Automatisierung von Projektplan-Aktualisierungen basierend auf neuen Phasen oder Aufgaben","Generierung von phasenbasierten Projektplänen mit zugewiesenen Rollen und Aufgaben","Fehlerbehebung bei Projektplan-Inkonsistenzen gegenüber dem aktuellen Projekt-Snapshot"],"pt":["Automatizar atualizações de planos de projeto com base em novas fases ou tarefas","Gerar cronogramas de projeto baseados em fases com funções e tarefas atribuídas","Depurar inconsistências de planos de projeto em relação ao instantâneo de projeto atual"],"ru":["Автоматизировать обновления планов проекта на основе новых фаз или задач","Генерировать графики проекта на основе фаз с назначенными ролями и задачами","Отладить несоответствия планов проекта с текущим снимком проекта"],"ar":["توفير تحديثات خطط المشروع آليًا بناءً على مراحل أو مهام جديدة","توليد جداول زمنية للمشروع المستندة إلى المراحل مع الأدوار والمهام المحددة","تصحيح عدم الاتساق في خطط المشروع مقابل لقطات المشروع الحالية"]},"limitations":{"en":["Requires access to project snapshot documents in `docs/project_state/`","Limited to phase-based project planning"],"zh":["需要访问存储在 `docs/project_state/` 中的项目快照文档","仅限基于阶段的项目规划"],"ja":["`docs/project_state/` に保存されたプロジェクトスナップショットドキュメントへのアクセスが必要","フェーズベースのプロジェクト計画のみ"],"ko":["`docs/project_state/`에 저장된 프로젝트 스냅샷 문서에 대한 액세스가 필요합니다.","단계 기반 프로젝트 계획만 해당"],"es":["Requiere acceso a documentos de instantáneas de proyecto en `docs/project_state/`","Limitado a la planificación de proyectos basada en fases"],"fr":["Nécessite un accès aux documents d''instantanés de projet dans `docs/project_state/`","Limité à la planification de projet basée sur les phases"],"de":["Benötigt Zugriff auf Projekt-Snapshot-Dokumente in `docs/project_state/`","Begrenzt auf phasenbasierte Projektplanung"],"pt":["Requer acesso a documentos de instantâneos de projeto em `docs/project_state/`","Limitado ao planejamento de projeto baseado em fases"],"ru":["Требует доступа к документам снимков проекта в `docs/project_state/`","Ограничен планированием проекта на основе фаз"],"ar":["يتطلب الوصول إلى مستندات لقطات المشروع في `docs/project_state/`","محدود بالتخطيط للمشروع المستند إلى المراحل"]},"version":4},"contentHash":"3202dd4dde5f464a8d66f911a387713857b48ff2bb5d666b525c4252be34fe0f","qualityScore":23}');
DELETE FROM skills_fts WHERE id = 'gw-ai-security/ats-cv-scorer/project-phase-planner';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gw-ai-security/ats-cv-scorer/project-phase-planner', 'project-phase-planner', 'gw-ai-security', 'ats-cv-scorer', 'community', 'project-phase-planner gw-ai-security ats-cv-scorer community The project-phase-planner skill generates and updates phase-based project plans, including roles, tasks, and artifacts. It benefits project managers and team leads by streamlining project planning. 项目阶段规划器是一种自动化项目管理的工具，通过读取项目快照、更新阶段计划、分配任务和角色等功能，帮助开发者高效管理项目 プロジェクトフェーズプランナーは、プロジェクト管理を自動化するツールです。プロジェクトスナップショットの読み取り、フェーズプランの更新、タスクとロールの割り当てなどを通じて、開発者のプロジェクト管理を効率化します 프로젝트 단계 계획工具은 프로젝트 관리를 자동화하는 도구입니다. 프로젝트 스냅숏을 읽고, 단계 계획을 업데이트하고, 태스크와 역할을 할당하는 등 개발자의 프로젝트 관리를 효율화합니다 Project-phase-planner es una herramienta para planificar y actualizar proyectos por fases, incluyendo roles, tareas y artefactos. Se utiliza para adaptar el plan a los cambios en el proyecto. Project-phase-planner est un outil pour planifier et mettre à jour les projets par phases, incluant les rôles, les tâches et les artefacts. Il est utilisé pour adapter le plan aux changements dans le projet. Project-phase-planner ist ein Tool zur Planung und Aktualisierung von Projekten nach Phasen, einschließlich Rollen, Aufgaben und Artefakten. Es wird verwendet, um den Plan an die Änderungen im Projekt anzupassen. O project-phase-planner é uma ferramenta para gerenciar fases, tarefas e papéis em projetos ИИ Агент project-phase-planner помогает автоматизировать планирование проектов project-phase-planner هو أداة لإنشاء وتحديث مراحل المشروع how to use project-phase-planner project-phase-planner setup guide project-phase-planner alternative project-phase-planner vs traditional planning project-phase-planner install phase-based project planning with AI 项目阶段规划器 AIエージェント 项目管理工具 自动化项目管理 CLI项目管理 多阶段项目管理 项目状态更新 开发者工具 项目管理软件 Reads the latest project snapshot from `docs/project_state/` Derives phases, tasks, and status from the project snapshot Updates the phase plan based on the current project snapshot Supports dynamic adaptation of project plans to new phases or tasks Integrates with project planning workflows to ensure consistency project-phase-planner is a skill that automates the creation and updating of phase-based project plans, incorporating roles, tasks, artifacts, and completion criteria.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kousaku-maron/Carbon/tauri-release', 'community', 'kousaku-maron', 'Carbon', 'kousaku-maron/Carbon', 'tauri-release', 0, 0, 23, '2026-03-04T08:54:56Z', '2026-03-07T03:51:53.060Z', '032f5c661ac2a6ade8ccf0a55e8352ed387451579789f957c3c7e5adc95c0ca5', '{"id":"kousaku-maron/Carbon/tauri-release","name":"tauri-release","description":{"en":"The tauri-release skill automates the release process for desktop apps, managing versions and tags. It benefits developers by simplifying the deployment process.","zh":"Tauri Release 是一个用于自动化桌面应用发布的技能，通过管理版本和标签来实现自动化发布","ja":"Tauri Release はデスクトップアプリのリリースを自動化するスキルで、バージョン管理とタグ付けによって自動化されたリリースを実現します","ko":"Tauri Release는 자동화된 데스크탑 애플리케이션 배포를 위한 스킬로 버전 관리와 태그 지정에 의한 자동화된 배포를 구현합니다","es":"tauri-release es una habilidad para desplegar aplicaciones de escritorio con versiones semánticas y Git. Configura tu proyecto con tauri.conf.json","fr":"tauri-release est une compétence pour déployer des applications de bureau avec des versions sémantiques et Git. Configurez votre projet avec tauri.conf.json","de":"tauri-release ist eine Fähigkeit zur Bereitstellung von Desktop-Anwendungen mit semantischen Versionen und Git. Konfigurieren Sie Ihr Projekt mit tauri.conf.json","pt":"O Tauri-Release é uma ferramenta para automatizar a criação de versões de aplicativos desktop com Git e CLI.","ru":"Tauri-Release - это инструмент для автоматизации создания версий десктоп-приложений с помощью Git и CLI.","ar":"توري-ريليز هو أداة لتحديث تطبيقات سطح المكتب باستخدام Git و CLI"},"seo":{"title":{"en":"tauri-release: Automated Desktop App Release Setup Guide ...","zh":"Tauri Release Setup Guide: 自动化桌面应用发布","ja":"Tauri Release セットアップガイド: デスクトップアプリの自動リリース","ko":"Tauri Release 설정 가이드: 자동화 데스크탑 애플리케이션 배포","es":"Guía de configuración de tauri-release para despliegue de...","fr":"Guide d''installation de tauri-release pour le déploiement...","de":"Einrichtungsanleitung für tauri-release zur Bereitstellun...","pt":"Guia de Configuração do Tauri-Release para Desenvolvedores","ru":"ИИ Агенты: Настройка Tauri-Release для Разработчиков","ar":"إعداد توري-ريليز للIDES: دليل المستخدم"},"description":{"en":"Streamline your desktop app release process with tauri-release. Learn how to automate version management and deployment with this AI agent skill.","zh":"了解 Tauri Release 的技术细节和自动化发布流程，优化您的桌面应用开发","ja":"Tauri Release の技術的詳細と自動化されたリリースプロセスを学び、デスクトップアプリの開発を最適化する","ko":"Tauri Release의 기술 세부 사항과 자동화 배포 프로세스에 대해 알아보고 데스크탑 애플리케이션 개발을 최적화하십시오","es":"Aprende a configurar tauri-release para desplegar aplicaciones de escritorio con Git y versiones semánticas","fr":"Découvrez comment configurer tauri-release pour déployer des applications de bureau avec Git et des versions sémantiques","de":"Erfahren Sie, wie Sie tauri-release einrichten, um Desktop-Anwendungen mit Git und semantischen Versionen bereitzustellen","pt":"Aprenda a configurar o Tauri-Release para automatizar a criação de versões de aplicativos desktop com Git e CLI","ru":"Настройте Tauri-Release для автоматизации создания версий десктоп-приложений с помощью Git и CLI","ar":"تعلم كيفية إعداد توري-ريليز لتحديث تطبيقات سطح المكتب باستخدام Git و CLI"},"definition":{"en":"tauri-release is a skill that automates the release of desktop applications, handling version management and tagging.","zh":"Tauri Release 是一种 AI エージェント，用于自动化桌面应用的发布和版本管理","ja":"Tauri Release はデスクトップアプリのリリースとバージョン管理を自動化する AI エージェントです","ko":"Tauri Release는 데스크탑 애플리케이션의 배포와 버전 관리를 자동화하는 AI 에이전트입니다","es":"tauri-release es una herramienta de AI para desplegar aplicaciones de escritorio","fr":"tauri-release est un outil d''IA pour déployer des applications de bureau","de":"tauri-release ist ein AI-Tool zur Bereitstellung von Desktop-Anwendungen","pt":"O que é Tauri-Release? Uma ferramenta para gerenciar versões de aplicativos desktop.","ru":"Что такое Tauri-Release? Инструмент для управления версиями десктоп-приложений.","ar":"ما هو توري-ريليز؟ أداة لإدارة إصدارات تطبيقات سطح المكتب"},"features":{"en":["Manages versioning using the `version` field in `app/src-tauri/tauri.conf.json`","Creates tags in the format `v{version}` on the `main` branch","Executes `git pull origin main` to ensure the latest code","Checks for uncommitted changes and warns the user","Automatically stops processing if issues occur during execution"],"zh":["自动化桌面应用发布","版本管理通过 tauri.conf.json 文件","标签格式为 v{version}","自动化发布流程","主分支确认和更新"],"ja":["デスクトップアプリの自動リリース","バージョン管理を tauri.conf.json ファイルで実行","タグのフォーマットは v{version}","自動化されたリリースプロセス","メインブランチの確認と更新"],"ko":["自动화된 데스크탑 애플리케이션 배포","버전 관리를 tauri.conf.json 파일로 수행","태그 형식은 v{version}","자동화된 배포 프로세스","메인 브랜치 확인 및 업데이트"],"es":["Gestión de versiones semánticas en tauri.conf.json","Despliegue de aplicaciones de escritorio con Git","Comprobación automática de la rama main","Actualización de la versión con git pull origin main","Detección de cambios no comprometidos en el proyecto"],"fr":["Gestion de versions sémantiques dans tauri.conf.json","Déploiement d''applications de bureau avec Git","Vérification automatique de la branche main","Mise à jour de la version avec git pull origin main","Détection de modifications non validées dans le projet"],"de":["Verwaltung von semantischen Versionen in tauri.conf.json","Bereitstellung von Desktop-Anwendungen mit Git","Automatische Überprüfung des main-Zweigs","Aktualisierung der Version mit git pull origin main","Erkennung von nicht committeten Änderungen im Projekt"],"pt":["Gerenciamento de versões com Git","Criação automática de tags com formato v{version}","Verificação de branch main antes da criação de versão","Integração com CLI para automação","Leitura de versão a partir de tauri.conf.json"],"ru":["Управление версиями с помощью Git","Автоматическое создание тегов с форматом v{version}","Проверка ветки main перед созданием версии","Интеграция с CLI для автоматизации","Чтение версии из tauri.conf.json"],"ar":["إدارة الإصدارات مع Git","إنشاء تلقائي للعلامات بالتنسيق v{version}","التحقق من الفرع الرئيسي قبل إنشاء الإصدار","التكامل مع CLI للتحديث التلقائي","قراءة الإصدار من tauri.conf.json"]},"keywords":{"en":["how to use tauri-release","tauri-release setup guide","automated desktop app release","version management with tauri-release","tauri-release vs manual deployment","installing tauri-release","what is tauri-release","tauri-release tutorial","desktop app deployment with tauri-release"],"zh":["Tauri Release","自动化桌面应用发布","版本管理","AI エージェント","桌面应用开发","自动化发布流程"],"ja":["Tauri Release","デスクトップアプリの自動リリース","バージョン管理","AI エージェント","デスクトップアプリの開発","自動化されたリリースプロセス"],"ko":["Tauri Release","自动화된 데스크탑 애플리케이션 배포","버전 관리","AI 에이전트","데스크탑 애플리케이션 개발","자동화된 배포 프로세스"],"es":["tauri-release","despliegue de aplicaciones de escritorio","versiones semánticas","Git","tauri.conf.json","herramientas de AI para desarrolladores","desarrollo de aplicaciones de escritorio","integración continua"],"fr":["tauri-release","déploiement d''applications de bureau","versions sémantiques","Git","tauri.conf.json","outils d''IA pour les développeurs","développement d''applications de bureau","intégration continue"],"de":["tauri-release","Bereitstellung von Desktop-Anwendungen","semantische Versionen","Git","tauri.conf.json","AI-Tools für Entwickler","Entwicklung von Desktop-Anwendungen","kontinuierliche Integration"],"pt":["tauri release","git para desenvolvedores","criação de versões automática","gerenciamento de versões","CLI para automação","desenvolvimento de aplicativos desktop","tauri.conf.json"],"ru":["tauri release","git для разработчиков","автоматическое создание версий","управление версиями","CLI для автоматизации","разработка десктоп-приложений","tauri.conf.json"],"ar":["توري-ريليز","جيت للIDES","إنشاء إصدارات تلقائي","إدارة الإصدارات","CLI للتحديث التلقائي","تطوير تطبيقات سطح المكتب","tauri.conf.json"]}},"owner":"kousaku-maron","repo":"Carbon","repoPath":"kousaku-maron/Carbon","stars":0,"forks":0,"updatedAt":"2026-03-04T08:54:56Z","topics":[],"category":"community","skillMd":{"name":"tauri-release","description":"デスクトップアプリのリリース。バージョンタグの作成とプッシュを実行する。","bodyPreview":"# Release\n\nデスクトップアプリのリリースを実行するスキル。\n\n## バージョン管理ルール\n\n- バージョンは `app/src-tauri/tauri.conf.json` の `version` フィールドで管理する\n- タグのフォーマットは `v{version}`（例: version が `0.1.0` なら タグは `v0.1.0`）\n- タグは必ず `main` ブランチ上で作成する\n\n## 実行手順\n\n以下のステップを順番に実行すること。各ステップで問題が発生した場合は、即座に停止してユーザーに報告する。\n\n### 1. mainブランチの確認\n\n- 現在のブランチが `main` であることを確認する\n- `main` でない場合は、処理を停止してユーザーに警告する。自動的にブランチを切り替えてはいけない\n- `main` ブランチの場合、`git pull origin main` で最新の状態にする\n- コミットされていない変更がある場合は、停止してユーザーに確認する\n\n### 2. バージョンの読み取り\n\n- `app/src-tauri/tauri.c","body":"# Release\n\nデスクトップアプリのリリースを実行するスキル。\n\n## バージョン管理ルール\n\n- バージョンは `app/src-tauri/tauri.conf.json` の `version` フィールドで管理する\n- タグのフォーマットは `v{version}`（例: version が `0.1.0` なら タグは `v0.1.0`）\n- タグは必ず `main` ブランチ上で作成する\n\n## 実行手順\n\n以下のステップを順番に実行すること。各ステップで問題が発生した場合は、即座に停止してユーザーに報告する。\n\n### 1. mainブランチの確認\n\n- 現在のブランチが `main` であることを確認する\n- `main` でない場合は、処理を停止してユーザーに警告する。自動的にブランチを切り替えてはいけない\n- `main` ブランチの場合、`git pull origin main` で最新の状態にする\n- コミットされていない変更がある場合は、停止してユーザーに確認する\n\n### 2. バージョンの読み取り\n\n- `app/src-tauri/tauri.conf.json` の `version` フィールドを読み取る\n- タグ名 `v{version}` を決定し、ユーザーに表示する\n\n### 3. タグの重複チェック\n\n- `git tag -l \"v{version}\"` でローカルにタグが存在しないことを確認する\n- `git ls-remote --tags origin \"refs/tags/v{version}\"` でGitHub上にタグが存在しないことを確認する\n- タグがすでに存在する場合は、停止してユーザーに報告する\n\n### 4. 前バージョンのタグ確認\n\n- `git ls-remote --tags origin \"refs/tags/v*\"` でGitHub上の既存タグ一覧を取得する\n- 前のバージョンのタグ（例: 今回が `v0.1.1` なら `v0.1.0`）がGitHub上に存在することを確認する\n- 前バージョンのタグが存在しない場合は、停止してユーザーに警告する（バージョンの飛ばしや指定ミスの可能性）\n\n### 5. タグの作成とプッシュ\n\n- ユーザーにタグ `v{version}` を作成してプッシュしてよいか確認する\n- 承認を得たら以下を実行:\n  - `git tag v{version}`\n  - `git push origin v{version}`\n\n### 6. 完了報告\n\n- リリースタグのプッシュが完了したことを報告する\n- GitHub Actionsのリリースワークフローが自動的に起動されることを伝える\n"},"lastSynced":"2026-03-07T03:51:53.060Z","agentAnalysis":{"suitability":{"en":"Ideal for Automated Deployment Agents seeking to streamline desktop app release processes with version management and tagging.","zh":"适合自动化部署代理，旨在简化带有版本管理和标签的桌面应用程序发布流程。","ja":"デスクトップアプリのリリースプロセスをバージョン管理とタグ付けで効率化したい自動化デプロイエージェントに最適。","ko":"데스크톱 애플리케이션의 릴리스 프로세스를 버전 관리 및 태그를 통해 간소화하려는 자동화 배포 에이전트에 적합합니다.","es":"Ideal para Agentes de Implementación Automatizada que buscan optimizar los procesos de lanzamiento de aplicaciones de escritorio con gestión de versiones y etiquetado.","fr":"Idéal pour les Agents de Déploiement Automatisé cherchant à rationaliser les processus de publication d''applications de bureau avec gestion de versions et étiquetage.","de":"Ideal für automatisierte Bereitstellungsagenten, die Desktop-App-Veröffentlichungsprozesse mit Versionsverwaltung und Tagging optimieren möchten.","pt":"Ideal para Agentes de Implantação Automatizados que buscam otimizar os processos de lançamento de aplicativos de desktop com gerenciamento de versão e marcação.","ru":"Идеально для Автоматических Агентов Развертывания, стремящихся оптимизировать процессы выпуска настольных приложений с управлением версиями и тегами.","ar":"مثالي للوكلاء الآليين لتوزيع التطبيقات التي تهدف إلى تسريع عمليات إصدار تطبيقات سطح المكتب مع إدارة الإصدارات ووضع العلامات."},"recommendation":{"en":"Empowers agents to automate the release process for desktop apps, managing versions and tags through `tauri.conf.json` and adhering to a strict `v{version}` tagging format, ensuring seamless deployment and version control using Git.","zh":"赋予代理自动化桌面应用程序的发布流程的能力，通过 `tauri.conf.json` 管理版本和标签，遵循严格的 `v{version}` 标签格式，确保使用 Git 进行无缝的部署和版本控制。","ja":"エージェントにデスクトップアプリのリリースプロセスを自動化する能力を与え、`tauri.conf.json` を介してバージョンとタグを管理し、厳格な `v{version}` タグ付け形式に従い、Git を使用した無縫なデプロイとバージョン管理を保証します。","ko":"에이전트가 데스크톱 애플리케이션의 릴리스 프로세스를 자동화 할 수 있는 능력을 부여하며, `tauri.conf.json`을 통해 버전 및 태그를 관리하고, 엄격한 `v{version}` 태그 지정 형식을 준수하여 Git을 사용하여 무중단 배포 및 버전 제어를 보장합니다.","es":"Habilita a los agentes a automatizar el proceso de publicación para aplicaciones de escritorio, administrando versiones y etiquetas a través de `tauri.conf.json` y siguiendo un formato de etiquetado estricto `v{version}`, garantizando una implementación y control de versiones sin problemas utilizando Git.","fr":"Permet aux agents d''automatiser le processus de publication pour les applications de bureau, en gérant les versions et les étiquettes via `tauri.conf.json` et en suivant un format d''étiquetage strict `v{version}`, assurant ainsi un déploiement et un contrôle de version sans problème avec Git.","de":"Ermächtigt Agenten, den Veröffentlichungsprozess für Desktop-Apps zu automatisieren, indem sie Versionen und Tags über `tauri.conf.json` verwalten und einem strengen `v{version}`-Tagging-Format folgen, um so eine reibungslose Bereitstellung und Versionskontrolle mit Git zu gewährleisten.","pt":"Habilita os agentes a automatizar o processo de lançamento para aplicativos de desktop, gerenciando versões e tags por meio do `tauri.conf.json` e aderindo a um formato de marcação estrito `v{version}`, garantindo uma implantação e controle de versão sem problemas usando Git.","ru":"Наделяет агентов возможностью автоматизировать процесс выпуска для настольных приложений, управляя версиями и тегами через `tauri.conf.json` и придерживаясь строгого формата тегов `v{version}`, обеспечивая бесперебойное развертывание и контроль версий с помощью Git.","ar":"تمكّن الوكلاء من توفير عملية إصدار تطبيقات سطح المكتب، وإدارة الإصدارات والعلامات من خلال `tauri.conf.json` والالتزام بتنسيق علامات صارم `v{version}` ، مما يضمن توزيعًا وتحكمًا في الإصدارات بدون مشاكل باستخدام Git."},"useCases":{"en":["Automating desktop app releases with version updates","Managing tags for different app versions on the `main` branch","Validating and updating `tauri.conf.json` for consistent versioning"],"zh":["使用版本更新自动化桌面应用程序的发布","在 `main` 分支上为不同应用程序版本管理标签","验证和更新 `tauri.conf.json` 以实现一致的版本管理"],"ja":["バージョン更新を使用してデスクトップアプリのリリースを自動化する","`main` ブランチ上でさまざまなアプリバージョンのタグを管理する","一貫したバージョニングのために `tauri.conf.json` を検証および更新する"],"ko":["버전 업데이트를 사용하여 데스크톱 애플리케이션의 릴리스를 자동화하는 것","`main` 브랜치에서 다양한 애플리케이션 버전에 대한 태그를 관리하는 것","일관된 버전 관리를 위해 `tauri.conf.json`을 검증 및 업데이트하는 것"],"es":["Automatizar la publicación de aplicaciones de escritorio con actualizaciones de versiones","Administrar etiquetas para diferentes versiones de aplicaciones en la rama `main`","Validar y actualizar `tauri.conf.json` para una versionamiento coherente"],"fr":["Automatiser la publication d''applications de bureau avec des mises à jour de versions","Gérer les étiquettes pour différentes versions d''applications sur la branche `main`","Valider et mettre à jour `tauri.conf.json` pour un versionnement cohérent"],"de":["Automatisieren der Veröffentlichung von Desktop-Apps mit Versionsaktualisierungen","Verwalten von Tags für verschiedene App-Versionen im `main`-Branch","Validieren und Aktualisieren von `tauri.conf.json` für ein konsistentes Versioning"],"pt":["Automatizar lançamentos de aplicativos de desktop com atualizações de versão","Gerenciar tags para diferentes versões de aplicativos no branch `main`","Validar e atualizar `tauri.conf.json` para versionamento consistente"],"ru":["Автоматизировать выпуск настольных приложений с обновлениями версий","Управлять тегами для разных версий приложений на ветке `main`","Проверять и обновлять `tauri.conf.json` для последовательного версионирования"],"ar":["توفير إصدار تطبيقات سطح المكتب مع تحديثات الإصدار","إدارة العلامات للنسخ المختلفة من التطبيقات على الفرع `main`","التحقق من صحة وتحديث `tauri.conf.json` من أجل إصدارات متسقة"]},"limitations":{"en":["Requires `main` branch to be the current branch","Needs a `tauri.conf.json` file for version management","Only supports Git for version control and tagging"],"zh":["需要 `main` 分支作为当前分支","需要 `tauri.conf.json` 文件进行版本管理","仅支持 Git 进行版本控制和标签管理"],"ja":["現在のブランチとして `main` ブランチが必要","バージョン管理のために `tauri.conf.json` ファイルが必要","バージョン管理とタグ管理は Git でのみサポートされる"],"ko":["현재 분기로서 `main` 분기가 필요합니다","`tauri.conf.json` 파일이 버전 관리를 위해 필요합니다","버전 제어 및 태그 지정은 Git을 통해서만 지원됩니다"],"es":["Requiere que la rama `main` sea la rama actual","Necesita un archivo `tauri.conf.json` para la gestión de versiones","Solo admite Git para el control y etiquetado de versiones"],"fr":["Nécessite que la branche `main` soit la branche actuelle","A besoin d''un fichier `tauri.conf.json` pour la gestion de versions","N''aide que Git pour le contrôle et l''étiquetage des versions"],"de":["Benötigt, dass der `main`-Branch der aktuelle Branch ist","Benötigt eine `tauri.conf.json`-Datei für die Versionsverwaltung","Unterstützt nur Git für die Versionskontrolle und -etikettierung"],"pt":["Requer que o branch `main` seja o branch atual","Necessita de um arquivo `tauri.conf.json` para gerenciamento de versão","Apenas suporta Git para controle e marcação de versão"],"ru":["Требует, чтобы ветка `main` была текущей веткой","Требует файла `tauri.conf.json` для управления версиями","Поддерживает только Git для контроля и тегов версий"],"ar":["يتطلب أن يكون الفرع `main` هو الفرع الحالي","يحتاج إلى ملف `tauri.conf.json` لإدارة الإصدارات","يدعم فقط Git للتحكم في الإصدارات ووضع العلامات"]},"version":4},"contentHash":"032f5c661ac2a6ade8ccf0a55e8352ed387451579789f957c3c7e5adc95c0ca5","qualityScore":23}');
