INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kousaku-maron/Carbon/tauri-release', 'tauri-release', 'kousaku-maron', 'Carbon', 'community', 'tauri-release kousaku-maron Carbon community The tauri-release skill automates the release process for desktop apps, managing versions and tags. It benefits developers by simplifying the deployment process. Tauri Release 是一个用于自动化桌面应用发布的技能，通过管理版本和标签来实现自动化发布 Tauri Release はデスクトップアプリのリリースを自動化するスキルで、バージョン管理とタグ付けによって自動化されたリリースを実現します Tauri Release는 자동화된 데스크탑 애플리케이션 배포를 위한 스킬로 버전 관리와 태그 지정에 의한 자동화된 배포를 구현합니다 tauri-release es una habilidad para desplegar aplicaciones de escritorio con versiones semánticas y Git. Configura tu proyecto con tauri.conf.json tauri-release est une compétence pour déployer des applications de bureau avec des versions sémantiques et Git. Configurez votre projet avec tauri.conf.json tauri-release ist eine Fähigkeit zur Bereitstellung von Desktop-Anwendungen mit semantischen Versionen und Git. Konfigurieren Sie Ihr Projekt mit tauri.conf.json O Tauri-Release é uma ferramenta para automatizar a criação de versões de aplicativos desktop com Git e CLI. Tauri-Release - это инструмент для автоматизации создания версий десктоп-приложений с помощью Git и CLI. توري-ريليز هو أداة لتحديث تطبيقات سطح المكتب باستخدام Git و CLI how to use tauri-release tauri-release setup guide automated desktop app release version management with tauri-release tauri-release vs manual deployment installing tauri-release what is tauri-release tauri-release tutorial desktop app deployment with tauri-release Tauri Release 自动化桌面应用发布 版本管理 AI エージェント 桌面应用开发 自动化发布流程 Manages versioning using the `version` field in `app/src-tauri/tauri.conf.json` Creates tags in the format `v{version}` on the `main` branch Executes `git pull origin main` to ensure the latest code Checks for uncommitted changes and warns the user Automatically stops processing if issues occur during execution tauri-release is a skill that automates the release of desktop applications, handling version management and tagging.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ghirschhorn987/event-scheduling-app/Code Quality & Testing', 'community', 'ghirschhorn987', 'event-scheduling-app', 'ghirschhorn987/event-scheduling-app', 'Code Quality & Testing', 0, 0, 23, '2026-03-07T01:35:47Z', '2026-03-07T03:57:10.323Z', 'e3085af0220cf46c9bb5fc2b8f2bfb19468ed3b23c7b5ddd8442a8801ebeda3f', '{"id":"ghirschhorn987/event-scheduling-app/Code Quality & Testing","name":"Code Quality & Testing","description":{"en":"Code Quality & Testing automates testing and linting for developers, ensuring high-quality code with commands like npm run lint:fix and npm run test:unit.","zh":"代码质量和测试是软件开发中的关键环节，本节介绍如何使用npm run lint:fix和测试套件确保代码质量","ja":"コード品質とテストはソフトウェア開発の重要なステップです。本節では、npm run lint:fixとテストスイートを使用してコード品質を確保する方法を紹介します","ko":"코드 품질 및 테스트는 소프트웨어 개발의 핵심 단계입니다. 본 절에서는 npm run lint:fix 및 테스트套件을 사용하여 코드 품질을 보장하는 방법을 설명합니다","es":"La calidad y pruebas de código son fundamentales para el desarrollo de software. Utilice herramientas de AI para automatizar tareas como npm run lint:fix y test:unit.","fr":"La qualité et les tests de code sont essentiels pour le développement de logiciels. Utilisez des outils d''IA pour automatiser des tâches comme npm run lint:fix et test:unit.","de":"Code-Qualität und -Testing sind für die Software-Entwicklung von entscheidender Bedeutung. Verwenden Sie KI-Tools, um Aufgaben wie npm run lint:fix und test:unit zu automatisieren.","pt":"Melhore a qualidade do seu código e teste-o com eficácia usando npm run lint:fix e npm run test:unit","ru":"Улучшите качество вашего кода и протестируйте его эффективно с помощью npm run lint:fix и npm run test:unit","ar":"حسن جودة كودك واختبره بفعالية باستخدام npm run lint:fix و npm run test:unit"},"seo":{"title":{"en":"Code Quality & Testing: Automated Testing Setup Guide | A...","zh":"代码质量和测试最佳实践 - AI工具","ja":"コード品質とテストのセットアップガイド - AIエージェント","ko":"코드 품질 및 테스트 설정 안내 - 인공지능 툴","es":"Guía de Configuración de Calidad y Pruebas de Código con ...","fr":"Guide de Configuration de la Qualité et des Tests de Code...","de":"Einrichtungsleitfaden für Code-Qualität und -Testing mit ...","pt":"Guia de Configuração de Qualidade de Código e Testes com ...","ru":"Настройка качества кода и тестирования с помощью ИИ Агентов","ar":"دليل إعداد جودة الكود واختبارها مع أدوات الذكاء الاصطناعي"},"description":{"en":"Boost your code quality with automated testing! Learn how to setup and use Code Quality & Testing to ensure 85% test coverage and resolve linting errors","zh":"了解代码质量和测试的重要性，并学习如何使用npm run lint:fix和测试套件自动化代码审查","ja":"コード品質とテストの重要性を学び、npm run lint:fixやテストスイートを使用したコードレビューの自動化方法を紹介","ko":"코드 품질 및 테스트의 중요성을 배우고, npm run lint:fix 및 테스트套件을 사용한 코드 검토 자동화 방법을 알아보세요","es":"Aprende a configurar y utilizar herramientas de AI para mejorar la calidad y pruebas de tu código con npm run lint:fix y test:unit","fr":"Découvrez comment configurer et utiliser des outils d''IA pour améliorer la qualité et les tests de votre code avec npm run lint:fix et test:unit","de":"Erfahren Sie, wie Sie KI-Tools für die Verbesserung der Code-Qualität und -Tests mit npm run lint:fix und test:unit einrichten und verwenden","pt":"Aprenda a melhorar a qualidade do seu código e a testá-lo com eficácia usando comandos como npm run lint:fix e npm run test:unit","ru":"Узнайте, как улучшить качество вашего кода и протестировать его эффективно с помощью команд như npm run lint:fix и npm run test:unit","ar":"تعلم كيف تحسن جودة كودك واختباره بفعالية باستخدام أوامر مثل npm run lint:fix و npm run test:unit"},"definition":{"en":"Code Quality & Testing is a skill that automates code quality checks and testing using npm commands to ensure high test coverage and resolve styling errors","zh":"代码质量和测试是指通过自动化工具和测试套件来确保软件代码的可靠性和稳定性","ja":"コード品質とテストとは、自動化ツールとテストスイートを使用してソフトウェアコードの信頼性と安定性を確保すること","ko":"코드 품질 및 테스트는 자동화 도구 및 테스트套件을 사용하여 소프트웨어 코드의 신뢰성 및 안정성을 보장하는 것","es":"La calidad y pruebas de código se refiere a la evaluación y mejora de la calidad del código mediante herramientas de AI","fr":"La qualité et les tests de code font référence à l''évaluation et à l''amélioration de la qualité du code à l''aide d''outils d''IA","de":"Code-Qualität und -Testing beziehen sich auf die Bewertung und Verbesserung der Code-Qualität mit Hilfe von KI-Tools","pt":"Qualidade de código e teste é a capacidade de garantir a qualidade e a funcionalidade do código","ru":"Качество кода и тестирование - это способность обеспечить качество и функциональность кода","ar":"جودة الكود واختبارها هي القدرة على ضمان جودة ووظيفية الكود"},"features":{"en":["Automatically resolves styling and standard linting errors using npm run lint:fix","Executes core logic test suite using npm run test:unit","Runs end-to-end browser tests for UI validation using npm run test:e2e","Ensures 85% test coverage by automatically writing missing tests","Supports automated testing using npm commands","Enforces test coverage guardrails to maintain high-quality code"],"zh":["自动化代码风格和标准linting错误修复","执行核心逻辑单元测试","运行端到端浏览器测试进行UI验证","测试覆盖率低于85%时自动编写缺失测试"],"ja":["コードスタイルと標準lintingエラーの自動修復","コアロジックの単体テストの実行","エンドツーエンドブラウザテストによるUIの検証","テストカバレッジが85%未満の場合に欠けているテストを自動的に記述"],"ko":["자동화된 코드 스타일 및 표준 linting 오류 수정","코어 로직 단위 테스트 실행","엔드 투 엔드 브라우저 테스트를 통해 UI 검증","테스트 커버리지가 85% 미만일 때 자동으로 누락된 테스트 작성"],"es":["Automatización de tareas con npm run lint:fix","Ejecución de pruebas unitarias con npm run test:unit","Ejecución de pruebas de extremo a extremo con npm run test:e2e","Cobertura de pruebas con un umbral de 85%","Integración con herramientas de AI para la mejora de la calidad del código","Soporte para la automatización de pruebas con CLI"],"fr":["Automatisation de tâches avec npm run lint:fix","Exécution de tests unitaires avec npm run test:unit","Exécution de tests de bout en bout avec npm run test:e2e","Couverture de tests avec un seuil de 85%","Intégration avec des outils d''IA pour l''amélioration de la qualité du code","Prise en charge de l''automatisation des tests avec CLI"],"de":["Automatisierung von Aufgaben mit npm run lint:fix","Ausführung von Einheitstests mit npm run test:unit","Ausführung von End-to-End-Tests mit npm run test:e2e","Testabdeckung mit einem Schwellenwert von 85%","Integration mit KI-Tools für die Verbesserung der Code-Qualität","Unterstützung für die Automatisierung von Tests mit CLI"],"pt":["Comandos npm run lint:fix para resolver erros de estilo e linting","Comandos npm run test:unit para executar testes unitários","Comandos npm run test:e2e para executar testes de ponta a ponta","Guardrails para garantir a cobertura de testes de pelo menos 85%","Integração com ferramentas de IA para melhorar a qualidade do código","Capacidade de escrever testes automatizados"],"ru":["Команды npm run lint:fix для исправления ошибок стиля и linting","Команды npm run test:unit для выполнения юнит-тестов","Команды npm run test:e2e для выполнения тестов end-to-end","Гардрейлы для обеспечения покрытия тестами не менее 85%","Интеграция с ИИ Агентами для улучшения качества кода","Возможность написания автоматических тестов"],"ar":["أوامر npm run lint:fix لتصحيح أخطاء الأسلوب وlinting","أوامر npm run test:unit لتشغيل اختبارات الوحدات","أوامر npm run test:e2e لتشغيل اختبارات نهاية إلى نهاية","حواجز أمان لضمان تغطية الاختبارات بنسبة 85% على الأقل","التكامل مع أدوات الذكاء الاصطناعي لتحسين جودة الكود","القدرة على كتابة اختبارات آلية"]},"keywords":{"en":["how to use Code Quality & Testing","Code Quality & Testing setup guide","automated testing with npm","Code Quality & Testing vs Jest","Code Quality & Testing install","what is Code Quality & Testing","Code Quality & Testing alternative","npm run lint:fix tutorial","Code Quality & Testing best practices"],"zh":["代码质量","测试自动化","npm run lint:fix","单元测试","端到端测试","AI工具","代码审查","自动化测试"],"ja":["コード品質","テスト自動化","npm run lint:fix","単体テスト","エンドツーエンドテスト","AIエージェント","コードレビュー","自動テスト"],"ko":["코드 품질","테스트 자동화","npm run lint:fix","단위 테스트","엔드 투 엔드 테스트","인공지능 툴","코드 검토","자동 테스트"],"es":["calidad de código","pruebas de código","herramientas de AI","npm run lint:fix","test:unit","test:e2e","cobertura de pruebas","automatización de pruebas","desarrollo de software"],"fr":["qualité de code","tests de code","outils d''IA","npm run lint:fix","test:unit","test:e2e","couverture de tests","automatisation des tests","développement de logiciels"],"de":["Code-Qualität","Code-Testing","KI-Tools","npm run lint:fix","test:unit","test:e2e","Testabdeckung","Automatisierung von Tests","Software-Entwicklung"],"pt":["qualidade de código","teste de software","npm run lint:fix","npm run test:unit","guardrails","ferramentas de IA","desenvolvimento de software","testes automatizados"],"ru":["качество кода","тестирование программного обеспечения","npm run lint:fix","npm run test:unit","гαρдрейлы","ИИ Агенты","разработка программного обеспечения","автоматические тесты"],"ar":["جودة الكود","اختبار البرمجيات","npm run lint:fix","npm run test:unit","حواجز أمان","أدوات الذكاء الاصطناعي","تطوير البرمجيات","اختبارات آلية"]}},"owner":"ghirschhorn987","repo":"event-scheduling-app","repoPath":"ghirschhorn987/event-scheduling-app","stars":0,"forks":0,"updatedAt":"2026-03-07T01:35:47Z","topics":[],"category":"community","skillMd":{"name":"Code Quality & Testing","description":"Use these tools to ensure all code meets the projects architectural and quality standards before considering a task complete.","bodyPreview":"**Allowed Commands:**\r\n- `npm run lint:fix`: Automatically resolve styling and standard linting errors.\r\n- `npm run test:unit`: Execute the core logic test suite.\r\n- `npm run test:e2e`: Run the end-to-end browser tests for UI validation.\r\n**Guardrails:** If test coverage drops below 85% after modifying a module, you must automatically write the missing tests before marking the task as done.","body":"**Allowed Commands:**\r\n- `npm run lint:fix`: Automatically resolve styling and standard linting errors.\r\n- `npm run test:unit`: Execute the core logic test suite.\r\n- `npm run test:e2e`: Run the end-to-end browser tests for UI validation.\r\n**Guardrails:** If test coverage drops below 85% after modifying a module, you must automatically write the missing tests before marking the task as done.\r\n"},"lastSynced":"2026-03-07T03:57:10.323Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated code quality assurance and testing capabilities with npm and linting tools.","zh":"适合需要使用npm和linting工具进行自动化代码质量保证和测试的开发代理。","ja":"npmとlintingツールを使用した自動コード品質保証とテスト機能が必要な開発エージェントに適しています。","ko":"npm과 linting 툴을 사용하여 자동화된 코드 품질 보증 및 테스트 기능이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan garantía y pruebas de calidad de código automatizadas con npm y herramientas de linting.","fr":"Parfait pour les Agents de Développement ayant besoin d''une assurance et de tests de qualité de code automatisés avec npm et des outils de linting.","de":"Perfekt für Entwicklungagenten, die eine automatisierte Qualitätssicherung und Testfunktionen mit npm und Linting-Tools benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de garantia e teste de qualidade de código automatizados com npm e ferramentas de linting.","ru":"Идеально подходит для агентов разработки, которым требуются автоматизированные возможности обеспечения качества кода и тестирования с помощью npm и инструментов линтинга.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى ضمان جودة التعليمات البرمجية التلقائي و khả năng الاختبار مع npm وأدوات لينтинغ."},"recommendation":{"en":"Empowers agents to enforce high-quality code standards using npm run lint:fix and npm run test:unit, ensuring test coverage and validating UI with end-to-end browser tests via npm run test:e2e.","zh":"赋予代理执行高质量代码标准的能力，使用npm run lint:fix和npm run test:unit，确保测试覆盖率，并通过npm run test:e2e进行端到端浏览器测试以验证UI。","ja":"npm run lint:fixとnpm run test:unitを使用して、高品質のコード規範をエージェントが実施できるようにし、テストカバレッジを確保し、npm run test:e2eによるエンドツーエンドブラウザーテストでUIを検証します。","ko":"npm run lint:fix와 npm run test:unit을 사용하여 에이전트가 높은 品質의 코드 표준을 시행할 수 있도록 하며, 테스트 커버리지가 보장되며, npm run test:e2e를 통해 브라우저 테스트를 수행하여 UI를 검증합니다.","es":"Habilita a los agentes a aplicar estándares de código de alta calidad utilizando npm run lint:fix y npm run test:unit, garantizando la cobertura de pruebas y validando la interfaz de usuario con pruebas de extremo a extremo en el navegador mediante npm run test:e2e.","fr":"Permet aux agents d''appliquer des normes de code de haute qualité en utilisant npm run lint:fix et npm run test:unit, en garantissant la couverture des tests et en validant l''interface utilisateur avec des tests de bout en bout dans le navigateur via npm run test:e2e.","de":"Ermöglicht es den Agenten, hochwertige Code-Standards mit npm run lint:fix und npm run test:unit durchzusetzen, die Testabdeckung sicherzustellen und die Benutzeroberfläche mit End-to-End-Browertests über npm run test:e2e zu validieren.","pt":"Habilita os agentes a impor padrões de código de alta qualidade usando npm run lint:fix e npm run test:unit, garantindo cobertura de teste e validando a interface do usuário com testes de ponta a ponta do navegador via npm run test:e2e.","ru":"Наделяет агентов возможностью обеспечивать высокие стандарты качества кода с помощью npm run lint:fix и npm run test:unit, гарантируя покрытие тестирования и проверку валидности интерфейса пользователя с помощью тестов от начала до конца в браузере через npm run test:e2e.","ar":"يمنح الوكلاء القدرة على فرض معايير عالية الجودة للتعليمات البرمجية باستخدام npm run lint:fix و npm run test:unit، وضمان تغطية الاختبار والتحقق من صحة واجهة المستخدم مع اختبارات متصفح من النهاية إلى النهاية عبر npm run test:e2e."},"useCases":{"en":["Automating styling and standard linting error resolution","Executing core logic test suites","Running end-to-end browser tests for UI validation"],"zh":["自动化样式和标准linting错误解析","执行核心逻辑测试套件","运行端到端浏览器测试以验证UI"],"ja":["スタイルと標準のlintingエラーレゾリューションの自動化","コアロジックテストスイートの実行","エンドツーエンドブラウザーテストの実行によるUIの検証"],"ko":["스타일 및 표준 linting 오류 해결 자동화","코어 로직 테스트 스위트 실행","UI 검증을 위한 브라우저 테스트 실행"],"es":["Automatización del estilo y resolución de errores de linting estándar","Ejecución de suites de pruebas de lógica principal","Ejecución de pruebas de extremo a extremo en el navegador para la validación de la interfaz de usuario"],"fr":["Automatisation du style et résolution des erreurs de linting standard","Exécution des suites de tests de logique principale","Exécution des tests de bout en bout dans le navigateur pour la validation de l''interface utilisateur"],"de":["Automatisierung des Stils und Auflösung von Linting-Standardfehlern","Ausführung von Test-Suiten für die Kernlogik","Ausführung von End-to-End-Browertest für die Validierung der Benutzeroberfläche"],"pt":["Automatizar estilização e resolução de erros de linting padrão","Executar conjuntos de testes de lógica central","Executar testes de navegador de ponta a ponta para validação da interface do usuário"],"ru":["Автоматизировать стилизацию и решение стандартных ошибок линтинга","Выполнять основные наборы тестов логики","Выполнять тесты браузера от начала до конца для проверки валидности интерфейса пользователя"],"ar":["التنسيق التلقائي وتحليل أخطاء لينتينغ الموحدة","تشغيل مجموعة اختبارات المنطق الأساسية","تشغيل اختبارات متصفح من النهاية إلى النهاية للتحقق من صحة واجهة المستخدم"]},"limitations":{"en":["Requires npm environment","Test coverage must be above 85%"],"zh":["需要npm环境","测试覆盖率必须超过85%"],"ja":["npm環境が必要","テストカバレッジは85%を超える必要がある"],"ko":["npm 환경이 필요","테스트 커버리지는 85% 이상이어야 함"],"es":["Requiere entorno npm","La cobertura de las pruebas debe ser superior al 85%"],"fr":["Nécessite un environnement npm","La couverture des tests doit être supérieure à 85%"],"de":["Benötigt npm-Umgebung","Die Testabdeckung muss über 85% liegen"],"pt":["Requer ambiente npm","A cobertura de teste deve estar acima de 85%"],"ru":["Требуется среда npm","Покрытие тестирования должно быть выше 85%"],"ar":["يتطلب بيئة npm","يجب أن تكون تغطية الاختبار أعلى من 85%"]},"version":4},"contentHash":"e3085af0220cf46c9bb5fc2b8f2bfb19468ed3b23c7b5ddd8442a8801ebeda3f","qualityScore":23}');
