gage des flux de travail d''analyse de contenu"],"de":["Automatisierung von redaktionellen Überprüfungsaufgaben","Generierung von präziser Prosa basierend auf XML-Anweisungen","Fehlerbehebung in Content-Analyse-Workflows"],"pt":["Automatizar tarefas de revisão editorial","Gerar prosa precisa com base em instruções XML","Depurar fluxos de trabalho de análise de conteúdo"],"ru":["Автоматизация задач редактирования","Генерация точной прозы на основе инструкций XML","Отладка рабочих процессов анализа контента"],"ar":["أتمتة مهام المراجعة التحريرية","генерация نثر دقيق بناءً على تعليمات XML","تصحيح أخطاء تدفقات العمل لتحليل المحتوى"]},"limitations":{"en":["Requires access to the {project-root}/_bmad/core/tasks/editorial-review-prose.xml task file","XML file format dependency"],"zh":["需要访问{project-root}/_bmad/core/tasks/editorial-review-prose.xml任务文件","依赖于XML文件格式"],"ja":["{project-root}/_bmad/core/tasks/editorial-review-prose.xmlタスクファイルへのアクセスが必要","XMLファイル形式への依存"],"ko":["{project-root}/_bmad/core/tasks/editorial-review-prose.xml 작업 파일에 대한 액세스가 필요함","XML 파일 형식 의존"],"es":["Requiere acceso al archivo de tareas {project-root}/_bmad/core/tasks/editorial-review-prose.xml","Dependencia del formato de archivo XML"],"fr":["Nécessite l''accès au fichier de tâches {project-root}/_bmad/core/tasks/editorial-review-prose.xml","Dépendance du format de fichier XML"],"de":["Benötigt Zugriff auf die Task-Datei {project-root}/_bmad/core/tasks/editorial-review-prose.xml","Abhängigkeit vom XML-Dateiformat"],"pt":["Exige acesso ao arquivo de tarefa {project-root}/_bmad/core/tasks/editorial-review-prose.xml","Dependência do formato de arquivo XML"],"ru":["Требует доступа к файлу задания {project-root}/_bmad/core/tasks/editorial-review-prose.xml","Зависимость от формата файла XML"],"ar":["يتطلب الوصول إلى ملف المهمة {project-root}/_bmad/core/tasks/editorial-review-prose.xml","اعتماد تنسيق الملف XML"]},"version":4},"contentHash":"58ec69d58e9dfd6be6f008af863d9599f764bc0b1fd8822b2ef5c6e8cb0423f8","q