INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('boseungk/career-narrative-lab/episode-mining', 'episode-mining', 'boseungk', 'career-narrative-lab', 'community', 'episode-mining boseungk career-narrative-lab community The episode-mining skill automates the process of extracting and organizing episodes from project files, benefiting developers and project managers. It scans files such as README.md, design documents, and reports to identify key episodes. Episode Mining是一种AI工具，用于自动提取项目文件中的关键信息。通过扫描项目文件，开发人员可以快速地找到所需的信息 エピソードマイニングは、プロジェクトファイルから重要な情報を自動的に抽出するAIエージェントです。プロジェクトファイルのスキャンにより、開発者は必要な情報を迅速に発見できます 에피소드 발굴 스킬은 프로젝트 파일에서 핵심 정보를 자동으로 추출하는 AI 에이전트입니다. 프로젝트 파일을 스캔하여 개발자는 필요한 정보를 신속하게 발견할 수 있습니다 Episode-mining es una habilidad que permite a los desarrolladores extraer automáticamente contenido de proyectos y clasificarlo de manera sistemática Episode-mining est une compétence qui permet aux développeurs d''extraire automatiquement du contenu de projets et de le classer de manière systématique Episode-Mining ist eine Fähigkeit, die es Entwicklern ermöglicht, Projektinhalte automatisch zu extrahieren und systematisch zu klassifizieren O Episode-Mining é uma ferramenta de extração de conteúdo que utiliza técnicas de ИИ Агенты para automatizar a extração de dados de arquivos de projeto. Episode-Mining - это инструмент для извлечения данных, использующий методы ИИ Агенты для автоматизации извлечения данных из файлов проекта. Episode-Mining هو أداة لاستخراج المحتوى التي تستخدم تقنيات ИИ Агенты لتحسين استخراج البيانات من ملفات المشروع. how to use episode-mining episode-mining setup guide episode-mining alternative episode-mining vs manual episode extraction automated project file scanning episode-mining install what is episode-mining episode-mining workflow episode-mining Mode A and Mode B Episode Mining AIエージェント 项目文件扫描 自动信息提取 Python脚本 CLI命令行界面 Git SVN 项目管理工具 Scans project folders to extract episode information from files like README.md and design documents Supports Mode A (file scanning) and Mode B (dialogue-based) workflows Automatically extracts data from files such as package.json, requirements.txt, and .pptx Explores folder contents, including docs/ folders and infrastructure files Follows a detailed guide outlined in project-scan-guide.md for file scanning Episode-mining is a skill that systematically extracts, organizes, and categorizes episodes from project files, using techniques such as file scanning and dialogue-based workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DaniyalFaraz2003/dirctl/rust-standards', 'community', 'DaniyalFaraz2003', 'dirctl', 'DaniyalFaraz2003/dirctl', 'rust-standards', 0, 0, 23, '2026-03-02T16:27:54Z', '2026-03-07T04:07:53.149Z', 'beed634db1d9e91126cd165b4d1bb4a1b2f48415c798b145d7c826ab1ae3fd31', '{"id":"DaniyalFaraz2003/dirctl/rust-standards","name":"rust-standards","description":{"en":"The rust-standards skill provides explicit Rust best practices and automated guidance for generating idiomatic and safe Rust code. This skill benefits developers working with dirctl.","zh":"Rust 标准设置指南，提供 dirctl 的最佳实践和自动化指导，确保生成的代码是惯用的和安全的","ja":"Rust Standards Setup Guide - dirctl のベストプラクティスと自動化ガイダンスを提供し、生成されたコードがイディオマティックで安全であることを保証する","ko":"Rust 표준 설정 가이드 - dirctl의 최고의 관행과 자동화 가이드를 제공하여 생성된 코드가 관용적이고 안전한지 보장합니다","es":"Rust Standards proporciona orientación explícita para generar código Rust idiomático y seguro, utilizando herramientas como estaerror y rustfmt","fr":"Rust Standards fournit des conseils explicites pour générer du code Rust idiomatique et sécurisé, en utilisant des outils tels que cetteerror et rustfmt","de":"Rust Standards bietet explizite Anleitung für die Erstellung von idiomatischem und sicherem Rust-Code, unter Verwendung von Tools wie dieser Fehler und rustfmt","pt":"O skill de padrões de Rust fornece orientação explícita para desenvolver código Rust idiomático e seguro","ru":"Навык стандартов Rust обеспечивает явное руководство для разработки идиоматического и безопасного кода на Rust","ar":"توفير مهارة معايير الرست إرشادات明确 لتطوير رمز الرست المتوافق والأمن"},"seo":{"title":{"en":"rust-standards: Idiomatic Code Generation for AI Agents |...","zh":"Rust 标准设置指南 - 使用 dirctl 实现最佳实践","ja":"Rust Standards Setup Guide - dirctl を使用したベストプラクティスの実現","ko":"Rust 표준 설정 가이드 - dirctl을 사용한 최고의 관행 구현","es":"Guía de configuración de Rust Standards para desarrolladores","fr":"Guide de mise en place des normes Rust pour les développeurs","de":"Rust-Standards-Setup-Leitfaden für Entwickler","pt":"Padrões de Rust: Guia de Configuração para Desenvolvedores","ru":"ИИ Агенты: Настройка Стандартов Rust для Разработчиков","ar":"إعداد معايير الرست: دليل للمطورين"},"description":{"en":"Discover how rust-standards enforces best practices and safety in Rust code generation. Learn how to setup and use this skill for idiomatic and safe code.","zh":"学习如何使用 dirctl 实现 Rust 最佳实践，确保生成的代码是惯用的和安全的，了解关键规则和技术细节","ja":"dirctl を使用して Rust のベストプラクティスを実現する方法を学び、生成されたコードがイディオマティックで安全であることを確認し、重要なルールとテクニカルな詳細を理解する","ko":"dirctl을 사용하여 Rust의 최고의 관행을 실현하는 방법을 배우고 생성된 코드가 관용적이고 안전한지 확인하며 핵심 규칙과 기술적 세부 사항을 이해하십시오","es":"Aprende a aplicar las mejores prácticas de Rust con nuestra guía de configuración de Rust Standards, incluyendo estaerror y rustfmt","fr":"Découvrez comment appliquer les meilleures pratiques de Rust avec notre guide de mise en place des normes Rust, y compris cetteerror et rustfmt","de":"Erfahren Sie, wie Sie die besten Rust-Praktiken mit unserem Rust-Standards-Setup-Leitfaden anwenden, einschließlich dieser Fehler und rustfmt","pt":"Aprenda a configurar os padrões de Rust para desenvolver código idiomático e seguro com o skill de padrões de Rust","ru":"Узнайте, как настроить стандарты Rust для разработки идиоматического и безопасного кода с помощью навыка стандартов Rust и ИИ Агентов","ar":"تعرف على كيفية إعداد معايير الرست لتطوير رمز متوافق وأمن باستخدام مهارة معايير الرست"},"definition":{"en":"rust-standards is a skill that enforces Rust best practices, such as using thiserror for error types and avoiding unwrap and expect in core crates.","zh":"Rust 标准是指使用 dirctl 实现 Rust 代码的最佳实践和安全性","ja":"Rust Standards は、dirctl を使用して Rust コードのベストプラクティスと安全性を実現すること","ko":"Rust 표준은 dirctl을 사용하여 Rust 코드의 최고의 관행과 안전성을 실현하는 것","es":"Rust Standards es un conjunto de reglas y prácticas para garantizar la calidad y seguridad del código Rust","fr":"Rust Standards est un ensemble de règles et de pratiques pour garantir la qualité et la sécurité du code Rust","de":"Rust Standards ist ein Satz von Regeln und Praktiken, um die Qualität und Sicherheit von Rust-Code zu gewährleisten","pt":"O que são padrões de Rust? São diretrizes para desenvolver código Rust seguro e idiomático","ru":"Что такое стандарты Rust? Это руководящие принципы для разработки безопасного и идиоматического кода на Rust","ar":"ما هي معايير الرست؟ هي إرشادات لتطوير رمز الرست الآمن والمتوافق"},"features":{"en":["Enforces no unwrap or expect in core crates, only allowing them in tests","Utilizes thiserror for crate-local error types and maps external errors at boundaries","Prevents panic in library code for safer execution","Ensures explicit ordering for iteration affecting semantics, such as sorting keys","Integrates rustfmt for consistent code formatting"],"zh":["使用 thiserror 实现 crate-local 错误类型","在边界处映射外部错误","避免在核心包中使用 unwrap() 或 expect()","使用 rustfmt 和 explicit ordering 实现代码格式化","禁止在库代码中使用 panic!"],"ja":["thiserror を使用した crate-local エラータイプの実現","境界での外部エラーのマッピング","unwrap() または expect() のコアクレートでの使用を避ける","rustfmt と explicit ordering を使用したコードのフォーマット","ライブラリコードでの panic! の使用を禁止"],"ko":["thiserror를 사용한 crate-local 오류 유형 구현","경계에서 외부 오류 매핑","unwrap() 또는 expect()의 코어 패키지에서의 사용을 피함","rustfmt 및 명시적 정렬을 사용한 코드 형식화","라이브러리 코드에서 panic!의 사용을 금지"],"es":["Evita el uso de unwrap() y expect() en los crates core","Utiliza estaerror para tipos de error de crate local","No utiliza panic! en el código de biblioteca","Orden explícito para cualquier iteración que afecte la semántica","Soporte para rustfmt"],"fr":["Évitez l''utilisation de unwrap() et expect() dans les crates core","Utilisez cetteerror pour les types d''erreur de crate local","N''utilisez pas panic! dans le code de bibliothèque","Ordre explicite pour toute itération affectant la sémantique","Prise en charge de rustfmt"],"de":["Vermeiden Sie die Verwendung von unwrap() und expect() in den Core-Crates","Verwenden Sie diesen Fehler für crate-lokale Fehlerarten","Verwenden Sie kein panic! im Bibliothekscod","Explizite Reihenfolge für jede Iteration, die die Semantik beeinflusst","Unterstützung für rustfmt"],"pt":["Proibição do uso de `unwrap()` e `expect()` em crates principais","Uso de `thiserror` para tipos de erro locais","Proibição do uso de `panic!` em código de biblioteca","Ordenação explícita para iterações que afetam a semântica","Uso de `rustfmt` para formatação de código"],"ru":["Запрет использования `unwrap()` и `expect()` в основных crate","Использование `thiserror` для местных типов ошибок","Запрет использования `panic!` в библиотечном коде","Явная упорядоченность для итераций, влияющих на семантику","Использование `rustfmt` для форматирования кода"],"ar":["منع استخدام `unwrap()` و `expect()` في الحزم الرئيسية","استخدام `thiserror` لإنشاء أنواع الأخطاء المحلية","منع استخدام `panic!` في رمز المكتبة","ترتيب صريح للتنقلات التي تؤثر على الدلالات","استخدام `rustfmt` لتنسيق الرمز"]},"keywords":{"en":["how to use rust-standards","rust-standards setup guide","rust-standards vs rustfmt","rust-standards install","what is rust-standards","rust-standards alternative","rust-standards best practices","rust-standards safety features","rust-standards and dirctl"],"zh":["Rust 标准","dirctl","Rust 最佳实践","Rust 代码安全","thiserror","rustfmt","explicit ordering","AIエージェント","Rust 开发","代码质量"],"ja":["Rust Standards","dirctl","Rust ベストプラクティス","Rust コードの安全性","thiserror","rustfmt","explicit ordering","AIエージェント","Rust 開発","コード品質"],"ko":["Rust 표준","dirctl","Rust 최고의 관행","Rust 코드 안전","thiserror","rustfmt","명시적 정렬","AI 에이전트","Rust 개발","코드 품질"],"es":["Rust Standards","estaerror","rustfmt","código Rust idiomático","código Rust seguro","mejores prácticas de Rust","desarrollo de software en Rust","herramientas de desarrollo de Rust"],"fr":["Rust Standards","thiserror","rustfmt","code Rust idiomatique","code Rust sécurisé","meilleures pratiques de Rust","développement de logiciels en Rust","outils de développement de Rust"],"de":["Rust Standards","thiserror","rustfmt","idiomatischer Rust-Code","sicherer Rust-Code","beste Rust-Praktiken","Software-Entwicklung in Rust","Rust-Entwicklungstools"],"pt":["padrões de rust","desenvolvimento de código rust","código idiomático","código seguro","rustfmt","thiserror","unwrap","expect","panic"],"ru":["стандарты rust","разработка кода на rust","идиоматический код","безопасный код","rustfmt","thiserror","unwrap","expect","panic","ИИ Агенты"],"ar":["معايير الرست","تطوير رمز الرست","رمز متوافق","رمز آمن","rustfmt","thiserror","unwrap","expect","panic","أدوات الذكاء الاصطناعي"]}},"owner":"DaniyalFaraz2003","repo":"dirctl","repoPath":"DaniyalFaraz2003/dirctl","stars":0,"forks":0,"updatedAt":"2026-03-02T16:27:54Z","topics":[],"category":"community","skillMd":{"name":"rust-standards","description":">-","bodyPreview":"# dirctl — Rust Standards (Skill)\n\n## Purpose\nProvide explicit Rust best practices and automated guidance when generating or\nrefactoring Rust code for dirctl. Ensure generated code is idiomatic and safe.\n\n## Key rules (to enforce)\n- No `unwrap()` or `expect()` in core crates; allowed only in tests.\n- Use `thiserror` for crate-local error types; map external errors at boundaries.\n- No `panic!` in library code.\n- Explicit ordering for any iteration affecting semantics (sort keys).\n- `rustfmt` and","body":"# dirctl — Rust Standards (Skill)\n\n## Purpose\nProvide explicit Rust best practices and automated guidance when generating or\nrefactoring Rust code for dirctl. Ensure generated code is idiomatic and safe.\n\n## Key rules (to enforce)\n- No `unwrap()` or `expect()` in core crates; allowed only in tests.\n- Use `thiserror` for crate-local error types; map external errors at boundaries.\n- No `panic!` in library code.\n- Explicit ordering for any iteration affecting semantics (sort keys).\n- `rustfmt` and `clippy` compliance required.\n\n## What to produce on request\n- If asked to change code, return diffs that follow the rules above.\n- If tests fail, explain failures and propose fixes.\n- Provide minimal, focused changes (do not refactor unrelated code).\n\n## Example invocation\n- \"Generate a deterministic iteration snippet for Planner following rust-standards.\"\n\n## Verification commands\n- `rustfmt --check $(git ls-files ''*.rs'' | tr ''\\n'' '' '')`\n- `cargo clippy --all-targets --all-features -- -D warnings`"},"lastSynced":"2026-03-07T04:07:53.149Z","agentAnalysis":{"suitability":{"en":"Perfect for Rust Development Agents needing idiomatic and safe code generation capabilities.","zh":"非常适合需要惯用且安全的代码生成能力的Rust开发代理。","ja":"Rust開発エージェントが、イディオマティックで安全なコード生成機能を必要とする場合に最適です。","ko":"루스트 개발 에이전트가 관용적이고 안전한 코드 생성 기능을 필요로 할 때 완벽합니다.","es":"Perfecto para agentes de desarrollo de Rust que necesitan capacidades de generación de código idiomático y seguro.","fr":"Parfait pour les agents de développement Rust nécessitant des capacités de génération de code idiomatique et sécurisé.","de":"Perfekt für Rust-Entwicklungsagenten, die idiomatiche und sichere Code-Generierungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Rust que precisam de capacidades de geração de código idiomático e seguro.","ru":"Идеально подходит для агентов развития Rust, которым необходимы возможности генерации идiomатического и безопасного кода.","ar":"مثالي للوكلاء النمطية روست التي تحتاج إلى قدرات توليد الرمز المحلي والأمني."},"recommendation":{"en":"Empowers agents to enforce Rust best practices, utilizing libraries like `thiserror` for error handling and `rustfmt` for code formatting, ensuring generated code is both safe and idiomatic, with explicit ordering for iteration and no use of `unwrap()` or `expect()` in core crates.","zh":"赋予代理人强制执行Rust最佳实践的能力，利用像`thiserror`的错误处理和`rustfmt`的代码格式化等库，确保生成的代码既安全又惯用，具有显式的迭代顺序，不在核心crate中使用`unwrap()`或`expect()`。","ja":"エージェントにRustのベストプラクティスを適用させる能力を与え、`thiserror`によるエラーハンドリングや`rustfmt`によるコードフォーマットなどのライブラリを利用し、生成されたコードが安全でイディオマティックであることを保証し、明示的なイテレーションの順序を持ち、`unwrap()`や`expect()`はコアクレートでは使用しません。","ko":"에이전트가 루스트의 최선의 관행을 시행하도록 하는 기능을 제공하며, `thiserror`를 통한 오류 처리 및 `rustfmt`를 통한 코드 형식화와 같은 라이브러리를 활용하여 생성된 코드가 안전하고 관용적이라는 것을 보장하며, 명시적인 반복 순서를 가지며 핵심 크레이트에서는 `unwrap()`나 `expect()`를 사용하지 않습니다.","es":"Empodera a los agentes para hacer cumplir las mejores prácticas de Rust, utilizando bibliotecas como `thiserror` para el manejo de errores y `rustfmt` para la configuración de código, asegurando que el código generado sea seguro e idiomático, con ordenación explícita para iteración y sin uso de `unwrap()` o `expect()` en crates core.","fr":"Permet aux agents d''appliquer les meilleures pratiques de Rust, en utilisant des bibliothèques comme `thiserror` pour la gestion des erreurs et `rustfmt` pour la mise en forme du code, en garantissant que le code généré est à la fois sécurisé et idiomatique, avec un ordonnancement explicite pour l''itération et sans utilisation de `unwrap()` ou `expect()` dans les crates core.","de":"Ermächtigt Agenten, die besten Praktiken von Rust durchzusetzen, indem Bibliotheken wie `thiserror` für die Fehlerbehandlung und `rustfmt` für die Codeformatierung verwendet werden, um sicherzustellen, dass der generierte Code sicher und idiomatisch ist, mit expliziter Reihenfolge für die Iteration und ohne Verwendung von `unwrap()` oder `expect()` in Core-Crates.","pt":"Habilita os agentes a impor as melhores práticas Rust, utilizando bibliotecas como `thiserror` para tratamento de erros e `rustfmt` para formatação de código, garantindo que o código gerado seja seguro e idiomático, com ordenação explícita para iteração e sem uso de `unwrap()` ou `expect()` em crates principais.","ru":"Наделяет агентов возможностью соблюдать лучшие практики Rust, используя библиотеки типа `thiserror` для обработки ошибок и `rustfmt` для форматирования кода, обеспечивая генерацию кода, который является одновременно безопасным и идiomатическим, с явной упорядоченностью для итерации и без использования `unwrap()` или `expect()` в основных крейтах.","ar":"يمنح الوكلاء القدرة على فرض أفضل الممارسات روست، باستخدام المكتبات مثل `thiserror` لمعالجة الأخطاء و `rustfmt` لتنسيق الشفرة، مما يضمن توليد شفرة آمنة ومحلية، مع ترتيب صريح للتكرار وبدون استخدام `unwrap()` أو `expect()` في الحزم الأساسية."},"useCases":{"en":["Enforcing Rust coding standards in dirctl projects","Automating code reviews for idiomatic Rust code","Generating safe and efficient Rust code with `thiserror` and `rustfmt`"],"zh":["在dirctl项目中执行Rust编码标准","自动审查惯用Rust代码","使用`thiserror`和`rustfmt`生成安全且高效的Rust代码"],"ja":["dirctlプロジェクトでRustコーディング規約を適用する","イディオマティックなRustコードの自動レビュー","`thiserror`と`rustfmt`を使用して安全で効率的なRustコードを生成する"],"ko":["dirctl 프로젝트에서 루스트 코딩 표준 적용하기","관용적인 루스트 코드에 대한 자동 코드 리뷰","`thiserror`와 `rustfmt`를 사용하여 안전하고 효율적인 루스트 코드 생성"],"es":["Hacer cumplir los estándares de codificación de Rust en proyectos dirctl","Automatizar las revisiones de código para código Rust idiomático","Generar código Rust seguro y eficiente con `thiserror` y `rustfmt`"],"fr":["Faire respecter les normes de codage Rust dans les projets dirctl","Automatiser les examens de code pour le code Rust idiomatique","Générer du code Rust sécurisé et efficace avec `thiserror` et `rustfmt`"],"de":["Durchsetzen der Rust-Codierungsstandards in dirctl-Projekten","Automatisieren von Code-Reviews für idiomaticen Rust-Code","Generieren von sicherem und effizientem Rust-Code mit `thiserror` und `rustfmt`"],"pt":["Fazer cumprir os padrões de codificação Rust em projetos dirctl","Automatizar revisões de código para código Rust idiomático","Gerar código Rust seguro e eficiente com `thiserror` e `rustfmt`"],"ru":["Применение стандартов кодирования Rust в проектах dirctl","Автоматизация проверок кода для идiomатического кода Rust","Генерация безопасного и эффективного кода Rust с помощью `thiserror` и `rustfmt`"],"ar":["فرض معايير الترميز روست في مشاريع dirctl","تأتمتIZATION المراجعة الشفرة للشفرة روست المحلية","توليد شفرة روست آمنة وفعالة باستخدام `thiserror` و `rustfmt`"]},"limitations":{"en":["Limited to Rust programming language","Requires adherence to specific coding standards","No support for `panic!` in library code"],"zh":["仅限于Rust编程语言","需要遵守特定的编码标准","不支持库代码中的`panic!`"],"ja":["Rustプログラミング言語のみに限定される","特定のコーディング規約に従う必要がある","ライブラリコードでは`panic!`はサポートされない"],"ko":["루스트 프로그래밍 언어만 해당","특정 코딩 표준을 준수해야 함","라이브러리 코드에서 `panic!`를 지원하지 않음"],"es":["Limitado al lenguaje de programación Rust","Requiere adherencia a estándares de codificación específicos","No hay soporte para `panic!` en código de biblioteca"],"fr":["Limité au langage de programmation Rust","Nécessite l''adhésion à des normes de codage spécifiques","Aucun support pour `panic!` dans le code de bibliothèque"],"de":["Begrenzt auf die Rust-Programmiersprache","Erfordert die Einhaltung spezifischer Codierungsstandards","Keine Unterstützung für `panic!` in Bibliothekscodes"],"pt":["Limitado à linguagem de programação Rust","Exige aderência a padrões de codificação específicos","Sem suporte para `panic!` em código de biblioteca"],"ru":["Ограничен языком программирования Rust","Требует соблюдения определенных стандартов кодирования","Нет поддержки `panic!` в библиотечном коде"],"ar":["محدود بلغة البرمجة روست","يتطلب الالتزام بمعايير الترميز الخاصة","لا يدعم `panic!` في شفرة المكتبة"]},"version":4},"contentHash":"beed634db1d9e91126cd165b4d1bb4a1b2f48415c798b145d7c826ab1ae3fd31","qualityScore":23}');
