INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DaniyalFaraz2003/dirctl/rust-standards', 'rust-standards', 'DaniyalFaraz2003', 'dirctl', 'community', 'rust-standards DaniyalFaraz2003 dirctl community The rust-standards skill provides explicit Rust best practices and automated guidance for generating idiomatic and safe Rust code. This skill benefits developers working with dirctl. Rust 标准设置指南，提供 dirctl 的最佳实践和自动化指导，确保生成的代码是惯用的和安全的 Rust Standards Setup Guide - dirctl のベストプラクティスと自動化ガイダンスを提供し、生成されたコードがイディオマティックで安全であることを保証する Rust 표준 설정 가이드 - dirctl의 최고의 관행과 자동화 가이드를 제공하여 생성된 코드가 관용적이고 안전한지 보장합니다 Rust Standards proporciona orientación explícita para generar código Rust idiomático y seguro, utilizando herramientas como estaerror y rustfmt Rust Standards fournit des conseils explicites pour générer du code Rust idiomatique et sécurisé, en utilisant des outils tels que cetteerror et rustfmt Rust Standards bietet explizite Anleitung für die Erstellung von idiomatischem und sicherem Rust-Code, unter Verwendung von Tools wie dieser Fehler und rustfmt O skill de padrões de Rust fornece orientação explícita para desenvolver código Rust idiomático e seguro Навык стандартов Rust обеспечивает явное руководство для разработки идиоматического и безопасного кода на Rust توفير مهارة معايير الرست إرشادات明确 لتطوير رمز الرست المتوافق والأمن how to use rust-standards rust-standards setup guide rust-standards vs rustfmt rust-standards install what is rust-standards rust-standards alternative rust-standards best practices rust-standards safety features rust-standards and dirctl Rust 标准 dirctl Rust 最佳实践 Rust 代码安全 thiserror rustfmt explicit ordering AIエージェント Rust 开发 代码质量 Enforces no unwrap or expect in core crates, only allowing them in tests Utilizes thiserror for crate-local error types and maps external errors at boundaries Prevents panic in library code for safer execution Ensures explicit ordering for iteration affecting semantics, such as sorting keys Integrates rustfmt for consistent code formatting rust-standards is a skill that enforces Rust best practices, such as using thiserror for error types and avoiding unwrap and expect in core crates.');
