INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('siriushex/hba1c/nightscout-platform-entrypoint', 'nightscout-platform-entrypoint', 'siriushex', 'hba1c', 'community', 'nightscout-platform-entrypoint siriushex hba1c community The nightscout-platform-entrypoint skill serves as the main entry point for Nightscout development tasks, providing a foundation for API navigation, job management, and data security. It benefits developers working with Nightscout platforms. Nightscout平台入口点是开发者的入口，提供API导航和任务开发 NightscoutプラットフォームENTRYPOINTは開発者のための入口で、APIナビゲーションとタスク開発を提供する Nightscout 플랫폼 엔트리포인트는 개발자를 위한入口으로 API 탐색 및 작업 개발을 제공합니다 El punto de entrada de Nightscout Platform es el punto de partida para desarrollar aplicaciones con tecnologías como API Map y Nightscout Runtime. Le point d''entrée de Nightscout Platform est le point de départ pour développer des applications avec des technologies comme API Map et Nightscout Runtime. Der Einstiegspunkt von Nightscout Platform ist der Ausgangspunkt für die Entwicklung von Anwendungen mit Technologien wie API Map und Nightscout Runtime. O Nightscout Platform Entrypoint é um ponto de entrada para desenvolvedores, fornecendo acesso à API Map, Nightscout Runtime e Autenticação de Telegram ИИ Агент Nightscout Platform —EntryPoint является точкой входа для разработчиков, предоставляющей доступ к API Map, Nightscout Runtime и аутентификации Telegram نقطة الدخول إلى منصة Nightscout هي نقطة دخول للمطورين، توفر إمكانية الوصول إلى API Map و Nightscout Runtime وتحقق Telegram how to use nightscout-platform-entrypoint nightscout-platform-entrypoint setup guide nightscout-platform-entrypoint vs nightscout-runtime nightscout-platform-entrypoint install what is nightscout-platform-entrypoint nightscout-platform-entrypoint alternative nightscout-platform-entrypoint api navigation nightscout-platform-entrypoint data security Nightscout平台 AIエージェント API导航 开发任务 Nightscout-runtime auth-telegram-mobile Prisma 数据安全存储 Utilizes the nightscout-platform skill for invariant and rule management Leverages the api-map skill for API endpoint navigation Integrates with nightscout-runtime for job management tasks Supports Telegram, Mini App, and Mobile development through auth-telegram-mobile Ensures data security and storage through Prisma and data-security-storage nightscout-platform-entrypoint is a foundational skill for Nightscout development, outlining essential tasks and tools for working with the platform.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('seeker71/Coherence-Network/spec-driven', 'community', 'seeker71', 'Coherence-Network', 'seeker71/Coherence-Network', 'spec-driven', 0, 0, 23, '2026-03-03T07:29:05Z', '2026-03-07T04:10:19.177Z', '79d30d636c6e26f5c8d6a12cb64f4dfceb5fcb8d1ca790d584c44942ec8c98dc', '{"id":"seeker71/Coherence-Network/spec-driven","name":"spec-driven","description":{"en":"The spec-driven skill enables developers to implement specifications accurately, modifying only listed files and without changing tests. It benefits developers who need to follow strict implementation guidelines.","zh":"Spec-Driven开发是一种按照规范实现的开发方法，确保代码质量和效率","ja":"Spec-Driven開発は、AIエージェントの仕様に従った実装方法で、コードの品質と効率を向上させる","ko":"Spec-Driven 구현은 사양에 따른 개발 방법으로 코드 품질과 효율을 높입니다","es":"Spec-driven es una metodología que se centra en implementar solo lo que dice la especificación, sin características adicionales ni refactorizaciones","fr":"Spec-driven est une méthodologie qui se concentre sur la mise en œuvre de ce que dit la spécification, sans fonctionnalités supplémentaires ni refactorisations","de":"Spec-driven ist eine Methodik, die sich auf die Implementierung dessen konzentriert, was die Spezifikation sagt, ohne zusätzliche Funktionen oder Refactorings","pt":"O desenvolvimento dirigido por especificações é uma abordagem que visa implementar apenas o que está especificado, sem recursos adicionais ou refatoração","ru":"Разработка на основе спецификаций - это подход, который заключается в реализации только того, что указано в спецификации, без дополнительных функций или рефакторинга","ar":"التوجيه بالمواصفات هو نهج يهدف إلى تنفيذ ما هو محدد فقط، دون ميزات إضافية أو إعادة هيكلة"},"seo":{"title":{"en":"Spec-Driven: Implementation Setup Guide | AI Agent Skill","zh":"Spec-Driven实现指南 - 按规范开发","ja":"Spec-Driven開発ガイド - AIエージェントの仕様に従った実装","ko":"Spec-Driven 구현 방법 - 사양에 따른 개발","es":"Guía de Implementación Spec-Driven para Desarrolladores","fr":"Guide d''Implémentation Spec-Driven pour les Développeurs","de":"Spec-Driven Implementierungsleitfaden für Entwickler","pt":"Guia de Configuração do Desenvolvimento Dirigido por Espe...","ru":"Настройка ИИ Агента: Руководство по разработке на основе ...","ar":"دليل إعداد العميل الذكي: تنفيذ مدفوع بالمواصفات"},"description":{"en":"Discover how to implement specs with precision. Learn the spec-driven approach and start building with confidence. Get started now!","zh":"了解Spec-Driven开发，按照规范实现，提高代码质量和效率","ja":"Spec-Driven開発のベストプラクティスを学び、AIエージェントの仕様に従った実装を実現","ko":"Spec-Driven 구현을 위한 가이드를 확인하고 사양에 따른 개발을 효율적으로 진행","es":"Aprende a implementar spec-driven de manera efectiva con nuestra guía paso a paso para desarrolladores de AI Agentes","fr":"Découvrez comment implémenter spec-driven de manière efficace avec notre guide étape par étape pour les développeurs d''outils d''IA","de":"Erfahren Sie, wie Sie spec-driven effektiv implementieren können, mit unserer Schritt-für-Schritt-Anleitung für Entwickler von KI-Tools","pt":"Aprenda a implementar o desenvolvimento dirigido por especificações com nosso guia passo a passo, otimizando seu fluxo de trabalho de desenvolvimento de soft...","ru":"Исследуйте наш подход к разработке на основе спецификаций для ИИ Агентов, чтобы улучшить свой процесс разработки программного обеспечения","ar":"اكتشف كيف يمكنك تحسين عملية تطوير البرمجيات الخاصة بك من خلال تطبيق مبدأ التوجيه بالمواصفات لعميلك الذكي"},"definition":{"en":"spec-driven is a development approach that involves reading and implementing specifications precisely, without adding extra features or refactoring adjacent code.","zh":"Spec-Driven是指按照预定义的规范实现开发的方法","ja":"Spec-Drivenは、事前に定義された仕様に従って開発を実現する方法","ko":"Spec-Driven은 사전에 정의된 사양에 따라 개발을 구현하는 방법","es":"Spec-driven es una aproximación a la implementación de software que se centra en seguir estrictamente la especificación","fr":"Spec-driven est une approche de mise en œuvre de logiciels qui se concentre sur le respect strict de la spécification","de":"Spec-driven ist ein Ansatz zur Softwareimplementierung, der sich auf die strikte Einhaltung der Spezifikation konzentriert","pt":"Desenvolvimento dirigido por especificações é uma técnica de desenvolvimento de software que segue estritamente as especificações fornecidas","ru":"Разработка на основе спецификаций - это техника разработки программного обеспечения, которая严格 следует предоставленным спецификациям","ar":"التوجيه بالمواصفات هو تقنية في تطوير البرمجيات تتبع بدقة المواصفات المحددة"},"features":{"en":["Implements specifications according to the ''Files to Create/Modify'' section","Modifies only listed files, as referenced in the spec","Does not change tests, focusing on fixing implementation instead","Follows a strict ''read the spec'' and ''implement only what it says'' approach","Supports adherence to constraints, such as not adding docs or READMEs unless required","Enforces a disciplined development workflow, reducing unnecessary changes"],"zh":["按规范实现开发","只修改指定文件","不改变测试代码","提高代码质量和效率","减少错误和 BUG"],"ja":["AIエージェントの仕様に従った実装","指定されたファイルのみを変更","テストコードを変更しない","コードの品質と効率を向上","エラーとバグを減らす"],"ko":["사양에 따른 개발 구현","지정된 파일만 수정","테스트 코드를 변경하지 않음","코드 품질과 효율을 높임","오류와 버그를 줄임"],"es":["Implementación estricta de la especificación","Modificación solo de archivos listados en la especificación","No se permiten refactorizaciones no solicitadas","No se permiten cambios en las pruebas","Enfoque en la implementación de características específicas"],"fr":["Mise en œuvre stricte de la spécification","Modification uniquement des fichiers répertoriés dans la spécification","Refactorisations non demandées non autorisées","Changements dans les tests non autorisés","Focalisation sur la mise en œuvre de fonctionnalités spécifiques"],"de":["Strenges Befolgen der Spezifikation","Änderung nur von Dateien, die in der Spezifikation aufgeführt sind","Nicht angeforderte Refactorings nicht erlaubt","Änderungen an den Tests nicht erlaubt","Fokus auf die Implementierung spezifischer Funktionen"],"pt":["Leitura da especificação antes da implementação","Implementação apenas do que está especificado","Modificação apenas dos arquivos listados","Manutenção dos testes intactos","Seguimento estrito das especificações"],"ru":["Чтение спецификации перед реализацией","Реализация только того, что указано в спецификации","Модификация только перечисленных файлов","Сохранение тестов без изменений","С严格ым соблюдением спецификаций"],"ar":["قراءة المواصفات قبل التنفيذ","تنفيذ ما هو محدد فقط","تعديل الملفات المحددة فقط","الحفاظ على الاختبارات بدون تغيير","الالتزام الصارم بالمواصفات"]},"keywords":{"en":["how to use spec-driven","spec-driven implementation guide","what is spec-driven development","spec-driven vs agile","spec-driven setup guide","spec-driven install for AI agents","spec-driven alternative approaches","spec-driven best practices for developers"],"zh":["Spec-Driven开发","按规范实现","代码质量","效率提高","减少错误","开发方法","AI工具","开发指南"],"ja":["Spec-Driven開発","AIエージェント","仕様に従った実装","コード品質","効率向上","エラー削減","開発方法","AIツール","開発ガイド"],"ko":["Spec-Driven 구현","사양에 따른 개발","코드 품질","효율 향상","오류 줄이기","개발 방법","AI 에이전트","개발 가이드"],"es":["spec-driven","implementación de software","desarrollo de AI Agentes","guía de implementación","mejores prácticas de desarrollo","Herramientas de IA","desarrollo de herramientas de IA"],"fr":["spec-driven","mise en œuvre de logiciels","développement d''outils d''IA","guide de mise en œuvre","meilleures pratiques de développement","Outils d''IA","développement d''outils d''IA"],"de":["spec-driven","Softwareimplementierung","Entwicklung von KI-Tools","Implementierungsleitfaden","Best Practices für die Entwicklung","KI-Tools","Entwicklung von KI-Tools"],"pt":["desenvolvimento dirigido por especificações","implementação de software","especificações de desenvolvimento","guias de configuração","ferramentas de desenvolvimento","práticas de desenvolvimento de software","desenvolvimento de software ágil","melhorias de processo de desenvolvimento"],"ru":["разработка на основе спецификаций","реализация программного обеспечения","спецификации разработки","руководства по настройке","инструменты разработки","практики разработки программного обеспечения","гибкая разработка программного обеспечения","улучшение процесса разработки"],"ar":["تطوير مدفوع بالمواصفات","تنفيذ البرمجيات","مواصفات التطوير","دليل الإعداد","أدوات التطوير","ممارسات تطوير البرمجيات","تطوير البرمجيات المُتأصل","تحسين عملية التطوير"]}},"owner":"seeker71","repo":"Coherence-Network","repoPath":"seeker71/Coherence-Network","stars":0,"forks":0,"updatedAt":"2026-03-03T07:29:05Z","topics":[],"category":"community","skillMd":{"name":"spec-driven","description":"Implements features strictly from specs. Reads specs first, modifies only listed files, no scope creep. Use when implementing a feature, working with specs/, or when the user references a spec number.","bodyPreview":"# Spec-Driven Implementation\n\n## Quick Start\n\n1. **Read the spec** — `specs/NNN-feature-name.md` or the spec referenced in the task\n2. **Implement only what it says** — no extra features, no adjacent refactors\n3. **Modify only listed files** — see \"Files to Create/Modify\" in the spec\n4. **Do not change tests** — fix implementation, not tests\n\n## Constraints\n\n- Only modify files listed in the spec''s \"Files to Create/Modify\" section\n- Do not add docs, READMEs, or refactors unless the spec requires","body":"# Spec-Driven Implementation\n\n## Quick Start\n\n1. **Read the spec** — `specs/NNN-feature-name.md` or the spec referenced in the task\n2. **Implement only what it says** — no extra features, no adjacent refactors\n3. **Modify only listed files** — see \"Files to Create/Modify\" in the spec\n4. **Do not change tests** — fix implementation, not tests\n\n## Constraints\n\n- Only modify files listed in the spec''s \"Files to Create/Modify\" section\n- Do not add docs, READMEs, or refactors unless the spec requires them\n- Only escalate with `needs_decision` when truly stuck after research; prefer fixing in-scope\n- Follow API Contract and Data Model from the spec exactly\n\n## Spec Format Reference\n\nSpecs follow `specs/TEMPLATE.md`:\n- Purpose, Requirements, API Contract, Data Model\n- Files to Create/Modify (the allowed set)\n- Acceptance Tests, Out of Scope, Decision Gates\n\n## When Tests Fail\n\nFix the implementation. Do NOT modify tests to make them pass.\n"},"lastSynced":"2026-03-07T04:10:19.177Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring precise implementation of specifications, adhering to strict guidelines and modifying only listed files.","zh":"适合需要精确实现规格、遵守严格指南且仅修改列出的文件的开发代理。","ja":"開発エージェントが仕様を正確に実装し、厳格なガイドラインに従い、リストされたファイルのみを変更する必要がある場合に最適です。","ko":"개발 에이전트가 사양을 정확하게 구현하고 엄격한 지침을 준수하며 목록에 있는 파일만 수정해야 하는 경우 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren una implementación precisa de las especificaciones, que se adhieren a directrices estrictas y que solo modifican los archivos enumerados.","fr":"Idéal pour les Agents de Développement nécessitant une mise en œuvre précise des spécifications, qui respectent des directives strictes et qui ne modifient que les fichiers répertoriés.","de":"Ideal für Entwicklungssagenten, die eine präzise Implementierung von Spezifikationen erfordern, die sich an strenge Richtlinien halten und nur die aufgeführten Dateien ändern.","pt":"Ideal para Agentes de Desenvolvimento que requerem implementação precisa de especificações, seguindo diretrizes estritas e modificando apenas arquivos listados.","ru":"Идеально для агентов разработки, требующих точной реализации спецификаций, соблюдения строгих руководств и изменения только перечисленных файлов.","ar":"مثالي للوكلاء النموزجيون الذين يتطلبون تنفيذًا دقيقًا للمواصفات، والامتثال للمعايير الصارمة وتعديل الملفات المحددة فقط."},"recommendation":{"en":"Empowers agents to accurately implement specifications by following strict guidelines, modifying only listed files, and preserving existing tests, ensuring compliance with protocols like MD file references and task specifications.","zh":"赋予代理准确实现规格的能力，通过遵循严格的指南，仅修改列出的文件，并保留现有的测试，从而确保遵守MD文件引用和任务规格等协议。","ja":"厳格なガイドラインに従い、リストされたファイルのみを変更し、既存のテストを保留することで、エージェントが仕様を正確に実装できるようにします。MDファイル参照やタスク仕様などのプロトコルに準拠することを保証します。","ko":"엄격한 지침을 준수하고 목록에 있는 파일만 수정하며 기존 테스트를 보존하여 에이전트가 사양을 정확하게 구현할 수 있도록 합니다. MD 파일 참조 또는 작업 사양과 같은 프로토콜을 준수하는 것을 보장합니다.","es":"Habilita a los agentes a implementar las especificaciones de forma precisa siguiendo directrices estrictas, modificando solo los archivos enumerados y preservando las pruebas existentes, garantizando el cumplimiento de protocolos como referencias de archivos MD y especificaciones de tareas.","fr":"Permet aux agents de mettre en œuvre les spécifications avec précision en suivant des directives strictes, en modifiant uniquement les fichiers répertoriés et en préservant les tests existants, garantissant ainsi la conformité aux protocoles tels que les références de fichiers MD et les spécifications de tâches.","de":"Ermächtigt die Agenten, Spezifikationen genau umzusetzen, indem sie strenge Richtlinien befolgen, nur die aufgeführten Dateien ändern und bestehende Tests erhalten, und stellt so die Einhaltung von Protokollen wie MD-Dateireferenzen und Aufgabenbereitstellungen sicher.","pt":"Habilita os agentes a implementar especificações com precisão, seguindo diretrizes estritas, modificando apenas arquivos listados e preservando testes existentes, garantindo conformidade com protocolos como referências de arquivos MD e especificações de tarefas.","ru":"Наделяет агентов возможностью точно реализовать спецификации, следуя строгим руководствам, изменяя только перечисленные файлы и сохраняя существующие тесты, обеспечивая соблюдение протоколов, таких как ссылки на файлы MD и задания.","ar":"يمكن الوكلاء من تنفيذ المواصفات بدقة من خلال اتباع الإرشادات الصارمة وتعديل الملفات المحددة فقط والحفاظ على الاختبارات الموجودة، مما يضمن الامتثال لبروتوكولات مثل مراجع ملفات MD ومواصفات المهام."},"useCases":{"en":["Implementing feature updates according to spec","Modifying listed files without altering tests","Adhering to strict implementation guidelines for development projects"],"zh":["根据规格实现功能更新","修改列出的文件而不改变测试","遵守开发项目的严格实现指南"],"ja":["仕様に従った機能の更新の実装","テストを変更せずにリストされたファイルを変更","開発プロジェクトの厳格な実装ガイドラインに従う"],"ko":["사양에 따라 기능 업데이트 구현","테스트를 변경하지 않고 목록에 있는 파일을 수정","개발 프로젝트에 대한 엄격한 구현 지침을 따름"],"es":["Implementar actualizaciones de características según la especificación","Modificar archivos enumerados sin alterar las pruebas","Cumplir con directrices estrictas de implementación para proyectos de desarrollo"],"fr":["Mettre en œuvre des mises à jour de fonctionnalités selon la spécification","Modifier les fichiers répertoriés sans modifier les tests","Respecter des directives strictes de mise en œuvre pour les projets de développement"],"de":["Implementierung von Funktionsupdates gemäß Spezifikation","Ändern der aufgeführten Dateien ohne Änderung der Tests","Befolgen strenger Implementierungsrichtlinien für Entwicklungsvorhaben"],"pt":["Implementação de atualizações de recursos de acordo com a especificação","Modificação de arquivos listados sem alterar testes","Adesão a diretrizes estritas de implementação para projetos de desenvolvimento"],"ru":["Реализация обновлений функций в соответствии со спецификацией","Изменение перечисленных файлов без изменения тестов","Соблюдение строгих руководств по реализации для проектов разработки"],"ar":["تنفيذ تحديثات الميزات وفقًا للمواصفات","تعديل الملفات المحددة دون تعديل الاختبارات","الامتثال للإرشادات الصارمة للتطبيق لمشاريع التطوير"]},"limitations":{"en":["Requires access to spec files (e.g., specs/NNN-feature-name.md)","Limited to modifying files listed in the spec''s ''Files to Create/Modify'' section","No addition of docs, READMEs, or refactors unless specified"],"zh":["需要访问规格文件（例如 specs/NNN-feature-name.md）","仅限修改规格的''创建/修改文件''部分中列出的文件","除非指定，否则不允许添加文档、README或重构"],"ja":["仕様ファイル（例：specs/NNN-feature-name.md）へのアクセスが必要","仕様の「ファイルを作成/変更」セクションにリストされたファイルのみを変更","指定されていない限り、ドキュメント、README、またはリファクタリングの追加は許可されません"],"ko":["사양 파일(예: specs/NNN-feature-name.md) 액세스 필요","사양의 ''파일 생성/수정'' 섹션에 나열된 파일만 수정","지정된 경우를 제외하고 문서, README 또는 리팩토링 추가는 허용되지 않음"],"es":["Requiere acceso a archivos de especificación (por ejemplo, specs/NNN-nombre-característica.md)","Limitado a la modificación de archivos enumerados en la sección ''Archivos para crear/modificar'' de la especificación","No se permite la adición de documentación, archivos README ni refactorizaciones a menos que se especifique"],"fr":["Nécessite un accès aux fichiers de spécification (par exemple, specs/NNN-nom-fonctionnalité.md)","Limité à la modification des fichiers répertoriés dans la section ''Fichiers à créer/modifier'' de la spécification","L''ajout de documentation, de fichiers README ou de refactorisations n''est pas autorisé sauf si spécifié"],"de":["Erfordert Zugriff auf Spezifikationsdateien (z.B. specs/NNN-Funktionsname.md)","Begrenzt auf die Änderung von Dateien, die in der Sektion ''Dateien zum Erstellen/Ändern'' der Spezifikation aufgeführt sind","Hinzufügen von Dokumentation, README-Dateien oder Refactorings ist nicht erlaubt, es sei denn, es ist angegeben"],"pt":["Requer acesso a arquivos de especificação (por exemplo, specs/NNN-nome-da-funcionalidade.md)","Limitado à modificação de arquivos listados na seção ''Arquivos para Criar/Modificar'' da especificação","Nenhuma adição de docs, READMEs ou refactors, a menos que especificado"],"ru":["Требует доступа к файлам спецификации (например, specs/NNN-имя-функции.md)","Ограничен изменением файлов, перечисленных в разделе ''Файлы для создания/изменения'' спецификации","Нет добавления документов, README или рефакторинга, если не указано"],"ar":["يتطلب الوصول إلى ملفات المواصفات (على سبيل المثال، specs/NNN-اسم-الميزة.md)","محدود بالتعديل على الملفات المحددة في قسم ''ملفات الإنشاء/التعديل'' من المواصفات","لا إضافة مستندات أو READMEs أو إعادة هيكلة، إلا إذا تم تحديدها"]},"version":4},"contentHash":"79d30d636c6e26f5c8d6a12cb64f4dfceb5fcb8d1ca790d584c44942ec8c98dc","qualityScore":23}');
