INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('seeker71/Coherence-Network/spec-driven', 'spec-driven', 'seeker71', 'Coherence-Network', 'community', 'spec-driven seeker71 Coherence-Network community The spec-driven skill enables developers to implement specifications accurately, modifying only listed files and without changing tests. It benefits developers who need to follow strict implementation guidelines. Spec-Driven开发是一种按照规范实现的开发方法，确保代码质量和效率 Spec-Driven開発は、AIエージェントの仕様に従った実装方法で、コードの品質と効率を向上させる Spec-Driven 구현은 사양에 따른 개발 방법으로 코드 품질과 효율을 높입니다 Spec-driven es una metodología que se centra en implementar solo lo que dice la especificación, sin características adicionales ni refactorizaciones Spec-driven est une méthodologie qui se concentre sur la mise en œuvre de ce que dit la spécification, sans fonctionnalités supplémentaires ni refactorisations Spec-driven ist eine Methodik, die sich auf die Implementierung dessen konzentriert, was die Spezifikation sagt, ohne zusätzliche Funktionen oder Refactorings O desenvolvimento dirigido por especificações é uma abordagem que visa implementar apenas o que está especificado, sem recursos adicionais ou refatoração Разработка на основе спецификаций - это подход, который заключается в реализации только того, что указано в спецификации, без дополнительных функций или рефакторинга التوجيه بالمواصفات هو نهج يهدف إلى تنفيذ ما هو محدد فقط، دون ميزات إضافية أو إعادة هيكلة how to use spec-driven spec-driven implementation guide what is spec-driven development spec-driven vs agile spec-driven setup guide spec-driven install for AI agents spec-driven alternative approaches spec-driven best practices for developers Spec-Driven开发 按规范实现 代码质量 效率提高 减少错误 开发方法 AI工具 开发指南 Implements specifications according to the ''Files to Create/Modify'' section Modifies only listed files, as referenced in the spec Does not change tests, focusing on fixing implementation instead Follows a strict ''read the spec'' and ''implement only what it says'' approach Supports adherence to constraints, such as not adding docs or READMEs unless required Enforces a disciplined development workflow, reducing unnecessary changes spec-driven is a development approach that involves reading and implementing specifications precisely, without adding extra features or refactoring adjacent code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Texarkanine/ai-rizz/niko-plan', 'community', 'Texarkanine', 'ai-rizz', 'Texarkanine/ai-rizz', 'niko-plan', 0, 0, 23, '2026-02-22T00:20:19Z', '2026-03-07T04:10:29.778Z', '2d3987b0fa55ccdc3fcac00a47ab0d7b68fd6bc6f7d74b29aaf91d006becb180', '{"id":"Texarkanine/ai-rizz/niko-plan","name":"niko-plan","description":{"en":"niko-plan is a CLI tool for managing Cursor rules, benefiting developers by creating detailed implementation plans. It scales planning depth with complexity levels.","zh":"Niko-plan是一种CLI工具，用于管理Cursor规则，通过加载内存银行文件和确定复杂性级别来创建详细的实现计划","ja":"Niko-planは、Cursorルールを管理するためのCLIツールであり、メモリーバンクファイルの読み込みと複雑さレベルの決定を通じて詳細な実装計画を作成する","ko":"Niko-plan은 Cursor 규칙을 관리하기 위한 CLI 도구로, 메모리 뱅크 파일을 로드하고 복잡성 수준을 결정하여 자세한 구현 계획을 생성한다","es":"niko-plan es una herramienta de línea de comandos para gestionar reglas de cursor, que crea un plan de implementación detallado para la tarea actual","fr":"niko-plan est un outil CLI pour gérer les règles de curseur, qui crée un plan de mise en œuvre détaillé pour la tâche actuelle","de":"niko-plan ist ein CLI-Tool für die Verwaltung von Cursor-Regeln, das einen detaillierten Implementierungsplan für die aktuelle Aufgabe erstellt","pt":"O niko-plan é uma ferramenta CLI para gerenciar regras de cursor, permitindo a criação de planos de implementação detalhados para tarefas complexas","ru":"niko-plan - это инструмент командной строки для управления правилами курсора, позволяющий создавать подробные планы реализации для сложных задач","ar":"niko-plan هو أداة سطر الأوامر لإدارة قواعد المؤشر، مما يسمح بإنشاء خطط تنفيذ مفصلة للمهام المعقدة"},"seo":{"title":{"en":"niko-plan: Implementation Planning Setup Guide | AI Agent...","zh":"Niko-plan CLI工具设置指南 - AI智能代理","ja":"Niko-plan CLIツールのベストプラクティス - AIエージェント","ko":"Niko-plan CLI 도구 설정 가이드 - AI 에이전트","es":"Guía de configuración de niko-plan: Herramienta de línea ...","fr":"Guide d''installation de niko-plan : Outil CLI pour règles...","de":"Einrichtungsleitfaden für niko-plan: CLI-Tool für Cursor-...","pt":"Guia de Configuração do niko-plan: Ferramenta CLI para Re...","ru":"Настройка niko-plan: Инструмент командной строки для упра...","ar":"دليل الإعداد ل niko-plan: أداة سطر الأوامر لإدارة قواعد ا..."},"description":{"en":"Unlock efficient task management with niko-plan. Discover how to create detailed implementation plans and scale complexity levels. Get started now!","zh":"了解Niko-plan CLI工具的技术细节和设置方法，提高AI智能代理的管理效率","ja":"Niko-plan CLIツールの技術的な詳細と設定方法を学び、AIエージェントの管理効率を向上させる","ko":"Niko-plan CLI 도구의 기술적인 세부 사항과 설정 방법을 알아보고 AI 에이전트의 관리 효율성을 높여라","es":"Descubre cómo funciona niko-plan, una herramienta de línea de comandos para gestionar reglas de cursor, y aprende a configurarla para tus necesidades de desa...","fr":"Découvrez comment fonctionne niko-plan, un outil CLI pour gérer les règles de curseur, et apprenez à le configurer pour vos besoins de développement","de":"Erfahren Sie, wie niko-plan funktioniert, ein CLI-Tool für die Verwaltung von Cursor-Regeln, und lernen Sie, es für Ihre Entwicklungsbedürfnisse zu konfiguri...","pt":"Aprenda a configurar o niko-plan, uma ferramenta CLI para gerenciar regras de cursor, e otimize seu fluxo de trabalho de desenvolvimento","ru":"Узнайте, как настроить niko-plan, инструмент командной строки для управления правилами курсора, и оптимизируйте свой рабочий процесс разработки","ar":"تعرف على كيفية إعداد niko-plan، أداة سطر الأوامر لإدارة قواعد المؤشر، واضبط تدفق عملك التطويري"},"definition":{"en":"niko-plan is a command-line interface tool designed for managing Cursor rules, specifically for creating implementation plans based on task complexity.","zh":"Niko-plan是一种用于管理Cursor规则的CLI工具，通过技术规划实现高效的AI智能代理管理","ja":"Niko-planは、Cursorルールを管理するためのCLIツールであり、技術的な計画を通じて効率的なAIエージェントの管理を実現する","ko":"Niko-plan은 Cursor 규칙을 관리하기 위한 CLI 도구로, 기술적인 계획을 통해 효율적인 AI 에이전트의 관리를 실현한다","es":"niko-plan es una herramienta de línea de comandos que gestiona reglas de cursor para desarrolladores","fr":"niko-plan est un outil CLI qui gère les règles de curseur pour les développeurs","de":"niko-plan ist ein CLI-Tool, das Cursor-Regeln für Entwickler verwaltet","pt":"O que é niko-plan? É uma ferramenta CLI para gerenciar regras de cursor e criar planos de implementação","ru":"Что такое niko-plan? Это инструмент командной строки для управления правилами курсора и создания планов реализации","ar":"ما هو niko-plan؟ هو أداة سطر الأوامر لإدارة قواعد المؤشر وإنشاء خطط التنفيذ"},"features":{"en":["Creates detailed implementation plans for tasks based on complexity levels","Loads Memory Bank Files, including tasks.md and activeContext.md","Determines complexity levels from activeContext.md for scaled planning","Routes to level-specific planning documents for tailored implementation","Reads and writes to memory-bank files for persistent data management"],"zh":["加载内存银行文件（memory-bank/tasks.md和memory-bank/activeContext.md）","确定复杂性级别并创建详细的实现计划","支持CLI工具的技术规划和管理","高效的Cursor规则管理","简化的实现计划创建过程"],"ja":["メモリーバンクファイル（memory-bank/tasks.mdとmemory-bank/activeContext.md）の読み込み","複雑さレベルの決定と詳細な実装計画の作成","CLIツールの技術的な計画と管理のサポート","効率的なCursorルールの管理","実装計画の作成プロセスの簡素化"],"ko":["메모리 뱅크 파일（memory-bank/tasks.md와 memory-bank/activeContext.md）的 로드","복잡성 수준의 결정과 자세한 구현 계획의 생성","CLI 도구의 기술적인 계획과 관리의 지원","효율적인 Cursor 규칙의 관리","구현 계획의 생성 프로세스의 단순화"],"es":["Crea un plan de implementación detallado para la tarea actual","Lee archivos de memoria, como tasks.md y activeContext.md","Determina el nivel de complejidad de la tarea","Ruta a documentos de planificación específicos según el nivel de complejidad","Utiliza comandos de línea de comandos para gestionar reglas de cursor"],"fr":["Crée un plan de mise en œuvre détaillé pour la tâche actuelle","Lit des fichiers de mémoire, tels que tasks.md et activeContext.md","Détermine le niveau de complexité de la tâche","Route vers des documents de planification spécifiques en fonction du niveau de complexité","Utilise des commandes de ligne de commande pour gérer les règles de curseur"],"de":["Erstellt einen detaillierten Implementierungsplan für die aktuelle Aufgabe","Liest Speicherdateien, wie tasks.md und activeContext.md","Bestimmt das Komplexitätsniveau der Aufgabe","Leitet an spezifische Planungsdokumente gemäß dem Komplexitätsniveau weiter","Verwendet Befehlszeilenbefehle zur Verwaltung von Cursor-Regeln"],"pt":["Criação de planos de implementação detalhados para tarefas complexas","Leitura de arquivos de memória para determinar o nível de complexidade","Suporte à escalabilidade de planos de implementação com base no nível de complexidade","Integração com arquivos de contexto ativo para determinar o nível de complexidade","Utilização de comandos CLI para gerenciar regras de cursor","Suporte à leitura de arquivos de tarefas e contexto ativo"],"ru":["Создание подробных планов реализации для сложных задач","Чтение файлов памяти для определения уровня сложности","Поддержка масштабируемости планов реализации на основе уровня сложности","Интеграция с файлами активного контекста для определения уровня сложности","Использование команд CLI для управления правилами курсора","Поддержка чтения файлов задач и активного контекста"],"ar":["إنشاء خطط تنفيذ مفصلة للمهام المعقدة","قراءة ملفات الذاكرة لتحديد مستوى التعقيد","دعم قابلية التوسع لخطط التنفيذ بالاعتماد على مستوى التعقيد","دمج ملفات السياق النشط لتحديد مستوى التعقيد","استخدام أوامر سطر الأوامر لإدارة قواعد المؤشر","دعم قراءة ملفات المهام والسياق النشط"]},"keywords":{"en":["how to use niko-plan","niko-plan setup guide","niko-plan alternative","niko-plan vs cursor tools","niko-plan install","what is niko-plan","niko-plan implementation planning","niko-plan complexity level management","niko-plan CLI tool"],"zh":["Niko-plan","AI智能代理","CLI工具","Cursor规则管理","技术规划","内存银行文件","复杂性级别","实现计划","AI开发工具"],"ja":["Niko-plan","AIエージェント","CLIツール","Cursorルールの管理","技術的な計画","メモリーバンクファイル","複雑さレベル","実装計画","AI開発ツール"],"ko":["Niko-plan","AI 에이전트","CLI 도구","Cursor 규칙 관리","기술적인 계획","메모리 뱅크 파일","복잡성 수준","구현 계획","AI 개발 도구"],"es":["niko-plan","herramienta de línea de comandos","reglas de cursor","desarrollo de software","gestión de reglas","planificación de implementación","CLI","herramientas de desarrollo","agentes de IA","herramientas de línea de comandos para desarrolladores"],"fr":["niko-plan","outil de ligne de commande","règles de curseur","développement de logiciels","gestion de règles","planification de mise en œuvre","CLI","outils de développement","agents d''IA","outils de ligne de commande pour les développeurs"],"de":["niko-plan","CLI-Tool","Cursor-Regeln","Software-Entwicklung","Regel-Verwaltung","Implementierungsplanung","Befehlszeilenbefehle","Entwicklertools","KI-Agents","Befehlszeilen-Tools für Entwickler"],"pt":["niko-plan","ferramenta CLI","regras de cursor","gerenciamento de regras","plano de implementação","desenvolvimento de software","ferramentas de desenvolvimento","CLI para desenvolvedores","gerenciamento de tarefas","otimização de fluxo de trabalho"],"ru":["niko-plan","инструмент командной строки","правила курсора","управление правилами","план реализации","разработка программного обеспечения","инструменты разработки","CLI для разработчиков","управление задачами","оптимизация рабочего процесса"],"ar":["niko-plan","أداة سطر الأوامر","قواعد المؤشر","إدارة القواعد","خطة التنفيذ","تطوير البرمجيات","أدوات التطوير","سطر الأوامر للمطورين","إدارة المهام","تحسين تدفق العمل"]}},"owner":"Texarkanine","repo":"ai-rizz","repoPath":"Texarkanine/ai-rizz","stars":0,"forks":0,"updatedAt":"2026-02-22T00:20:19Z","topics":["ai","cursor","developer-tools"],"category":"community","skillMd":{"name":"niko-plan","description":"Niko Memory Bank System - Plan Phase - Implementation Planning","bodyPreview":"# Plan Phase - Implementation Planning\n\nThis command creates a detailed implementation plan for the current task. Planning depth scales with complexity level — this file routes to the appropriate level-specific planning document.\n\n## Step 1: Load Memory Bank Files\n\nRead:\n- `memory-bank/tasks.md`\n- `memory-bank/activeContext.md`\n\n## Step 2: Determine Complexity Level\n\nRead the complexity level from `memory-bank/activeContext.md`\n\nIf no complexity level is set, or `memory-bank/activeContext.md` do","body":"# Plan Phase - Implementation Planning\n\nThis command creates a detailed implementation plan for the current task. Planning depth scales with complexity level — this file routes to the appropriate level-specific planning document.\n\n## Step 1: Load Memory Bank Files\n\nRead:\n- `memory-bank/tasks.md`\n- `memory-bank/activeContext.md`\n\n## Step 2: Determine Complexity Level\n\nRead the complexity level from `memory-bank/activeContext.md`\n\nIf no complexity level is set, or `memory-bank/activeContext.md` does not exist: STOP PLANNING! Invoke the `niko` skill to initialize the memory bank and perform complexity analysis, then proceed as instructed there.\n\n## Step 3: Route to Level-Specific Planning\n\nLoad the appropriate complexity level-specific Niko workflow file, then use its phase mappings to proceed to the Plan phase.\n"},"lastSynced":"2026-03-07T04:10:29.778Z","agentAnalysis":{"suitability":{"en":"Ideal for CLI-based AI Agents like Cursor, needing advanced implementation planning capabilities for managing complex tasks.","zh":"适用于像Cursor这样的基于CLI的AI代理，需要高级的实现规划能力来管理复杂任务。","ja":"CursorのようなCLIベースのAIエージェントに適しています。複雑なタスクを管理するための高度な実装計画能力が必要です。","ko":"Cursor와 같은 CLI 기반 AI 에이전트에 적합합니다. 복잡한 작업을 관리하기 위한 고급 구현 계획 기능이 필요합니다.","es":"Ideal para agentes de IA basados en CLI como Cursor, que necesitan capacidades de planificación de implementación avanzadas para gestionar tareas complejas.","fr":"Idéal pour les agents d''IA basés sur CLI comme Cursor, nécessitant des capacités de planification d''implémentation avancées pour gérer des tâches complexes.","de":"Ideal für CLI-basierte KI-Agents wie Cursor, die erweiterte Implementierungsplanungsfähigkeiten für die Verwaltung komplexer Aufgaben benötigen.","pt":"Ideal para agentes de IA baseados em CLI, como Cursor, que necessitam de capacidades de planejamento de implementação avançadas para gerenciar tarefas complexas.","ru":"Идеально подходит для агентов ИИ на основе CLI, таких как Cursor, которым необходимы продвинутые возможности планирования реализации для управления сложными задачами.","ar":"مثالي لعميل الوكيل الذكي القائم على واجهة سطر الأوامر مثل Cursor، والذي يحتاج إلى إمكانيات تخطيط متقدمة لتنفيذ إدارة المهام المعقدة."},"recommendation":{"en":"Empowers agents to create detailed implementation plans by scaling planning depth with complexity levels, utilizing memory bank files such as `tasks.md` and `activeContext.md`, and determining complexity levels for tailored planning.","zh":"通过扩展规划深度以匹配复杂性水平，利用任务.md和activeContext.md等内存银行文件，并确定复杂性水平以实现个性化规划，从而使代理能够创建详细的实现计划。","ja":"複雑性レベルに合わせて計画の深度を拡張し、tasks.mdやactiveContext.mdなどのメモリーバンクファイルを利用し、複雑性レベルを決定してカスタマイズされた計画を行うことで、エージェントが詳細な実装計画を作成できるようにします。","ko":"복잡성 수준에 따라 계획의 깊이를 확장하고, tasks.md 및 activeContext.md와 같은 메모리 은행 파일을 활용하고, 복잡성 수준을 결정하여 맞춤형 계획을 수행함으로써 에이전트가詳細한 구현 계획을 생성할 수 있도록합니다.","es":"Permite a los agentes crear planes de implementación detallados al escalar la profundidad de planificación con los niveles de complejidad, utilizando archivos de banco de memoria como `tasks.md` y `activeContext.md`, y determinando los niveles de complejidad para una planificación personalizada.","fr":"Permet aux agents de créer des plans d''implémentation détaillés en faisant évoluer la profondeur de planification avec les niveaux de complexité, en utilisant des fichiers de banque de mémoire tels que `tasks.md` et `activeContext.md`, et en déterminant les niveles de complexité pour une planification sur mesure.","de":"Ermöglicht es Agents, detaillierte Implementierungspläne zu erstellen, indem die Planungstiefe mit den Komplexitätsstufen skaliert wird, unter Verwendung von Speicherbankdateien wie `tasks.md` und `activeContext.md`, und die Komplexitätsstufen für eine maßgeschneiderte Planung bestimmt werden.","pt":"Permite que os agentes criem planos de implementação detalhados, escalonando a profundidade do planejamento com os níveis de complexidade, utilizando arquivos de banco de memória como `tasks.md` e `activeContext.md` e determinando níveis de complexidade para planejamento personalizado.","ru":"Позволяет агентам создавать подробные планы реализации, масштабируя глубину планирования с уровнями сложности, используя файлы банка памяти, такие как `tasks.md` и `activeContext.md`, и определяя уровни сложности для индивидуального планирования.","ar":"يمكن للعميل إنشاء خطط تنفيذ مفصلة من خلال تحجيم عمق التخطيط مع مستويات التعقيد، واستخدام ملفات بنك الذاكرة مثل `tasks.md` و `activeContext.md` وتحديد مستويات التعقيد للتنظيم المخصص."},"useCases":{"en":["Automating task planning for Cursor rules","Generating implementation plans based on complexity levels","Debugging task implementation by analyzing memory bank files"],"zh":["为Cursor规则自动化任务规划","根据复杂性水平生成实现计划","通过分析内存银行文件来调试任务实现"],"ja":["Cursorルールのためのタスク計画の自動化","複雑性レベルに基づいた実装計画の生成","メモリーバンクファイルの分析によるタスク実装のデバッグ"],"ko":["Cursor 규칙을 위한 작업 계획 자동화","복잡성 수준에 따른 구현 계획 생성","메모리 은행 파일 분석을 통한 작업 구현 디버깅"],"es":["Automatización de la planificación de tareas para reglas de Cursor","Generación de planes de implementación basados en niveles de complejidad","Depuración de la implementación de tareas mediante el análisis de archivos de banco de memoria"],"fr":["Automatisation de la planification de tâches pour les règles de Cursor","Génération de plans d''implémentation basés sur les niveaux de complexité","Débogage de l''implémentation de tâches en analysant les fichiers de banque de mémoire"],"de":["Automatisierung der Aufgabenplanung für Cursor-Regeln","Erstellung von Implementierungsplänen basierend auf Komplexitätsstufen","Fehlersuche bei der Aufgabenimplementierung durch Analyse von Speicherbankdateien"],"pt":["Automatizar o planejamento de tarefas para regras do Cursor","Gerar planos de implementação com base em níveis de complexidade","Depurar a implementação da tarefa analisando arquivos de banco de memória"],"ru":["Автоматизировать планирование задач для правил Cursor","Генерировать планы реализации на основе уровней сложности","Отлаживать реализацию задачи, анализируя файлы банка памяти"],"ar":["أتمتة تخطيط المهام لقواعد Cursor","توليد خطط التنفيذ على أساس مستويات التعقيد","تصحيح تنفيذ المهمة من خلال تحليل ملفات بنك الذاكرة"]},"limitations":{"en":["Requires access to memory bank files (`tasks.md` and `activeContext.md`)","Limited to CLI-based interactions","Dependent on complexity level settings in `activeContext.md`"],"zh":["需要访问内存银行文件（tasks.md和activeContext.md）","仅限CLI-based交互","依赖于activeContext.md中的复杂性级别设置"],"ja":["メモリーバンクファイル（tasks.mdおよびactiveContext.md）へのアクセスが必要","CLIベースの相互作用のみ","activeContext.md内の複雑性レベル設定に依存する"],"ko":["메모리 은행 파일(tasks.md 및 activeContext.md) 액세스 필요","CLI 기반 상호 작용만","activeContext.md 내의 복잡성 수준 설정에 의존"],"es":["Requiere acceso a archivos de banco de memoria (`tasks.md` y `activeContext.md`)","Limitado a interacciones basadas en CLI","Dependiente de la configuración de niveles de complejidad en `activeContext.md`"],"fr":["Nécessite un accès aux fichiers de banque de mémoire (`tasks.md` et `activeContext.md`)","Limité aux interactions basées sur CLI","Dépendant des paramètres de niveau de complexité dans `activeContext.md`"],"de":["Erfordert Zugriff auf Speicherbankdateien (`tasks.md` und `activeContext.md`)","Begrenzt auf CLI-basierte Interaktionen","Abhängig von den Komplexitätsstufeneinstellungen in `activeContext.md`"],"pt":["Requer acesso a arquivos de banco de memória (`tasks.md` e `activeContext.md`)","Limitado a interações baseadas em CLI","Dependente das configurações de nível de complexidade em `activeContext.md`"],"ru":["Требует доступа к файлам банка памяти (`tasks.md` и `activeContext.md`)","Ограничен взаимодействиями на основе CLI","Зависит от настроек уровня сложности в `activeContext.md`"],"ar":["يتطلب الوصول إلى ملفات بنك الذاكرة (`tasks.md` و `activeContext.md`)","محدود بالتفاعلات القائمة على واجهة سطر الأوامر","يعتمد على إعدادات مستوى التعقيد في `activeContext.md`"]},"version":4},"contentHash":"2d3987b0fa55ccdc3fcac00a47ab0d7b68fd6bc6f7d74b29aaf91d006becb180","qualityScore":23}');
