INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Texarkanine/ai-rizz/niko-plan', 'niko-plan', 'Texarkanine', 'ai-rizz', 'community', 'niko-plan Texarkanine ai-rizz community ai cursor developer-tools niko-plan is a CLI tool for managing Cursor rules, benefiting developers by creating detailed implementation plans. It scales planning depth with complexity levels. Niko-plan是一种CLI工具，用于管理Cursor规则，通过加载内存银行文件和确定复杂性级别来创建详细的实现计划 Niko-planは、Cursorルールを管理するためのCLIツールであり、メモリーバンクファイルの読み込みと複雑さレベルの決定を通じて詳細な実装計画を作成する Niko-plan은 Cursor 규칙을 관리하기 위한 CLI 도구로, 메모리 뱅크 파일을 로드하고 복잡성 수준을 결정하여 자세한 구현 계획을 생성한다 niko-plan es una herramienta de línea de comandos para gestionar reglas de cursor, que crea un plan de implementación detallado para la tarea actual niko-plan est un outil CLI pour gérer les règles de curseur, qui crée un plan de mise en œuvre détaillé pour la tâche actuelle niko-plan ist ein CLI-Tool für die Verwaltung von Cursor-Regeln, das einen detaillierten Implementierungsplan für die aktuelle Aufgabe erstellt O niko-plan é uma ferramenta CLI para gerenciar regras de cursor, permitindo a criação de planos de implementação detalhados para tarefas complexas niko-plan - это инструмент командной строки для управления правилами курсора, позволяющий создавать подробные планы реализации для сложных задач niko-plan هو أداة سطر الأوامر لإدارة قواعد المؤشر، مما يسمح بإنشاء خطط تنفيذ مفصلة للمهام المعقدة how to use niko-plan niko-plan setup guide niko-plan alternative niko-plan vs cursor tools niko-plan install what is niko-plan niko-plan implementation planning niko-plan complexity level management niko-plan CLI tool Niko-plan AI智能代理 CLI工具 Cursor规则管理 技术规划 内存银行文件 复杂性级别 实现计划 AI开发工具 Creates detailed implementation plans for tasks based on complexity levels Loads Memory Bank Files, including tasks.md and activeContext.md Determines complexity levels from activeContext.md for scaled planning Routes to level-specific planning documents for tailored implementation Reads and writes to memory-bank files for persistent data management niko-plan is a command-line interface tool designed for managing Cursor rules, specifically for creating implementation plans based on task complexity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CodeHalwell/DoclingOptimisation/git-workflow-patterns', 'community', 'CodeHalwell', 'DoclingOptimisation', 'CodeHalwell/DoclingOptimisation', 'git-workflow-patterns', 0, 0, 23, '2026-03-04T09:50:47Z', '2026-03-07T04:13:19.565Z', '6f1a4f8a58d50592a3d7ed4366ba37247ec39b2799ce7514d919219059dab4e4', '{"id":"CodeHalwell/DoclingOptimisation/git-workflow-patterns","name":"git-workflow-patterns","description":{"en":"The git-workflow-patterns skill provides a standardized approach to Git workflow management, benefiting developers and teams. It ensures a consistent and efficient workflow.","zh":"Git 工作流模式提供了一种高效的代码管理方式，包括分支、提交和拉取请求的管理，以优化您的 Docling","ja":"Git ワークフロー パターンは、分岐、コミット、プルリクエストの管理を通じて、コード管理を効率化し、Docling を最適化します","ko":"Git 작업 흐름 패턴은 분기, 커밋, 풀 리퀘스트의 관리를 통해 코드 관리를 효율화하고 Docling을 최적화합니다","es":"El patrón de flujo de trabajo de Git permite una colaboración eficiente y una gestión de código efectiva","fr":"Le modèle de workflow Git permet une collaboration efficace et une gestion de code efficiente","de":"Das Git-Workflow-Muster ermöglicht eine effiziente Zusammenarbeit und eine effektive Codeverwaltung","pt":"O padrão de fluxo de trabalho Git é uma abordagem para gerenciar o código-fonte de projetos de software, utilizando branching, commits e pull requests de forma eficaz","ru":"Шаблон потока работы Git представляет собой подход к управлению исходным кодом программных проектов, использующий ветвление, коммиты и запросы на включение изменений","ar":"نمط سير العمل جيت هو نهج لإدارة مصدر مشاريع البرمجيات، باستخدام الفروع و Commit و الطلبات السحابية بشكل فعال"},"seo":{"title":{"en":"git-workflow-patterns: GitHub Flow Setup Guide | AI Agent...","zh":"Git 工作流模式设置指南 - 优化 Docling","ja":"Git ワークフロー パターン設定ガイド - AIエージェントによる Docling 最適化","ko":"Git 작업 흐름 패턴 설정 가이드 - AI 도구를 사용한 Docling 최적화","es":"Patrones de flujo de trabajo de Git: Guía de configuración","fr":"Modèles de workflow Git: Meilleures pratiques","de":"Git-Workflow-Muster: Einrichtungsleitfaden","pt":"Padrões de Fluxo de Trabalho Git: Guia de Configuração","ru":"Шаблоны Потока Работы Git: Настройка и Лучшие Практики с ...","ar":"نماذج سير العمل جيت: دليل الإعداد والأدوات الذكية"},"description":{"en":"Learn how to optimize your Git workflow with Docling optimization. Discover the best practices for branching, committing, and pull requests.","zh":"了解 Git 工作流模式的最佳实践，包括分支、提交和拉取请求的管理，以优化您的 Docling","ja":"Git ワークフロー パターンのベスト プラクティスを学び、分岐、コミット、プルリクエストの管理を最適化して、Docling を改善する","ko":"Git 작업 흐름 패턴의最佳实践을 학습하고 분기, 커밋, 풀 리퀘스트의 관리를 최적화하여 Docling을 개선합니다","es":"Aprende a implementar patrones de flujo de trabajo de Git para mejorar la colaboración y la eficiencia en tus proyectos de desarrollo de software","fr":"Découvrez comment mettre en place des modèles de workflow Git pour améliorer la collaboration et l''efficacité dans vos projets de développement de logiciels","de":"Erfahren Sie, wie Sie Git-Workflow-Muster implementieren können, um die Zusammenarbeit und Effizienz in Ihren Software-Entwicklungsprojekten zu verbessern","pt":"Aprenda a configurar padrões de fluxo de trabalho Git para melhorar a colaboração e a produtividade do seu time de desenvolvimento com commit-message.sh e sq...","ru":"Узнайте, как настроить шаблоны потока работы Git для повышения сотрудничества и производительности вашей команды разработки с помощью commit-message.sh и squ...","ar":"تعلم كيفية تعيين نمادج سير العمل جيت لتحسين التعاون وإنتاجية فريق التطوير الخاص بك مع commit-message.sh و squash merge والأدوات الذكية"},"definition":{"en":"git-workflow-patterns is a set of guidelines for managing Git workflows, including branching, committing, and pull requests, using the GitHub Flow and Conventional Commits.","zh":"Git 工作流模式是一种代码管理方式，用于优化 Docling","ja":"Git ワークフロー パターンとは、コード管理を効率化し、Docling を最適化するための方法論です","ko":"Git 작업 흐름 패턴은 코드 관리를 효율화하고 Docling을 최적화하는 방법론입니다","es":"Un patrón de flujo de trabajo de Git es un conjunto de reglas y prácticas para gestionar el código y la colaboración en proyectos de desarrollo de software","fr":"Un modèle de workflow Git est un ensemble de règles et de pratiques pour gérer le code et la collaboration dans les projets de développement de logiciels","de":"Ein Git-Workflow-Muster ist eine Sammlung von Regeln und Praktiken zur Verwaltung von Code und Zusammenarbeit in Software-Entwicklungsprojekten","pt":"Padrão de fluxo de trabalho Git é uma convenção para gerenciar o código-fonte de projetos de software","ru":"Шаблон потока работы Git — это соглашение для управления исходным кодом программных проектов","ar":"نمط سير العمل جيت هو اتفاقية لإدارة مصدر مشاريع البرمجيات"},"features":{"en":["Implements the GitHub Flow with a main branch that is always deployable","Supports short-lived feature branches with prefixes like feature/, fix/, and chore/","Enforces Conventional Commits using a commit-message.sh hook","Uses a squash merge strategy for pull requests","Deletes branches after merge to maintain a clean repository","Formats commits with type(scope): description for clear changelogs"],"zh":["分支管理：main 分支始终可部署","提交管理：Conventional Commit 格式","拉取请求管理：保持小而专注","自动化提交消息验证：commit-message.sh hook","分支删除：合并后删除分支"],"ja":["ブランチ管理：main ブランチは常にデプロイ可能","コミット管理：Conventional Commit 形式","プルリクエスト管理：小さくて集中したまま","自動化コミットメッセージ検証：commit-message.sh hook","ブランチ削除：マージ後のブランチ削除"],"ko":["분기 관리：main 분기 항상 배포 가능","커밋 관리：Conventional Commit 형식","풀 리퀘스트 관리：작고 집중된 상태로 유지","자동화 커밋 메시지 검증：commit-message.sh hook","분기 삭제：병합 후 분기 삭제"],"es":["Ramificación (GitHub Flow) con una rama principal siempre desplegable","Commits con formato convencional (type(scope): description)","Solicitudes de extracción (Pull Requests) pequeñas y enfocadas","Merge de squash para mantener un historial de commits limpio","Uso de hooks para enfocar los mensajes de commit","Eliminación de ramas después de la fusión"],"fr":["Branchement (GitHub Flow) avec une branche principale toujours déployable","Commits avec format conventionnel (type(scope): description)","Demandes d''extraction (Pull Requests) petites et ciblées","Merge de squash pour maintenir un historique de commits propre","Utilisation de hooks pour contrôler les messages de commit","Suppression de branches après fusion"],"de":["Verzweigung (GitHub Flow) mit einer immer auslieferbaren Hauptbranch","Commits mit konventionellem Format (type(scope): description)","Zugriffsanfragen (Pull Requests) klein und fokussiert","Squash-Merge zur Aufrechterhaltung eines sauberen Commit-Historie","Verwendung von Hooks zur Kontrolle der Commit-Meldungen","Löschung von Branches nach Merge"],"pt":["Branching com `main` sempre deployável","Commits com formato `type(scope): description`","Pull requests pequenos e focados com squash merge","Uso de `commit-message.sh` hook para validar commits","Branches de recursos curtos com `feature/`, `fix/`, `chore/`, `docs/`"],"ru":["Ветвление с `main`, всегда готовым к развертыванию","Коммиты с форматом `type(scope): description`","Запросы на включение изменений небольшие и сосредоточенные с squash merge","Использование `commit-message.sh` hook для проверки коммитов","Ветки функций короткие с `feature/`, `fix/`, `chore/`, `docs/`"],"ar":["الفروع مع `main` دائمًا جاهزة للنشر","التعليقات مع تنسيق `type(scope): description`","طلبات السحب الصغيرة والمتواضعة مع squash merge","استخدام `commit-message.sh` hook للتحقق من التعليقات","فروع الميزات قصيرة مع `feature/`, `fix/`, `chore/`, `docs/`"]},"keywords":{"en":["git-workflow-patterns setup guide","github flow best practices","conventional commits tutorial","git workflow management","how to use git-workflow-patterns","git-workflow-patterns vs gitflow","install git-workflow-patterns","git workflow optimization techniques","git-workflow-patterns documentation","git workflow patterns for developers"],"zh":["Git 工作流模式","Docling 优化","代码管理","分支管理","提交管理","拉取请求管理","Conventional Commit","commit-message.sh hook"],"ja":["Git ワークフロー パターン","Docling 最適化","コード管理","ブランチ管理","コミット管理","プルリクエスト管理","Conventional Commit","commit-message.sh hook"],"ko":["Git 작업 흐름 패턴","Docling 최적화","코드 관리","분기 관리","커밋 관리","풀 리퀘스트 관리","Conventional Commit","commit-message.sh hook"],"es":["patrones de flujo de trabajo de Git","GitHub Flow","commits convencionales","solicitudes de extracción","merge de squash","hooks de commit","ramificación de Git","colaboración en desarrollo de software","gestión de código","desarrollo de software ágil"],"fr":["modèles de workflow Git","GitHub Flow","commits conventionnels","demandes d''extraction","merge de squash","hooks de commit","branchement de Git","collaboration dans le développement de logiciels","gestion de code","développement de logiciels agile"],"de":["Git-Workflow-Muster","GitHub Flow","konventionelle Commits","Zugriffsanfragen","Squash-Merge","Commit-Hooks","Git-Verzweigung","Zusammenarbeit in der Software-Entwicklung","Codeverwaltung","agiles Software-Entwickeln"],"pt":["padrões de fluxo de trabalho git","git workflow","commit-message.sh","squash merge","branching","commits","pull requests","desenvolvimento de software","colaboração em equipe"],"ru":["шаблоны потока работы git","git workflow","commit-message.sh","squash merge","ветвление","коммиты","запросы на включение изменений","разработка программного обеспечения","сотрудничество команды","ИИ Агенты"],"ar":["نماذج سير العمل جيت","git workflow","commit-message.sh","squash merge","الفروع","التعليقات","طلبات السحب","تطوير البرمجيات","التعاون الفريق","الأدوات الذكية"]}},"owner":"CodeHalwell","repo":"DoclingOptimisation","repoPath":"CodeHalwell/DoclingOptimisation","stars":0,"forks":0,"updatedAt":"2026-03-04T09:50:47Z","topics":[],"category":"community","skillMd":{"name":"git-workflow-patterns","description":">","bodyPreview":"# Git Workflow — DoclingOptimisation\n\n## Branching (GitHub Flow)\n- `main` is always deployable\n- Short-lived feature branches: `feature/`, `fix/`, `chore/`, `docs/`\n- Branch from main, merge back to main\n- Delete branches after merge\n\n## Commits (Conventional)\n- Format: `type(scope): description`\n- Types: feat, fix, docs, style, refactor, perf, test, build, ci, chore\n- Enforced by `commit-message.sh` hook\n- Body explains WHY, not what\n\n## Pull Requests\n- Keep PRs small and focused\n- Squash merge","body":"# Git Workflow — DoclingOptimisation\n\n## Branching (GitHub Flow)\n- `main` is always deployable\n- Short-lived feature branches: `feature/`, `fix/`, `chore/`, `docs/`\n- Branch from main, merge back to main\n- Delete branches after merge\n\n## Commits (Conventional)\n- Format: `type(scope): description`\n- Types: feat, fix, docs, style, refactor, perf, test, build, ci, chore\n- Enforced by `commit-message.sh` hook\n- Body explains WHY, not what\n\n## Pull Requests\n- Keep PRs small and focused\n- Squash merge to main\n- Include What/Why/How/Testing sections in description\n\n## Releases\n- Semantic versioning in pyproject.toml\n- Docker image tags follow semver\n- Git tags trigger CI/CD deployment\n"},"lastSynced":"2026-03-07T04:13:19.565Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing standardized Git workflow management and automation.","zh":"非常适合需要标准化 Git 工作流管理和自动化的开发代理。","ja":"標準化されたGitワークフロー管理と自動化を必要とする開発エージェントに最適です。","ko":"표준화된 Git 워크플로 관리 및 자동화를 필요한 개발 에이전트에게 최적입니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión y automatización de flujo de trabajo de Git estandarizada.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion et d''une automatisation de workflow Git standardisées.","de":"Perfekt für Entwicklungssagenten, die eine standardisierte Git-Workflow-Verwaltung und -Automatisierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gestão e automação de fluxo de trabalho do Git padronizada.","ru":"Идеально подходит для агентов разработки, которым требуется стандартизированное управление и автоматизация рабочего процесса Git.","ar":"مثالي للوكلاء التطوير الذين يحتاجون إلى إدارة وآليّة تدفق عمل Git معيارية."},"recommendation":{"en":"Empowers agents to enforce Conventional Commits using commit-message.sh hooks, manage short-lived feature branches with GitHub Flow, and optimize pull requests with squash merge, ensuring a consistent and efficient workflow.","zh":"赋予代理人使用commit-message.sh钩子强制执行Conventional Commits，使用GitHub Flow管理短暂的特性分支，并使用squash merge优化拉取请求，确保工作流的一致性和效率。","ja":"commit-message.shフックを使用してConventional Commitsを適用し、GitHub Flowで短命の機能ブランチを管理し、squash mergeでプルリクエストを最適化することで、ワークフローの一貫性と効率を確保します。","ko":"commit-message.sh 훅을 사용하여 Conventional Commits를 적용하고 GitHub Flow로 短暂한 기능 브랜치를 관리하며 squash merge로 풀 리퀘스트를 최적화하여 워크플로의 일관성과 효율성을 보장합니다.","es":"Habilita a los agentes a aplicar Commits Convencionales utilizando hooks de commit-message.sh, gestionar ramas de características de vida corta con GitHub Flow y optimizar solicitudes de extracción con squash merge, garantizando un flujo de trabajo coherente y eficiente.","fr":"Permet aux agents d''appliquer des Commits Conventionnels en utilisant des hooks commit-message.sh, de gérer des branches de fonctionnalités à durée de vie courte avec GitHub Flow et d''optimiser les demandes d''extraction avec une fusion écrasante, garantissant ainsi un workflow cohérent et efficace.","de":"Ermächtigt Agenten, Conventional Commits mithilfe von commit-message.sh-Hooks durchzusetzen, kurze Feature-Branches mit GitHub Flow zu verwalten und Pull-Requests mit Squash-Merge zu optimieren, um so einen konsistenten und effizienten Workflow sicherzustellen.","pt":"Habilita os agentes a impor Commits Convencionais usando hooks commit-message.sh, gerenciar branches de recurso de vida curta com GitHub Flow e otimizar pull requests com merge squash, garantindo um fluxo de trabalho consistente e eficiente.","ru":"Наделяет агентов возможностью обеспечить соблюдение Конвенциональных коммитов с помощью хуков commit-message.sh, управлять ветками с коротким жизненным циклом с помощью GitHub Flow и оптимизировать запросы на включение с помощью сжатого слияния, обеспечивая последовательный и эффективный рабочий процесс.","ar":"يمكن الوكلاء من فرض Commits التقليدية باستخدام hooks commit-message.sh، وإدارة فروع الميزة قصيرة الأجل مع GitHub Flow، وتحسين طلبات السحب مع دمج squash، مما يضمن تدفق عمل متسق وفعال."},"useCases":{"en":["Automating branch management with main as the deployable branch","Generating commit messages following the Conventional format","Streamlining pull requests with small and focused changes"],"zh":["使用main作为部署分支来自动化分支管理","生成遵循Conventional格式的提交消息","通过小型和专注的更改来简化拉取请求"],"ja":["mainをデプロイ可能なブランチとして使用してブランチ管理を自動化する","Conventional形式のコミットメッセージを生成する","小さくて集中した変更でプルリクエストを簡素化する"],"ko":["main을 배포 가능한 브랜치로 사용하여 브랜치 관리를 자동화하는 것","Conventional 형식의 커밋 메시지를 생성하는 것","작고 집중된 변경으로 풀 리퀘스트를 간소화하는 것"],"es":["Automatizar la gestión de ramas con main como rama desplegable","Generar mensajes de commit siguiendo el formato Convencional","Optimizar las solicitudes de extracción con cambios pequeños y centrados"],"fr":["Automatiser la gestion des branches avec main en tant que branche déployable","Générer des messages de commit suivant le format Conventionnel","Optimiser les demandes d''extraction avec des modifications petites et ciblées"],"de":["Automatisieren der Verwaltung von Zweigen mit main als ausführbarer Zweig","Generieren von Commit-Nachrichten im Conventional-Format","Optimieren von Pull-Requests mit kleinen und fokussierten Änderungen"],"pt":["Automatizar gerenciamento de branches com main como branch implantável","Gerar mensagens de commit seguindo o formato Convencional","Otimizar pull requests com alterações pequenas e focadas"],"ru":["Автоматизировать управление ветками с main как развертываемой веткой","Генерировать сообщения коммитов в соответствии с Конвенциональным форматом","Оптимизировать запросы на включение с небольшими и сосредоточенными изменениями"],"ar":["آليّة إدارة الفروع مع main كفرع قابل للتثبيت","توليد رسائل Commit اتباع التنسيق التقليدي","تبسيط طلبات السحب مع изменения صغيرة ومُركزة"]},"limitations":{"en":["Requires Git version control system","Limited to GitHub Flow branching pattern"],"zh":["需要Git版本控制系统","仅限于GitHub Flow分支模式"],"ja":["Gitバージョン管理システムが必要","GitHub Flowブランチパターンに限定される"],"ko":["Git 버전 관리 시스템이 필요함","GitHub Flow 브랜치 패턴에만 제한됨"],"es":["Requiere sistema de control de versiones Git","Limitado al patrón de ramificación GitHub Flow"],"fr":["Nécessite un système de contrôle de version Git","Limité au modèle de branchement GitHub Flow"],"de":["Erfordert Git-Versionskontrollsystem","Begrenzt auf GitHub-Flow-Verzweigungsmuster"],"pt":["Requer sistema de controle de versão Git","Limitado ao padrão de ramificação GitHub Flow"],"ru":["Требуется система контроля версий Git","Ограничен шаблоном ветвления GitHub Flow"],"ar":["يتطلب نظام التحكم في الإصدار Git","محدود بنمط الفرع GitHub Flow"]},"version":4},"contentHash":"6f1a4f8a58d50592a3d7ed4366ba37247ec39b2799ce7514d919219059dab4e4","qualityScore":23}');
