INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CodeHalwell/DoclingOptimisation/git-workflow-patterns', 'git-workflow-patterns', 'CodeHalwell', 'DoclingOptimisation', 'community', 'git-workflow-patterns CodeHalwell DoclingOptimisation community The git-workflow-patterns skill provides a standardized approach to Git workflow management, benefiting developers and teams. It ensures a consistent and efficient workflow. Git 工作流模式提供了一种高效的代码管理方式，包括分支、提交和拉取请求的管理，以优化您的 Docling Git ワークフロー パターンは、分岐、コミット、プルリクエストの管理を通じて、コード管理を効率化し、Docling を最適化します Git 작업 흐름 패턴은 분기, 커밋, 풀 리퀘스트의 관리를 통해 코드 관리를 효율화하고 Docling을 최적화합니다 El patrón de flujo de trabajo de Git permite una colaboración eficiente y una gestión de código efectiva Le modèle de workflow Git permet une collaboration efficace et une gestion de code efficiente Das Git-Workflow-Muster ermöglicht eine effiziente Zusammenarbeit und eine effektive Codeverwaltung O padrão de fluxo de trabalho Git é uma abordagem para gerenciar o código-fonte de projetos de software, utilizando branching, commits e pull requests de forma eficaz Шаблон потока работы Git представляет собой подход к управлению исходным кодом программных проектов, использующий ветвление, коммиты и запросы на включение изменений نمط سير العمل جيت هو نهج لإدارة مصدر مشاريع البرمجيات، باستخدام الفروع و Commit و الطلبات السحابية بشكل فعال git-workflow-patterns setup guide github flow best practices conventional commits tutorial git workflow management how to use git-workflow-patterns git-workflow-patterns vs gitflow install git-workflow-patterns git workflow optimization techniques git-workflow-patterns documentation git workflow patterns for developers Git 工作流模式 Docling 优化 代码管理 分支管理 提交管理 拉取请求管理 Conventional Commit commit-message.sh hook Implements the GitHub Flow with a main branch that is always deployable Supports short-lived feature branches with prefixes like feature/, fix/, and chore/ Enforces Conventional Commits using a commit-message.sh hook Uses a squash merge strategy for pull requests Deletes branches after merge to maintain a clean repository Formats commits with type(scope): description for clear changelogs git-workflow-patterns is a set of guidelines for managing Git workflows, including branching, committing, and pull requests, using the GitHub Flow and Conventional Commits.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('frinfo702/english-test-generator/english-question-generator', 'community', 'frinfo702', 'english-test-generator', 'frinfo702/english-test-generator', 'english-question-generator', 0, 0, 23, '2026-02-18T14:00:21Z', '2026-03-07T04:17:43.453Z', 'df5bf2248cc537c64789cf7f85132b9672a89d3493ce8d11d13f611feda188ca', '{"id":"frinfo702/english-test-generator/english-question-generator","name":"english-question-generator","description":{"en":"The english-question-generator skill creates English questions for TOEFL/TOEIC exams, benefiting developers and educators. It generates questions based on specific tasks and sections.","zh":"英语题目生成器是一种AI工具，用于生成TOEFL/TOEIC英语问题，支持多种题型和难度级别","ja":"英語問題生成ツールは、TOEFL/TOEIC英語問題を生成するAIエージェントであり、多種多様な問題タイプと難易度をサポート","ko":"영어 문항 생성기는 TOEFL/TOEIC 영어 문항을 생성하는 AI 도구로, 여러 유형과 난이도 수준을 지원","es":"El generador de preguntas de inglés es una herramienta para crear preguntas de TOEFL/TOEIC. Utiliza scripts y JSON para generar preguntas personalizadas.","fr":"Le générateur de questions anglaises est un outil pour créer des questions de TOEFL/TOEIC. Il utilise des scripts et du JSON pour générer des questions personnalisées.","de":"Der Englisch-Fragen-Generator ist ein Tool zum Erstellen von TOEFL/TOEIC-Fragen. Es verwendet Skripte und JSON, um individuelle Fragen zu generieren.","pt":"O gerador de perguntas em inglês é uma ferramenta para criar perguntas para exames TOEFL/TOEIC com scripts em CLI e estruturas JSON.","ru":"Генератор вопросов по английскому языку - это инструмент для создания вопросов для экзаменов TOEFL/TOEIC с помощью скриптов CLI и структур JSON.","ar":"مُولِد الأسئلة الإنجليزية هو أداة لإنشاء أسئلة للاختبارات TOEFL/TOEIC باستخدام سكريبتات CLI وهياكل JSON."},"seo":{"title":{"en":"english-question-generator: TOEFL/TOEIC Question Setup Gu...","zh":"英语题目生成器_setup指南","ja":"英語問題生成ツール_Best Practices","ko":"영어 문항 생성기_Setup Guide","es":"Generador de Preguntas de Inglés: Guía de Configuración p...","fr":"Générateur de Questions Anglaises: Guide d''Installation p...","de":"Englisch-Fragen-Generator: Einrichtungsanleitung für TOEF...","pt":"Guia de Configuração do Gerador de Perguntas em Inglês","ru":"Руководство по настройке генератора вопросов по английско...","ar":"دليل إعداد مُولِد الأسئلة الإنجليزية"},"description":{"en":"Discover how to generate English questions for TOEFL/TOEIC exams using the english-question-generator skill. Learn how to create custom questions with ease.","zh":"了解英语题目生成器的技术细节和实现步骤，包括TOEFL/TOEIC问题生成","ja":"英語問題生成ツールの技術的側面と実装手順を学ぶ、TOEFL/TOEIC問題生成を含む","ko":"영어 문항 생성기의 기술적 세부 사항과 구현 단계를 알아보세요, TOEFL/TOEIC 문항 생성 포함","es":"Aprende a configurar el generador de preguntas de inglés para TOEFL/TOEIC con nuestro paso a paso","fr":"Découvrez comment configurer le générateur de questions anglaises pour TOEFL/TOEIC avec notre guide étape par étape","de":"Erfahren Sie, wie Sie den Englisch-Fragen-Generator für TOEFL/TOEIC mit unserem Schritt-für-Schritt-Anleitung einrichten","pt":"Aprenda a configurar o gerador de perguntas em inglês para TOEFL/TOEIC com scripts em CLI e estruturas JSON","ru":"Узнайте, как настроить генератор вопросов по английскому языку для TOEFL/TOEIC с помощью скриптов CLI и структур JSON","ar":"تعرف على كيفية إعداد مُولِد الأسئلة الإنجليزية لاختبارات TOEFL/TOEIC باستخدام سكريبتات CLI وهياكل JSON"},"definition":{"en":"english-question-generator is a skill that generates English questions for TOEFL/TOEIC exams, following specific schemas and tasks.","zh":"英语题目生成器是一种AI工具，用于生成英语问题","ja":"英語問題生成ツールは、英語問題を生成するAIエージェント","ko":"영어 문항 생성기는 영어 문항을 생성하는 AI 도구","es":"Un generador de preguntas de inglés es una herramienta de software que crea preguntas de inglés para exámenes como TOEFL/TOEIC","fr":"Un générateur de questions anglaises est un outil logiciel qui crée des questions d''anglais pour des examens comme TOEFL/TOEIC","de":"Ein Englisch-Fragen-Generator ist ein Software-Tool, das Englisch-Fragen für Prüfungen wie TOEFL/TOEIC erstellt","pt":"O que é um gerador de perguntas em inglês? É uma ferramenta para criar perguntas para exames de inglês.","ru":"Что такое генератор вопросов по английскому языку? Это инструмент для создания вопросов для экзаменов по английскому языку.","ar":"ما هو مُولِد الأسئلة الإنجليزية? هو أداة لإنشاء أسئلة للاختبارات الإنجليزية."},"features":{"en":["Generates question JSON files using scripts/make-question.sh","Supports TOEFL/TOEIC question generation for reading and writing sections","Creates questions based on specific tasks, such as complete-words and daily-life","Validates question structure against references/question-schemas.md","Allows for custom difficulty levels, including Module 1 (standard)"],"zh":["支持TOEFL/TOEIC问题生成","多种题型支持，包括阅读和写作","难易度级别可调节","使用scripts/make-question.sh脚本生成问题","问题结构遵循references/question-schemas.md规范"],"ja":["TOEFL/TOEIC問題生成をサポート","多種多様な問題タイプをサポート、読解と作文を含む","難易度レベルを調整可能","scripts/make-question.shスクリプトを使用して問題を生成","問題構造はreferences/question-schemas.md規格に準拠"],"ko":["TOEFL/TOEIC 문항 생성 지원","문항 유형 多样性 지원, 독해와 작문을 포함","난이도 수준 조정 가능","scripts/make-question.sh 스크립트 사용하여 문항 생성","문항 구조는 references/question-schemas.md 규격에 준수"],"es":["Generación de preguntas personalizadas con scripts y JSON","Compatibilidad con TOEFL/TOEIC","Soporte para secciones de lectura y escritura","Uso de la CLI para ejecutar scripts","Estructura de preguntas basada en esquemas JSON","Personalización de la dificultad de las preguntas"],"fr":["Génération de questions personnalisées avec des scripts et du JSON","Compatibilité avec TOEFL/TOEIC","Prise en charge des sections de lecture et d''écriture","Utilisation de la CLI pour exécuter des scripts","Structure de questions basée sur des schémas JSON","Personnalisation de la difficulté des questions"],"de":["Generierung von individualisierten Fragen mit Skripten und JSON","Kompatibilität mit TOEFL/TOEIC","Unterstützung für Lese- und Schreibabschnitte","Verwendung der CLI zum Ausführen von Skripten","Fragenstruktur basierend auf JSON-Schemata","Anpassung der Schwierigkeitsgrade der Fragen"],"pt":["Geração de perguntas para exames TOEFL/TOEIC","Uso de scripts em CLI para criação de perguntas","Estruturas JSON para organização de perguntas","Suporte a tarefas de leitura e escrita","Compatibilidade com módulos de dificuldade variável"],"ru":["Генерация вопросов для экзаменов TOEFL/TOEIC","Использование скриптов CLI для создания вопросов","Структуры JSON для организации вопросов","Поддержка задач по чтению и письму","Совместимость с модулями разного уровня сложности"],"ar":["إنشاء أسئلة للاختبارات TOEFL/TOEIC","استخدام سكريبتات CLI لإنشاء الأسئلة","هياكل JSON لتنظيم الأسئلة","دعم المهام القرائية والكتابة","التوافق مع الوحدات المتغيرة الصعوبة"]},"keywords":{"en":["how to use english-question-generator","english-question-generator setup guide","TOEFL question generator","TOEIC question generator","english-question-generator alternative","english-question-generator vs question generator tools","install english-question-generator","english-question-generator for AI agents"],"zh":["英语题目生成器","TOEFL问题生成","TOEIC问题生成","AI工具","英语问题生成","scripts/make-question.sh","references/question-schemas.md"],"ja":["英語問題生成ツール","TOEFL問題生成","TOEIC問題生成","AIエージェント","英語問題生成","scripts/make-question.sh","references/question-schemas.md"],"ko":["영어 문항 생성기","TOEFL 문항 생성","TOEIC 문항 생성","AI 도구","영어 문항 생성","scripts/make-question.sh","references/question-schemas.md"],"es":["generador de preguntas de inglés","TOEFL","TOEIC","preguntas personalizadas","scripts","JSON","CLI","exámenes de inglés","herramientas de software para inglés"],"fr":["générateur de questions anglaises","TOEFL","TOEIC","questions personnalisées","scripts","JSON","CLI","examens d''anglais","outils logiciels pour l''anglais"],"de":["Englisch-Fragen-Generator","TOEFL","TOEIC","individualisierte Fragen","Skripte","JSON","CLI","Englisch-Prüfungen","Software-Tools für Englisch"],"pt":["gerador de perguntas em inglês","TOEFL","TOEIC","scripts em CLI","estruturas JSON","exames de inglês","ferramentas de estudo","aprendizado de inglês","tecnologia educacional"],"ru":["генератор вопросов по английскому языку","TOEFL","TOEIC","скрипты CLI","структуры JSON","экзамены по английскому языку","инструменты для изучения","обучение английскому языку","образовательная технология"],"ar":["مُولِد الأسئلة الإنجليزية","TOEFL","TOEIC","سكريبتات CLI","هياكل JSON","اختبارات الإنجليزية","أدوات التعلم","تعلم الإنجليزية","تكنولوجيا التعليم"]}},"owner":"frinfo702","repo":"english-test-generator","repoPath":"frinfo702/english-test-generator","stars":0,"forks":0,"updatedAt":"2026-02-18T14:00:21Z","topics":[],"category":"community","skillMd":{"name":"english-question-generator","description":">","bodyPreview":"# TOEFL / TOEIC Question Generator\n\n## 先に確認すること\n\n- `references/question-schemas.md` を先に読む\n- 生成対象タスクの既存サンプルを `public/questions/...` で確認する\n\n## 実行手順\n\n1. 依頼から試験種別・セクション・タスクを特定する\n2. セクション/タスク未指定ならユーザーに確認する\n3. 難易度未指定なら Module 1（標準）を採用する\n4. `scripts/make-question.sh <task>` で雛形JSONを作成する\n5. 生成ファイルの `TODO` を本番問題に置換する\n6. JSON構造を `references/question-schemas.md` と照合する\n7. 保存先パスとファイル名を明示して完了報告する\n\n## task パス\n\n- `toefl/reading/complete-words`\n- `toefl/reading/daily-life`\n- `toefl/reading/academic`\n- `toefl/wri","body":"# TOEFL / TOEIC Question Generator\n\n## 先に確認すること\n\n- `references/question-schemas.md` を先に読む\n- 生成対象タスクの既存サンプルを `public/questions/...` で確認する\n\n## 実行手順\n\n1. 依頼から試験種別・セクション・タスクを特定する\n2. セクション/タスク未指定ならユーザーに確認する\n3. 難易度未指定なら Module 1（標準）を採用する\n4. `scripts/make-question.sh <task>` で雛形JSONを作成する\n5. 生成ファイルの `TODO` を本番問題に置換する\n6. JSON構造を `references/question-schemas.md` と照合する\n7. 保存先パスとファイル名を明示して完了報告する\n\n## task パス\n\n- `toefl/reading/complete-words`\n- `toefl/reading/daily-life`\n- `toefl/reading/academic`\n- `toefl/writing/build-sentence`\n- `toefl/writing/email`\n- `toefl/writing/discussion`\n- `toefl/speaking/listen-repeat`\n- `toefl/speaking/interview`\n- `toeic/part5`\n- `toeic/part6`\n- `toeic/part7`\n\n## Complete the Words の必須仕様\n\n- 70〜100語の学術段落を作る\n- 空欄は10個に固定する\n- `items[].hint` は 2〜3文字にする\n- `items[].answer` は完全な正解単語を入れる\n- `items[].hint` を `items[].answer` の先頭一致にする\n- **解答者は hint の続きのみを入力する前提で作る**\n- 続き文字数 = `answer.length - hint.length` で揃える\n- `items[].placeholder` は `hint + 続き文字数分の _` にする\n- `paragraph` 内の空欄表現を `items[].placeholder` と完全一致させる\n- 文脈から一意に正解できる語だけを選ぶ\n\n## 品質チェック\n\n- `index` は 0 始まりで連番にする\n- 各 `placeholder` は段落内に1回だけ出現させる\n- 綴り・文法・語彙レベルを難易度要件に合わせる\n- TOEICはビジネス文脈、TOEFLは学習者向け学術/日常文脈に寄せる\n"},"lastSynced":"2026-03-07T04:17:43.453Z","agentAnalysis":{"suitability":{"en":"Ideal for Language Learning Agents requiring automated TOEFL/TOEIC question generation capabilities.","zh":"适合需要自动化TOEFL/TOEIC题目生成能力的语言学习代理。","ja":"TOEFL/TOEICの質問生成機能を自動化する言語学習エージェントに最適。","ko":"자동화된 TOEFL/TOEIC 문제 생성 기능을 필요로 하는 언어 학습 에이전트에 적합합니다.","es":"Ideal para Agentes de Aprendizaje de Idiomas que requieren capacidades de generación de preguntas de TOEFL/TOEIC automatizadas.","fr":"Idéal pour les Agents d''Apprentissage de Langue nécessitant des capacités de génération de questions de TOEFL/TOEIC automatisées.","de":"Ideal für Sprachlernagenten, die automatisierte TOEFL/TOEIC-Fragen generierende Funktionen erfordern.","pt":"Ideal para Agentes de Aprendizado de Linguagem que exigem capacidades de geração automática de perguntas do TOEFL/TOEIC.","ru":"Идеально подходит для агентов по обучению языкам, требующих автоматизированных возможностей генерации вопросов TOEFL/TOEIC.","ar":"مثالي للوكلاء الذين يتعلمون اللغة الذين يتطلبون إمكانيات توليد أسئلة TOEFL/TOEIC أوتوماتيكيا."},"recommendation":{"en":"Empowers agents to create English questions for TOEFL/TOEIC exams, leveraging task-specific templates and JSON schema validation, with support for sections like reading and writing, utilizing scripts like `make-question.sh` for efficient question generation.","zh":"赋予代理创建英语问题的能力，用于TOEFL/TOEIC考试，利用特定任务的模板和JSON模式验证，并支持阅读和写作等部分，使用脚本如`make-question.sh`进行高效的问题生成。","ja":"TOEFL/TOEIC試験の英語の質問を作成するエージェントを可能にし、タスク固有のテンプレートとJSONスキーマ検証を利用し、読解と作文などのセクションをサポートし、`make-question.sh`などのスクリプトを使用して効率的な質問生成を行う。","ko":"에이전트가 TOEFL/TOEIC 시험을 위한 영어 문제를 생성하도록 하며, 작업별 템플릿과 JSON 스키마 검증을 활용하며, 읽기와 쓰기 등 부분을 지원하며, `make-question.sh`와 같은 스크립트를 사용하여 효율적인 문제 생성을 수행합니다.","es":"Habilita a los agentes a crear preguntas en inglés para exámenes de TOEFL/TOEIC, aprovechando plantillas específicas de tarea y validación de esquema JSON, con soporte para secciones como lectura y escritura, utilizando scripts como `make-question.sh` para una generación eficiente de preguntas.","fr":"Permet aux agents de créer des questions en anglais pour les examens de TOEFL/TOEIC, en exploitant des modèles spécifiques à la tâche et une validation de schéma JSON, avec un support pour des sections comme la lecture et l''écriture, en utilisant des scripts comme `make-question.sh` pour une génération efficace de questions.","de":"Ermächtigt Agenten, Englisch-Fragen für TOEFL/TOEIC-Prüfungen zu erstellen, indem sie taskspezifische Vorlagen und JSON-Schemavalidierung nutzen, mit Unterstützung für Abschnitte wie Lesen und Schreiben, unter Verwendung von Skripten wie `make-question.sh` für eine effiziente Fragegenerierung.","pt":"Permite que os agentes criem perguntas em inglês para exames TOEFL/TOEIC, utilizando modelos de tarefas específicas e validação de esquema JSON, com suporte a seções como leitura e escrita, utilizando scripts como `make-question.sh` para geração eficiente de perguntas.","ru":"Наделяет агентов возможностью создавать английские вопросы для экзаменов TOEFL/TOEIC, используя задачеспецифические шаблоны и валидацию схемы JSON, с поддержкой разделов, таких как чтение и письмо, используя скрипты, такие как `make-question.sh`, для эффективной генерации вопросов.","ar":"تمكن الوكلاء من إنشاء أسئلة اللغة الإنجليزية لأجلة TOEFL/TOEIC، مستخدمين قوالب مهام محددة وتبعيث مخطط JSON، مع دعم للاقسام مثل القراءة والكتابة، باستخدام سكريبتات مثل `make-question.sh` لتوليد الأسئلة بكفاءة."},"useCases":{"en":["Generating reading comprehension questions for TOEFL exams","Creating writing prompts for TOEIC practice tests","Automating question generation for academic and daily life sections"],"zh":["为TOEFL考试生成阅读理解问题","为TOEIC练习测试创建写作提示","自动化学术和日常生活部分的问题生成"],"ja":["TOEFL試験の読解問題を生成する","TOEIC練習試験の作文のヒントを作成する","学術的および日常生活のセクションの質問生成を自動化する"],"ko":["TOEFL 시험을 위한 읽기 이해 문제 생성","TOEIC 연습 시험을 위한 글쓰기 프롬프트 생성","학술 및 일상 부분의 문제 생성 자동화"],"es":["Generar preguntas de comprensión lectora para exámenes de TOEFL","Crear textos de escritura para pruebas de práctica de TOEIC","Automatizar la generación de preguntas para secciones académicas y de la vida diaria"],"fr":["Générer des questions de compréhension de lecture pour les examens de TOEFL","Créer des textes d''écriture pour les tests de pratique de TOEIC","Automatiser la génération de questions pour les sections académiques et de la vie quotidienne"],"de":["Generieren von Leseverständnisfragen für TOEFL-Prüfungen","Erstellen von Schreibaufgaben für TOEIC-Übungstests","Automatisieren der Fragegenerierung für akademische und alltägliche Abschnitte"],"pt":["Geração de perguntas de compreensão de leitura para exames TOEFL","Criação de prompts de escrita para testes de prática TOEIC","Automação da geração de perguntas para seções acadêmicas e da vida diária"],"ru":["Генерация вопросов для чтения для экзаменов TOEFL","Создание заданий для письма для практических тестов TOEIC","Автоматизация генерации вопросов для академических и повседневных разделов"],"ar":["توليد أسئلة فهم القراءة لأجلة TOEFL","إنشاء محفزات الكتابة للاختبارات العملية لTOEIC","أتمتة توليد الأسئلة للأقسام الأكاديمية والحياة اليومية"]},"limitations":{"en":["Requires knowledge of JSON schema and question templates","Limited to TOEFL/TOEIC exam formats","Dependent on `scripts/make-question.sh` for question generation"],"zh":["需要JSON模式和问题模板的知识","仅限TOEFL/TOEIC考试格式","依赖于`scripts/make-question.sh`进行问题生成"],"ja":["JSONスキーマと質問テンプレートの知識が必要","TOEFL/TOEIC試験形式のみ","質問生成には`scripts/make-question.sh`に依存"],"ko":["JSON 스키마 및 문제 템플릿에 대한 지식이 필요","TOEFL/TOEIC 시험 형식만 해당","`scripts/make-question.sh`에 의존하여 문제 생성"],"es":["Requiere conocimiento de esquema JSON y plantillas de preguntas","Limitado a formatos de exámenes de TOEFL/TOEIC","Dependiente de `scripts/make-question.sh` para la generación de preguntas"],"fr":["Nécessite des connaissances en schéma JSON et modèles de questions","Limité aux formats d''examens de TOEFL/TOEIC","Dépendant de `scripts/make-question.sh` pour la génération de questions"],"de":["Benötigt Kenntnisse von JSON-Schema und Fragevorlagen","Begrenzt auf TOEFL/TOEIC-Prüfungsmuster","Abhängig von `scripts/make-question.sh` für die Fragegenerierung"],"pt":["Exige conhecimento de esquema JSON e modelos de perguntas","Limitado a formatos de exames TOEFL/TOEIC","Dependente de `scripts/make-question.sh` para geração de perguntas"],"ru":["Требует знания схемы JSON и шаблонов вопросов","Ограничен форматами экзаменов TOEFL/TOEIC","Зависит от `scripts/make-question.sh` для генерации вопросов"],"ar":["يتطلب معرفة مخطط JSON وقوالب الأسئلة","محدود بنماذج امتحانات TOEFL/TOEIC","يعتمد على `scripts/make-question.sh` لتوليد الأسئلة"]},"version":4},"contentHash":"df5bf2248cc537c64789cf7f85132b9672a89d3493ce8d11d13f611feda188ca","qualityScore":23}');
