INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('frinfo702/english-test-generator/english-question-generator', 'english-question-generator', 'frinfo702', 'english-test-generator', 'community', 'english-question-generator frinfo702 english-test-generator community The english-question-generator skill creates English questions for TOEFL/TOEIC exams, benefiting developers and educators. It generates questions based on specific tasks and sections. 英语题目生成器是一种AI工具，用于生成TOEFL/TOEIC英语问题，支持多种题型和难度级别 英語問題生成ツールは、TOEFL/TOEIC英語問題を生成するAIエージェントであり、多種多様な問題タイプと難易度をサポート 영어 문항 생성기는 TOEFL/TOEIC 영어 문항을 생성하는 AI 도구로, 여러 유형과 난이도 수준을 지원 El generador de preguntas de inglés es una herramienta para crear preguntas de TOEFL/TOEIC. Utiliza scripts y JSON para generar preguntas personalizadas. Le générateur de questions anglaises est un outil pour créer des questions de TOEFL/TOEIC. Il utilise des scripts et du JSON pour générer des questions personnalisées. Der Englisch-Fragen-Generator ist ein Tool zum Erstellen von TOEFL/TOEIC-Fragen. Es verwendet Skripte und JSON, um individuelle Fragen zu generieren. O gerador de perguntas em inglês é uma ferramenta para criar perguntas para exames TOEFL/TOEIC com scripts em CLI e estruturas JSON. Генератор вопросов по английскому языку - это инструмент для создания вопросов для экзаменов TOEFL/TOEIC с помощью скриптов CLI и структур JSON. مُولِد الأسئلة الإنجليزية هو أداة لإنشاء أسئلة للاختبارات TOEFL/TOEIC باستخدام سكريبتات CLI وهياكل JSON. how to use english-question-generator english-question-generator setup guide TOEFL question generator TOEIC question generator english-question-generator alternative english-question-generator vs question generator tools install english-question-generator english-question-generator for AI agents 英语题目生成器 TOEFL问题生成 TOEIC问题生成 AI工具 英语问题生成 scripts/make-question.sh references/question-schemas.md Generates question JSON files using scripts/make-question.sh Supports TOEFL/TOEIC question generation for reading and writing sections Creates questions based on specific tasks, such as complete-words and daily-life Validates question structure against references/question-schemas.md Allows for custom difficulty levels, including Module 1 (standard) english-question-generator is a skill that generates English questions for TOEFL/TOEIC exams, following specific schemas and tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tdwhere123/do-what/agent-automation-smart-agent', 'community', 'tdwhere123', 'do-what', 'tdwhere123/do-what', 'agent-automation-smart-agent', 0, 0, 23, '2026-03-04T15:27:21Z', '2026-03-07T04:19:55.879Z', 'cd9f6469114280292848e72b34820381f869c68a5d22ca210d4eed6b5172ddc3', '{"id":"tdwhere123/do-what/agent-automation-smart-agent","name":"agent-automation-smart-agent","description":{"en":"The agent-automation-smart-agent skill automates tasks for AI agents, focusing on engineering memory capability architecture tests. It benefits developers seeking continuous self-improvement.","zh":"agent-automation-smart-agent 是一个本地优先的 AI 工作台，用于进行对工程记忆能力的架构测试","ja":"agent-automation-smart-agent は、エンジニアリング メモリ能力のアーキテクチャ テストを実行するローカル優先の AI ワークステーション","ko":"agent-automation-smart-agent 는 엔지니어링 메모리 능력의 아키텍처 테스트를 수행하는 로컬 우선의 지능형 에이전트 작업장","es":"El agente de automatización inteligente es una herramienta de IA que permite la automatización de tareas y el aprendizaje continuo","fr":"L''agent d''automatisation intelligent est un outil d''IA qui permet l''automatisation des tâches et l''apprentissage continu","de":"Der intelligente Automatisierungsagent ist ein Werkzeug der KI, das die Automatisierung von Aufgaben und das kontinuierliche Lernen ermöglicht","pt":"O agente de automação inteligente é uma plataforma local que visa testar a capacidade de memória de engenharia para melhorar continuamente. Ele utiliza topologia hierárquica para coordenação e armazena padrões bem-sucedidos","ru":"ИИ агент автоматизации - это локальная платформа, целью которой является тестирование способности инженерной памяти для постоянного улучшения. Он использует иерархическую топологию для координации и хранит успешные паттерны","ar":"وكيل التلقائية الذكية هو منصة محلية تهدف إلى اختبار القدرة على الذاكرة الهندسية لتحسين مستمر. يستخدم التخطيط الهيكلي الهرمي للتنسيق وتخزين الأنماط الناجحة"},"seo":{"title":{"en":"agent-automation-smart-agent: Automation Setup Guide | AI...","zh":"agent-automation-smart-agent 本地优先AI工作台设置指南","ja":"AIエージェント agent-automation-smart-agent のベストプラクティス","ko":"agent-automation-smart-agent 지능형 에이전트 자동화 가이드","es":"Guía de Configuración de Agentes de Automatización Inteli...","fr":"Guide de Mise en Place de l''Agent d''Automatisation Intell...","de":"Einrichtungsleitfaden für Intelligente Automatisierungsag...","pt":"Guia de Configuração do Agente de Automação Inteligente","ru":"Настройка ИИ Агента Автоматизации: Руководство","ar":"دليل إعداد وكيل التلقائية الذكية"},"description":{"en":"Unlock efficient automation with agent-automation-smart-agent. Learn how to trigger, skip, and optimize this skill for AI agents. Get started now!","zh":"了解 agent-automation-smart-agent 的核心目标和技术细节，实现持续不断的自我改进","ja":"AIエージェント agent-automation-smart-agent を使用してエンジニアリング メモリ能力をテストし、自我改進を実現","ko":"agent-automation-smart-agent 를 사용하여 지능형 에이전트 자동화를 구현하고 지속적인 개선을 달성","es":"Aprende a configurar y utilizar el agente de automatización inteligente para mejorar tus flujos de trabajo con tecnologías de IA como do-what","fr":"Découvrez comment configurer et utiliser l''agent d''automatisation intelligent pour améliorer vos flux de travail avec des technologies d''IA comme do-what","de":"Erfahren Sie, wie Sie den intelligenten Automatisierungsagenten konfigurieren und nutzen können, um Ihre Arbeitsabläufe mit Technologien wie do-what zu verbe...","pt":"Aprenda a configurar o agente de automação inteligente para melhorar a eficiência do seu workflow com técnicas de memória de engenharia","ru":"Узнайте, как настроить ИИ агента автоматизации для улучшения эффективности вашего рабочего процесса с помощью инженерных методов памяти","ar":"تعلم كيفية إعداد وكيل التلقائية الذكية لتحسين كفاءة تدفق العمل باستخدام تقنيات الذاكرة الهندسية"},"definition":{"en":"agent-automation-smart-agent is a custom skill for automating tasks, emphasizing hierarchical topology and memory pattern storage for AI agents.","zh":"agent-automation-smart-agent 是一个用于测试工程记忆能力的 AI 工作台","ja":"agent-automation-smart-agent は、エンジニアリング メモリ能力をテストする AI エージェント","ko":"agent-automation-smart-agent 는 엔지니어링 메모리 능력을 테스트하는 지능형 에이전트","es":"Un agente de automatización inteligente es un software que utiliza técnicas de IA para automatizar tareas y mejorar la eficiencia","fr":"Un agent d''automatisation intelligent est un logiciel qui utilise des techniques d''IA pour automatiser des tâches et améliorer l''efficacité","de":"Ein intelligenter Automatisierungsagent ist eine Software, die Techniken der KI nutzt, um Aufgaben zu automatisieren und die Effizienz zu verbessern","pt":"O que é um agente de automação inteligente? É uma plataforma que testa a capacidade de memória de engenharia para melhorar a eficiência","ru":"Что такое ИИ агент автоматизации? Это платформа, которая тестирует способность инженерной памяти для улучшения эффективности","ar":"ما هو وكيل التلقائية الذكية؟ منصة تختبر القدرة على الذاكرة الهندسية لتحسين الكفاءة"},"features":{"en":["Triggers automation based on defined conditions","Skips unnecessary tasks using specific criteria","Utilizes hierarchical topology for coordination","Stores successful patterns after completion","Documents new learnings for future improvements"],"zh":["核心目标是进行对工程记忆能力的架构测试","使用分层拓扑结构进行协调","存储成功的模式以实现自我改进","记录新的学习成果"],"ja":["エンジニアリング メモリ能力のアーキテクチャ テストを実行","階層型トポロジーを使用して協調","成功したパターンを保存して自我改進を実現","新しい学習成果を記録"],"ko":["엔지니어링 메모리 능력의 아키텍처 테스트를 수행","계층형 토폴로지를 사용하여 협조","성공한 패턴을 저장하여 자가 개선을 실현","新的 학습 성과를 기록"],"es":["Arquitectura de memoria para el aprendizaje continuo","Topología jerárquica para la coordinación","Almacenamiento de patrones exitosos después de la finalización","Documentación de nuevos conocimientos"],"fr":["Architecture de mémoire pour l''apprentissage continu","Topologie hiérarchique pour la coordination","Stockage de modèles réussis après l''achèvement","Documentation de nouvelles connaissanc