INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('soundcheck-capital/closing-form/stripe-best-practices', 'stripe-best-practices', 'soundcheck-capital', 'closing-form', 'community', 'stripe-best-practices soundcheck-capital closing-form community The stripe-best-practices skill provides technical guidance for developers integrating Stripe payments, ensuring a smooth go-live process with the latest API version. 本指南提供了Stripe API的最佳实践，包括如何使用最新版本和集成选项来优化您的支付系统 このガイドでは、Stripe APIのベストプラクティスについて説明し、最新バージョンと統合オプションを使用して支払いシステムを最適化する方法を紹介します 이 가이드는 스트라이프 API의 최적화된 설정을 제공하며, 최신 버전과 통합 옵션을 사용하여 결제 시스템을 최적화하는 방법을 설명합니다 Integre Stripe de manera efectiva con nuestras mejores prácticas y checklist de lanzamiento Intégrez Stripe de manière efficace avec nos meilleures pratiques et checklist de lancement Integrieren Sie Stripe effektiv mit unseren Best-Practices und Launch-Checklist As melhores práticas para integrar a API Stripe, incluindo a versão 2026-01-28.clover e checklist de pré-lançamento Лучшие практики интеграции API Stripe, включая версию 2026-01-28.clover и чек-лист перед запуском أفضل الممارسات لتكامل واجهة برمجة تطبيقات سترايب، بما في ذلك الإصدار 2026-01-28.clover وقائمة التحقق قبل الإطلاق how to use stripe-best-practices stripe-best-practices setup guide stripe integration best practices stripe api version 2026-01-28.clover what is stripe-best-practices stripe payments integration tutorial stripe go live checklist stripe integration options documentation Stripe最佳实践 Stripe API 支付系统优化 AI工具 集成选项 API Tour Go Live Checklist Utilizes the latest Stripe API version (2026-01-28.clover) for integrations References Stripe''s Integration Options documentation for design guidance Leverages the API Tour for a comprehensive understanding of Stripe payments Employs the Go Live Checklist to ensure a smooth transition to production Prioritizes documentation from Stripe''s official resources for accuracy stripe-best-practices is a set of guidelines for optimizing Stripe integrations, focusing on the latest API version and best practices for going live');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Hakuya5247/yomicord/repo-guardrails', 'community', 'Hakuya5247', 'yomicord', 'Hakuya5247/yomicord', 'repo-guardrails', 0, 0, 23, '2026-03-06T12:59:22.240Z', '2026-03-06T14:27:22.283Z', '1bdd0c7d9c098bc50212f0cadd09671cdf57bef2e522b7428264139da9a19b19', '{"id":"Hakuya5247/yomicord/repo-guardrails","name":"repo-guardrails","description":{"en":"repo-guardrails is a skill that enforces absolute rules within a repository, ensuring secure data access and compliance. It benefits developers by limiting database access and enforcing API input/output definitions.","zh":"repo-guardrails 是一种代码仓库安全保障工具，强制执行绝对规则，包括数据库访问控制和 API 输入输出定义","ja":"repo-guardrails はコードリポジトリのセキュリティを強化するツールです。絶対ルールを強制的に実施し、データベースへのアクセス制限や API の入出力定義を行います","ko":"repo-guardrails 는 코드 저장소 보안을 강화하는 도구입니다. 절대 규칙을 강제로 실행하여 데이터베이스 접근 제한과 API 입력 출력 정의를 수행합니다","es":"repo-guardrails es una habilidad que fuerza reglas absolutas en los repositorios, limitando el acceso a la base de datos y restringiendo las dependencias","fr":"repo-guardrails est une compétence qui impose des règles absolues dans les dépôts, limitant l''accès à la base de données et restreignant les dépendances","de":"repo-guardrails ist eine Fähigkeit, die absolute Regeln in den Repositorys durchsetzt, den Zugriff auf die Datenbank beschränkt und Abhängigkeiten einschränkt","pt":"O repo-guardrails é uma ferramenta de controle de acesso que garante a segurança dos dados no repositório Git, definindo regras de acesso claras e automatizando a verificação de alterações","ru":"repo-guardrails - это инструмент контроля доступа, обеспечивающий безопасность данных в репозитории Git, определяющий четкие правила доступа и автоматизирующий проверку изменений с помощью ИИ Агентов","ar":"repo-guardrails هو أداة مراقبة الوصول التي تضمن أمان البيانات في مستودع Git، وتحدد قواعد الوصول الواضحة وتتألف من عمليات التحقق الآلية"},"seo":{"title":{"en":"repo-guardrails: Enforcement of Repository Rules for AI A...","zh":"repo-guardrails_SETUP GUIDE: 代码仓库安全保障","ja":"repo-guardrails セットアップガイド: リポジトリの絶対ルール強制","ko":"repo-guardrails 설정 가이드: 코드 저장소 보안 강화","es":"Configuración de repo-guardrails: Guía de implementación","fr":"Mise en place de repo-guardrails: Meilleures pratiques","de":"Einrichtung von repo-guardrails: Leitfaden für Entwickler","pt":"repo-guardrails: Guia de Configuração para Controle de Ac...","ru":"repo-guardrails: Руководство по настройке контроля доступ...","ar":"repo-guardrails: دليل الإعداد لمراقبة الوصول إلى المستودع"},"description":{"en":"Discover how repo-guardrails enforces absolute rules in your repository, ensuring secure access and compliance. Learn how to set up and use repo-guardrails t...","zh":"了解 repo-guardrails 的功能和特点，包括代码仓库安全保障和绝对规则强制，提高开发效率和安全性","ja":"repo-guardrails の機能と特徴を紹介します。コードリポジトリのセキュリティと絶対ルールを強制して、開発効率とセキュリティを向上させます","ko":"repo-guardrails 기능과 특징을 소개합니다. 코드 저장소 보안과 절대 규칙 강제로 개발 효율성과 보안성을 높입니다","es":"Aprende a configurar repo-guardrails para proteger tus repositorios con reglas absolutas y evitar accesos no autorizados a la base de datos","fr":"Découvrez comment mettre en place repo-guardrails pour sécuriser vos dépôts avec des règles absolues et prévenir les accès non autorisés à la base de données","de":"Erfahren Sie, wie Sie repo-guardrails einrichten, um Ihre Repositorys mit absoluten Regeln zu schützen und unbefugten Zugriff auf die Datenbank zu verhindern","pt":"Aprenda a configurar o repo-guardrails para controlar o acesso ao seu repositório Git e garantir a segurança dos seus dados com regras de acesso bem definidas","ru":"Узнайте, как настроить repo-guardrails для контроля доступа к вашему репозиторию Git и обеспечения безопасности ваших данных с помощью ИИ Агентов","ar":"تعرف على كيفية تكوين repo-guardrails لمراقبة الوصول إلى مستودعك Git وضمان أمان بياناتك باتباع قواعد الوصول المحددة"},"definition":{"en":"repo-guardrails is a repository rule enforcement skill that restricts database access, enforces API contracts, and limits file modifications to ensure secure and compliant development practices.","zh":"repo-guardrails 是一种代码仓库安全保障工具，用于强制执行绝对规则","ja":"repo-guardrails はコードリポジトリのセキュリティを強化するツールです","ko":"repo-guardrails 는 코드 저장소 보안을 강화하는 도구입니다","es":"repo-guardrails es una herramienta de AI que impone reglas de seguridad en los repositorios para prevenir accesos no autorizados","fr":"repo-guardrails est un outil d''IA qui impose des règles de sécurité dans les dépôts pour prévenir les accès non autorisés","de":"repo-guardrails ist ein AI-Tool, das Sicherheitsregeln in den Repositorys durchsetzt, um unbefugten Zugriff zu verhindern","pt":"repo-guardrails é uma ferramenta de controle de acesso que define regras de acesso claras para o repositório Git","ru":"repo-guardrails - это инструмент контроля доступа, определяющий четкие правила доступа для репозитория Git с помощью ИИ Агентов","ar":"repo-guardrails هو أداة مراقبة الوصول التي تحدد قواعد الوصول الواضحة لمستودع Git"},"features":{"en":["Enforces database access restriction to apps/api only","Prevents direct database access from apps/bot","Validates API input/output definitions against packages/contracts","Automates read-only commands like git status and git diff","Requires pre-approval for destructive or external commands","Limits file modifications to prevent unintended changes"],"zh":["数据库访问控制：仅允许 apps/api 访问数据库","API 输入输出定义：使用 packages/contracts 定义 API 输入输出","代码更改限制：禁止更改未经请求的文件或目录","命令执行控制：自动执行读取专用命令，手动确认破坏性命令"],"ja":["データベースアクセス制限：apps/api からのデータベースアクセスのみを許可","API 入出力定義：packages/contracts を使用して API 入出力定義","コード変更制限：依頼されていないファイルやディレクトリの変更を禁止","コマンド実行制御：読み取り専用コマンドの自動実行、破壊的コマンドの事前確認"],"ko":["데이터베이스 접근 제한：apps/api 에서 데이터베이스 접근만 허용","API 입력 출력 정의：packages/contracts 를 사용하여 API 입력 출력 정의","코드 변경 제한：요청되지 않은 파일이나 디렉토리의 변경을 금지","명령어 실행 제어：읽기 전용 명령어의 자동 실행, 파괴적 명령어의 사전 확인"],"es":["Limitación del acceso a la base de datos a través de apps/api","Restricción de las dependencias para evitar conflictos","Validación de las definiciones de entrada y salida de la API","Detección de cambios no autorizados en el repositorio","Automatización de comandos de lectura para mejorar la eficiencia"],"fr":["Limitation de l''accès à la base de données via apps/api","Restricción des dépendances pour éviter les conflits","Validation des définitions d''entrée et de sortie de l''API","Détection de modifications non autorisées dans le dépôt","Automatisation des commandes de lecture pour améliorer l''efficacité"],"de":["Einschränkung des Zugriffs auf die Datenbank über apps/api","Beschränkung der Abhängigkeiten, um Konflikte zu vermeiden","Validierung der Eingabe- und Ausgabedefinitionen der API","Erkennung von nicht autorisierten Änderungen im Repository","Automatisierung von Lesebefehlen, um die Effizienz zu verbessern"],"pt":["Controle de acesso ao repositório Git","Definição de regras de acesso claras","Automação da verificação de alterações","Restrição de acesso à base de dados","Verificação de dependências não declaradas","Limitação de alterações em arquivos e diretórios"],"ru":["Контроль доступа к репозиторию Git","Определение четких правил доступа","Автоматизация проверки изменений","Ограничение доступа к базе данных","Проверка не объявленных зависимостей","Ограничение изменений в файлах и директориях с помощью ИИ Агентов"],"ar":["مراقبة الوصول إلى مستودع Git","تحديد قواعد الوصول الواضحة","التأليف الآلي لعمليات التحقق","تحديد الوصول إلى قاعدة البيانات","التحقق من التبعيات غير المعلنة","تحديد التغييرات في الملفات والمجلدات"]},"keywords":{"en":["how to use repo-guardrails","repo-guardrails setup guide","repo-guardrails vs git hooks","repo-guardrails install","what is repo-guardrails","repo-guardrails alternative","repo-guardrails for AI agents","enforcing repository rules","secure data access with repo-guardrails","repo-guardrails best practices"],"zh":["代码仓库安全","repo-guardrails","AI エージェント","代码安全保障","数据库访问控制","API 输入输出定义","代码更改限制","命令执行控制"],"ja":["コードリポジトリのセキュリティ","repo-guardrails","AI エージェント","コードセキュリティ","データベースアクセス制限","API 入出力定義","コード変更制限","コマンド実行制御"],"ko":["코드 저장소 보안","repo-guardrails","AI 에이전트","코드 보안","데이터베이스 접근 제한","API 입력 출력 정의","코드 변경 제한","명령어 실행 제어"],"es":["repo-guardrails","seguridad de la base de datos","reglas de seguridad","acceso no autorizado","dependencias","API","herramientas de AI","desarrollo de software","gestión de repositorios"],"fr":["repo-guardrails","sécurité de la base de données","règles de sécurité","accès non autorisé","dépendances","API","outils d''IA","développement de logiciels","gestion de dépôts"],"de":["repo-guardrails","Datenbanksicherheit","Sicherheitsregeln","unbefugter Zugriff","Abhängigkeiten","API","AI-Tools","Softwareentwicklung","Repository-Management"],"pt":["repo-guardrails","controle de acesso","regras de acesso","segurança de dados","Git","automação de verificação","restrição de acesso","dependências não declaradas"],"ru":["repo-guardrails","контроль доступа","правила доступа","безопасность данных","Git","автоматизация проверки","ограничение доступа","не объявленные зависимости","ИИ Агенты"],"ar":["repo-guardrails","مراقبة الوصول","قواعد الوصول","أمان البيانات","Git","التأليف الآلي","تحديد الوصول","التبعيات غير المعلنة","أدوات الذكاء الاصطناعي"]}},"owner":"Hakuya5247","repo":"yomicord","repoPath":"Hakuya5247/yomicord","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.240Z","topics":[],"category":"community","skillMd":{"name":"repo-guardrails","description":"リポジトリの絶対ルール（DB境界・契約ファースト・作業範囲制御）を強制する","bodyPreview":"# repo-guardrails\n\nこの skill は、リポジトリにおける絶対ルールを強制する。\n\n## 絶対ルール\n\n- データベースへのアクセスは `apps/api` のみに限定する。\n- `apps/bot` からデータベースへ直接アクセスしない。\n- API の入出力定義は `packages/contracts` を正とする。\n\n## 作業範囲\n\n- 依頼されていないファイルやディレクトリを変更しない。\n- 明示されていない依存関係の追加を行わない。\n- 差分が約200行を超える見込みの場合、作業を止めて確認を求める。\n\n## コマンド実行\n\n- 読み取り専用コマンドは自動実行してよい（例: git status, git diff, git grep, ls）。\n- 破壊的または外部影響のあるコマンドは事前確認を行う。","body":"# repo-guardrails\n\nこの skill は、リポジトリにおける絶対ルールを強制する。\n\n## 絶対ルール\n\n- データベースへのアクセスは `apps/api` のみに限定する。\n- `apps/bot` からデータベースへ直接アクセスしない。\n- API の入出力定義は `packages/contracts` を正とする。\n\n## 作業範囲\n\n- 依頼されていないファイルやディレクトリを変更しない。\n- 明示されていない依存関係の追加を行わない。\n- 差分が約200行を超える見込みの場合、作業を止めて確認を求める。\n\n## コマンド実行\n\n- 読み取り専用コマンドは自動実行してよい（例: git status, git diff, git grep, ls）。\n- 破壊的または外部影響のあるコマンドは事前確認を行う。\n"},"lastSynced":"2026-03-06T14:27:22.283Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing strict repository access control and compliance enforcement.","zh":"适用于需要严格仓库访问控制和合规性执行的代码审查代理。","ja":"コードレビューエージェントが厳格なリポジトリアクセス制御とコンプライアンスの適用を必要とする場合に最適です。","ko":"코드 리뷰 에이전트가 엄격한 저장소 액세스 제어 및 규정 준수를 필요로 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan un control de acceso estricto al repositorio y cumplimiento normativo.","fr":"Parfait pour les Agents de Révision de Code nécessitant un contrôle d''accès strict aux référentiels et une application des normes.","de":"Perfekt für Code-Review-Agents, die eine strenge Zugriffskontrolle auf das Repository und Einhaltung von Vorschriften benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de controle de acesso estrito ao repositório e aplicação de conformidade.","ru":"Идеально для агентов кодового обзора, требующих строгого контроля доступа к репозиторию и обеспечения соблюдения требований.","ar":"مثالي للوكلاء المراجعة الكودية الذين يحتاجون إلى سيطرة الوصول المخزن الصارم وتطبيق الامتثال."},"recommendation":{"en":"Enforces absolute rules within a repository, ensuring secure data access and compliance by limiting database access to specific directories like `apps/api` and enforcing API input/output definitions through `packages/contracts`.","zh":"在仓库内强制执行绝对规则，通过限制数据库访问到特定目录（如 `apps/api` ）并通过 `packages/contracts` 强制执行 API 输入/输出定义，确保安全的数据访问和合规性。","ja":"リポジトリ内で絶対ルールを強制適用し、データベースへのアクセスを特定のディレクトリ（例： `apps/api` ）に制限し、`packages/contracts` を介して API の入出力定義を強制適用して、安全なデータアクセスとコンプライアンスを確保します。","ko":"저장소 내에서 절대 규칙을 강제로 적용하여 데이터베이스 액세스를 특정 디렉토리(`apps/api`)로 제한하고 `packages/contracts`를 통해 API 입력/출력 정의를 강제 적용하여 안전한 데이터 액세스와 규정 준수를 보장합니다.","es":"Aplica reglas absolutas dentro de un repositorio, asegurando un acceso seguro a los datos y el cumplimiento normativo limitando el acceso a la base de datos a directorios específicos como `apps/api` y aplicando definiciones de entrada/salida de API a través de `packages/contracts`.","fr":" Applique des règles absolues au sein d''un référentiel, assurant un accès sécurisé aux données et le respect des normes en limitant l''accès à la base de données à des répertoires spécifiques comme `apps/api` et en appliquant des définitions d''entrée/sortie d''API via `packages/contracts`.","de":"Wendet absolute Regeln innerhalb eines Repositorys an, um sicherzustellen, dass der Datenzugriff sicher ist und die Vorschriften eingehalten werden, indem der Zugriff auf die Datenbank auf bestimmte Verzeichnisse wie `apps/api` beschränkt und API-Eingabe/Ausgabedefinitionen durch `packages/contracts` erzwungen werden.","pt":"Aplica regras absolutas dentro de um repositório, garantindo acesso de dados seguro e conformidade, limitando o acesso ao banco de dados a diretórios específicos como `apps/api` e aplicando definições de entrada/saída da API por meio de `packages/contracts`.","ru":"Применяет абсолютные правила внутри репозитория, обеспечивая безопасный доступ к данным и соблюдение требований, ограничивая доступ к базе данных до конкретных директорий, таких как `apps/api`, и применяя определения ввода/вывода API через `packages/contracts`.","ar":"تطبق قواعد مطلقة داخل مستودع، مما يضمن وصول بيانات آمن وامتثال، وقيود الوصول إلى قاعدة البيانات إلى دلائل محددة مثل `apps/api` وتطبيق تعريفات الإدخال والإخراج من قبل `packages/contracts`."},"useCases":{"en":["Enforcing database access restrictions","Validating API input/output definitions","Preventing unauthorized dependency additions","Automating compliance checks for code changes"],"zh":["强制执行数据库访问限制","验证 API 输入/输出定义","防止未经授权的依赖关系添加","自动执行代码更改的合规性检查"],"ja":["データベースアクセス制限の適用","API 入出力定義の検証","未承認の依存関係の追加の防止","コード変更のコンプライアンスチェックの自動化"],"ko":["데이터베이스 액세스 제한 강제 적용","API 입력/출력 정의 검증","승인되지 않은 의존성 추가 방지","코드 변경의 규정 준수 검사 자동화"],"es":["Aplicar restricciones de acceso a la base de datos","Validar definiciones de entrada/salida de API","Prevenir adiciones de dependencias no autorizadas","Automatizar controles de cumplimiento para cambios de código"],"fr":["Appliquer des restrictions d''accès à la base de données","Valider les définitions d''entrée/sortie d''API","Prévenir les ajouts de dépendances non autorisés","Automatiser les contrôles de conformité pour les modifications de code"],"de":["Zugriffsbeschränkungen für die Datenbank anwenden","API-Eingabe/Ausgabedefinitionen validieren","Nicht autorisierte Abhängigkeitsadditionen verhindern","Conformitätsprüfungen für Codeänderungen automatisieren"],"pt":["Aplicar restrições de acesso ao banco de dados","Validar definições de entrada/saída da API","Prevenir adições de dependências não autorizadas","Automatizar verificações de conformidade para alterações de código"],"ru":["Применение ограничений доступа к базе данных","Проверка определений ввода/вывода API","Предотвращение добавления неавторизованных зависимостей","Автоматизация проверок соблюдения требований для изменений кода"],"ar":["تطبيق قيود الوصول إلى قاعدة البيانات","تحقق من تعريفات الإدخال والإخراج من قبل","منع الإضافات التابعة غير المصرح بها","توفير التفتيش على الامتثال للتغييرات في الشفرة"]},"limitations":{"en":["Requires explicit definition of absolute rules","Limited to repository-level access control","May require manual confirmation for large code changes exceeding 200 lines"],"zh":["需要明确定义绝对规则","仅限于仓库级别的访问控制","可能需要手动确认大型代码更改（超过 200 行）"],"ja":["絶対ルールの明示的な定義が必要","リポジトリレベルのアクセス制御のみ","200 行を超える大規模なコード変更の場合、手動での確認が必要になる可能性がある"],"ko":["절대 규칙의 명시적 정의가 필요","저장소 수준의 액세스 제어만","200행을 넘는 대규모 코드 변경의 경우 수동 확인이 필요할 수 있음"],"es":["Requiere una definición explícita de reglas absolutas","Limitado al control de acceso a nivel de repositorio","Puede requerir confirmación manual para grandes cambios de código que excedan las 200 líneas"],"fr":["Nécessite une définition explicite de règles absolues","Limité au contrôle d''accès au niveau du référentiel","Peut nécessiter une confirmation manuelle pour les grands changements de code dépassant les 200 lignes"],"de":["Benötigt eine explizite Definition absoluter Regeln","Begrenzt auf die Zugriffskontrolle auf Repository-Ebene","Kann manuelle Bestätigung für große Codeänderungen über 200 Zeilen erfordern"],"pt":["Exige definição explícita de regras absolutas","Limitado ao controle de acesso ao nível do repositório","Pode exigir confirmação manual para alterações de código grandes que excedam 200 linhas"],"ru":["Требует явного определения абсолютных правил","Ограничен до контроля доступа на уровне репозитория","Может требовать ручного подтверждения для крупных изменений кода, превышающих 200 строк"],"ar":["يتطلب تعريفًا صريحًا للقواعد المطلقة","محدود بالتحكم في الوصول إلى مستوى المستودع","يمكن أن يتطلب تأكيدًا يدويًا للتغييرات الكبيرة في الشفرة التي تتجاوز 200 سطرًا"]},"version":4},"contentHash":"1bdd0c7d9c098bc50212f0cadd09671cdf57bef2e522b7428264139da9a19b19","qualityScore":23}');
