INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Hakuya5247/yomicord/repo-guardrails', 'repo-guardrails', 'Hakuya5247', 'yomicord', 'community', 'repo-guardrails Hakuya5247 yomicord community repo-guardrails is a skill that enforces absolute rules within a repository, ensuring secure data access and compliance. It benefits developers by limiting database access and enforcing API input/output definitions. repo-guardrails 是一种代码仓库安全保障工具，强制执行绝对规则，包括数据库访问控制和 API 输入输出定义 repo-guardrails はコードリポジトリのセキュリティを強化するツールです。絶対ルールを強制的に実施し、データベースへのアクセス制限や API の入出力定義を行います repo-guardrails 는 코드 저장소 보안을 강화하는 도구입니다. 절대 규칙을 강제로 실행하여 데이터베이스 접근 제한과 API 입력 출력 정의를 수행합니다 repo-guardrails es una habilidad que fuerza reglas absolutas en los repositorios, limitando el acceso a la base de datos y restringiendo las dependencias repo-guardrails est une compétence qui impose des règles absolues dans les dépôts, limitant l''accès à la base de données et restreignant les dépendances repo-guardrails ist eine Fähigkeit, die absolute Regeln in den Repositorys durchsetzt, den Zugriff auf die Datenbank beschränkt und Abhängigkeiten einschränkt O repo-guardrails é uma ferramenta de controle de acesso que garante a segurança dos dados no repositório Git, definindo regras de acesso claras e automatizando a verificação de alterações repo-guardrails - это инструмент контроля доступа, обеспечивающий безопасность данных в репозитории Git, определяющий четкие правила доступа и автоматизирующий проверку изменений с помощью ИИ Агентов repo-guardrails هو أداة مراقبة الوصول التي تضمن أمان البيانات في مستودع Git، وتحدد قواعد الوصول الواضحة وتتألف من عمليات التحقق الآلية how to use repo-guardrails repo-guardrails setup guide repo-guardrails vs git hooks repo-guardrails install what is repo-guardrails repo-guardrails alternative repo-guardrails for AI agents enforcing repository rules secure data access with repo-guardrails repo-guardrails best practices 代码仓库安全 repo-guardrails AI エージェント 代码安全保障 数据库访问控制 API 输入输出定义 代码更改限制 命令执行控制 Enforces database access restriction to apps/api only Prevents direct database access from apps/bot Validates API input/output definitions against packages/contracts Automates read-only commands like git status and git diff Requires pre-approval for destructive or external commands Limits file modifications to prevent unintended changes repo-guardrails is a repository rule enforcement skill that restricts database access, enforces API contracts, and limits file modifications to ensure secure and compliant development practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yiyousiow000814/API-Router/codex-deepwiki', 'community', 'yiyousiow000814', 'API-Router', 'yiyousiow000814/API-Router', 'codex-deepwiki', 0, 0, 23, '2026-03-01T17:53:31Z', '2026-03-07T13:12:30.150Z', '3c6e7105999edb92b66389a5771a3318cb58bb8cc9ff65c7dc79e1d282d78cb7', '{"id":"yiyousiow000814/API-Router/codex-deepwiki","name":"codex-deepwiki","description":{"en":"codex-deepwiki is an API router for Codex that provides a local gateway, provider switching, and failover. It benefits developers by streamlining project internals.","zh":"codex-deepwiki 是一个 API 路由器，提供本地网关、提供者切换和故障转移功能","ja":"codex-deepwiki は API ルーターであり、ローカルゲートウェイ、プロバイダ切り替え、フォールトオーバー機能を提供します","ko":"codex-deepwiki는 API 라우터로, 로컬 게이트웨이, 제공자 전환, 장애 조치 기능을 제공합니다","es":"codex-deepwiki es una habilidad que proporciona un enrutador de API local y permite la conmutación entre proveedores y la conmutación por error","fr":"codex-deepwiki est une compétence qui fournit un routeur d''API local et permet la commutation entre les fournisseurs et la commutation d''urgence","de":"codex-deepwiki ist eine Fähigkeit, die einen lokalen API-Router bereitstellt und die Anbieterumstellung und Fehlerübernahme ermöglicht","pt":"O Codex-Deepwiki é um API Router para consultas de projetos internos, fornecendo links e fluxos de trabalho mínimos para verificar comportamentos contra documentação e código local","ru":"Codex-Deepwiki - это API Router для запросов проектных внутренностей, предоставляющий ссылки и минимальный рабочий процесс для проверки поведения против документации и локального кода","ar":"Codex-Deepwiki هو وسيط API لاستفسارات المشاريع الداخلية ، يوفر روابط وعمليات عمل حداقل للتحقق من السلوك ضد الوثائق والكود المحلي"},"seo":{"title":{"en":"codex-deepwiki: API Router Setup Guide | AI Agent Skill","zh":"codex-deepwiki 设置指南：API 路由器和本地网关","ja":"codex-deepwiki セットアップガイド：API ルーターとローカルゲートウェイ","ko":"codex-deepwiki 설정 안내: API 라우터 및 로컬 게이트웨이","es":"Guía de configuración de codex-deepwiki para desarrolladores","fr":"Guide d''installation de codex-deepwiki pour les développeurs","de":"Einrichtungsleitfaden für codex-deepwiki-Entwickler","pt":"Guia de Configuração do Codex-Deepwiki: API Router para D...","ru":"Настройка Codex-Deepwiki: ИИ Агенты для API Router","ar":"دليل إعداد Codex-Deepwiki: وسيط API للبرمجة"},"description":{"en":"Discover how codex-deepwiki simplifies project internals with its local gateway and provider switching. Learn to set it up now!","zh":"了解 codex-deepwiki 的技术细节，包括 API 路由、提供者切换和故障转移","ja":"codex-deepwiki の技術的な詳細を学びます。API ルーティング、プロバイダ切り替え、フォールトオーバーなど","ko":"codex-deepwiki의 기술적 세부 정보를 알아보세요. API 라우팅, 제공자 전환, 장애 조치 등","es":"Aprende a implementar codex-deepwiki como API Router para gestionar proveedores y conmutación por error","fr":"Découvrez comment mettre en œuvre codex-deepwiki comme API Router pour gérer les fournisseurs et la commutation d''urgence","de":"Erfahren Sie, wie Sie codex-deepwiki als API-Router für die Anbieterverwaltung und Fehlerübernahme einsetzen","pt":"Aprenda a configurar o Codex-Deepwiki para consultas de projetos internos e obtenha links e fluxos de trabalho mínimos para verificar comportamentos contra d...","ru":"Узнайте, как настроить Codex-Deepwiki для запросов проектных внутренностей и получить ссылки и минимальный рабочий процесс для проверки поведения против доку...","ar":"تعرف على كيفية تهيئة Codex-Deepwiki لاستفسارات المشاريع الداخلية وحصل على روابط وعمليات عمل حداقل للتحقق من السلوك ضد الوثائق والكود المحلي"},"definition":{"en":"codex-deepwiki is an API router skill that enables local gateway, provider switching, and failover for Codex, facilitating project internal management.","zh":"codex-deepwiki 是一个用于项目内部问题的 API 路由器","ja":"codex-deepwiki はプロジェクト内部の問題に対する API ルーターです","ko":"codex-deepwiki는 프로젝트 내부 문제를 위한 API 라우터입니다","es":"codex-deepwiki es un agente de IA que actúa como enrutador de API para la gestión de proveedores","fr":"codex-deepwiki est un agent IA qui agit comme routeur d''API pour la gestion des fournisseurs","de":"codex-deepwiki ist ein IA-Agent, der als API-Router für die Anbieterverwaltung fungiert","pt":"O Codex-Deepwiki é um skill que fornece uma API Router para consultas de projetos internos","ru":"Codex-Deepwiki - это навык, который предоставляет API Router для запросов проектных внутренностей","ar":"Codex-Deepwiki هو مهارة توفر وسيط API لاستفسارات المشاريع الداخلية"},"features":{"en":["Provides links to relevant DeepWiki pages for project internal verification","Supports minimal workflow to verify behavior against documentation and local code","Enables extraction of exact behavior, paths, and precedence from DeepWiki pages","Allows for quoting and summarizing behavior from DeepWiki references","Includes a list of relevant DeepWiki pages in references/deepwiki.md"],"zh":["API 路由","本地网关","提供者切换","故障转移","DeepWiki 页面访问","项目内部问题解决"],"ja":["API ルーティング","ローカルゲートウェイ","プロバイダ切り替え","フォールトオーバー","DeepWiki ページアクセス","プロジェクト内部問題解決"],"ko":["API 라우팅","로컬 게이트웨이","제공자 전환","장애 조치","DeepWiki 페이지 접근","프로젝트 내부 문제 해결"],"es":["Enrutador de API local para la gestión de proveedores","Conmutación entre proveedores para garantizar la disponibilidad","Conmutación por error para minimizar el tiempo de inactividad","Integración con DeepWiki para la documentación y verificación del comportamiento","Flujo de trabajo minimalista para la verificación del comportamiento contra la documentación"],"fr":["Routeur d''API local pour la gestion des fournisseurs","Commutation entre les fournisseurs pour assurer la disponibilité","Commutation d''urgence pour minimiser le temps d''arrêt","Intégration avec DeepWiki pour la documentation et la vérification du comportement","Flux de travail minimaliste pour la vérification du comportement contre la documentation"],"de":["Lokaler API-Router für die Anbieterverwaltung","Anbieterumstellung für die Gewährleistung der Verfügbar