INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yiyousiow000814/API-Router/codex-deepwiki', 'codex-deepwiki', 'yiyousiow000814', 'API-Router', 'community', 'codex-deepwiki yiyousiow000814 API-Router community codex-deepwiki is an API router for Codex that provides a local gateway, provider switching, and failover. It benefits developers by streamlining project internals. codex-deepwiki 是一个 API 路由器，提供本地网关、提供者切换和故障转移功能 codex-deepwiki は API ルーターであり、ローカルゲートウェイ、プロバイダ切り替え、フォールトオーバー機能を提供します codex-deepwiki는 API 라우터로, 로컬 게이트웨이, 제공자 전환, 장애 조치 기능을 제공합니다 codex-deepwiki es una habilidad que proporciona un enrutador de API local y permite la conmutación entre proveedores y la conmutación por error codex-deepwiki est une compétence qui fournit un routeur d''API local et permet la commutation entre les fournisseurs et la commutation d''urgence codex-deepwiki ist eine Fähigkeit, die einen lokalen API-Router bereitstellt und die Anbieterumstellung und Fehlerübernahme ermöglicht O Codex-Deepwiki é um API Router para consultas de projetos internos, fornecendo links e fluxos de trabalho mínimos para verificar comportamentos contra documentação e código local Codex-Deepwiki - это API Router для запросов проектных внутренностей, предоставляющий ссылки и минимальный рабочий процесс для проверки поведения против документации и локального кода Codex-Deepwiki هو وسيط API لاستفسارات المشاريع الداخلية ، يوفر روابط وعمليات عمل حداقل للتحقق من السلوك ضد الوثائق والكود المحلي how to use codex-deepwiki codex-deepwiki setup guide codex-deepwiki alternative codex-deepwiki vs API gateway codex-deepwiki install what is codex-deepwiki codex-deepwiki documentation codex-deepwiki local gateway codex-deepwiki provider switching AIエージェント codex-deepwiki API 路由器 本地网关 提供者切换 故障转移 DeepWiki 项目内部问题解决 Provides links to relevant DeepWiki pages for project internal verification Supports minimal workflow to verify behavior against documentation and local code Enables extraction of exact behavior, paths, and precedence from DeepWiki pages Allows for quoting and summarizing behavior from DeepWiki references Includes a list of relevant DeepWiki pages in references/deepwiki.md codex-deepwiki is an API router skill that enables local gateway, provider switching, and failover for Codex, facilitating project internal management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Kotaro7750/typing_engine/document-update', 'community', 'Kotaro7750', 'typing_engine', 'Kotaro7750/typing_engine', 'document-update', 0, 0, 23, '2026-01-19T13:34:02Z', '2026-03-07T13:12:24.725Z', '68b846bba6398c60c2ce6b9da495539e8058886f5ec080c7db36ea15a2323e60', '{"id":"Kotaro7750/typing_engine/document-update","name":"document-update","description":{"en":"The document-update skill helps developers keep their Rust documentation aligned with current code by updating doc comments, non-doc comments, and README files. It supports Rust modules, public types, and functions.","zh":"文档更新工具是一种 Rust 代码库，用于创建输入游戏，支持日语和英语。它可以保持代码和文档的同步，提高代码质量和可维护性","ja":"ドキュメント更新ツールは、Rust コードライブラリであり、日本語と英語をサポートする入力ゲームを作成するために使用されます。コードとドキュメントを同期させ、コード品質とメンテナンス性を向上させます","ko":"문서 업데이트 도구는 Rust 코드 라이브러리로서 일본어와 영어를 지원하는 입력 게임을 만들기 위해 사용됩니다. 코드와 문서를同步시키고 코드 품질과 유지보수성을 향상시킵니다","es":"La biblioteca document-update ayuda a mantener la documentación actualizada con el código más reciente, soportando Rust y README","fr":"La bibliothèque document-update aide à maintenir la documentation à jour avec le code le plus récent, en prenant en charge Rust et README","de":"Die Bibliothek document-update hilft dabei, die Dokumentation mit dem neuesten Code aktuell zu halten, einschließlich Rust und README","pt":"O Document-Update é uma biblioteca para manter a documentação sincronizada com o código, incluindo comentários em Rust e arquivos README","ru":"Document-Update - это библиотека для поддержания документации в синхронизации с кодом, включая комментарии в Rust и файлы README","ar":"أداة تحديث الوثائق هي مكتبة للحفاظ على توافق الوثائق مع الكود، بما في ذلك تعليقات Rust وملفات README"},"seo":{"title":{"en":"document-update: Rust Documentation Setup Guide | AI Agen...","zh":"文档更新工具：Rust 代码同步指南","ja":"ドキュメント更新ツール：Rust コード同期ベストプラクティス","ko":"문서 업데이트 도구: Rust 코드同步 가이드","es":"Guía de configuración de document-update para mantener la...","fr":"Mise à jour de document : guide de configuration pour les...","de":"Document-Update-Setup: Anleitung für Entwickler zur Aktua...","pt":"Guia de Configuração do Document-Update para Ferramentas ...","ru":"Настройка ИИ Агентов: Document-Update Руководство","ar":"دليل إعداد أداة تحديث الوثائق للأدوات الذكية"},"description":{"en":"Learn how to keep your Rust docs and comments up-to-date with document-update. Discover the workflow and best practices for aligning code and documentation.","zh":"使用文档更新工具保持 Rust 代码和文档的同步，提高代码质量和可维护性","ja":"ドキュメント更新ツールを使用して、Rust コードとドキュメントを同期させ、コード品質とメンテナンス性を向上させます","ko":"문서 업데이트 도구를 사용하여 Rust 코드와 문서를同步시키고 코드 품질과 유지보수성을 향상시키세요","es":"Aprende a utilizar document-update para mantener tus documentos y comentarios actualizados con el código más reciente, incluyendo Rust y README","fr":"Découvrez comment utiliser document-update pour maintenir vos documents et commentaires à jour avec le code le plus récent, y compris Rust et README","de":"Erfahren Sie, wie Sie document-update verwenden, um Ihre Dokumente und Kommentare mit dem neuesten Code, einschließlich Rust und README, aktuell zu halten","pt":"Aprenda a manter a documentação sincronizada com o código usando o Document-Update, uma biblioteca para criar jogos de digitação","ru":"Изучите, как поддерживать документацию в синхронизации с кодом с помощью Document-Update, библиотеки для создания игр набора текста","ar":"تعرف على كيفية الحفاظ على توافق الوثائق مع الكود باستخدام أداة تحديث الوثائق، مكتبة لإنشاء ألعاب الكتابة"},"definition":{"en":"document-update is a library crate for maintaining accurate and consistent Rust documentation, ensuring that comments and code remain in sync.","zh":"文档更新工具是一种自动化工具，用于保持 Rust 代码和文档的同步","ja":"ドキュメント更新ツールは、Rust コードとドキュメントを同期させるための自動化ツールです","ko":"문서 업데이트 도구는 Rust 코드와 문서를同步시키는 자동화 도구입니다","es":"Document-update es una herramienta de AI que ayuda a mantener la documentación actualizada con el código","fr":"Document-update est un outil d''IA qui aide à maintenir la documentation à jour avec le code","de":"Document-update ist ein AI-Tool, das hilft, die Dokumentation mit dem Code aktuell zu halten","pt":"O Document-Update é uma ferramenta de IA para manter a documentação atualizada e sincronizada com o código","ru":"Document-Update - это инструмент ИИ для поддержания документации в актуальном состоянии и синхронизации с кодом","ar":"أداة تحديث الوثائق هي أداة ذكية لتحديث الوثائق وضمان توافقها مع الكود"},"features":{"en":["Updates Rust doc comments to reflect current code","Supports synchronization of non-doc comments with code changes","Automatically updates README files to ensure consistency","Identifies and addresses out-of-sync files, including Rust modules and public types/functions","Treats current code as the source of truth, preventing unnecessary changes"],"zh":["支持日语和英语","保持 Rust 代码和文档的同步","自动更新 README 和非文档注释","不改变代码行为或 API","识别更改或不同步的文件"],"ja":["日本語と英語をサポート","Rust コードとドキュメントを同期させる","README と非ドキュメント注釈を自動更新","コードの動作や API を変更しない","変更または同期していないファイルを識別"],"ko":["일본어와 영어를 지원","Rust 코드와 문서를同步시키기","README 와 비문서 주석을 자동으로 업데이트","코드 동작이나 API 를 변경하지 않음","변경 또는 동기화되지 않은 파일을 식별"],"es":["Mantiene la documentación actualizada con el código más reciente","Soporta Rust y README","Permite la actualización de comentarios y documentación sin cambiar el comportamiento o las API","Establece el código como fuente de verdad para la documentación","Detiene la actualización si se requieren cambios en el código"],"fr":["Maintient la documentation à jour avec le code le plus récent","Prend en charge Rust et README","Permet la mise à jour des commentaires et de la documentation sans changer le comportement ou les API","Établit le code comme source de vérité pour la documentation","Arrête la mise à jour si des modifications de code sont nécessaires"],"de":["Hält die Dokumentation mit dem neuesten Code aktuell","Unterstützt Rust und README","Ermöglicht die Aktualisierung von Kommentaren und Dokumentation ohne Änderung des Verhaltens oder der API","Legt den Code als Quelle der Wahrheit für die Dokumentation fest","Stoppt die Aktualisierung, wenn Änderungen am Code erforderlich sind"],"pt":["Manter comentários em Rust atualizados","Sincronizar arquivos README com o código","Identificar arquivos que precisam ser atualizados","Tratar o código como fonte de verdade","Parar e perguntar se as alterações nos documentos implicam alterações no código"],"ru":["Поддерживать комментарии в Rust в актуальном состоянии","Синхронизировать файлы README с кодом","Определить файлы, которые необходимо обновить","Рассматривать код как источник истины","Остановиться и спросить, если изменения в документах подразумевают изменения в коде"],"ar":["الحفاظ على تعليقات Rust محدثة","تماشى ملفات README مع الكود","تحديد الملفات التي تحتاج إلى تحديث","معاملة الكود كمرجع","التوقف وسؤال إذا كانت التغييرات على الوثائق تشير إلى التغييرات في الكود"]},"keywords":{"en":["how to use document-update","document-update setup guide","Rust documentation best practices","document-update alternative","document-update vs rustdoc","keeping rust docs up-to-date","rust documentation workflow","document-update install","rust code commenting"],"zh":["Rust 代码库","文档更新工具","代码同步","输入游戏","日语支持","英语支持","自动化工具","代码质量","可维护性"],"ja":["Rust コードライブラリ","ドキュメント更新ツール","コード同期","入力ゲーム","日本語サポート","英語サポート","自動化ツール","コード品質","メンテナンス性"],"ko":["Rust 코드 라이브러리","문서 업데이트 도구","코드 동기화","입력 게임","일본어 지원","영어 지원","자동화 도구","코드 품질","유지보수성"],"es":["herramientas de AI para desarrolladores","document-update","Rust","README","mantenimiento de documentación","actualización de código","desarrollo de software","herramientas de desarrollo","IA para desarrolladores"],"fr":["outils d''IA pour les développeurs","document-update","Rust","README","maintenance de la documentation","mise à jour de code","développement de logiciels","outils de développement","IA pour les développeurs"],"de":["AI-Tools für Entwickler","document-update","Rust","README","Dokumentationspflege","Code-Aktualisierung","Software-Entwicklung","Entwicklungstools","KI für Entwickler"],"pt":["ferramentas de IA","documentação de código","comentários em Rust","arquivos README","sincronização de código","desenvolvimento de software","ferramentas de desenvolvimento","bibliotecas de código","jogos de digitação"],"ru":["инструменты ИИ","документация кода","комментарии в Rust","файлы README","синхронизация кода","разработка программного обеспечения","инструменты разработки","библиотеки кода","игры набора текста"],"ar":["أدوات ذكية","توثيق الكود","تعليقات Rust","ملفات README","تماشى الكود","تطوير البرمجيات","أدوات التطوير","مكتبات الكود","ألعاب الكتابة"]}},"owner":"Kotaro7750","repo":"typing_engine","repoPath":"Kotaro7750/typing_engine","stars":0,"forks":0,"updatedAt":"2026-01-19T13:34:02Z","topics":[],"category":"community","skillMd":{"name":"document-update","description":"Update documentation to match code and design changes in this repo. Use when code or design changes cause drift in Rust doc comments (module-level //! and item-level ///), non-doc comments, and README.md. Focus on intent, rationale, invariants, and relationships between major symbols rather than restating obvious names or signatures.","bodyPreview":"# Document Update\n\n## Overview\nKeep docs and comments aligned with the current code by updating Rust doc comments, non-doc comments, and README without changing behavior or APIs.\n\n## Workflow\n\n### 1) Establish scope and sources of truth\n- Identify which files changed or are likely out of sync (Rust modules, public types/functions, README).\n- Treat current code as the source of truth; do not change code while updating docs.\n- If doc changes imply code changes are needed, stop and ask.\n\n### 2) Rea","body":"# Document Update\n\n## Overview\nKeep docs and comments aligned with the current code by updating Rust doc comments, non-doc comments, and README without changing behavior or APIs.\n\n## Workflow\n\n### 1) Establish scope and sources of truth\n- Identify which files changed or are likely out of sync (Rust modules, public types/functions, README).\n- Treat current code as the source of truth; do not change code while updating docs.\n- If doc changes imply code changes are needed, stop and ask.\n\n### 2) Read existing tone and structure\n- Read the local section/module/file to match tone, language, and formatting.\n- If the file mixes languages, prefer the surrounding section’s language.\n- Keep README concise; do not inflate with speculative content.\n\n### 3) Update Rust doc comments\n- **Module-level `//!`**: Describe the module’s role, then explain relationships and differences between its major symbols (types/functions/modules) and how they fit together.\n- **Item-level `///`**: Explain design intent, invariants, constraints, tradeoffs, and non-obvious behavior. Avoid repeating obvious names, fields, or signatures.\n- Add/adjust examples only when they clarify non-obvious usage or invariants.\n\n### 4) Update non-doc comments (`//`, `/* */`)\n- Use comments for rationale and high-level flow of complex logic.\n- Avoid restating line-by-line behavior; prefer intent and “why.”\n- Remove or rewrite comments that are now misleading or redundant.\n\n### 5) Update README\n- Ensure summary, usage pointers, and examples align with current API and behavior.\n- Keep the README brief; link to docs.rs or other references when appropriate.\n\n### 6) Final consistency check\n- No code changes.\n- No stale terminology or outdated file/module names.\n- Comments do not contradict each other or the code.\n\n## Quality Checklist\n- Doc comments explain intent and invariants, not just “what.”\n- Module docs explain relationships/differences between key symbols.\n- Non-doc comments describe rationale or flow for complex sections.\n- README aligns with current public API and behavior.\n- Language and tone match the existing file.\n\n## References\n- `references/doc-style.md` for project-specific tone and conventions.\n"},"lastSynced":"2026-03-07T13:12:24.725Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Maintenance Agents needing automated Rust documentation updates.","zh":"非常适合需要自动化Rust文档更新的代码维护代理。","ja":"Rustのドキュメントを自動更新する必要があるコードメンテナンスエージェントに最適です。","ko":"자동화된 Rust 문서 업데이트가 필요한 코드 유지 보수 에이전트에 적합합니다.","es":"Perfecto para agentes de mantenimiento de código que necesitan actualizaciones automatizadas de documentación de Rust.","fr":"Idéal pour les agents de maintenance de code nécessitant des mises à jour automatiques de la documentation Rust.","de":"Perfekt für Code-Wartungsagenten, die automatisierte Rust-Dokumentationsupdates benötigen.","pt":"Perfeito para Agentes de Manutenção de Código que precisam de atualizações automatizadas de documentação Rust.","ru":"Идеально для Агентов по обслуживанию кода, которым необходимы автоматические обновления документации Rust.","ar":"مثالي للوكلاء المسؤولين عن صيانة الشفرة الذين يحتاجون إلى تحديثات وثائق Rust آليًا."},"recommendation":{"en":"Empowers agents to keep Rust documentation aligned with current code by updating doc comments, non-doc comments, and README files, ensuring consistency without changing behavior or APIs, and supporting Rust modules, public types, and functions.","zh":"赋予代理保持Rust文档与当前代码一致的能力，通过更新文档注释、非文档注释和README文件，确保一致性而不改变行为或API，并支持Rust模块、公共类型和函数。","ja":"エージェントがRustのドキュメントを最新のコードと一致させる能力を提供します。ドキュメントのコメント、非ドキュメントのコメント、READMEファイルを更新し、一貫性を保ちながら動作やAPIを変更せず、Rustモジュール、公開型、関数をサポートします。","ko":"에이전트가 현재 코드와 일치하는 Rust 문서를 유지할 수 있는 능력을 제공합니다. 문서 주석, 비문서 주석 및 README 파일을 업데이트하여 일관성을 유지하면서 동작 또는 API를 변경하지 않으며 Rust 모듈, 공개 유형 및 함수를 지원합니다.","es":"Habilita a los agentes a mantener la documentación de Rust alineada con el código actual, actualizando comentarios de documentación, comentarios no documentados y archivos README, garantizando la consistencia sin cambiar el comportamiento o las API, y admitiendo módulos de Rust, tipos públicos y funciones.","fr":"Permet aux agents de maintenir la documentation Rust à jour avec le code actuel en mettant à jour les commentaires de documentation, les commentaires non documentés et les fichiers README, en garantissant la cohérence sans modifier le comportement ou les API, et en prenant en charge les modules Rust, les types publics et les fonctions.","de":"Ermächtigt Agenten, die Rust-Dokumentation mit dem aktuellen Code in Einklang zu halten, indem sie Dokumentationskommentare, nicht dokumentierte Kommentare und README-Dateien aktualisieren, die Konsistenz ohne Änderung des Verhaltens oder der APIs sicherstellen und Rust-Module, öffentliche Typen und Funktionen unterstützen.","pt":"Habilita os agentes a manter a documentação Rust alinhada com o código atual, atualizando comentários de documentação, comentários não documentados e arquivos README, garantindo a consistência sem alterar o comportamento ou as APIs, e suportando módulos Rust, tipos públicos e funções.","ru":"Наделяет агентов возможностью поддерживать документацию Rust в соответствии с текущим кодом, обновляя комментарии документации, некомментированные комментарии и файлы README, обеспечивая согласованность без изменения поведения или API, и поддерживая модули Rust, публичные типы и функции.","ar":"تمكّن الوكلاء من الحفاظ على توافق وثائق Rust مع الشفرة الحالية عن طريق تحديث تعليقات الوثائق والتعليقات غير المضمنة في الوثائق وملفات README، مما يضمن الاتساق دون تغيير السلوك أو واجهات برمجة التطبيقات، ودعم وحدات Rust والأنواع العامة والدوال."},"useCases":{"en":["Updating Rust doc comments for public types and functions","Synchronizing README files with current codebase","Maintaining consistency between code and documentation for Rust modules"],"zh":["为公共类型和函数更新Rust文档注释","将README文件与当前代码库同步","维护代码和文档之间的一致性，适用于Rust模块"],"ja":["公開型と関数のRustドキュメントのコメントを更新する","READMEファイルを最新のコードベースと同期する","コードとドキュメントの間の一貫性を維持する、Rustモジュールに対応"],"ko":["공개 유형 및 함수에 대한 Rust 문서 주석을 업데이트하는 것","README 파일을 현재 코드베이스와 동기화하는 것","코드와 문서 간의 일관성을 유지하는 것, Rust 모듈을 위한 것"],"es":["Actualización de comentarios de documentación de Rust para tipos y funciones públicos","Sincronización de archivos README con la base de código actual","Mantenimiento de la consistencia entre el código y la documentación para módulos de Rust"],"fr":["Mise à jour des commentaires de documentation Rust pour les types et les fonctions publiques","Synchronisation des fichiers README avec la base de code actuelle","Maintenance de la cohérence entre le code et la documentation pour les modules Rust"],"de":["Aktualisierung von Rust-Dokumentationskommentaren für öffentliche Typen und Funktionen","Synchronisierung von README-Dateien mit dem aktuellen Codebestand","Beibehaltung der Konsistenz zwischen Code und Dokumentation für Rust-Module"],"pt":["Atualizar comentários de documentação Rust para tipos e funções públicos","Sincronizar arquivos README com a base de código atual","Manter a consistência entre o código e a documentação para módulos Rust"],"ru":["Обновление комментариев документации Rust для публичных типов и функций","Синхронизация файлов README с текущей базой кода","Поддержание согласованности между кодом и документацией для модулей Rust"],"ar":["تحديث تعليقات وثائق Rust للأصناف والدوال العامة","تماشى ملفات README مع قاعدة الشفرة الحالية","الحفاظ على الاتساق بين الشفرة ووثائق وحدات Rust"]},"limitations":{"en":["Limited to Rust programming language","Does not modify code, only updates documentation","Requires identification of files changed or out of sync"],"zh":["仅限于Rust编程语言","不修改代码，只更新文档","需要识别已更改或不一致的文件"],"ja":["Rustプログラミング言語に限定される","コードを変更せず、ドキュメントのみを更新する","変更されたり同期が取れていないファイルを識別する必要がある"],"ko":["Rust 프로그래밍 언어에만 제한됨","코드를 수정하지 않고 문서만 업데이트함","변경되거나 동기화되지 않은 파일을 식별해야 함"],"es":["Limitado al lenguaje de programación Rust","No modifica el código, solo actualiza la documentación","Requiere la identificación de archivos modificados o desincronizados"],"fr":["Limité au langage de programmation Rust","Ne modifie pas le code, ne met à jour que la documentation","Nécessite l''identification des fichiers modifiés ou désynchronisés"],"de":["Begrenzt auf die Rust-Programmiersprache","Ändert den Code nicht, aktualisiert nur die Dokumentation","Erfordert die Identifizierung von geänderten oder nicht synchronisierten Dateien"],"pt":["Limitado à linguagem de programação Rust","Não modifica o código, apenas atualiza a documentação","Requer identificação de arquivos alterados ou fora de sincronia"],"ru":["Ограничен языком программирования Rust","Не изменяет код, только обновляет документацию","Требует идентификации изменённых или несинхронизированных файлов"],"ar":["محدود بلغة برمجة Rust","لا يعدل الشفرة، بل يقوم بتحديث الوثائق فقط","يتطلب تحديد الملفات المعدلة أو التي لا تتماشى"]},"version":4},"contentHash":"68b846bba6398c60c2ce6b9da495539e8058886f5ec080c7db36ea15a2323e60","qualityScore":23}');
