INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Kotaro7750/typing_engine/document-update', 'document-update', 'Kotaro7750', 'typing_engine', 'community', 'document-update Kotaro7750 typing_engine community The document-update skill helps developers keep their Rust documentation aligned with current code by updating doc comments, non-doc comments, and README files. It supports Rust modules, public types, and functions. 文档更新工具是一种 Rust 代码库，用于创建输入游戏，支持日语和英语。它可以保持代码和文档的同步，提高代码质量和可维护性 ドキュメント更新ツールは、Rust コードライブラリであり、日本語と英語をサポートする入力ゲームを作成するために使用されます。コードとドキュメントを同期させ、コード品質とメンテナンス性を向上させます 문서 업데이트 도구는 Rust 코드 라이브러리로서 일본어와 영어를 지원하는 입력 게임을 만들기 위해 사용됩니다. 코드와 문서를同步시키고 코드 품질과 유지보수성을 향상시킵니다 La biblioteca document-update ayuda a mantener la documentación actualizada con el código más reciente, soportando Rust y README La bibliothèque document-update aide à maintenir la documentation à jour avec le code le plus récent, en prenant en charge Rust et README Die Bibliothek document-update hilft dabei, die Dokumentation mit dem neuesten Code aktuell zu halten, einschließlich Rust und README O Document-Update é uma biblioteca para manter a documentação sincronizada com o código, incluindo comentários em Rust e arquivos README Document-Update - это библиотека для поддержания документации в синхронизации с кодом, включая комментарии в Rust и файлы README أداة تحديث الوثائق هي مكتبة للحفاظ على توافق الوثائق مع الكود، بما في ذلك تعليقات Rust وملفات README how to use document-update document-update setup guide Rust documentation best practices document-update alternative document-update vs rustdoc keeping rust docs up-to-date rust documentation workflow document-update install rust code commenting Rust 代码库 文档更新工具 代码同步 输入游戏 日语支持 英语支持 自动化工具 代码质量 可维护性 Updates Rust doc comments to reflect current code Supports synchronization of non-doc comments with code changes Automatically updates README files to ensure consistency Identifies and addresses out-of-sync files, including Rust modules and public types/functions Treats current code as the source of truth, preventing unnecessary changes document-update is a library crate for maintaining accurate and consistent Rust documentation, ensuring that comments and code remain in sync.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Itshalffull/Concept-Oriented-Programming-Framework/attribution', 'community', 'Itshalffull', 'Concept-Oriented-Programming-Framework', 'Itshalffull/Concept-Oriented-Programming-Framework', 'attribution', 0, 0, 23, '2026-03-06T19:45:52Z', '2026-03-07T13:12:53.089Z', '01d46e9860745791b1b058c466057dcb0f6835853cb296a410869d7258e87c38', '{"id":"Itshalffull/Concept-Oriented-Programming-Framework/attribution","name":"attribution","description":{"en":"Attribution is a concept-first, spec-first, multi-language programming framework that binds agent identity to content regions. It supports tracking who created or modified each piece of content.","zh":"Attribution是一个概念先、规范先的多语言编程框架，支持代码所有权和内容追踪","ja":"Attributionは概念先、規範先のマルチ言語プログラミングフレームワークで、コード所有権とコンテンツ追跡をサポート","ko":"Attribution은 개념 우선, 규약 우선의 멀티 언어 프로그래밍 프레임워크로 코드 소유권과 콘텐츠 추적을 지원","es":"La atribución es un concepto de programación que permite vincular la identidad de un agente a regiones de contenido, permitiendo el seguimiento de la autoría y la historia de modificaciones","fr":"L''attribution est un concept de programmation qui permet de lier l''identité d''un agent à des régions de contenu, permettant ainsi de suivre l''historique des modifications et l''authorship","de":"Die Attribution ist ein Programmierkonzept, das die Bindung der Agentenidentität an Inhaltsbereiche ermöglicht, um die Urheberschaft und die Änderungshistorie zu verfolgen","pt":"Atribuição é um framework de programação multilíngue que vincula a identidade do agente à região de conteúdo, permitindo o rastreamento de quem criou ou modificou cada peça de conteúdo.","ru":"Атрибуция - это многоязычный 프реймворк программирования, который привязывает идентичность агента к региону контента, позволяя отслеживать, кто создал или изменил каждую часть контента.","ar":"الأنساب هو إطار عمل برمجي متعدد اللغات يربط بين هوية الوكيل ومنطقة المحتوى، مما يسمح بالتتبع من谁_created أو قام بتعديل كل قطعة من المحتوى."},"seo":{"title":{"en":"Attribution: Setup Guide for AI Agents | AI Agent Skill","zh":"Attribution.Setup 指南：代码拥有者和内容追踪","ja":"Attribution設定ガイド：コード所有者とコンテンツ追跡","ko":"Attribution 설정 가이드: 코드 소유자와 콘텐츠 추적","es":"Guía de configuración de atribución para agentes de intel...","fr":"Guide de mise en place de l''attribution pour les outils d...","de":"Einrichtungsleitfaden für Attribution in KI-Agenten","pt":"Guia de Configuração de Atribuição para Ferramentas de IA","ru":"Руководство по настройке атрибуции для ИИ Агентов","ar":"دليل إعداد الأنساب للموكلين الإصطناعيين"},"description":{"en":"Discover how attribution tracks content region authors. Learn to bind agent identity and query blame with this AI agent skill. Get started now!","zh":"了解Attribution的概念和功能，包括代码所有权、内容追踪和blame查询等","ja":"Attributionの概念と機能について学び、コード所有権、コンテンツ追跡、blameクエリーなど","ko":"Attribution의 개념과 기능에 대해 알아보세요. 코드 소유권, 콘텐츠 추적, 블레임 쿼리 등","es":"Aprende a configurar la atribución para rastrear la autoría de regiones de contenido en proyectos de desarrollo de software","fr":"Découvrez comment configurer l''attribution pour suivre l''historique des modifications de régions de contenu dans les projets de développement de logiciels","de":"Erfahren Sie, wie Sie die Attribution einrichten, um die Urheberschaft von Inhaltbereichen in Software-Entwicklungsprojekten zu verfolgen","pt":"Aprenda a vincular a identidade do agente à região de conteúdo com a atribuição, suportando consultas de culpa e histórico de autorias","ru":"Узнайте, как привязать идентичность агента к региону контента с помощью атрибуции, поддерживающей запросы вины и историю авторства","ar":"تعلم كيفية ربط هوية الوكيل بمنطقة المحتوى باستخدام الأنساب، مع دعم استفسارات اللوم وتاريخ الملكية"},"definition":{"en":"Attribution is a framework that tracks content region authors, supporting blame queries and CODEOWNERS style ownership patterns.","zh":"Attribution是指将代码所有权和内容追踪绑定到特定代码区域的过程","ja":"Attributionはコード所有権とコンテンツ追跡を特定のコード領域にバインドするプロセス","ko":"Attribution은 코드 소유권과 콘텐츠 추적을 특정 코드 영역에 바인딩하는 프로세스","es":"La atribución es un mecanismo que permite rastrear quién creó o modificó cada pieza de contenido","fr":"L''attribution est un mécanisme qui permet de suivre qui a créé ou modifié chaque région de contenu","de":"Die Attribution ist ein Mechanismus, der es ermöglicht, zu verfolgen, wer jeden Inhaltbereich erstellt oder geändert hat","pt":"Atribuição é a capacidade de vincular a identidade do agente à região de conteúdo, permitindo o rastreamento de autorias e modificações","ru":"Атрибуция - это способность привязать идентичность агента к региону контента, позволяющая отслеживать авторство и изменения","ar":"الأنساب هي القدرة على ربط هوية الوكيل بمنطقة المحتوى، مما يسمح بالتتبع لمعلومات الملكية والتعديلات"},"features":{"en":["Binds agent identity to content regions using the attribute command","Supports blame queries for tracking content modifications","Enables per region authorship history","Implements CODEOWNERS style ownership patterns","Utilizes the $0 contentRef argument for attribution record creation","Allows for tracking who created or modified each piece of content"],"zh":["支持代码所有权和内容追踪","提供blame查询和per region authorship history","支持CODEOWNERS样式的所有权模式","绑定agent身份到内容区域","支持多语言编程"],"ja":["コード所有権とコンテンツ追跡をサポート","blameクエリーとper region authorship historyを提供","CODEOWNERSスタイルの所有権パターンをサポート","エージェントIDをコンテンツ領域にバインド","マルチ言語プログラミングをサポート"],"ko":["코드 소유권과 콘텐츠 추적을 지원","블레임 쿼리와 per region 저자ship history를 제공","CODEOWNERS 스타일의 소유권 패턴을 지원","에이전트 ID를 콘텐츠 영역에 바인딩","멀티 언어 프로그래밍을 지원"],"es":["Vinculación de la identidad del agente a regiones de contenido","Seguimiento de la autoría y la historia de modificaciones","Soporte para consultas de blame y patrones de propiedad de código","Compatibilidad con múltiples lenguajes de programación"],"fr":["Liaison de l''identité de l''agent à des régions de contenu","Suivi de l''historique des modifications et de l''authorship","Prise en charge des requêtes de blame et des modèles de propriété de code","Compatibilité avec plusieurs langages de programmation"],"de":["Bindung der Agentenidentität an Inhaltsbereiche","Verfolgung der Urheberschaft und der Änderungshistorie","Unterstützung für Blame-Abfragen und CODEOWNERS-Style-Eigentumsverhältnisse","Kompatibilität mit mehreren Programmiersprachen"],"pt":["Vinculação da identidade do agente à região de conteúdo","Suporte a consultas de culpa e histórico de autorias","Padrões de propriedade de estilo CODEOWNERS","Rastreamento de quem criou ou modificou cada peça de conteúdo","Suporte a múltiplas linguagens de programação"],"ru":["Привязка идентичности агента к региону контента","Поддержка запросов вины и истории авторства","Паттерны собственности стиля CODEOWNERS","Отслеживание того, кто создал или изменил каждую часть контента","Поддержка нескольких языков программирования"],"ar":["ربط هوية الوكيل بمنطقة المحتوى","دعم استفسارات اللوم وتاريخ الملكية","أنماط ملكية نمط CODEOWNERS","التتبع لمن созд أو قام بتعديل كل قطعة من المحتوى","دعم لغات برمجة متعددة"]},"keywords":{"en":["how to use attribution","attribution setup guide","attribution alternative","attribution vs git","attribution install","what is attribution","attribution for AI agents","attribution multi-language support","attribution concept-first framework"],"zh":["Attribution","代码所有权","内容追踪","blame查询","CODEOWNERS","多语言编程","AIエージェント","AI工具"],"ja":["Attribution","コード所有権","コンテンツ追跡","blameクエリー","CODEOWNERS","マルチ言語プログラミング","AIエージェント","AIツール"],"ko":["Attribution","코드 소유권","콘텐츠 추적","블레임 쿼리","CODEOWNERS","멀티 언어 프로그래밍","AI 에이전트","AI 도구"],"es":["agentes de inteligencia artificial","attribution en desarrollo de software","seguimiento de autoría","historia de modificaciones","programación multi-lenguaje","integración de agentes","desarrollo de software ágil","herramientas de desarrollo de software","tecnologías de inteligencia artificial"],"fr":["outils d''intelligence artificielle","attribution dans le développement de logiciels","suivi de l''authorship","historique des modifications","programmation multi-langage","intégration d''agents","développement de logiciels agile","outils de développement de logiciels","technologies d''intelligence artificielle"],"de":["KI-Agenten","Attribution in der Software-Entwicklung","Verfolgung der Urheberschaft","Änderungshistorie","Multi-Lenguage-Programmierung","Integration von Agenten","Agile Software-Entwicklung","Software-Entwicklungstools","Künstliche-Intelligenz-Technologien"],"pt":["atribuição de agente","ferramentas de ia","programação multilíngue","rastreamento de autorias","consultas de culpa","padrões de propriedade","codeowners","desenvolvimento de software","engenharia de software"],"ru":["атрибуция агента","ии агенты","многоязычное программирование","отслеживание авторства","запросы вины","паттерны собственности","codeowners","разработка программного обеспечения","инженерия программного обеспечения"],"ar":["أنساب الوكيل","موكلين إصطناعيين","برمجة متعددة اللغات","تتبع ملكية","استفسارات اللوم","أنماط ملكية","codeowners","تطوير برامج","هندسة برمجية"]}},"owner":"Itshalffull","repo":"Concept-Oriented-Programming-Framework","repoPath":"Itshalffull/Concept-Oriented-Programming-Framework","stars":0,"forks":0,"updatedAt":"2026-03-06T19:45:52Z","topics":[],"category":"community","skillMd":{"name":"attribution","description":"Bind agent identity to content regions , tracking who created or","bodyPreview":"<!-- Auto-generated by Clef Clef Bind — claude-skills target -->\n<!-- Concept: Attribution -->\n<!-- Do not edit manually; regenerate with: clef interface generate -->\n\n# Attribution\n\nBind agent identity to content regions , tracking who created or \n modified each piece . Supports blame queries , per region authorship \n history , and CODEOWNERS style ownership patterns .\n\n## Commands\n\n### attribute\nAttribution record created binding agent to content region .\n\n**Arguments:** `$0` **contentRef** (s","body":"<!-- Auto-generated by Clef Clef Bind — claude-skills target -->\n<!-- Concept: Attribution -->\n<!-- Do not edit manually; regenerate with: clef interface generate -->\n\n# Attribution\n\nBind agent identity to content regions , tracking who created or \n modified each piece . Supports blame queries , per region authorship \n history , and CODEOWNERS style ownership patterns .\n\n## Commands\n\n### attribute\nAttribution record created binding agent to content region .\n\n**Arguments:** `$0` **contentRef** (string), `$1` **region** (bytes), `$2` **agent** (string), `$3` **changeRef** (string)\n\n### blame\nReturns full blame map each region mapped to its most recent author .\n\n**Arguments:** `$0` **contentRef** (string)\n\n### history\nFull attribution chain for a specific region in chronological order .\n\n**Arguments:** `$0` **contentRef** (string), `$1` **region** (bytes)\n\n### setOwnership\nCODEOWNERS style ownership rule set for path pattern .\n\n**Arguments:** `$0` **pattern** (string), `$1` **owners** (string[])\n\n### queryOwners\nReturns owners matching the path against ownership patterns .\n\n**Arguments:** `$0` **path** (string)\n"},"lastSynced":"2026-03-07T13:12:53.089Z","agentAnalysis":{"suitability":{"en":"Perfect for Multi-Language Programming Agents needing advanced content tracking and authorship analysis.","zh":"适合需要高级内容跟踪和作者分析的多语言编程代理。","ja":"マルチ言語プログラミングエージェントが高度なコンテンツ追跡と著者分析を必要とする場合に最適です。","ko":"멀티 언어 프로그래밍 에이전트가 고급 콘텐츠 추적 및 저자 분석을 필요로 할 경우 적합합니다.","es":"Perfecto para Agentes de Programación de Multi-Lenguaje que necesitan un seguimiento de contenido avanzado y análisis de autoría.","fr":"Parfait pour les Agents de Programmation Multi-Langage nécessitant un suivi de contenu avancé et une analyse d''auteur.","de":"Perfekt für Multi-Language-Programming-Agents, die ein erweitertes Inhalts-Tracking und eine Autorenanalyse benötigen.","pt":"Perfeito para Agentes de Programação de Múltiplos Idiomas que necessitam de rastreamento de conteúdo avançado e análise de autorias.","ru":"Идеально подходит для Многоязычных Программных Агентов, которым требуется продвинутый отслеживание контента и анализ авторства.","ar":"مثالي لعميل البرمجة المتعددة اللغات الذي يحتاج إلى تتبع المحتوى المتقدم وتحليل الملكية."},"recommendation":{"en":"Empowers agents to bind agent identity to content regions, supporting blame queries, per region authorship history, and CODEOWNERS style ownership patterns using multi-language programming frameworks.","zh":"赋予代理绑定代理身份到内容区域的能力，支持责问查询、每个区域的作者历史记录和CODEOWNERS风格的所有权模式，使用多语言编程框架。","ja":"エージェントはエージェントのIDをコンテンツ領域にバインドする機能を提供し、blameクエリ、リージョンごとの著者履歴、およびCODEOWNERSスタイルの所有権パターンをサポートし、マルチ言語プログラミングフレームワークを使用します。","ko":"에이전트가 에이전트 ID를 콘텐츠 영역에 바인딩할 수 있는 기능을 제공하여, 책임 질의, 지역별 저자 기록 및 CODEOWNERS 스타일의 소유권 패턴을 지원하며, 멀티 언어 프로그래밍 프레임워크를 사용합니다.","es":"Habilita a los agentes para enlazar la identidad del agente con regiones de contenido, lo que admite consultas de culpas, historial de autoría por región y patrones de propiedad de estilo CODEOWNERS utilizando frameworks de programación de multi-lenguaje.","fr":"Permet aux agents de lier l''identité de l''agent aux régions de contenu, en prenant en charge les requêtes de blâme, l''historique d''auteur par région et les modèles de propriété de style CODEOWNERS en utilisant des frameworks de programmation multi-langage.","de":"Ermöglicht es Agenten, die Agentenidentität an Inhaltsregionen zu binden, was die Unterstützung von Schuldanfragen, Autorenverlaufsprotokollen pro Region und CODEOWNERS-ähnlichen Eigentumsverhaltensmustern unter Verwendung von Multi-Language-Programming-Frameworks ermöglicht.","pt":"Habilita os agentes a vincular a identidade do agente a regiões de conteúdo, suportando consultas de culpa, histórico de autorias por região e padrões de propriedade do tipo CODEOWNERS usando estruturas de programação de múltiplos idiomas.","ru":"Наделяет агентов возможностью привязать идентичность агента к регионам контента, поддерживая запросы виновности, историю авторства по регионам и модели владения типа CODEOWNERS с использованием многоязычных программных фреймворков.","ar":"يمنح الوكيل khảية ربط هوية الوكيل بمناطق المحتوى، ودعم استفسارات اللوم وتاريخ ملكية المنطقة ونماذج ملكية نمط CODEOWNERS باستخدام إطارات برمجة متعددة اللغات."},"useCases":{"en":["Tracking content modifications","Generating authorship history reports","Debugging content region ownership"],"zh":["跟踪内容修改","生成作者历史报告","调试内容区域所有权"],"ja":["コンテンツの変更を追跡する","著者履歴レポートを生成する","コンテンツ領域の所有権をデバッグする"],"ko":["콘텐츠 수정을 추적한다","저자 기록 보고서를 생성한다","콘텐츠 영역 소유권을 디버깅한다"],"es":["Seguimiento de modificaciones de contenido","Generación de informes de historial de autoría","Depuración de la propiedad de regiones de contenido"],"fr":["Suivi des modifications de contenu","Génération d''histoires d''auteur","Débogage de la propriété des régions de contenu"],"de":["Nachverfolgung von Inhaltsänderungen","Erstellung von Autorenverlaufsprotokollen","Fehlerbehebung bei der Eigentumsnahme von Inhaltsbereichen"],"pt":["Rastreamento de modificações de conteúdo","Geração de relatórios de histórico de autorias","Depuração da propriedade de regiões de conteúdo"],"ru":["Отслеживание изменений контента","Генерация отчетов об истории авторства","Отладка владения регионами контента"],"ar":["تتبع تعديلات المحتوى","توليد تقارير تاريخ ملكية","تصحيح أخطاء ملكية منطقة المحتوى"]},"limitations":{"en":["Requires content region definitions","Multi-language support may require additional configuration"],"zh":["需要内容区域定义","多语言支持可能需要额外配置"],"ja":["コンテンツ領域の定義が必要","マルチ言語サポートには追加の構成が必要になる場合がある"],"ko":["콘텐츠 영역 정의가 필요하다","멀티 언어 지원은 추가 구성이 필요할 수 있다"],"es":["Requiere definiciones de regiones de contenido","La compatibilidad con varios idiomas puede requerir una configuración adicional"],"fr":["Nécessite des définitions de régions de contenu","La prise en charge de plusieurs langues peut nécessiter une configuration supplémentaire"],"de":["Benötigt Inhaltsbereichsdefinitionen","Die Unterstützung mehrerer Sprachen kann eine zusätzliche Konfiguration erfordern"],"pt":["Requer definições de regiões de conteúdo","O suporte a múltiplos idiomas pode requerer configuração adicional"],"ru":["Требует определения регионов контента","Поддержка 多язычности может требовать дополнительной настройки"],"ar":["يتطلب تعريف مناطق المحتوى","دعم اللغات المتعددة قد يتطلب تكوين إضافي"]},"version":4},"contentHash":"01d46e9860745791b1b058c466057dcb0f6835853cb296a410869d7258e87c38","qualityScore":23}');
