INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Itshalffull/Concept-Oriented-Programming-Framework/attribution', 'attribution', 'Itshalffull', 'Concept-Oriented-Programming-Framework', 'community', 'attribution Itshalffull Concept-Oriented-Programming-Framework community Attribution is a concept-first, spec-first, multi-language programming framework that binds agent identity to content regions. It supports tracking who created or modified each piece of content. Attribution是一个概念先、规范先的多语言编程框架，支持代码所有权和内容追踪 Attributionは概念先、規範先のマルチ言語プログラミングフレームワークで、コード所有権とコンテンツ追跡をサポート Attribution은 개념 우선, 규약 우선의 멀티 언어 프로그래밍 프레임워크로 코드 소유권과 콘텐츠 추적을 지원 La atribución es un concepto de programación que permite vincular la identidad de un agente a regiones de contenido, permitiendo el seguimiento de la autoría y la historia de modificaciones L''attribution est un concept de programmation qui permet de lier l''identité d''un agent à des régions de contenu, permettant ainsi de suivre l''historique des modifications et l''authorship Die Attribution ist ein Programmierkonzept, das die Bindung der Agentenidentität an Inhaltsbereiche ermöglicht, um die Urheberschaft und die Änderungshistorie zu verfolgen Atribuição é um framework de programação multilíngue que vincula a identidade do agente à região de conteúdo, permitindo o rastreamento de quem criou ou modificou cada peça de conteúdo. Атрибуция - это многоязычный 프реймворк программирования, который привязывает идентичность агента к региону контента, позволяя отслеживать, кто создал или изменил каждую часть контента. الأنساب هو إطار عمل برمجي متعدد اللغات يربط بين هوية الوكيل ومنطقة المحتوى، مما يسمح بالتتبع من谁_created أو قام بتعديل كل قطعة من المحتوى. how to use attribution attribution setup guide attribution alternative attribution vs git attribution install what is attribution attribution for AI agents attribution multi-language support attribution concept-first framework Attribution 代码所有权 内容追踪 blame查询 CODEOWNERS 多语言编程 AIエージェント AI工具 Binds agent identity to content regions using the attribute command Supports blame queries for tracking content modifications Enables per region authorship history Implements CODEOWNERS style ownership patterns Utilizes the $0 contentRef argument for attribution record creation Allows for tracking who created or modified each piece of content Attribution is a framework that tracks content region authors, supporting blame queries and CODEOWNERS style ownership patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HoangNguyen0403/agent-skills-standard/Android Dependency Injection (Hilt)', 'community', 'HoangNguyen0403', 'agent-skills-standard', 'HoangNguyen0403/agent-skills-standard', 'Android Dependency Injection (Hilt)', 0, 0, 23, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:09.005Z', 'd0c658505612f623933e3d196c6f4a68db94d5ca23af10b563b9988b7967b4d4', '{"id":"HoangNguyen0403/agent-skills-standard/Android Dependency Injection (Hilt)","name":"Android Dependency Injection (Hilt)","description":{"en":"Android Dependency Injection (Hilt) is a collection of best practices for programming languages and frameworks, helping AI agents follow standards. It benefits Android developers by providing a structured approach to dependency injection.","zh":"Android 依赖注入 (Hilt) 是一种用于管理 Android 应用程序依赖关系的技术。通过使用 Hilt，可以提高代码质量和可维护性","ja":"Android 依存性インジェクション (Hilt) は、Android アプリケーションの依存関係を管理するための技術です。Hilt を使用することで、コード品質とメンテナンス性を向上させることができます","ko":"Android 의존성 주입 (Hilt) 는 Android 애플리케이션의 의존 관계를 관리하기 위한 기술입니다. Hilt를 사용하면 코드 품질과 유지보수성을 향상시킬 수 있습니다","es":"La inyección de dependencias de Android con Hilt es una técnica para mejorar la calidad del código y reducir la complejidad","fr":"L''injection de dépendances Android avec Hilt est une technique pour améliorer la qualité du code et réduire la complexité","de":"Die Abhängigkeitsinjektion in Android mit Hilt ist eine Technik, um die Code-Qualität zu verbessern und die Komplexität zu reduzieren","pt":"O Android Dependency Injection (Hilt) é uma coleção de habilidades de agente padrão e melhores práticas para frameworks e linguagens de programação","ru":"Android Dependency Injection (Hilt) - это коллекция стандартных навыков агента и лучших практик для фреймворков и языков программирования - ИИ Агенты","ar":"Android Dependency Injection (Hilt) هي مجموعة من مهارات الوكيل المعيارية وأفضل الممارسات لأطر العمل ولغات البرمجة - أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Android Dependency Injection (Hilt): Setup Guide for AI A...","zh":"Android 依赖注入 (Hilt)_SETUP GUIDE","ja":"Android 依存性インジェクション (Hilt) ベストプラクティス","ko":"Android 의존성 주입 (Hilt) 구현 가이드","es":"Guía de Configuración de Inyección de Dependencias de And...","fr":"Guide de Configuration de l''Injection de Dépendances Andr...","de":"Konfigurationsleitfaden für Android-Abhängigkeitsinjektio...","pt":"Guia de Configuração do Android Dependency Injection (Hilt)","ru":"Настройка Android Dependency Injection (Hilt) - ИИ Агенты","ar":"دليل إعداد Android Dependency Injection (Hilt) لأدوات الذ..."},"description":{"en":"Discover how to implement Android Dependency Injection (Hilt) with our expert guide. Learn best practices for setup, modules, and constructor injection.","zh":"使用 Hilt 实现 Android 依赖注入，提高代码质量和可维护性。了解 setup 和最佳实践","ja":"Hilt を使用して Android 依存性インジェクションを実現し、コード品質とメンテナンス性を向上させる。セットアップとベストプラクティスを学ぶ","ko":"Hilt를 사용하여 Android 의존성 주입을 구현하고 코드 품질 및 유지보수성을 향상시키는 방법에 대해 알아보세요. 설정 및 모범 사례","es":"Aprende a configurar la inyección de dependencias en Android con Hilt, mejora la calidad de tu código y reduce la complejidad","fr":"Découvrez comment configurer l''injection de dépendances sur Android avec Hilt, améliorez la qualité de votre code et réduisez la complexité","de":"Erfahren Sie, wie Sie die Abhängigkeitsinjektion in Android mit Hilt konfigurieren, um die Code-Qualität zu verbessern und die Komplexität zu reduzieren","pt":"Aprenda a configurar o Android Dependency Injection (Hilt) com nossas melhores práticas e guias passo a passo para desenvolvedores","ru":"Узнайте, как настроить Android Dependency Injection (Hilt) с помощью наших лучших практик и пошаговых руководств для разработчиков - ИИ Агенты","ar":"تعلم كيفية إعداد Android Dependency Injection (Hilt) باستخدام أفضل الممارسات ودليل خطوة بخطوة لل مطورين - أدوات الذكاء الاصطناعي"},"definition":{"en":"Android Dependency Injection (Hilt) is a framework for managing dependencies in Android applications, utilizing annotations like @HiltAndroidApp and @AndroidEntryPoint.","zh":"Android 依赖注入 (Hilt) 是一种用于管理 Android 应用程序依赖关系的技术","ja":"Android 依存性インジェクション (Hilt) は、Android アプリケーションの依存関係を管理するための技術","ko":"Android 의존성 주입 (Hilt) 는 Android 애플리케이션의 의존 관계를 관리하기 위한 기술","es":"La inyección de dependencias de Android con Hilt es una técnica de programación que permite gestionar las dependencias entre componentes","fr":"L''injection de dépendances Android avec Hilt est une technique de programmation qui permet de gérer les dépendances entre les composants","de":"Die Abhängigkeitsinjektion in Android mit Hilt ist eine ProgrammierTechnik, die es ermöglicht, die Abhängigkeiten zwischen Komponenten zu verwalten","pt":"Android Dependency Injection (Hilt) é uma técnica de injeção de dependência para aplicações Android","ru":"Android Dependency Injection (Hilt) - это техника внедрения зависимостей для приложений Android - ИИ Агенты","ar":"Android Dependency Injection (Hilt) هو تقنية لحقن التبعيات لتطبيقات Android - أدوات الذكاء الاصطناعي"},"features":{"en":["Annotates Application class with @HiltAndroidApp for setup","Uses @AndroidEntryPoint for activities and fragments","Prefers @Binds over @Provides for binding modules","Utilizes @InstallIn for explicit component installation","Supports constructor injection over field injection"],"zh":["使用 @HiltAndroidApp 注解应用程序类","使用 @AndroidEntryPoint 注解活动和片段","使用 @Binds 和 @Provides 进行依赖绑定","使用 Constructor Injection 代替 Field Injection","使用 SingletonComponent 和 ViewModelComponent 进行依赖安装"],"ja":["アプリケーションクラスに @HiltAndroidApp アノテーションを使用","アクティビティとフラグメントに @AndroidEntryPoint アノテーションを使用","依存関係バインディングに @Binds と @Provides を使用","フィールドインジェクションよりもコンストラクタインジェクションを使用","SingletonComponent と ViewModelComponent を使用した依存関係のインストール"],"ko":["애플리케이션 클래스에 @HiltAndroidApp 어노테이션 사용","액티비티와 프래그먼트에 @AndroidEntryPoint 어노테이션 사용","의존성 바인딩에 @Binds와 @Provides 사용","필드 인젝션보다 생성자 인젝션 사용","SingletonComponent와 ViewModelComponent를 사용한 의존성 설치"],"es":["Configuración de la inyección de dependencias con @HiltAndroidApp","Uso de @AndroidEntryPoint para anotar Activities y Fragments","Uso de @Binds para enlazar dependencias","Instalación explícita de componentes con @InstallIn","Inyección de constructores con preferencia sobre la inyección de campos"],"fr":["Configuration de l''injection de dépendances avec @HiltAndroidApp","Utilisation de @AndroidEntryPoint pour annoter les Activities et les Fragments","Utilisation de @Binds pour relier les dépendances","Installation explicite des composants avec @InstallIn","Injection de constructeurs avec préférence sur l''injection de champs"],"de":["Konfiguration der Abhängigkeitsinjektion mit @HiltAndroidApp","Verwendung von @AndroidEntryPoint, um Activities und Fragments zu annotieren","Verwendung von @Binds, um Abhängigkeiten zu binden","Explizite Installation von Komponenten mit @InstallIn","Konstruktorinjektion mit Vorzug vor Feldinjektion"],"pt":["Uso de @HiltAndroidApp para anotar a classe Application","Uso de @AndroidEntryPoint para anotar Activities e Fragments","Uso de @Binds em vez de @Provides quando possível","Uso explícito de SingletonComponent e ViewModelComponent","Preferência por injeção de construtor em vez de injeção de campo"],"ru":["Использование @HiltAndroidApp для аннотации класса Application - ИИ Агенты","Использование @AndroidEntryPoint для аннотации Activities и Fragments","Использование @Binds вместо @Provides когда возможно","Явное использование SingletonComponent и ViewModelComponent","Предпочтение конструкторной инъекции вместо инъекции поля"],"ar":["استخدام @HiltAndroidApp لتعليمة فئة التطبيق","استخدام @AndroidEntryPoint لتعليمة الأنشطة والشظايا","استخدام @Binds بدلاً من @Provides عندما يكون ذلك ممكنًا","استخدام SingletonComponent و ViewModelComponent بشكل صريح","التفضيل لحقن البناء على حقن الحقل"]},"keywords":{"en":["Android Dependency Injection (Hilt) setup guide","how to use Hilt in Android","what is Android Dependency Injection (Hilt)","Hilt vs Dagger","Android Dependency Injection (Hilt) alternative","installing Android Dependency Injection (Hilt)"],"zh":["Android 依赖注入","Hilt","依赖注入框架","Android 应用程序开发","代码质量","可维护性","AIエージェント","Android 依赖管理"],"ja":["Android 依存性インジェクション","Hilt","依存性インジェクションフレームワーク","Android アプリケーション開発","コード品質","メンテナンス性","AIエージェント","Android 依存管理"],"ko":["Android 의존성 주입","Hilt","의존성 주입 프레임워크","Android 애플리케이션 개발","코드 품질","유지보수성","AI 에이전트","Android 의존성 관리"],"es":["inyección de dependencias android","hilt android","programación android","desarrollo de aplicaciones android","patrón de inyección de dependencias","android dependency injection","hilt tutorial"],"fr":["injection de dépendances android","hilt android","programmation android","développement d''applications android","modèle d''injection de dépendances","android dependency injection","hilt tutoriel"],"de":["Abhängigkeitsinjektion in Android","Hilt Android","Android-Programmierung","Android-App-Entwicklung","Abhängigkeitsinjektionsmuster","Android-Abhängigkeitsinjektion","Hilt-Anleitung"],"pt":["Android Dependency Injection","Hilt","injeção de dependência","desenvolvimento de aplicações Android","melhores práticas de programação","frameworks de programação"],"ru":["Android Dependency Injection","Hilt","внедрение зависимостей","разработка приложений Android","лучшие практики программирования","фреймворки программирования - ИИ Агенты"],"ar":["Android Dependency Injection","Hilt","حقن التبعيات","تطوير تطبيقات Android","أفضل الممارسات في البرمجة","أطر العمل البرمجية - أدوات الذكاء الاصطناعي"]}},"owner":"HoangNguyen0403","repo":"agent-skills-standard","repoPath":"HoangNguyen0403/agent-skills-standard","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.270Z","topics":[],"category":"community","skillMd":{"name":"Android Dependency Injection (Hilt)","description":"Standards for Hilt Setup, Scoping, and Modules. Use when setting up Hilt dependency injection, component scoping, or modules in Android.","bodyPreview":"# Android Dependency Injection (Hilt)\n\n## **Priority: P0**\n\n## Implementation Guidelines\n\n### Setup\n\n- **App**: Must annotate `Application` class with `@HiltAndroidApp`.\n- **Entries**: Annotate Activities/Fragments with `@AndroidEntryPoint`.\n\n### Modules\n\n- **Binding**: Use `@Binds` (abstract class) over `@Provides` when possible (smaller generated code).\n- **InstallIn**: Be explicit (`SingletonComponent`, `ViewModelComponent`).\n\n### Construction\n\n- **Constructor Injection**: Prefer over Field I","body":"# Android Dependency Injection (Hilt)\n\n## **Priority: P0**\n\n## Implementation Guidelines\n\n### Setup\n\n- **App**: Must annotate `Application` class with `@HiltAndroidApp`.\n- **Entries**: Annotate Activities/Fragments with `@AndroidEntryPoint`.\n\n### Modules\n\n- **Binding**: Use `@Binds` (abstract class) over `@Provides` when possible (smaller generated code).\n- **InstallIn**: Be explicit (`SingletonComponent`, `ViewModelComponent`).\n\n### Construction\n\n- **Constructor Injection**: Prefer over Field Injection (`@Inject constructor(...)`).\n- **Assisted Injection**: Use for runtime parameters (`@AssistedInject`).\n\n## Anti-Patterns\n\n- **Component Manual Creation**: `**No Manual Dagger**: Use Hilt Standard.`\n- **Field Inject in Logic**: `**No Field Inject**: Only in Android Components.`\n\n## References\n\n- [Module Templates](references/files.md)\n"},"lastSynced":"2026-03-08T02:00:09.005Z","agentAnalysis":{"suitability":{"en":"Ideal for Mobile Agents focusing on Android app development needing structured dependency injection with Hilt","zh":"适合专注于Android应用开发并需要结构化依赖注入的Hilt的移动代理","ja":"Androidアプリ開発に焦点を当ててHiltを使用した構造化された依存性の注入が必要なモバイルエージェントに適しています","ko":"Android 애플리케이션 개발에 중점을 두고 Hilt를 사용한 구조화된 의존성 주입이 필요한 모바일 에이전트에 적합합니다","es":"Ideal para Agentes Móviles que se centran en el desarrollo de aplicaciones de Android y necesitan inyección de dependencias estructurada con Hilt","fr":"Idéal pour les Agents Mobiles se concentrant sur le développement d''applications Android nécessitant une injection de dépendances structurée avec Hilt","de":"Ideal für Mobile Agenten, die sich auf die Entwicklung von Android-Apps konzentrieren und strukturierte Abhängigkeitsinjektion mit Hilt benötigen","pt":"Ideal para Agentes Móveis focados no desenvolvimento de aplicativos Android que necessitam de injeção de dependência estruturada com Hilt","ru":"Идеально для мобильных агентов, ориентированных на разработку приложений для Android, требующих структурированного внедрения зависимостей с помощью Hilt","ar":"مثالية لعميل الهاتف المحمول الذي يركز على تطوير تطبيقات Android التي تحتاج إلى حقن تبعيات منظمة مع Hilt"},"recommendation":{"en":"Empowers agents to implement modular and testable Android applications using Hilt''s @HiltAndroidApp, @AndroidEntryPoint, and @Binds annotations, streamlining dependency management with SingletonComponent and ViewModelComponent","zh":"赋予代理实现使用Hilt的@HiltAndroidApp、@AndroidEntryPoint和@Binds注解的模块化和可测试的Android应用程序，通过SingletonComponent和ViewModelComponent简化依赖管理","ja":"エージェントがHiltの@HiltAndroidApp、@AndroidEntryPoint、@Bindsアノテーションを使用してモジュール化されテスト可能なAndroidアプリケーションを実装できるようにし、SingletonComponentとViewModelComponentで依存関係の管理を簡素化する","ko":"에이전트가 Hilt의 @HiltAndroidApp, @AndroidEntryPoint, @Binds 어노테이션을 사용하여 모듈화되고 테스트 가능한 Android 애플리케이션을 구현할 수 있도록 하며, SingletonComponent와 ViewModelComponent로 의존성 관리를 간소화합니다","es":"Permite a los agentes implementar aplicaciones de Android modulares y probables utilizando las anotaciones @HiltAndroidApp, @AndroidEntryPoint y @Binds de Hilt, simplificando la gestión de dependencias con SingletonComponent y ViewModelComponent","fr":"Permet aux agents de mettre en œuvre des applications Android modulaires et testables en utilisant les annotations @HiltAndroidApp, @AndroidEntryPoint et @Binds de Hilt, rationalisant la gestion des dépendances avec SingletonComponent et ViewModelComponent","de":"Ermöglicht es den Agenten, modulare und testbare Android-Anwendungen mit den Hilt-Anotations @HiltAndroidApp, @AndroidEntryPoint und @Binds zu implementieren, wodurch die Verwaltung von Abhängigkeiten mit SingletonComponent und ViewModelComponent vereinfacht wird","pt":"Habilita os agentes a implementar aplicações Android modulares e testáveis usando as anotações @HiltAndroidApp, @AndroidEntryPoint e @Binds do Hilt, simplificando a gestão de dependências com SingletonComponent e ViewModelComponent","ru":"Наделяет агентов возможностью реализовывать модульные и тестируемые приложения для Android, используя аннотации @HiltAndroidApp, @AndroidEntryPoint и @Binds из Hilt, упрощая управление зависимостями с помощью SingletonComponent и ViewModelComponent","ar":"تمكين الوكلاء من تنفيذ تطبيقات Android القابلة للتحديث والاختبار باستخدام تعليقات @HiltAndroidApp و @AndroidEntryPoint و @Binds من Hilt، وبذلك يتم تبسيط إدارة التبعيات مع SingletonComponent و ViewModelComponent"},"useCases":{"en":["Implementing constructor injection for Android components","Managing dependencies across Activities and Fragments","Creating modular and reusable code with Hilt modules"],"zh":["为Android组件实现构造函数注入","跨Activity和Fragment管理依赖","使用Hilt模块创建模块化和可重用的代码"],"ja":["Androidコンポーネントのコンストラクタインジェクションの実装","アクティビティとフラグメント間の依存関係の管理","Hiltモジュールを使用したモジュール化および再利用可能なコードの作成"],"ko":["Android 컴포넌트의 생성자 주입 구현","액티비티 및 프래그먼트 간 의존성 관리","Hilt 모듈을 사용한 모듈화 및 재사용 가능한 코드 생성"],"es":["Implementar inyección de constructores para componentes de Android","Gestionar dependencias en Actividades y Fragmentos","Crear código modular y reutilizable con módulos de Hilt"],"fr":["Mettre en œuvre l''injection de constructeurs pour les composants Android","Gérer les dépendances entre les Activités et les Fragments","Créer du code modulaire et réutilisable avec les modules Hilt"],"de":["Implementierung von Konstruktorinjektion für Android-Komponenten","Verwaltung von Abhängigkeiten über Activities und Fragments","Erstellung von modularem und wiederverwendbarem Code mit Hilt-Modulen"],"pt":["Implementar injeção de construtor para componentes Android","Gerenciar dependências em toda a Atividade e Fragmentos","Criar código modular e reutilizável com módulos Hilt"],"ru":["Реализовать внедрение конструктора для компонентов Android","Управлять зависимостями во всех Activitis и Fragmentах","Создать модульный и многократно используемый код с помощью модулей Hilt"],"ar":["تنفيذ حقن البناء لمكونات Android","إدارة التبعيات عبر الأنشطة والشظايا","إنشاء رمز قابل للتوسيع وقابل لإعادة الاستخدام باستخدام وحدات Hilt"]},"limitations":{"en":["Requires Android development environment","Hilt-specific annotations and setup"],"zh":["需要Android开发环境","Hilt特定的注解和设置"],"ja":["Android開発環境の必要性","Hilt特有のアノテーションと設定"],"ko":["Android 개발 환경 필요","Hilt 특정 어노테이션 및 설정"],"es":["Requiere un entorno de desarrollo de Android","Anotaciones y configuración específicas de Hilt"],"fr":["Nécessite un environnement de développement Android","Anotations et configuration spécifiques à Hilt"],"de":["Benötigt eine Android-Entwicklungsumgebung","Hilt-spezifische Anotations und Einrichtung"],"pt":["Exige ambiente de desenvolvimento Android","Anotações e configuração específicas do Hilt"],"ru":["Требует среды разработки Android","Аннотации и настройка, специфичные для Hilt"],"ar":["يتطلب بيئة تطوير Android","تعليقات وتفاصيل إعداد محددة لـ Hilt"]},"version":4},"contentHash":"d0c658505612f623933e3d196c6f4a68db94d5ca23af10b563b9988b7967b4d4","qualityScore":23}');
