INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HoangNguyen0403/agent-skills-standard/Android Dependency Injection (Hilt)', 'Android Dependency Injection (Hilt)', 'HoangNguyen0403', 'agent-skills-standard', 'community', 'Android Dependency Injection (Hilt) HoangNguyen0403 agent-skills-standard community Android Dependency Injection (Hilt) is a collection of best practices for programming languages and frameworks, helping AI agents follow standards. It benefits Android developers by providing a structured approach to dependency injection. Android 依赖注入 (Hilt) 是一种用于管理 Android 应用程序依赖关系的技术。通过使用 Hilt，可以提高代码质量和可维护性 Android 依存性インジェクション (Hilt) は、Android アプリケーションの依存関係を管理するための技術です。Hilt を使用することで、コード品質とメンテナンス性を向上させることができます Android 의존성 주입 (Hilt) 는 Android 애플리케이션의 의존 관계를 관리하기 위한 기술입니다. Hilt를 사용하면 코드 품질과 유지보수성을 향상시킬 수 있습니다 La inyección de dependencias de Android con Hilt es una técnica para mejorar la calidad del código y reducir la complejidad L''injection de dépendances Android avec Hilt est une technique pour améliorer la qualité du code et réduire la complexité Die Abhängigkeitsinjektion in Android mit Hilt ist eine Technik, um die Code-Qualität zu verbessern und die Komplexität zu reduzieren O Android Dependency Injection (Hilt) é uma coleção de habilidades de agente padrão e melhores práticas para frameworks e linguagens de programação Android Dependency Injection (Hilt) - это коллекция стандартных навыков агента и лучших практик для фреймворков и языков программирования - ИИ Агенты Android Dependency Injection (Hilt) هي مجموعة من مهارات الوكيل المعيارية وأفضل الممارسات لأطر العمل ولغات البرمجة - أدوات الذكاء الاصطناعي Android Dependency Injection (Hilt) setup guide how to use Hilt in Android what is Android Dependency Injection (Hilt) Hilt vs Dagger Android Dependency Injection (Hilt) alternative installing Android Dependency Injection (Hilt) Android 依赖注入 Hilt 依赖注入框架 Android 应用程序开发 代码质量 可维护性 AIエージェント Android 依赖管理 Annotates Application class with @HiltAndroidApp for setup Uses @AndroidEntryPoint for activities and fragments Prefers @Binds over @Provides for binding modules Utilizes @InstallIn for explicit component installation Supports constructor injection over field injection Android Dependency Injection (Hilt) is a framework for managing dependencies in Android applications, utilizing annotations like @HiltAndroidApp and @AndroidEntryPoint.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cubenlp/ChatTool/dns', 'community', 'cubenlp', 'ChatTool', 'cubenlp/ChatTool', 'dns', 0, 0, 23, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:12.257Z', 'bf23ce97f2c3bde2e3f5f9016548ed5ff7bc396bc1af50c2684b943015ffa8de', '{"id":"cubenlp/ChatTool/dns","name":"dns","description":{"en":"The dns skill allows developers to manage DNS records and SSL certificates using the ChatTool library, supporting features like listing domains and retrieving DNS records.","zh":"DNS 管理工具允许您管理 DNS 记录和 SSL 证书，支持 Aliyun 和 Tencent。","ja":"DNS マネージャー AIエージェントは、DNS レコードと SSL 証明書を管理するためのツールキットです。","ko":"DNS 관리 도구는 DNS 기록과 SSL 인증서를 관리하기 위한 툴킷입니다.","es":"La herramienta de gestión de DNS permite administrar registros DNS y certificados SSL para Chat API. Incluye capacidades como lista de dominios, recuperación de registros y actualización de certificados SSL.","fr":"L''outil de gestion DNS permet de gérer les enregistrements DNS et les certificats SSL pour Chat API. Il inclut des capacités comme la liste des domaines, la récupération des enregistrements et la mise à jour des certificats SSL.","de":"Die DNS-Verwaltungstool ermöglicht die Verwaltung von DNS-Einträgen und SSL-Zertifikaten für Chat API. Sie umfasst Funktionen wie die Liste der Domains, die Abruf von Einträgen und die Aktualisierung von SSL-Zertifikaten.","pt":"O skill DNS permite gerenciar registros DNS e certificados SSL usando a biblioteca ChatTool. Ele oferece funcionalidades como listagem de domínios, obtenção de registros e gerenciamento de certificados SSL.","ru":"Навык DNS позволяет управлять записями DNS и сертификатами SSL с помощью библиотеки ChatTool. Он предлагает функции, такие как список доменов, получение записей и управление сертификатами SSL для ИИ Агентов.","ar":"المهارة DNS تمكنك من إدارة السجلات DNS وشهادات SSL باستخدام مكتبة ChatTool. وهي توفر ميزات مثل قائمة المجالات و الحصول على السجلات وإدارة شهادات SSL للأدوات الذكية."},"seo":{"title":{"en":"dns: Dynamic DNS Management for AI Agents | AI Agent Skill","zh":"DNS 管理工具：设置指南","ja":"DNS マネージャー AIエージェント：ベストプラクティス","ko":"DNS 관리 도구: 설정 가이드","es":"Guía de Configuración de DNS: Administración de Registros...","fr":"Guide de Configuration DNS : Gestion des Enregistrements ...","de":"DNS-Setup-Leitfaden: Verwaltung von DNS-Einträgen und SSL...","pt":"Guia de Configuração DNS: Gerenciamento de Registros e Ce...","ru":"Настройка DNS: Руководство по управлению записями и серти...","ar":"دليل إعداد DNS: إدارة السجلات وشهادات SSL للأدوات الذكية"},"description":{"en":"Discover how to manage DNS records and SSL certificates with the dns skill. Learn how to list domains, get records, and update dynamic DNS records with ease.","zh":"使用 DNS 管理工具管理 DNS 记录和 SSL 证书，支持 Aliyun 和 Tencent。","ja":"DNS マネージャー AIエージェントを使用して DNS レコードと SSL 証明書を管理します。","ko":"DNS 관리 도구를 사용하여 DNS 기록과 SSL 인증서를 관리합니다.","es":"Aprenda a administrar registros DNS y certificados SSL con nuestra herramienta de gestión de DNS para Chat API","fr":"Découvrez comment gérer les enregistrements DNS et les certificats SSL avec notre outil de gestion DNS pour Chat API","de":"Erfahren Sie, wie Sie DNS-Einträge und SSL-Zertifikate mit unserer DNS-Verwaltungstool für Chat API verwalten","pt":"Aprenda a gerenciar registros DNS e certificados SSL com o ChatTool library. Descubra como listar domínios, adicionar e excluir registros e muito mais.","ru":"Узнайте, как управлять записями DNS и сертификатами SSL с помощью ChatTool library. Откройте для себя, как список доменов, добавлять и удалять записи и много...","ar":"تعرف على كيفية إدارة السجلات DNS وشهادات SSL باستخدام مكتبة ChatTool. اكتشف كيفية قائمة المجالات وإضافة وحذف السجلات والمزيد للأدوات الذكية."},"definition":{"en":"dns is a toolkit for managing DNS records and SSL certificates, enabling developers to modify DNS records and request Let''s Encrypt certificates.","zh":"DNS 管理工具是一种管理 DNS 记录和 SSL 证书的工具","ja":"DNS マネージャー AIエージェントは、DNS レコードと SSL 証明書を管理するためのツールです","ko":"DNS 관리 도구는 DNS 기록과 SSL 인증서를 관리하기 위한 도구입니다","es":"La herramienta de gestión de DNS es una herramienta de Chat API que permite administrar registros DNS y certificados SSL","fr":"L''outil de gestion DNS est un outil de Chat API qui permet de gérer les enregistrements DNS et les certificats SSL","de":"Die DNS-Verwaltungstool ist ein Tool von Chat API, das die Verwaltung von DNS-Einträgen und SSL-Zertifikaten ermöglicht","pt":"O DNS é um sistema de gerenciamento de registros de domínio que permite configurar e gerenciar registros DNS e certificados SSL.","ru":"DNS - это система управления записями домена, которая позволяет настраивать и управлять записями DNS и сертификатами SSL для ИИ Агентов.","ar":"DNS هو نظام لإدارة سجلات المجال التي يسمح بتهيئة وإدارة السجلات DNS وشهادات SSL للأدوات الذكية."},"features":{"en":["List Domains: View all domains under the configured account (Aliyun/Tencent)","Get Records: Retrieve DNS records for a specific domain","Add/Delete Records: Modify DNS records using the ChatTool library","DDNS: Update dynamic DNS records","SSL Certificates: Request or renew Let''s Encrypt certificates"],"zh":["列出域名","获取 DNS 记录","添加/删除 DNS 记录","动态 DNS 更新","SSL 证书请求和更新"],"ja":["ドメインの一覧表示","DNS レコードの取得","DNS レコードの追加/削除","動的 DNS 更新","SSL 証明書の要求と更新"],"ko":["도메인 목록","DNS 기록 조회","DNS 기록 추가/삭제","동적 DNS 업데이트","SSL 인증서 요청 및 갱신"],"es":["Lista de dominios","Recuperación de registros DNS","Agregar o eliminar registros DNS","Actualización de registros DNS dinámicos","Solicitud o renovación de certificados SSL de Let''s Encrypt"],"fr":["Liste des domaines","Récupération des enregistrements DNS","Ajout ou suppression d''enregistrements DNS","Mise à jour des enregistrements DNS dynamiques","Demande ou renouvellement de certificats SSL Let''s Encrypt"],"de":[" Liste der Domains","Abruf von DNS-Einträgen","Hinzufügen oder Löschen von DNS-Einträgen","Aktualisierung von dynamischen DNS-Einträgen","Anforderung oder Verlängerung von SSL-Zertifikaten von Let''s Encrypt"],"pt":["Listagem de domínios configurados","Obtenção de registros DNS para um domínio específico","Adição e exclusão de registros DNS","Atualização de registros DNS dinâmicos","Gerenciamento de certificados SSL com Let''s Encrypt"],"ru":["Список настроенных доменов","Получение записей DNS для конкретного домена","Добавление и удаление записей DNS","Обновление динамических записей DNS","Управление сертификатами SSL с Let''s Encrypt для ИИ Агентов"],"ar":["قائمة المجالات المconfigured","الحصول على السجلات DNS لمجال معين","إضافة وحذف السجلات DNS","تحديث السجلات DNS الديناميكية","إدارة شهادات SSL مع Let''s Encrypt للأدوات الذكية"]},"keywords":{"en":["how to use dns","dns setup guide","dns alternative","dns vs cloudflare","dns install","dynamic dns management","what is dns","dns for ai agents","dns management toolkit"],"zh":["DNS 管理工具","DNS 记录管理","SSL 证书管理","Aliyun DNS","Tencent DNS","动态 DNS 更新","SSL 证书请求","DNS 设置指南"],"ja":["DNS マネージャー AIエージェント","DNS レコード管理","SSL 証明書管理","Aliyun DNS","Tencent DNS","動的 DNS 更新","SSL 証明書の要求","DNS 設定ガイド"],"ko":["DNS 관리 도구","DNS 기록 관리","SSL 인증서 관리","Aliyun DNS","Tencent DNS","동적 DNS 업데이트","SSL 인증서 요청","DNS 설정 가이드"],"es":["herramienta de gestión de DNS","registros DNS","certificados SSL","Chat API","gestión de dominios","actualización de registros DNS","Let''s Encrypt","SSL","DNS dinámico"],"fr":["outil de gestion DNS","enregistrements DNS","certificats SSL","Chat API","gestion de domaines","mise à jour des enregistrements DNS","Let''s Encrypt","SSL","DNS dynamique"],"de":["DNS-Verwaltungstool","DNS-Einträge","SSL-Zertifikate","Chat API","Domainverwaltung","Aktualisierung von DNS-Einträgen","Let''s Encrypt","SSL","dynamischer DNS"],"pt":["dns","gerenciamento de registros dns","certificados ssl","chattool library","listagem de domínios","obtenção de registros dns","adição e exclusão de registros dns","atualização de registros dns dinâmicos","gerenciamento de certificados ssl"],"ru":["dns","управление записями dns","сертификаты ssl","chattool library","список доменов","получение записей dns","добавление и удаление записей dns","обновление динамических записей dns","управление сертификатами ssl для ИИ Агентов"],"ar":["dns","إدارة السجلات DNS","شهادات SSL","مكتبة ChatTool","قائمة المجالات","الحصول على السجلات DNS","إضافة وحذف السجلات DNS","تحديث السجلات DNS الديناميكية","إدارة شهادات SSL للأدوات الذكية"]}},"owner":"cubenlp","repo":"ChatTool","repoPath":"cubenlp/ChatTool","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.270Z","topics":[],"category":"community","skillMd":{"name":"dns","description":"Manages DNS records, DDNS, and SSL certificates using ChatTool. Invoke when user wants to list domains, modify DNS records, or update certificates.","bodyPreview":"# DNS Manager\n\nThis skill allows you to manage DNS records and SSL certificates using the ChatTool library.\n\n## Capabilities\n\n- **List Domains**: View all domains under the configured account (Aliyun/Tencent).\n- **Get Records**: Retrieve DNS records for a specific domain.\n- **Add/Delete Records**: Modify DNS records.\n- **DDNS**: Update dynamic DNS records.\n- **SSL Certificates**: Request or renew Let''s Encrypt certificates.\n\n## Tools\n\nYou should use the available MCP tools for these operations:","body":"# DNS Manager\n\nThis skill allows you to manage DNS records and SSL certificates using the ChatTool library.\n\n## Capabilities\n\n- **List Domains**: View all domains under the configured account (Aliyun/Tencent).\n- **Get Records**: Retrieve DNS records for a specific domain.\n- **Add/Delete Records**: Modify DNS records.\n- **DDNS**: Update dynamic DNS records.\n- **SSL Certificates**: Request or renew Let''s Encrypt certificates.\n\n## Tools\n\nYou should use the available MCP tools for these operations:\n- `dns_list_domains`\n- `dns_get_records`\n- `dns_add_record`\n- `dns_delete_record`\n- `dns_ddns_update`\n- `dns_cert_update`\n\n## Configuration\n\nEnsure the environment variables for the DNS provider are set (e.g., `ALIBABA_CLOUD_ACCESS_KEY_ID`, `TENCENT_CLOUD_SECRET_ID`, etc.).\n"},"lastSynced":"2026-03-08T02:00:12.257Z","agentAnalysis":{"suitability":{"en":"Ideal for Network Administration Agents requiring dynamic DNS management and SSL certificate automation.","zh":"适用于需要动态DNS管理和SSL证书自动化的网络管理代理。","ja":"動的DNS管理およびSSL証明書の自動化を必要とするネットワーク管理エージェントに適しています。","ko":"동적 DNS 관리 및 SSL 인증서 자동화가 필요한 네트워크 관리 에이전트에 적합합니다.","es":"Ideal para agentes de administración de redes que requieren gestión dinámica de DNS y automatización de certificados SSL.","fr":"Idéal pour les agents d''administration réseau nécessitant une gestion dynamique de DNS et une automatisation de certificats SSL.","de":"Ideal für Netzwerkadministration-Agenten, die eine dynamische DNS-Verwaltung und eine Automatisierung von SSL-Zertifikaten erfordern.","pt":"Ideal para Agentes de Administração de Rede que exigem gerenciamento de DNS dinâmico e automação de certificado SSL.","ru":"Идеально для агентов сетевой администрации, требующих динамического управления DNS и автоматизации сертификатов SSL.","ar":"مثالي لعمليات وكيل إدارة الشبكة التي تتطلب إدارة DNS ديناميكي وتضمين شهادات SSL."},"recommendation":{"en":"Empowers agents to manage DNS records and SSL certificates using the ChatTool library, supporting features like listing domains, retrieving DNS records, and requesting Let''s Encrypt certificates over protocols like HTTPS.","zh":"赋予代理管理DNS记录和SSL证书的能力，使用ChatTool库，支持列出域名、检索DNS记录、以及请求Let''s Encrypt证书等功能，通过HTTPS等协议。","ja":"ChatToolライブラリを使用して、エージェントがDNSレコードとSSL証明書を管理できるようにし、ドメインのリスト表示、DNSレコードの取得、Let''s Encrypt証明書の要求などの機能をサポートし、HTTPSなどのプロトコルを介して通信します。","ko":"ChatTool 라이브러리를 사용하여 에이전트가 DNS 레코드 및 SSL 인증서를 관리할 수 있도록 하며, 도메인 목록 표시, DNS 레코드 검색, Let''s Encrypt 인증서 요청 등의 기능을 지원하며, HTTPS 등의 프로토콜을 통해 통신합니다.","es":"Habilita a los agentes a gestionar registros DNS y certificados SSL utilizando la biblioteca ChatTool, que admite características como la lista de dominios, la recuperación de registros DNS y la solicitud de certificados Let''s Encrypt a través de protocolos como HTTPS.","fr":"Permet aux agents de gérer les enregistrements DNS et les certificats SSL en utilisant la bibliothèque ChatTool, qui prend en charge des fonctionnalités comme la liste des domaines, la récupération des enregistrements DNS et la demande de certificats Let''s Encrypt via des protocoles comme HTTPS.","de":"Ermächtigt die Agenten, DNS-Einträge und SSL-Zertifikate mithilfe der ChatTool-Bibliothek zu verwalten, die Funktionen wie die Auflistung von Domains, das Abrufen von DNS-Einträgen und das Anfordern von Let''s Encrypt-Zertifikaten über Protokolle wie HTTPS unterstützt.","pt":"Permite que os agentes gerenciem registros de DNS e certificados SSL usando a biblioteca ChatTool, com recursos como listagem de domínios, recuperação de registros de DNS e solicitação de certificados Let''s Encrypt sobre protocolos como HTTPS.","ru":"Наделяет агентов возможностью управлять записями DNS и сертификатами SSL с помощью библиотеки ChatTool, поддерживающей функции, такие как перечисление доменов, получение записей DNS и запрос сертификатов Let''s Encrypt по протоколам, таким как HTTPS.","ar":"يمكّن الوكلاء من إدارة سجلات DNS وشهادات SSL باستخدام مكتبة ChatTool، ودعم الميزات مثل قائمة النطاقات، واسترجاع سجلات DNS، وطلب شهادات Let''s Encrypt عبر بروتوكولات مثل HTTPS."},"useCases":{"en":["Automating DNS record updates","Generating Let''s Encrypt SSL certificates","Debugging domain configuration issues","Updating dynamic DNS records"],"zh":["自动更新DNS记录","生成Let''s Encrypt SSL证书","调试域配置问题","更新动态DNS记录"],"ja":["DNSレコードの自動更新","Let''s Encrypt SSL証明書の生成","ドメイン構成の問題のデバッグ","動的DNSレコードの更新"],"ko":["DNS 레코드 자동 업데이트","Let''s Encrypt SSL 인증서 생성","도메인 구성 문제 디버깅","동적 DNS 레코드 업데이트"],"es":["Automatización de actualizaciones de registros DNS","Generación de certificados SSL de Let''s Encrypt","Depuración de problemas de configuración de dominio","Actualización de registros DNS dinámicos"],"fr":["Automatisation des mises à jour des enregistrements DNS","Génération de certificats SSL Let''s Encrypt","Débogage des problèmes de configuration de domaine","Mise à jour des enregistrements DNS dynamiques"],"de":["Automatisierung von DNS-Eintrag-Aktualisierungen","Generierung von Let''s Encrypt-SSL-Zertifikaten","Fehlerbehebung bei Domain-Konfigurationsproblemen","Aktualisierung von dynamischen DNS-Einträgen"],"pt":["Automatizar atualizações de registros de DNS","Gerar certificados SSL Let''s Encrypt","Depurar problemas de configuração de domínio","Atualizar registros de DNS dinâmicos"],"ru":["Автоматизировать обновления записей DNS","Генерировать сертификаты SSL Let''s Encrypt","Отлаживать проблемы конфигурации домена","Обновлять динамические записи DNS"],"ar":["توفير تحديثات سجلات DNS","توليد شهادات SSL Let''s Encrypt","تصحيح أخطاء تهيئة النطاق","تحديث سجلات DNS الديناميكية"]},"limitations":{"en":["Requires Aliyun or Tencent account configuration","Limited to ChatTool library compatibility"],"zh":["需要阿里云或腾讯云账户配置","仅限ChatTool库兼容性"],"ja":["アリババクラウドまたはテンセントクラウドアカウントの構成が必要","ChatToolライブラリの互換性に限られる"],"ko":["阿里巴巴 클라우드 또는 텐센트 클라우드 계정 구성 필요","ChatTool 라이브러리 호환성에 제한됨"],"es":["Requiere configuración de cuenta de Aliyun o Tencent","Limitado a la compatibilidad de la biblioteca ChatTool"],"fr":["Nécessite une configuration de compte Aliyun ou Tencent","Limité à la compatibilité de la bibliothèque ChatTool"],"de":["Erfordert Aliyun- oder Tencent-Kontokonfiguration","Begrenzt auf die Kompatibilität der ChatTool-Bibliothek"],"pt":["Exige configuração de conta Aliyun ou Tencent","Limitado à compatibilidade da biblioteca ChatTool"],"ru":["Требует настройки учетной записи Aliyun или Tencent","Ограничен совместимостью библиотеки ChatTool"],"ar":["يتطلب تكوين حساب Aliyun أو Tencent","محدود بالتوافق مع مكتبة ChatTool"]},"version":4},"contentHash":"bf23ce97f2c3bde2e3f5f9016548ed5ff7bc396bc1af50c2684b943015ffa8de","qualityScore":23}');
