INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cubenlp/ChatTool/dns', 'dns', 'cubenlp', 'ChatTool', 'community', 'dns cubenlp ChatTool community The dns skill allows developers to manage DNS records and SSL certificates using the ChatTool library, supporting features like listing domains and retrieving DNS records. DNS 管理工具允许您管理 DNS 记录和 SSL 证书，支持 Aliyun 和 Tencent。 DNS マネージャー AIエージェントは、DNS レコードと SSL 証明書を管理するためのツールキットです。 DNS 관리 도구는 DNS 기록과 SSL 인증서를 관리하기 위한 툴킷입니다. La herramienta de gestión de DNS permite administrar registros DNS y certificados SSL para Chat API. Incluye capacidades como lista de dominios, recuperación de registros y actualización de certificados SSL. L''outil de gestion DNS permet de gérer les enregistrements DNS et les certificats SSL pour Chat API. Il inclut des capacités comme la liste des domaines, la récupération des enregistrements et la mise à jour des certificats SSL. Die DNS-Verwaltungstool ermöglicht die Verwaltung von DNS-Einträgen und SSL-Zertifikaten für Chat API. Sie umfasst Funktionen wie die Liste der Domains, die Abruf von Einträgen und die Aktualisierung von SSL-Zertifikaten. O skill DNS permite gerenciar registros DNS e certificados SSL usando a biblioteca ChatTool. Ele oferece funcionalidades como listagem de domínios, obtenção de registros e gerenciamento de certificados SSL. Навык DNS позволяет управлять записями DNS и сертификатами SSL с помощью библиотеки ChatTool. Он предлагает функции, такие как список доменов, получение записей и управление сертификатами SSL для ИИ Агентов. المهارة DNS تمكنك من إدارة السجلات DNS وشهادات SSL باستخدام مكتبة ChatTool. وهي توفر ميزات مثل قائمة المجالات و الحصول على السجلات وإدارة شهادات SSL للأدوات الذكية. how to use dns dns setup guide dns alternative dns vs cloudflare dns install dynamic dns management what is dns dns for ai agents dns management toolkit DNS 管理工具 DNS 记录管理 SSL 证书管理 Aliyun DNS Tencent DNS 动态 DNS 更新 SSL 证书请求 DNS 设置指南 List Domains: View all domains under the configured account (Aliyun/Tencent) Get Records: Retrieve DNS records for a specific domain Add/Delete Records: Modify DNS records using the ChatTool library DDNS: Update dynamic DNS records SSL Certificates: Request or renew Let''s Encrypt certificates dns is a toolkit for managing DNS records and SSL certificates, enabling developers to modify DNS records and request Let''s Encrypt certificates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CsHeng/dot-claude/git', 'community', 'CsHeng', 'dot-claude', 'CsHeng/dot-claude', 'git', 0, 0, 23, '2026-03-08T01:57:15.272Z', '2026-03-08T02:00:23.015Z', '0e980e9c544011e91c233808dcf277e22d65731f5337f2a41f6204ab05aab6c9', '{"id":"CsHeng/dot-claude/git","name":"git","description":{"en":"The git skill allows AI agents to inspect and manage git repositories using commands like git.status and git.diff. It benefits developers by providing a safe way to apply patches.","zh":"本文介绍如何使用 Claude 代码规则和命令来管理 git 项目，包括 git 状态、差异和补丁应用","ja":"本文では、Claude コード ルールとコマンドを使用して git プロジェクトを管理する方法を紹介します。git 状態、差異、パッチ適用など","ko":"본 문서는 Claude 코드 규칙과 명령을 사용하여 git 프로젝트를 관리하는 방법을 소개합니다. git 상태, 차이, 패치 적용 등","es":"El skill de git permite a los agentes de IA realizar operaciones de lectura y escritura de forma segura. Utiliza comandos como git.status y git.diff para inspeccionar y aplicar parches.","fr":"Le skill de git permet aux outils d''IA d''effectuer des opérations de lecture et d''écriture de manière sécurisée. Utilisez des commandes comme git.status et git.diff pour inspecter et appliquer des correctifs.","de":"Das git-Skill ermöglicht es KI-Tools, Lese- und Schreiboperationen sicher durchzuführen. Verwenden Sie Befehle wie git.status und git.diff, um zu inspectieren und Patches anzuwenden.","pt":"O Git é uma ferramenta essencial para controle de versão, com comandos como git.status e git.diff. Saiba como usá-los de forma segura.","ru":"Git - это важнейший инструмент для контроля версий, с командами seperti git.status и git.diff. Узнайте, как использовать их безопасно для ИИ Агентов.","ar":"Git هو أداة أساسية للتحكم في الإصدارات، مع أوامر مثل git.status و git.diff. تعرف على كيفية استخدامهم بأمان للأدوات الذكية."},"seo":{"title":{"en":"git: Setup Guide for AI Agents | AI Agent Skill","zh":"git Setup Guide: 使用 Claude 代码规则和命令","ja":"git Setup Guide: Claude コード ルールとコマンドの使用","ko":"git 설정 가이드: Claude 코드 규칙 및 명령 사용","es":"Guía de configuración de git para agentes de IA","fr":"Guide de mise en place de git pour les outils d''IA","de":"Git-Konfigurationsleitfaden für KI-Tools","pt":"Guia de Configuração Git: Comandos e Práticas de Segurança","ru":"Настройка Git: Руководство по командам и безопасным практ...","ar":"دليل إعداد Git: أوامر وأفضل الممارسات للأدوات الذكية"},"description":{"en":"Unlock git''s potential with our AI agent skill. Learn how to sync rules and apply patches safely. Get started now and optimize your workflow!","zh":"了解如何使用 Claude 代码规则和命令来管理 git 项目，包括 git 状态、差异和补丁应用","ja":"Claude コード ルールとコマンドを使用して git プロジェクトを管理する方法を学びます。git 状態、差異、パッチ適用など","ko":"Claude 코드 규칙과 명령을 사용하여 git 프로젝트를 관리하는 방법을 알아보세요. git 상태, 차이, 패치 적용 등","es":"Aprende a configurar git para agentes de IA con nuestra guía paso a paso y aprovecha funciones como git.status y git.diff","fr":"Découvrez comment configurer git pour les outils d''IA avec notre guide étape par étape et profitez de fonctionnalités comme git.status et git.diff","de":"Erfahren Sie, wie Sie git für KI-Tools konfigurieren, mit unserer Schritt-für-Schritt-Anleitung und nutzen Sie Funktionen wie git.status und git.diff","pt":"Aprenda a configurar e utilizar o Git de forma segura com comandos como git.status e git.diff, e entenda as restrições para operações de commit e push.","ru":"Узнайте, как настроить и использовать Git безопасно с командами seperti git.status и git.diff, и поймите ограничения для операций commit и push для ИИ Агентов.","ar":"تعرف على كيفية إعداد وتشغيل Git بأمان باستخدام أوامر مثل git.status و git.diff، وفهم القيود لعمليات Commit و Push للأدوات الذكية."},"definition":{"en":"git is a version control system that enables AI agents to manage and synchronize code repositories using specific commands and settings.","zh":"git 是一个版本控制系统，Claude 代码规则和命令用于管理 git 项目","ja":"git はバージョン管理システムであり、Claude コード ルールとコマンドは git プロジェクトを管理するために使用されます","ko":"git은 버전 관리 시스템이며, Claude 코드 규칙과 명령은 git 프로젝트를 관리하는 데 사용됩니다","es":"El skill de git es una función que permite a los agentes de IA interactuar con el sistema de control de versiones git de forma segura","fr":"Le skill de git est une fonctionnalité qui permet aux outils d''IA d''interagir avec le système de contrôle de version git de manière sécurisée","de":"Das git-Skill ist eine Funktion, die es KI-Tools ermöglicht, mit dem Versionskontrollsystem git sicher zu interagieren","pt":"O que é Git? É um sistema de controle de versão que permite gerenciar alterações no código.","ru":"Что такое Git? Это система контроля версий, которая позволяет управлять изменениями в коде для ИИ Агентов.","ar":"ما هو Git؟ إنه نظام التحكم في الإصدارات الذي يسمح بإدارة التغييرات في الكود للأدوات الذكية."},"features":{"en":["Executes git.status command for repository inspection","Runs git.diff command for change detection","Applies patches safely using git.applyPatch command","Syncs rules for Droid, OpenCode, Codex, Qwen, Cursor, and Copilot","Operates in read-only mode with safe patch application"],"zh":["git 状态检查","git 差异比较","git 补丁应用","只读检查和安全补丁应用","不执行 git 提交、推送或破坏性历史操作"],"ja":["git 状態の確認","git 差異の比較","git パッチの適用","読み取り専用の確認と安全なパッチ適用","git コミット、プッシュ、または破壊的な履歴操作の実行をしない"],"ko":["git 상태 확인","git 차이 비교","git 패치 적용","읽기 전용 확인 및 안전한 패치 적용","git 커밋, 푸시 또는 파괴적인 기록 작업을 수행하지 않음"],"es":["Soporte para comandos git como git.status y git.diff","Aplicación de parches de forma segura","Inspección de cambios con git.applyPatch","Compatibilidad con Droid, OpenCode, Codex, Qwen, Cursor y Copilot"],"fr":["Prise en charge des commandes git comme git.status et git.diff","Application de correctifs de manière sécurisée","Inspection des modifications avec git.applyPatch","Compatibilité avec Droid, OpenCode, Codex, Qwen, Cursor et Copilot"],"de":["Unterstützung für git-Befehle wie git.status und git.diff","Sichere Anwendung von Patches","Überprüfung von Änderungen mit git.applyPatch","Kompatibilität mit Droid, OpenCode, Codex, Qwen, Cursor und Copilot"],"pt":["Comandos git.status e git.diff para inspeção do código","Aplicação de patches de forma segura com git.applyPatch","Restrições para operações de commit e push para evitar perda de dados","Integração com Claude Code para sincronização de regras","Suporte a Droid, OpenCode, Codex, Qwen, Cursor e Copilot"],"ru":["Команды git.status и git.diff для инспекции кода","Применение патчей безопасно с git.applyPatch для ИИ Агентов","Ограничения для операций commit и push для предотвращения потери данных","Интеграция с Claude Code для синхронизации правил","Поддержка Droid, OpenCode, Codex, Qwen, Cursor и Copilot"],"ar":["أوامر git.status و git.diff لتفقيد الكود","تطبيق التصحيحات بأمان مع git.applyPatch للأدوات الذكية","قيود للعمليات Commit و Push لتجنب فقدان البيانات","التكامل مع Claude Code لتنسيق القواعد","دعم Droid و OpenCode و Codex و Qwen و Cursor و Copilot"]},"keywords":{"en":["how to use git with AI agents","git setup guide for developers","git alternative for version control","git vs SVN","git install for AI agents","git best practices for patch application"],"zh":["git 管理","Claude 代码规则","git 命令","版本控制系统","git 状态检查","git 差异比较","git 补丁应用","AI 工具","AI 에이전트"],"ja":["git 管理","Claude コード ルール","git コマンド","バージョン管理システム","git 状態の確認","git 差異の比較","git パッチの適用","AI エージェント","AI ツール"],"ko":["git 관리","Claude 코드 규칙","git 명령","버전 관리 시스템","git 상태 확인","git 차이 비교","git 패치 적용","AI 에이전트","AI 도구"],"es":["git para agentes de IA","configuración de git","comandos git","aplicación de parches","inspección de cambios","Droid","OpenCode","Codex","Qwen","Cursor","Copilot"],"fr":["git pour outils d''IA","configuration de git","commandes git","application de correctifs","inspection de modifications","Droid","OpenCode","Codex","Qwen","Cursor","Copilot"],"de":["git für KI-Tools","Konfiguration von git","git-Befehle","Anwendung von Patches","Überprüfung von Änderungen","Droid","OpenCode","Codex","Qwen","Cursor","Copilot"],"pt":["git configuração","git comandos","git segurança","controle de versão","desenvolvimento de software","ferramentas de desenvolvimento","git para iniciantes","git avançado"],"ru":["настройка git","команды git","безопасность git","контроль версий","разработка программного обеспечения","инструменты разработки","git для начинающих","advanced git для ИИ Агентов"],"ar":["إعداد git","أوامر git","أمان git","تحكم في الإصدارات","تطوير البرمجيات","أدوات التطوير","git للمبتدئين","git المتقدم للأدوات الذكية"]}},"owner":"CsHeng","repo":"dot-claude","repoPath":"CsHeng/dot-claude","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.272Z","topics":[],"category":"community","skillMd":{"name":"git","description":"Execution-layer skill for git inspection and safe patching","bodyPreview":"## Commands\n\n- git.status\n- git.diff\n- git.applyPatch\n\n## Constraints\n\n- Never run git commit, push, or destructive history operations.\n- Primary focus is read-only inspection plus safe patch application.","body":"## Commands\n\n- git.status\n- git.diff\n- git.applyPatch\n\n## Constraints\n\n- Never run git commit, push, or destructive history operations.\n- Primary focus is read-only inspection plus safe patch application.\n"},"lastSynced":"2026-03-08T02:00:23.015Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring version control and patch management capabilities through git","zh":"适合需要通过git进行版本控制和补丁管理的开发代理","ja":"gitを介したバージョン管理およびパッチ管理機能を必要とする開発エージェントに適しています","ko":"git를 통해 버전 관리 및 패치 관리 기능을 필요로 하는 개발 에이전트에 적합합니다","es":"Ideal para agentes de desarrollo que requieren control de versiones y capacidades de administración de parches a través de git","fr":"Idéal pour les agents de développement nécessitant une gestion de version et des capacités de gestion de correctifs via git","de":"Ideal für Entwicklungssagenten, die Versionierung und Patch-Management-Funktionen über git erfordern","pt":"Ideal para Agentes de Desenvolvimento que requerem controle de versão e capacidades de gerenciamento de patches por meio do git","ru":"Идеально для агентов разработки, требующих управления версиями и возможностей управления патчами через git","ar":"مثالي لعمليات التطوير التي تتطلب التحكم في الإصدار وإدارة التصحيحات من خلال git"},"recommendation":{"en":"Empowers agents to inspect git repositories using git.status and git.diff commands, and apply patches safely with git.applyPatch, ensuring a controlled development environment with read-only inspection and secure patch application","zh":"赋予代理检查git仓库使用git.status和git.diff命令的能力，并使用git.applyPatch安全地应用补丁，确保受控的开发环境，包括只读检查和安全的补丁应用","ja":"git.statusおよびgit.diffコマンドを使用してgitリポジトリを検査し、git.applyPatchを使用して安全にパッチを適用する機能をエージェントに提供し、制御された開発環境を確保します。読み取り専用の検査と安全なパッチ適用を提供します","ko":"git.status 및 git.diff 명령을 사용하여 git 리포지토리를 검사하고 git.applyPatch를 사용하여 보안으로 패치를 적용하여 제어된 개발 환경을 제공합니다. 읽기 전용 검사 및 보안 패치 적용을 제공합니다","es":"Habilita a los agentes a inspeccionar repositorios git utilizando los comandos git.status y git.diff, y aplicar parches de forma segura con git.applyPatch, asegurando un entorno de desarrollo controlado con inspección de solo lectura y aplicación de parches seguros","fr":"Permet aux agents d''inspecter les référentiels git à l''aide des commandes git.status et git.diff, et d''appliquer des correctifs de manière sécurisée avec git.applyPatch, garantissant un environnement de développement contrôlé avec inspection en lecture seule et application de correctifs sécurisée","de":"Ermächtigt Agenten, git-Repositorys mit den Befehlen git.status und git.diff zu untersuchen und Patches sicher mit git.applyPatch anzuwenden, wodurch ein kontrolliertes Entwicklungsumfeld mit schreibgeschützter Untersuchung und sicherer Patchanwendung gewährleistet wird","pt":"Permite que os agentes inspecionem repositórios git usando os comandos git.status e git.diff, e apliquem patches de forma segura com git.applyPatch, garantindo um ambiente de desenvolvimento controlado com inspeção somente leitura e aplicação de patches segura","ru":"Позволяет агентам осматривать репозитории git с помощью команд git.status и git.diff, и применять патчи безопасно с git.applyPatch, обеспечивая контролируемую среду разработки с чтением только и безопасным применением патчей","ar":"تمكن العميل من فحص مستودعات git باستخدام أوامر git.status و git.diff، وتطبيق التصحيحات بأمان باستخدام git.applyPatch، مما يضمن بيئة تطوير خاضعة للرقابة مع فحص القراءة فقط وتطبيق تصحيحات آمن"},"useCases":{"en":["Inspecting repository status with git.status","Comparing changes with git.diff","Applying patches securely with git.applyPatch"],"zh":["使用git.status检查仓库状态","使用git.diff比较更改","使用git.applyPatch安全地应用补丁"],"ja":["git.statusを使用してリポジトリの状態を確認する","git.diffを使用して変更を比較する","git.applyPatchを使用して安全にパッチを適用する"],"ko":["git.status를 사용하여 리포지토리 상태를 확인하는こと","git.diff를 사용하여 변경 사항을 비교하는 것","git.applyPatch를 사용하여 안전하게 패치를 적용하는 것"],"es":["Inspeccionar el estado del repositorio con git.status","Comparar cambios con git.diff","Aplicar parches de forma segura con git.applyPatch"],"fr":["Inspecter l''état du référentiel avec git.status","Comparer les modifications avec git.diff","Appliquer des correctifs de manière sécurisée avec git.applyPatch"],"de":["Status des Repositorys mit git.status untersuchen","Änderungen mit git.diff vergleichen","Patches sicher mit git.applyPatch anwenden"],"pt":["Inspecionar status do repositório com git.status","Comparar alterações com git.diff","Aplicar patches de forma segura com git.applyPatch"],"ru":["Осматривать статус репозитория с помощью git.status","Сравнивать изменения с помощью git.diff","Применять патчи безопасно с помощью git.applyPatch"],"ar":["فحص حالة المستودع مع git.status","مقارنة التغييرات مع git.diff","تطبيق التصحيحات بأمان مع git.applyPatch"]},"limitations":{"en":["Never runs git commit, push, or destructive history operations","Primary focus is read-only inspection plus safe patch application"],"zh":["永远不会执行git commit、push或破坏性历史操作","主要关注点是只读检查和安全的补丁应用"],"ja":["git commit、push、または破壊的な履歴操作は実行しません","主な焦点は読み取り専用の検査と安全なパッチ適用です"],"ko":["git commit, push 또는 파괴적인 기록 작성을 절대로 실행하지 않음","주된 초점은 읽기 전용 검사 및 안전한 패치 적용입니다"],"es":["Nunca ejecuta git commit, push o operaciones de historia destructiva","Enfoque principal es la inspección de solo lectura más la aplicación de parches segura"],"fr":["Ne lance jamais git commit, push ou opérations d''historique destructives","Focus principal est l''inspection en lecture seule plus l''application de correctifs sécurisée"],"de":["Führt nie git commit, push oder destruktive Historienoperationen aus","Hauptfokus liegt auf schreibgeschützter Untersuchung und sicherer Patchanwendung"],"pt":["Nunca executa git commit, push ou operações de histórico destrutivas","Foco principal é inspeção somente leitura mais aplicação de patches segura"],"ru":["Никогда не выполняет git commit, push или разрушительные операции с историей","Основной焦ус - чтение только и безопасное применение патчей"],"ar":["أبدا لا ينفذ git commit، push أو عمليات التاريخ التدميرية","التركيز الرئيسي هو فحص القراءة فقط وتطبيق تصحيحات آمن"]},"version":4},"contentHash":"0e980e9c544011e91c233808dcf277e22d65731f5337f2a41f6204ab05aab6c9","qualityScore":23}');
