INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rubenvitt/bluelight-hub/bmad-bmb-edit-workflow', 'bmad-bmb-edit-workflow', 'rubenvitt', 'bluelight-hub', 'community', 'bmad-bmb-edit-workflow rubenvitt bluelight-hub community The bmad-bmb-edit-workflow skill enables AI agents to edit workflows by loading the workflow-edit-workflow.md file, providing a critical workflow editing capability for developers. bmad-bmb-edit-workflow是用于编辑工作流的AI工具，需要加载特定工作流文件并遵循指令 bmad-bmb-edit-workflowはワークフロー編集用のAIエージェントで、特定のワークフローファイルを読み込み指示に従う必要がある bmad-bmb-edit-workflow는 워크플로 편집을 위한 AI 도구로 특정 워크플로 파일을 로드하고 지침을 따라야 함 El flujo de trabajo de edición de bmad-bmb-edit-workflow permite a los desarrolladores cargar y editar flujos de trabajo de manera eficiente Le flux de travail d''édition de bmad-bmb-edit-workflow permet aux développeurs de charger et d''éditer des flux de travail de manière efficace Der Edit-Workflow von bmad-bmb-edit-workflow ermöglicht es Entwicklern, Workflows effizient zu laden und zu bearbeiten O bmad-bmb-edit-workflow é uma ferramenta para edição de fluxos de trabalho que exige a carga do arquivo workflow-edit-workflow.md para funcionar corretamente bmad-bmb-edit-workflow - это инструмент для редакции рабочих процессов, который требует загрузки файла workflow-edit-workflow.md для правильной работы с ИИ Агентами bmad-bmb-edit-workflow هو أداة لتعديل سير العمل التي تتطلب تحميل ملف workflow-edit-workflow.md للعمل بشكل صحيح مع أدوات الذكاء الاصطناعي how to use bmad-bmb-edit-workflow bmad-bmb-edit-workflow setup guide what is bmad-bmb-edit-workflow bmad-bmb-edit-workflow alternative bmad-bmb-edit-workflow vs other workflow editing tools bmad-bmb-edit-workflow install workflow editing with AI agents bmad-bmb-edit-workflow workflow-edit-workflow.md AI agent workflow editing best practices bmad-bmb-edit-workflow AIエージェント 工作流编辑 CLI命令行工具 AI工具开发 工作流自动化 效率开发 Loads workflow-edit-workflow.md for step-by-step editing guidance Requires following directions exactly as outlined in the workflow-edit-workflow.md file Critical for workflow editing in AI agent applications Dependent on loading the full {project-root}/_bmad/bmb/workflows/workflow/workflow-edit-workflow.md file Enables efficient workflow editing for developers Supports AI agent workflow editing via specific command execution bmad-bmb-edit-workflow is a skill that allows AI agents to edit workflows by following specific directions outlined in the workflow-edit-workflow.md file');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ojowwalker77/Claude-Matrix/Matrix List', 'community', 'ojowwalker77', 'Claude-Matrix', 'ojowwalker77/Claude-Matrix', 'Matrix List', 0, 0, 23, '2026-03-08T01:57:15.286Z', '2026-03-08T02:00:56.825Z', 'ae0439b66cc72d91471f7f38a4e8df9065fb7bdb363d64532fbe3c9a5da1a635', '{"id":"ojowwalker77/Claude-Matrix/Matrix List","name":"Matrix List","description":{"en":"Matrix List is a tool for displaying and exporting Matrix memory contents and statistics, benefiting developers working with Claude on Rails. It provides detailed information and solutions lists.","zh":"Matrix List 是 Claude on Rails 的工具系统，用于显示和导出 Matrix 内存内容和统计信息","ja":"Matrix List は Claude on Rails のツールシステムで、Matrix 内存内容と統計情報を表示およびエクスポートします","ko":"Matrix List는 Claude on Rails의 툴 시스템으로 Matrix 메모리 내용 및 통계 정보를 표시하고 내보냅니다","es":"Matrix List es una herramienta de Claude on Rails que permite a los desarrolladores mostrar y exportar contenidos de memoria y estadísticas","fr":"Matrix List est un outil de Claude on Rails qui permet aux développeurs d''afficher et d''exporter les contenus de mémoire et les statistiques","de":"Matrix List ist ein Tool von Claude on Rails, mit dem Entwickler Speicherinhalte und Statistiken anzeigen und exportieren können","pt":"O Matrix List é uma ferramenta para exibir e exportar conteúdos de memória e estatísticas de desempenho do Claude Code","ru":"Matrix List - это инструмент для отображения и экспорта содержимого памяти и статистики производительности кода Claude для ИИ Агентов","ar":"قائمة المصفوفة هي أداة لعرض وإخراج محتويات الذاكرة و الإحصائيات الأدائية ل كود كلود من أجل أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Matrix List: Setup Guide for AI Agents | AI Agent Skill","zh":"Matrix List 设置指南 - Claude on Rails 工具系统","ja":"Matrix List 導入ガイド - Claude on Rails ツールシステム","ko":"Matrix List 설정 가이드 - Claude on Rails 툴 시스템","es":"Guía de Configuración de Matrix List para Desarrolladores","fr":"Guide de Mise en Place de Matrix List pour Développeurs","de":"Einrichtungsleitfaden für Matrix List für Entwickler","pt":"Guia de Configuração do Matrix List para Desenvolvedores","ru":"Руководство по настройке Matrix List для разработчиков ИИ...","ar":"دليل إعداد قائمة المصفوفة لمنشئي أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to use Matrix List to display and export Matrix memory contents and statistics. Learn how to retrieve information with matrix_status and more.","zh":"了解 Matrix List 的功能和用途，包括显示和导出 Matrix 内存内容和统计信息","ja":"Matrix List の機能と用途をご紹介します。Matrix 内存内容と統計情報の表示とエクスポートが可能です","ko":"Matrix List 기능 및 용도를 살펴보세요. Matrix 메모리 내용 및 통계 정보를 표시하고 내보낼 수 있습니다","es":"Aprende a utilizar Matrix List para mostrar y exportar contenidos de memoria y estadísticas con Claude on Rails","fr":"Découvrez comment utiliser Matrix List pour afficher et exporter les contenus de mémoire et les statistiques avec Claude on Rails","de":"Erfahren Sie, wie Sie Matrix List verwenden, um Speicherinhalte und Statistiken mit Claude on Rails anzuzeigen und zu exportieren","pt":"Aprenda a configurar o Matrix List para exibir e exportar conteúdos de memória e estatísticas de desempenho","ru":"Узнайте, как настроить Matrix List для отображения и экспорта содержимого памяти и статистики производительности ИИ Агентов","ar":"تعرف على كيفية إعداد قائمة المصفوفة لعرض وإخراج محتويات الذاكرة و الإحصائيات الأدائية لأدوات الذكاء الاصطناعي"},"definition":{"en":"Matrix List is a feature for displaying and exporting Matrix memory contents and statistics, using commands like matrix_status and matrix_warn.","zh":"Matrix List 是一个用于显示和导出 Matrix 内存内容和统计信息的工具","ja":"Matrix List は Matrix 内存内容と統計情報を表示およびエクスポートするツールです","ko":"Matrix List는 Matrix 메모리 내용 및 통계 정보를 표시하고 내보내는 툴입니다","es":"Matrix List es una herramienta de Claude on Rails que muestra y exporta contenidos de memoria y estadísticas","fr":"Matrix List est un outil de Claude on Rails qui affiche et exporte les contenus de mémoire et les statistiques","de":"Matrix List ist ein Tool von Claude on Rails, das Speicherinhalte und Statistiken anzeigt und exportiert","pt":"O que é Matrix List? É uma ferramenta de código aberto para exibir e exportar conteúdos de memória e estatísticas de desempenho","ru":"Что такое Matrix List? Это открытый инструмент для отображения и экспорта содержимого памяти и статистики производительности ИИ Агентов","ar":"ما هي قائمة المصفوفة؟ هي أداة مفتوحة المصدر لعرض وإخراج محتويات الذاكرة و الإحصائيات الأدائية"},"features":{"en":["Uses matrix_status to retrieve information and present it to the user","Supports filtering by statistics, failures, warnings, and solutions","Provides a detailed solutions list with the ''solutions'' argument","Allows exporting Matrix memory contents and statistics","Utilizes matrix_warn with action ''list'' to show warnings","Displays scope breakdown, recent solutions, and top performers"],"zh":["显示 Matrix 内存内容和统计信息","支持导出 Matrix 内存内容和统计信息","使用 `matrix_status` 命令检索信息","支持显示最近解决方案和顶级执行者","支持显示警告和失败记录"],"ja":["Matrix 内存内容と統計情報の表示","Matrix 内存内容と統計情報のエクスポート","`matrix_status` コマンドを使用して情報を取得","最近の解決策とトップパフォーマーの表示","警告と失敗記録の表示"],"ko":["Matrix 메모리 내용 및 통계 정보 표시","Matrix 메모리 내용 및 통계 정보 내보내기","`matrix_status` 명령을 사용하여 정보 가져오기","최근 해결方案 및 상위 수행자 표시","경고 및 실패 기록 표시"],"es":["Mostrar estadísticas y desglose de alcance","Listar soluciones detalladas","Enfocarse en estadísticas, fallos o advertencias","Exportar contenidos de memoria y estadísticas","Utilizar comandos como `matrix_status` y `matrix_warn`"],"fr":["Afficher les statistiques et la ventilation de la portée","Lister les solutions détaillées","Se concentrer sur les statistiques, les échecs ou les avertissements","Exporter les contenus de mémoire et les statistiques","Utiliser des commandes comme `matrix_status` et `matrix_warn`"],"de":["Anzeigen von Statistiken und Umfangsverteilung","Detaillierte Lösungen auflisten","Fokussieren auf Statistiken, Fehlschläge oder Warnungen","Exportieren von Speicherinhalten und Statistiken","Verwenden von Befehlen wie `matrix_status` und `matrix_warn`"],"pt":["Exibe estatísticas de desempenho do Claude Code","Permite exportar conteúdos de memória e estatísticas","Oferece opções de filtragem por estatísticas, falhas e avisos","Suporta comando `matrix_status` para recuperar informações","Integração com `matrix_warn` para exibir avisos","Opção de lista detalhada de soluções"],"ru":["Отображает статистику производительности кода Claude для ИИ Агентов","Позволяет экспортировать содержимое памяти и статистику","Предлагает опции фильтрации по статистике, сбоям и предупреждениям","Поддерживает команду `matrix_status` для получения информации","Интегрируется с `matrix_warn` для отображения предупреждений","Вариант детального списка решений"],"ar":["يعرض الإحصائيات الأدائية ل كود كلود","يسمح بإخراج محتويات الذاكرة و الإحصائيات","يقدم خيارات تصفية حسب الإحصائيات و الأخطاء و التحذيرات","يدعم الأمر `matrix_status` لاسترجاع المعلومات","يتكامل مع `matrix_warn` لعرض التحذيرات","خيار قائمة مفصلة للحلول"]},"keywords":{"en":["how to use Matrix List","Matrix List setup guide","what is Matrix List","Matrix List alternative","Matrix List vs Claude Code","Matrix List install","matrix_status command","matrix_warn action"],"zh":["Matrix List","Claude on Rails","AI 工具","Matrix 内存内容","统计信息","导出工具","显示工具","AIエージェント"],"ja":["Matrix List","Claude on Rails","AIエージェント","Matrix 内存内容","統計情報","エクスポートツール","表示ツール","AI ツール"],"ko":["Matrix List","Claude on Rails","AI 툴","Matrix 메모리 내용","통계 정보","내보내기 툴","표시 툴","AI 에이전트"],"es":["Matrix List","Claude on Rails","herramientas de desarrollo","estadísticas de memoria","exportar estadísticas","desarrollo de software","Herramientas de AI","Agentes de IA","desarrollo de aplicaciones"],"fr":["Matrix List","Claude on Rails","outils de développement","statistiques de mémoire","exporter des statistiques","développement de logiciels","Outils d''IA","Agents d''IA","développement d''applications"],"de":["Matrix List","Claude on Rails","Entwicklungstools","Speicherstatistiken","Statistiken exportieren","Softwareentwicklung","KI-Tools","KI-Agents","Anwendungsentwicklung"],"pt":["Matrix List","Claude Code","Desenvolvimento de AI","Ferramentas de código aberto","Estatísticas de desempenho","Exportar conteúdos de memória","Comandos CLI","Desenvolvedores de AI"],"ru":["Matrix List","Код Claude","Разработка ИИ Агентов","Открытые инструменты","Статистика производительности","Экспорт содержимого памяти","Команды CLI","Разработчики ИИ Агентов"],"ar":["قائمة المصفوفة","كود كلود","تنمية أدوات الذكاء الاصطناعي","أدوات مفتوحة المصدر","إحصائيات الأداء","إخراج محتويات الذاكرة","أوامر CLI","مطورو أدوات الذكاء الاصطناعي"]}},"owner":"ojowwalker77","repo":"Claude-Matrix","repoPath":"ojowwalker77/Claude-Matrix","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.286Z","topics":[],"category":"community","skillMd":{"name":"Matrix List","description":"This skill should be used when the user asks to list matrix solutions, show matrix stats, display memory contents, view matrix status, show failures, list warnings, export matrix data, backup matrix, export solutions, or needs to see or export Matrix memory.","bodyPreview":"# Matrix List & Export\n\nDisplay or export Matrix memory contents and statistics.\n\n## List (default)\n\nUse `matrix_status` to retrieve information and present it to the user.\n\n- **No arguments**: Show statistics, scope breakdown, recent solutions, top performers\n- **\"stats\"**: Focus on statistics only\n- **\"failures\"**: Focus on recorded failures\n- **\"warnings\"**: Use `matrix_warn` with action \"list\" to show warnings\n- **\"solutions\"**: Show detailed solutions list\n\n## Export\n\nWhen the user says \"ex","body":"# Matrix List & Export\n\nDisplay or export Matrix memory contents and statistics.\n\n## List (default)\n\nUse `matrix_status` to retrieve information and present it to the user.\n\n- **No arguments**: Show statistics, scope breakdown, recent solutions, top performers\n- **\"stats\"**: Focus on statistics only\n- **\"failures\"**: Focus on recorded failures\n- **\"warnings\"**: Use `matrix_warn` with action \"list\" to show warnings\n- **\"solutions\"**: Show detailed solutions list\n\n## Export\n\nWhen the user says \"export\" or \"backup\":\n\n1. Use `matrix_status` to get all data\n2. Format as JSON\n3. Use `Write` to save to the specified path (or default to `matrix-export.json`)\n"},"lastSynced":"2026-03-08T02:00:56.825Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents working with Claude on Rails needing detailed Matrix memory analysis and statistics.","zh":"非常适合与 Claude on Rails 合作的开发者代理，需要对 Matrix 内存进行详细分析和统计。","ja":"Claude on Rails を使用する開発者エージェントに最適で、Matrix メモリの詳細な分析と統計が必要です。","ko":"Claude on Rails와 협력하는 개발자 에이전트에게 적합하며, Matrix 메모리의 자세한 분석과 통계가 필요합니다.","es":"Perfecto para Agentes de Desarrollador que trabajan con Claude on Rails y necesitan un análisis detallado de la memoria de Matrix y estadísticas.","fr":"Parfait pour les agents de développement travaillant avec Claude on Rails et nécessitant une analyse détaillée de la mémoire de Matrix et des statistiques.","de":"Perfekt für Developer-Agents, die mit Claude on Rails arbeiten und eine detaillierte Matrix-Speicheranalyse und Statistiken benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que trabalham com Claude on Rails e necessitam de análise detalhada de memória da Matrix e estatísticas.","ru":"Идеально подходит для агентов-разработчиков, работающих с Claude on Rails, которым необходим подробный анализ памяти Matrix и статистики.","ar":"مثالي لعميل التطوير الذين يعملون مع Claude on Rails و يحتاجون إلى تحليل مفصل للذاكرة Matrix و الإحصائيات."},"recommendation":{"en":"Empowers agents to retrieve and display Matrix memory contents and statistics using `matrix_status`, focusing on solutions lists, failures, warnings, and scope breakdowns with protocols like `matrix_warn` for action-oriented insights.","zh":"赋予代理检索和显示 Matrix 内存内容和统计信息的能力，使用 `matrix_status`，关注解决方案列表、失败、警告和范围细分，使用类似 `matrix_warn` 的协议以获得面向行动的洞察。","ja":"エージェントが Matrix メモリの内容と統計を取得して表示する能力を与え、`matrix_status` を使用し、解決策のリスト、失敗、警告、スコープの細分化に焦点を当て、`matrix_warn` のようなプロトコルを使用してアクション指向の洞察を得る。","ko":"에이전트가 Matrix 메모리의 내용과 통계를 가져와 표시할 수 있는 능력을 부여하며, `matrix_status`를 사용하여, 해결책 목록, 실패, 경고 및 범위 세분화를 중점적으로 다루고, `matrix_warn`와 같은 프로토콜을 사용하여 행동 지향형 통찰력을 얻습니다.","es":"Habilita a los agentes a recuperar y mostrar el contenido de la memoria de Matrix y las estadísticas utilizando `matrix_status`, centrándose en listas de soluciones, fallos, advertencias y desglose de ámbito con protocolos como `matrix_warn` para conocimientos orientados a la acción.","fr":"Permet aux agents de récupérer et d''afficher le contenu de la mémoire de Matrix et les statistiques en utilisant `matrix_status`, en se concentrant sur les listes de solutions, les défaillances, les avertissements et la ventilation de la portée avec des protocoles tels que `matrix_warn` pour des connaissances axées sur l''action.","de":"Ermöglicht es Agenten, den Inhalt des Matrix-Speichers und Statistiken mithilfe von `matrix_status` abzurufen und anzuzeigen, wobei der Schwerpunkt auf Lösungslisten, Fehlern, Warnungen und Aufschlüsselung des Umfangs mit Protokollen wie `matrix_warn` für handlungsorientierte Erkenntnisse liegt.","pt":"Habilita os agentes a recuperar e exibir o conteúdo da memória da Matrix e estatísticas usando `matrix_status`, focando em listas de soluções, falhas, avisos e quebras de escopo com protocolos como `matrix_warn` para insights orientados à ação.","ru":"Наделяет агентов возможностью извлекать и отображать содержимое памяти Matrix и статистику с помощью `matrix_status`, фокусируясь на списках решений, сбоях, предупреждениях и разбивке объема с протоколами, такими как `matrix_warn`, для суждений, ориентированных на действие.","ar":"يمنح الوكلاء القدرة على استرجاع وعرض محتوى ذاكرة Matrix و الإحصائيات باستخدام `matrix_status`، مع التركيز على قوائم الحلول و الفشل و التحذيرات و كسر النطاق مع بروتوكولات مثل `matrix_warn` من أجل رؤى متجهة إلى العمل."},"useCases":{"en":["Displaying recent solutions and top performers","Exporting detailed statistics and scope breakdowns","Debugging recorded failures and warnings"],"zh":["显示最近的解决方案和顶级表现者","导出详细的统计和范围细分","调试记录的失败和警告"],"ja":["最近の解決策とトップパフォーマーを表示する","詳細な統計とスコープの細分化をエクスポートする","記録された失敗と警告をデバッグする"],"ko":["최근의 해결책과 최상위 수행자를 표시하는 것","자세한 통계 및 범위 세분화를 내보내기","기록된 실패 및 경고를 디버깅하는 것"],"es":["Mostrar soluciones recientes y mejores rendimientos","Exportar estadísticas detalladas y desglose de ámbito","Depurar fallos y advertencias grabadas"],"fr":["Afficher les solutions récentes et les meilleures performances","Exporter des statistiques détaillées et une ventilation de la portée","Déboguer les défaillances et les avertissements enregistrés"],"de":["Aktuelle Lösungen und Top-Leistungen anzeigen","Detaillierte Statistiken und Umfangsaufschlüssel exportieren","Aufgezeichnete Fehler und Warnungen debuggen"],"pt":["Exibindo soluções recentes e principais performáticos","Exportando estatísticas detalhadas e quebras de escopo","Depurando falhas e avisos registrados"],"ru":["Отображение недавних решений и лучших исполнителей","Экспорт подробных статистик и разбивки объема","Отладка записанных сбоев и предупреждений"],"ar":["عرض الحلول الحديثة و الأفضل أداء","استيراد الإحصائيات المفصلة و كسر النطاق","تصحيح الفشل و التحذيرات المسجلة"]},"limitations":{"en":["Requires Claude on Rails integration","Limited to Matrix memory contents and statistics"],"zh":["需要 Claude on Rails 集成","仅限 Matrix 内存内容和统计"],"ja":["Claude on Rails の統合が必要","Matrix メモリの内容と統計のみ"],"ko":["Claude on Rails 통합이 필요","Matrix 메모리 내용 및 통계만"],"es":["Requiere integración con Claude on Rails","Limitado al contenido de la memoria de Matrix y estadísticas"],"fr":["Nécessite une intégration avec Claude on Rails","Limité au contenu de la mémoire de Matrix et aux statistiques"],"de":["Benötigt Integration mit Claude on Rails","Begrenzt auf den Inhalt des Matrix-Speichers und Statistiken"],"pt":["Requer integração com Claude on Rails","Limitado ao conteúdo da memória da Matrix e estatísticas"],"ru":["Требует интеграции с Claude on Rails","Ограничен содержимым памяти Matrix и статистикой"],"ar":["يتطلب التكامل مع Claude on Rails","محدود بمحتوى ذاكرة Matrix و الإحصائيات"]},"version":4},"contentHash":"ae0439b66cc72d91471f7f38a4e8df9065fb7bdb363d64532fbe3c9a5da1a635","qualityScore":23}');
