INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ojowwalker77/Claude-Matrix/Matrix List', 'Matrix List', 'ojowwalker77', 'Claude-Matrix', 'community', 'Matrix List ojowwalker77 Claude-Matrix community Matrix List is a tool for displaying and exporting Matrix memory contents and statistics, benefiting developers working with Claude on Rails. It provides detailed information and solutions lists. Matrix List 是 Claude on Rails 的工具系统，用于显示和导出 Matrix 内存内容和统计信息 Matrix List は Claude on Rails のツールシステムで、Matrix 内存内容と統計情報を表示およびエクスポートします Matrix List는 Claude on Rails의 툴 시스템으로 Matrix 메모리 내용 및 통계 정보를 표시하고 내보냅니다 Matrix List es una herramienta de Claude on Rails que permite a los desarrolladores mostrar y exportar contenidos de memoria y estadísticas Matrix List est un outil de Claude on Rails qui permet aux développeurs d''afficher et d''exporter les contenus de mémoire et les statistiques Matrix List ist ein Tool von Claude on Rails, mit dem Entwickler Speicherinhalte und Statistiken anzeigen und exportieren können O Matrix List é uma ferramenta para exibir e exportar conteúdos de memória e estatísticas de desempenho do Claude Code Matrix List - это инструмент для отображения и экспорта содержимого памяти и статистики производительности кода Claude для ИИ Агентов قائمة المصفوفة هي أداة لعرض وإخراج محتويات الذاكرة و الإحصائيات الأدائية ل كود كلود من أجل أدوات الذكاء الاصطناعي how to use Matrix List Matrix List setup guide what is Matrix List Matrix List alternative Matrix List vs Claude Code Matrix List install matrix_status command matrix_warn action Matrix List Claude on Rails AI 工具 Matrix 内存内容 统计信息 导出工具 显示工具 AIエージェント Uses matrix_status to retrieve information and present it to the user Supports filtering by statistics, failures, warnings, and solutions Provides a detailed solutions list with the ''solutions'' argument Allows exporting Matrix memory contents and statistics Utilizes matrix_warn with action ''list'' to show warnings Displays scope breakdown, recent solutions, and top performers Matrix List is a feature for displaying and exporting Matrix memory contents and statistics, using commands like matrix_status and matrix_warn.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sammcj/agentic-coding/code-simplification', 'community', 'sammcj', 'agentic-coding', 'sammcj/agentic-coding', 'code-simplification', 0, 0, 23, '2026-03-08T01:57:15.286Z', '2026-03-08T02:00:59.817Z', 'e7ea6566174e298206fe51ccd8cd3e113aa1c133730c2ff5d2bb139039eb3b0e', '{"id":"sammcj/agentic-coding/code-simplification","name":"code-simplification","description":{"en":"Code-simplification helps developers become expert system architects by identifying and eliminating unnecessary complexity, resulting in maintainable code. It''s ideal for developers seeking to simplify their codebase.","zh":"代码简化是开发中的关键原则，旨在消除不必要的复杂性，实现简洁和高效的代码","ja":"コード簡素化は、開発における重要な原則であり、不要な複雑さを排除し、シンプルで効率的なコードを実現します","ko":"코드 단순화는 개발에서 핵심 원칙으로, 불필요한 복잡성을 제거하고 간결하고 효율적인 코드를 구현하는 것을 목표로 합니다","es":"La simplificación de código es crucial para una arquitectura de sistema y desarrollo de software eficaces. Aprende a identificar y eliminar la complejidad innecesaria.","fr":"La simplification de code est essentielle pour une architecture de système et un développement de logiciels efficaces. Apprenez à identifier et à éliminer la complexité inutile.","de":"Die Vereinfachung von Code ist entscheidend für eine effektive Systemarchitektur und Softwareentwicklung. Erfahren Sie, wie Sie unnötige Komplexität identifizieren und beseitigen.","pt":"Simplifique seu código com regras e templates de codificação agêntica. Reduza a complexidade e melhore a manutenção.","ru":"Упростите свой код с помощью агентских правил и шаблонов кодирования. Уменьшите сложность и улучшите поддержку.","ar":"بسط رموزك البرمجية باستخدام قواعد وصفحات القوالب البرمجية. قلل من التعقيد و تحسين الصيانة."},"seo":{"title":{"en":"Code-Simplification: Simplify Code with Agentic Coding Ru...","zh":"代码简化最佳实践指南","ja":"コード簡素化Setup Guide - AIエージェント","ko":"코드 단순화 가이드 - 효율적인 개발을 위한 팁","es":"Guía de Configuración para Simplificación de Código con H...","fr":"Guide de Mise en Place pour la Simplification de Code ave...","de":"Einrichtungsleitfaden für Code-Vereinfachung mit KI-Agent...","pt":"Guia de Simplificação de Código para Desenvolvedores","ru":"ИИ Агенты: Руководство по Упрощению КодаДля Разработчиков","ar":"دليل مبسط للرمز البرمجي للبرمجيين"},"description":{"en":"Transform convoluted code into elegant solutions with code-simplification. Learn how to identify and eliminate unnecessary complexity - start simplifying today!","zh":"学习代码简化的核心原则，包括简洁优先和消除不必要的复杂性，使用Agentic Coding Rules和模板","ja":"AIエージェントを使用してコードを簡素化する方法を学ぶ - コード簡素化のベストプラクティス","ko":"코드 단순화를 위한 핵심 원칙과 Agentic Coding Rules, 템플릿 등을 사용하여 효율적인 개발을 실현하세요","es":"Aprende a simplificar tu código con las reglas y plantillas de codificación de Agentic. Mejora la mantenibilidad y legibilidad de tu código.","fr":"Découvrez comment simplifier votre code avec les règles et modèles de codage d''Agentic. Améliorez la maintenabilité et la lisibilité de votre code.","de":"Erfahren Sie, wie Sie Ihren Code mit den Codierregeln und -vorlagen von Agentic vereinfachen. Verbessern Sie die Wartbarkeit und Lesbarkeit Ihres Codes.","pt":"Aprenda a simplificar código com regras e templates de codificação agêntica. Reduza a complexidade e melhore a manutenção.","ru":"Узнайте, как упростить код с помощью агентских правил и шаблонов кодирования. Уменьшите сложность и улучшите поддержку.","ar":"تعلم كيفية تبسيط الرموز البرمجية باستخدام قواعد وصفحات القوالب البرمجية. قلل من التعقيد و تحسين الصيانة."},"definition":{"en":"Code-simplification is a set of principles and rules that aim to eliminate unnecessary complexity in code, promoting simplicity and maintainability.","zh":"代码简化是指通过消除不必要的复杂性和代码重构来实现简洁和高效的代码","ja":"コード簡素化とは、不要な複雑さを排除し、コードを再構成することでシンプルで効率的なコードを実現すること","ko":"코드 단순화란 불필요한 복잡성을 제거하고 코드를 재구성하여 간결하고 효율적인 코드를 구현하는 것을 의미합니다","es":"La simplificación de código se refiere al proceso de identificar y eliminar la complejidad innecesaria en el código, para mejorar su mantenibilidad y legibilidad.","fr":"La simplification de code fait référence au processus d''identification et d''élimination de la complexité inutile dans le code, pour améliorer sa maintenabilité et sa lisibilité.","de":"Die Vereinfachung von Code bezeichnet den Prozess der Identifizierung und Beseitigung von unnötiger Komplexität im Code, um seine Wartbarkeit und Lesbarkeit zu verbessern.","pt":"Simplificação de código é a prática de reduzir a complexidade do código.","ru":"Упрощение кода - это практика снижения сложности кода.","ar":"تبسيط الرموز البرمجية هو ممارسة تقليل تعقيد الرموز البرمجية."},"features":{"en":["Applies Simplicity First principle to every line of code","Identifies and eliminates unnecessary complexity in code","Transforms convoluted solutions into elegant, maintainable code","Follows Agentic Coding Rules for optimal code structure","Enforces clear purpose for every line of code"],"zh":["简洁优先的代码设计","Agentic Coding Rules和模板的使用","消除不必要的复杂性","代码重构和优化","提高代码的可维护性和可扩展性"],"ja":["シンプルさを優先したコード設計","AIエージェントのAgentic Coding Rulesとテンプレートの使用","不要な複雑さの排除","コードの再構成と最適化","コードの保守性と拡張性の向上"],"ko":["간결성을 우선하는 코드 설계","Agentic Coding Rules와 템플릿의 사용","불필요한 복잡성의 제거","코드의 재구성과 최적화","코드의 유지 보수성과 확장성의 향상"],"es":["Simplificación de código con reglas y plantillas de Agentic","Identificación y eliminación de complejidad innecesaria","Mejora de la mantenibilidad y legibilidad del código","Aplicación de principios de simplicidad en cada línea de código","Transformación de soluciones complejas en código elegante y mantenible"],"fr":["Simplification de code avec des règles et des modèles d''Agentic","Identification et élimination de la complexité inutile","Amélioration de la maintenabilité et de la lisibilité du code","Application des principes de simplicité dans chaque ligne de code","Transformation de solutions complexes en code élégant et maintenable"],"de":["Vereinfachung von Code mit Regeln und Vorlagen von Agentic","Identifizierung und Beseitigung von unnötiger Komplexität","Verbesserung der Wartbarkeit und Lesbarkeit des Codes","Anwendung von Einfachheitsprinzipien in jeder Codezeile","Transformation von komplexen Lösungen in elegantes und wartbares Code"],"pt":["Simplicidade em primeiro lugar","Identificação e eliminação de complexidade desnecessária","Transformação de soluções convolutas em código elegante e mantenedor","Uso de regras e templates de codificação agêntica","Melhoria da manutenção e legibilidade do código"],"ru":["Простота прежде всего","Идентификация и устранение ненужной сложности","Преобразование запутанных решений в элегантный и поддерживаемый код","Использование агентских правил и шаблонов кодирования","Улучшение поддержки и читаемости кода"],"ar":["البساطة أولا","التعرف على وتقليل التعقيد غير الضروري","تحويل الحلول المعقدة إلى رموز برمجية أنيقة وسهلة الصيانة","استخدام قواعد وصفحات القوالب البرمجية","تحسين الصيانة وقراءة الرموز البرمجية"]},"keywords":{"en":["how to use code-simplification","code-simplification best practices","what is code-simplification","code-simplification alternative","code-simplification vs complexity reduction","code-simplification setup guide","code-simplification install","simplifying code with agentic coding rules","code-simplification for AI agents","code-simplification tutorial"],"zh":["代码简化","Agentic Coding Rules","代码重构","简洁优先","代码优化","开发最佳实践","代码设计","代码可维护性","代码可扩展性"],"ja":["コード簡素化","AIエージェント","Agentic Coding Rules","コード再構成","シンプルさを優先","コード最適化","開発ベストプラクティス","コード設計","コード保守性","コード拡張性"],"ko":["코드 단순화","Agentic Coding Rules","코드 재구성","간결성을 우선","코드 최적화","개발 최선의 관행","코드 설계","코드 유지 보수성","코드 확장성"],"es":["simplificación de código","herramientas de agente de IA","reglas de codificación","plantillas de codificación","desarrollo de software","arquitectura de sistema","mantenibilidad del código","legibilidad del código","principios de simplicidad"],"fr":["simplification de code","outils d''agent IA","règles de codage","modèles de codage","développement de logiciels","architecture de système","maintenabilité du code","lisibilité du code","principes de simplicité"],"de":["Vereinfachung von Code","KI-Agent-Tools","Codierregeln","Codierungsvorlagen","Softwareentwicklung","Systemarchitektur","Wartbarkeit des Codes","Lesbarkeit des Codes","Einfachheitsprinzipien"],"pt":["simplificação de código","regras de codificação agêntica","templates de codificação","desenvolvimento de software","melhoria da manutenção","legibilidade do código","práticas de codificação","otimização de código","desenvolvedores de software"],"ru":["ИИ Агенты","упрощение кода","агентские правила кодирования","шаблоны кодирования","разработка программного обеспечения","улучшение поддержки","читаемость кода","практики кодирования","оптимизация кода","разработчики программного обеспечения"],"ar":["دليل مبسط للرمز البرمجي","قواعد وصفحات القوالب البرمجية","تطوير البرمجيات","تحسين الصيانة","قراءة الرموز البرمجية","مبادئ الترميز","تحسين الرموز البرمجية","مطورو البرمجيات","ادوات الذكاء الاصطناعي"]}},"owner":"sammcj","repo":"agentic-coding","repoPath":"sammcj/agentic-coding","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.286Z","topics":[],"category":"community","skillMd":{"name":"code-simplification","description":"Use this skill when you need to review and refactor code to make it simpler, more maintainable, and easier to understand. Helps with identifying overly complex solutions, unnecessary abstractions.","bodyPreview":"The information outlined here aims to help you become an expert system architect and developer with an unwavering commitment to code simplicity.\n\nWhen focusing on code simplification it is your mission to identify and eliminate unnecessary complexity wherever it exists, transforming convoluted solutions into elegant, maintainable code.\n\nYour core principles:\n- **Simplicity First**: Every line of code should have a clear purpose. If it doesn''t contribute directly to solving the problem, it should","body":"The information outlined here aims to help you become an expert system architect and developer with an unwavering commitment to code simplicity.\n\nWhen focusing on code simplification it is your mission to identify and eliminate unnecessary complexity wherever it exists, transforming convoluted solutions into elegant, maintainable code.\n\nYour core principles:\n- **Simplicity First**: Every line of code should have a clear purpose. If it doesn''t contribute directly to solving the problem, it shouldn''t exist.\n- **Readability Over Cleverness**: Code is read far more often than it''s written. Optimise for human understanding, not for showing off technical prowess.\n- **Minimal Abstractions**: Only introduce abstractions when they genuinely reduce complexity. Premature abstraction is a form of complexity.\n- **Clear Intent**: Code should express what it does, not how it does it. The ''why'' should be obvious from reading the code.\n\nWhen reviewing code, you will:\n\n1. **Identify Complexity Hotspots**:\n   - Deeply nested conditionals or loops\n   - Functions doing too many things\n   - Unnecessary design patterns or abstractions\n   - Overly generic solutions for specific problems\n   - Complex boolean logic that could be simplified\n   - Redundant code or repeated patterns\n\n2. **Propose Simplifications**:\n   - Break down complex functions into smaller, focused ones\n   - Replace nested conditionals with early returns or guard clauses\n   - Eliminate intermediate variables that don''t add clarity\n   - Simplify data structures when possible\n   - Remove unused parameters, methods, or classes\n   - Convert complex boolean expressions to well-named functions\n\n3. **Maintain Functionality**:\n   - Ensure all simplifications preserve the original behaviour\n   - Consider edge cases and error handling\n   - Maintain or improve performance characteristics\n   - Keep necessary complexity that serves a real purpose\n\n4. **Provide Clear Refactoring Steps**:\n   - Explain why each change improves simplicity\n   - Show before/after comparisons\n   - Prioritise changes by impact\n   - Suggest incremental refactoring when dealing with large changes\n\n5. **Consider Context**:\n   - Respect project-specific patterns from CLAUDE.md files\n   - Align with established coding standards\n   - Consider the skill level of the team maintaining the code\n   - Balance simplicity with other requirements like performance or security\n\n6. **Consider requirements**:\n   - Don''t remove essential requirements for the proposed or implemented solution.\n   - Ensure that no functionality is lost. If you want to remove functionality, ask for feedback whether that is required.\n\nYour communication style:\n- Be direct and specific about complexity issues\n- Provide concrete examples of simplified code\n- Explain the benefits of each simplification\n- Acknowledge when complexity is necessary and justified\n- Focus on actionable improvements, not criticism\n\nRemember: The best code is not the code that does the most, but the code that does exactly what''s needed with the least cognitive overhead. Every simplification you suggest should make the codebase more approachable for the next developer who reads it.\n"},"lastSynced":"2026-03-08T02:00:59.817Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents seeking to refine their ability to identify and eliminate unnecessary complexity in codebases.","zh":"适用于代码审查代理，旨在提高识别和消除代码库中不必要复杂性的能力。","ja":"コードレビューエージェントがコードベースの中での不要な複雑さを特定して除去する能力を高めるのに適しています。","ko":"코드 리뷰 에이전트가 코드베이스에서 불필요한 복잡성을 식별하고 제거하는 능력을 향상시키는 데 적합합니다.","es":"Ideal para agentes de revisión de código que buscan perfeccionar su capacidad para identificar y eliminar la complejidad innecesaria en los conjuntos de código.","fr":"Idéal pour les agents de revue de code cherchant à affiner leur capacité à identifier et à éliminer la complexité inutile dans les bases de code.","de":"Ideal für Code-Review-Agenten, die ihre Fähigkeit verbessern möchten, unnötige Komplexität in Codebasen zu erkennen und zu eliminieren.","pt":"Ideal para Agentes de Revisão de Código que buscam aprimorar sua capacidade de identificar e eliminar complexidade desnecessária em codebases.","ru":"Идеально для Агентов Код-Ревью, стремящихся усовершенствовать свою способность выявлять и устранять ненужную сложность в кодовых базах.","ar":"مثالي للوكلاء المراجعة الكود الذين يسعون لتحسين قدرتهم على تحديد وإزالة التعقيد غير الضروري في قواعد الكود."},"recommendation":{"en":"Empowers agents to transform convoluted solutions into elegant, maintainable code by applying the Simplicity First principle, ensuring every line of code has a clear purpose and contributes directly to solving the problem, utilizing core principles to simplify code structures and improve overall system architecture.","zh":"赋予代理将复杂的解决方案转化为优雅、可维护的代码的能力，通过应用简洁第一原则，确保每行代码都有明确的目的并直接为解决问题做出贡献，利用核心原则简化代码结构并提高整体系统架构。","ja":"エージェントに、シンプルさ第一の原則を適用して、複雑なソリューションを優雅で維持可能なコードに変換する能力を付与し、すべてのコード行に明確な目的があって問題の解決に直接貢献するようにし、コア原則を使用してコード構造を簡素化し、全体的なシステムアーキテクチャを改善する。","ko":"에이전트가 복잡한 솔루션을 우아하고 유지보수 가능한 코드로 변환 할 수있는 기능을 부여하여, 모든 코드 라인이 명확한 목적을 가지며 문제 해결에 직접 기여하도록 단순성 우선 원칙을 적용하고, 핵심 원칙을 사용하여 코드 구조를 단순화하고 전체 시스템 아키텍처를 개선합니다.","es":"Permite a los agentes transformar soluciones enrevesadas en código elegante y mantenible aplicando el principio de Simplicidad First, asegurando que cada línea de código tenga un propósito claro y contribuya directamente a resolver el problema, utilizando principios básicos para simplificar las estructuras de código y mejorar la arquitectura del sistema en general.","fr":"Permet aux agents de transformer des solutions compliquées en code élégant et maintenable en appliquant le principe de Simplicité First, en s''assurant que chaque ligne de code a un but clair et contribue directement à résoudre le problème, en utilisant des principes de base pour simplifier les structures de code et améliorer l''architecture globale du système.","de":"Ermöglicht es Agenten, verwickelte Lösungen in elegantes, wartbare Code umzuwandeln, indem sie das Prinzip Simplicity First anwenden, um sicherzustellen, dass jede Codezeile einen klaren Zweck hat und direkt zum Lösen des Problems beiträgt, unter Verwendung von Grundprinzipien, um Codestrukturen zu vereinfachen und die Gesamtsystemarchitektur zu verbessern.","pt":"Habilita os agentes a transformar soluções complexas em código elegante e maintainável aplicando o princípio Simplicity First, garantindo que cada linha de código tenha um propósito claro e contribua diretamente para resolver o problema, utilizando princípios básicos para simplificar estruturas de código e melhorar a arquitetura geral do sistema.","ru":"Наделяет агентов возможностью преобразовывать запутанные решения в элегантный, поддерживаемый код, применяя принцип Simplicity First, гарантируя, что каждая строка кода имеет четкую цель и trực tiếp вносит вклад в решение проблемы, используя основные принципы для упрощения структур кода и улучшения общей системы архитектуры.","ar":"تمكّن الوكلاء من تحويل الحلول المعقدة إلى كود أنيق وقابل للصيانة بتطبيق مبدأ البساطة أولا، مما يضمن أن يكون لكل سطر من الكود غرض واضح ويسهم بشكل مباشر في حل المشكلة، مستخدما المبادئ الأساسية لتبسيط هياكل الكود وتحسين هيكل النظام بشكل عام."},"useCases":{"en":["Simplifying legacy codebases to improve maintainability","Refactoring complex algorithms for better performance","Eliminating redundant code to reduce technical debt"],"zh":["简化遗留代码库以提高可维护性","重构复杂算法以提高性能","消除冗余代码以减少技术债务"],"ja":["メンテナンス性を向上させるためにレガシーコードベースを簡素化する","パフォーマンスの向上のために複雑なアルゴリズムをリファクタリングする","技術的負債を削減するために冗長なコードを排除する"],"ko":["유지 보수성을 개선하기 위해 레거시 코드베이스를 단순화하는 것","성능을 개선하기 위해 복잡한 알고리즘을 리팩토링하는 것","기술 부채를 줄이기 위해冗余 코드를 제거하는 것"],"es":["Simplificar bases de código heredadas para mejorar la mantenibilidad","Reestructurar algoritmos complejos para una mejor rendimiento","Eliminar código redundante para reducir la deuda técnica"],"fr":["Simplifier les bases de code héritées pour améliorer la maintenabilité","Réorganiser les algorithmes complexes pour de meilleures performances","Éliminer le code redondant pour réduire la dette technique"],"de":["Vereinfachen von Legacy-Codebasen, um die Wartbarkeit zu verbessern","Umstrukturieren komplexer Algorithmen für bessere Leistung","Entfernen redundanter Code, um die technische Schulden zu reduzieren"],"pt":["Simplificar codebases legadas para melhorar a maintainabilidade","Reestruturar algoritmos complexos para melhor desempenho","Eliminar código redundante para reduzir a dívida técnica"],"ru":["Упрощение устаревших кодовых баз для улучшения поддерживаемости","Переструктуризация сложных алгоритмов для лучшей производительности","Удаление избыточного кода для снижения технического долга"],"ar":["تبسيط قواعد الكود القديمة لتحسين القدرة على الصيانة","إعادة هيكلة الخوارزميات المعقدة لتحسين الأداء","إزالة الكود المتكرر لتقليل الديون الفنية"]},"limitations":{"en":["Requires in-depth understanding of programming principles","May not be effective for highly optimized or obfuscated code"],"zh":["需要对编程原则有深入的理解","可能对高度优化或混淆的代码无效"],"ja":["プログラミング原則に対する深い理解が必要","高度に最適化またはオブスキュレーションされたコードに対しては効果がない可能性がある"],"ko":["프로그래밍 원칙에 대한 깊은 이해가 필요","높은 수준으로 최적화 또는 난독화 된 코드에 대해서는 효과가 없을 수 있다"],"es":["Requiere una comprensión profunda de los principios de programación","Puede que no sea efectivo para código altamente optimizado u ofuscado"],"fr":["Nécessite une compréhension approfondie des principes de programmation","Peut ne pas être efficace pour le code hautement optimisé ou obscurci"],"de":["Benötigt ein tiefes Verständnis der Programmierprinzipien","Kann für hoch optimierten oder verschleierten Code möglicherweise nicht effektiv sein"],"pt":["Exige compreensão aprofundada dos princípios de programação","Pode não ser eficaz para código altamente otimizado ou ofuscado"],"ru":["Требует глубокого понимания принципов программирования","Может быть неэффективным для высоко оптимизированного или запутанного кода"],"ar":["يتطلب فهمًا عميقًا لمبادئ البرمجة","يمكن أن لا يكون فعالًا للكود المتقن أو المخفي"]},"version":4},"contentHash":"e7ea6566174e298206fe51ccd8cd3e113aa1c133730c2ff5d2bb139039eb3b0e","qualityScore":23}');
