INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sammcj/agentic-coding/code-simplification', 'code-simplification', 'sammcj', 'agentic-coding', 'community', 'code-simplification sammcj agentic-coding community Code-simplification helps developers become expert system architects by identifying and eliminating unnecessary complexity, resulting in maintainable code. It''s ideal for developers seeking to simplify their codebase. 代码简化是开发中的关键原则，旨在消除不必要的复杂性，实现简洁和高效的代码 コード簡素化は、開発における重要な原則であり、不要な複雑さを排除し、シンプルで効率的なコードを実現します 코드 단순화는 개발에서 핵심 원칙으로, 불필요한 복잡성을 제거하고 간결하고 효율적인 코드를 구현하는 것을 목표로 합니다 La simplificación de código es crucial para una arquitectura de sistema y desarrollo de software eficaces. Aprende a identificar y eliminar la complejidad innecesaria. La simplification de code est essentielle pour une architecture de système et un développement de logiciels efficaces. Apprenez à identifier et à éliminer la complexité inutile. Die Vereinfachung von Code ist entscheidend für eine effektive Systemarchitektur und Softwareentwicklung. Erfahren Sie, wie Sie unnötige Komplexität identifizieren und beseitigen. Simplifique seu código com regras e templates de codificação agêntica. Reduza a complexidade e melhore a manutenção. Упростите свой код с помощью агентских правил и шаблонов кодирования. Уменьшите сложность и улучшите поддержку. بسط رموزك البرمجية باستخدام قواعد وصفحات القوالب البرمجية. قلل من التعقيد و تحسين الصيانة. how to use code-simplification code-simplification best practices what is code-simplification code-simplification alternative code-simplification vs complexity reduction code-simplification setup guide code-simplification install simplifying code with agentic coding rules code-simplification for AI agents code-simplification tutorial 代码简化 Agentic Coding Rules 代码重构 简洁优先 代码优化 开发最佳实践 代码设计 代码可维护性 代码可扩展性 Applies Simplicity First principle to every line of code Identifies and eliminates unnecessary complexity in code Transforms convoluted solutions into elegant, maintainable code Follows Agentic Coding Rules for optimal code structure Enforces clear purpose for every line of code Code-simplification is a set of principles and rules that aim to eliminate unnecessary complexity in code, promoting simplicity and maintainability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kokiebisu/sumitsugi/build-fix', 'community', 'kokiebisu', 'sumitsugi', 'kokiebisu/sumitsugi', 'build-fix', 0, 0, 23, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:30.020Z', '44b7881c5b85291e153dc4f1dc2b106ae040553f97329366648f9996943dcda5', '{"id":"kokiebisu/sumitsugi/build-fix","name":"build-fix","description":{"en":"The build-fix skill automates the process of fixing TypeScript and build errors, benefiting developers by streamlining their workflow. It runs builds, parses error output, and applies fixes incrementally.","zh":"Build-Fix 是一个用于增量修复 TypeScript 和构建错误的 AI 工具，通过 bun run build 和错误解析来提高开发效率","ja":"Build-Fix は、TypeScript とビルド エラーをインクリメンタルに修復する AI ツールで、bun run build とエラー解析で開発効率を向上","ko":"Build-Fix는 증분으로 TypeScript 및 빌드 오류를 수정하는 AI 도구로, bun run build 및 오류 분석을 통해 개발 효율성을 향상","es":"build-fix es una herramienta que corrige errores de TypeScript de manera incremental, mejorando la eficiencia del desarrollo","fr":"build-fix est un outil qui corrige les erreurs TypeScript de manière incrémentale, améliorant l''efficacité du développement","de":"build-fix ist ein Tool, das TypeScript-Fehler inkrementell korrigiert und die EntwicklungsEffizienz verbessert","pt":"O build-fix é uma ferramenta que corrige erros de compilação em projetos TypeScript de forma incremental. Ele executa o comando bun run build e analisa a saída de erro.","ru":"ИИ Агент build-fix - это инструмент, который исправляет ошибки сборки в проектах TypeScript поэтапно. Он выполняет команду bun run build и анализирует вывод ошибок.","ar":"build-fix هو أداة لتصحيح أخطاء الترجمة في مشاريع TypeScript بشكل متزايد. يقوم بتنفيذ الأمر bun run build ويتحليل مخرجات الخطأ."},"seo":{"title":{"en":"build-fix: Automated TypeScript Error Fixing Setup Guide ...","zh":"Build-Fix Setup Guide: Incremental TypeScript Error Resol...","ja":"Build-Fix セットアップガイド: Typ