INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kokiebisu/sumitsugi/build-fix', 'build-fix', 'kokiebisu', 'sumitsugi', 'community', 'build-fix kokiebisu sumitsugi community The build-fix skill automates the process of fixing TypeScript and build errors, benefiting developers by streamlining their workflow. It runs builds, parses error output, and applies fixes incrementally. Build-Fix 是一个用于增量修复 TypeScript 和构建错误的 AI 工具，通过 bun run build 和错误解析来提高开发效率 Build-Fix は、TypeScript とビルド エラーをインクリメンタルに修復する AI ツールで、bun run build とエラー解析で開発効率を向上 Build-Fix는 증분으로 TypeScript 및 빌드 오류를 수정하는 AI 도구로, bun run build 및 오류 분석을 통해 개발 효율성을 향상 build-fix es una herramienta que corrige errores de TypeScript de manera incremental, mejorando la eficiencia del desarrollo build-fix est un outil qui corrige les erreurs TypeScript de manière incrémentale, améliorant l''efficacité du développement build-fix ist ein Tool, das TypeScript-Fehler inkrementell korrigiert und die EntwicklungsEffizienz verbessert O build-fix é uma ferramenta que corrige erros de compilação em projetos TypeScript de forma incremental. Ele executa o comando bun run build e analisa a saída de erro. ИИ Агент build-fix - это инструмент, который исправляет ошибки сборки в проектах TypeScript поэтапно. Он выполняет команду bun run build и анализирует вывод ошибок. build-fix هو أداة لتصحيح أخطاء الترجمة في مشاريع TypeScript بشكل متزايد. يقوم بتنفيذ الأمر bun run build ويتحليل مخرجات الخطأ. how to use build-fix build-fix alternative build-fix setup guide automated TypeScript error fixing build-fix vs manual error fixing install build-fix what is build-fix build-fix for AI agents TypeScript error resolution Build-Fix TypeScript 错误修复 构建错误解决 AI 工具 bun run build 增量修复 错误解析 Runs build using bun run build command Parses error output and groups errors by file Explains issues and proposes fixes for each error Applies fixes and re-runs builds to verify resolution Stops fixing if new errors are introduced or same error persists after 3 attempts build-fix is a skill that incrementally fixes TypeScript and build errors by running builds, parsing error output, and applying fixes automatically.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yuki-programmer/savesmart_app/ui-ux-psychology', 'community', 'yuki-programmer', 'savesmart_app', 'yuki-programmer/savesmart_app', 'ui-ux-psychology', 0, 0, 23, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:41.799Z', '5cc6b3005f5290dd4ccd7de9ddc41921fedd9baed2bce44040ef1442c5e36539', '{"id":"yuki-programmer/savesmart_app/ui-ux-psychology","name":"ui-ux-psychology","description":{"en":"The ui-ux-psychology skill provides a reference for psychology-driven UI/UX design principles and techniques, benefiting developers and designers who want to create user-centered and engaging interfaces.","zh":"UI/UX心理学是一门研究如何应用心理学原理来改善用户体验的学科，涉及认知偏见、行为触发和知觉法则等方面","ja":"UI/UX心理学は、ユーザーエクスペリエンスを向上させるために心理学的原理を適用する方法を研究する学科です","ko":"UI/UX 심리학은 사용자 경험을 향상시키기 위해 심리학적 원리를 적용하는 방법을 연구하는 학문입니다","es":"La psicología de UI/UX se aplica en el diseño para mejorar la experiencia del usuario mediante principios como los sesgos cognitivos y los desencadenantes de comportamiento","fr":"La psychologie UI/UX est appliquée dans la conception pour améliorer l''expérience utilisateur via des principes tels que les biais cognitifs et les déclencheurs de comportement","de":"Die UI/UX-Psychologie wird im Design angewendet, um die Benutzererfahrung durch Prinzipien wie kognitive Verzerrungen und Verhaltensauslöser zu verbessern","pt":"A psicologia UI/UX é uma habilidade que ajuda a melhorar a experiência do usuário em ferramentas de IA, utilizando princípios como viés cognitivo e gatilhos comportamentais","ru":"Психология UI/UX - это навык, который помогает улучшить пользовательский опыт в ИИ Агентах, используя принципы, такие как когнитивные предубеждения и поведенческие триггеры","ar":"علم النفس UI/UX هو مهارة تساعد على تحسين تجربة المستخدم في أدوات الذكاء الاصطناعي، باستخدام مبادئ مثل الانحياز المعرفي والاستفزازات السلوكية"},"seo":{"title":{"en":"ui-ux-psychology: Psychology-Driven UI/UX Design Setup Gu...","zh":"UI/UX心理学设置指南","ja":"UI/UX心理学ベストプラクティス","ko":"UI/UX 심리학 구현 가이드","es":"Guía de configuración de psicología de UI/UX para agentes...","fr":"Guide de configuration de la psychologie UI/UX pour les o...","de":"Einrichtungsleitfaden für UI/UX-Psychologie in künstliche...","pt":"Guia de Configuração de Psicologia UI/UX para Ferramentas...","ru":"Настройка ИИ Агентов с помощью психологии UI/UX","ar":"دليل إعداد علم النفس UI/UX لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the power of psychology in UI/UX design. Learn how to apply cognitive biases, behavioral triggers, and perception laws to create engaging user experie...","zh":"了解UI/UX心理学的技术细节，包括认知偏见、行为触发和知觉法则，提高用户体验","ja":"UI/UX心理学の技術的な詳細を学び、ユーザーエクスペリエンスを向上させる","ko":"UI/UX 심리학의 기술적 세부 사항을 이해하고 사용자 경험을 향상시키는 방법","es":"Aprenda a aplicar principios psicológicos en el diseño de UI/UX para mejorar la experiencia del usuario con nuestra guía de configuración","fr":"Découvrez comment appliquer des principes psychologiques dans la conception UI/UX pour améliorer l''expérience utilisateur avec notre guide de configuration","de":"Erfahren Sie, wie Sie psychologische Prinzipien im UI/UX-Design anwenden können, um die Benutzererfahrung zu verbessern, mit unserem Einrichtungsleitfaden","pt":"Aprenda a aplicar princípios de psicologia UI/UX em ferramentas de IA para melhorar a experiência do usuário","ru":"Изучите, как использовать психологию UI/UX в ИИ Агентах для улучшения пользовательского опыта","ar":"تعرف على كيفية تطبيق مبادئ علم النفس UI/UX في أدوات الذكاء الاصطناعي لتحسين تجربة المستخدم"},"definition":{"en":"ui-ux-psychology is a set of principles and techniques that apply psychological insights to UI/UX design, including cognitive biases, behavioral triggers, and perception laws.","zh":"UI/UX心理学是指应用心理学原理来设计和优化用户界面","ja":"UI/UX心理学は、心理学的原理を適用してユーザーインターフェースを設計・最適化すること","ko":"UI/UX 심리학은 심리학적 원리를 적용하여 사용자 인터페이스를 설계하고 최적화하는 것을 말합니다","es":"La psicología de UI/UX es el estudio de cómo aplicar principios psicológicos en el diseño de interfaces de usuario para mejorar la experiencia del usuario","fr":"La psychologie UI/UX est l''étude de l''application de principes psychologiques dans la conception d''interfaces utilisateur pour améliorer l''expérience utilisateur","de":"Die UI/UX-Psychologie ist das Studium der Anwendung psychologischer Prinzipien im Design von Benutzeroberflächen, um die Benutzererfahrung zu verbessern","pt":"Psicologia UI/UX é o estudo de como os princípios psicológicos influenciam a interação do usuário com interfaces","ru":"Психология UI/UX - это изучение того, как психологические принципы влияют на взаимодействие пользователя с интерфейсами","ar":"علم النفس UI/UX هو دراسة كيفية تأثير المبادئ النفسية على взаимодействة المستخدم مع الواجهات"},"features":{"en":["References cognitive biases from cognitive-biases.md for informed design decisions","Applies behavioral triggers from behavioral-triggers.md to drive user engagement","Utilizes perception laws from perception-laws.md for effective UI layout and design","Incorporates emotional and social factors from emotional-social.md to build trust and user loyalty","Avoids dark patterns from dark-patterns.md to ensure ethical and user-friendly design"],"zh":["认知偏见分析","行为触发器设计","知觉法则应用","情感和社会性因素考虑","暗模式识别和避免"],"ja":["認知バイアス分析","行動トリガー設計","知覚法則適用","感情と社会性要因の考慮","ダークパターン識別と回避"],"ko":["인지 편향 분석","행동 트리거 설계","지각 법칙 적용","감정과 사회성 요인 고려","다크 패턴 식별과 회피"],"es":["Aplicación de sesgos cognitivos para influir en la toma de decisiones","Uso de desencadenantes de comportamiento para mejorar la participación del usuario","Diseño de interfaces de usuario basado en leyes de percepción","Incorporación de elementos emocionales y sociales para generar confianza","Evitación de patrones oscuros en el diseño"],"fr":["Application des biais cognitifs pour influencer la prise de décision","Utilisation de déclencheurs de comportement pour améliorer la participation de l''utilisateur","Conception d''interfaces utilisateur basée sur les lois de perception","Intégration d''éléments émotionnels et sociaux pour générer la confiance","Évitement de modèles sombres dans la conception"],"de":["Anwendung kognitiver Verzerrungen, um die Entscheidungsfindung zu beeinflussen","Verwendung von Verhaltensauslösern, um die Benutzerbeteiligung zu verbessern","Design von Benutzeroberflächen basierend auf Wahrnehmungsgesetzen","Einbindung emotionaler und sozialer Elemente, um Vertrauen zu erzeugen","Vermeidung dunkler Muster im Design"],"pt":["Aplicação de viés cognitivo para influenciar a tomada de decisões","Uso de gatilhos comportamentais para melhorar a engajamento","Implementação de leis de percepção para otimizar a UI","Integração de elementos emocionais e sociais para aumentar a confiança","Evitar padrões sombrios para garantir a experiência do usuário"],"ru":["Применение когнитивных предубеждений для влияния на принятие решений","Использование поведенческих триггеров для улучшения вовлеченности","Реализация законов восприятия для оптимизации интерфейса","Интеграция эмоциональных и социальных элементов для увеличения доверия","Избежание темных паттернов для обеспечения пользовательского опыта"],"ar":["تطبيق الانحياز المعرفي لتأثير اتخاذ القرارات","استخدام الاستفزازات السلوكية لتحسين المشاركة","تنفيذ قوانين الإدراك لتحسين الواجهة","دمج العناصر العاطفية والاجتماعية لزيادة الثقة","تجنب الأنماط المظلمة لضمان تجربة المستخدم"]},"keywords":{"en":["how to use ui-ux-psychology in design","ui-ux-psychology vs human-centered design","ui-ux-psychology setup guide for developers","what is ui-ux-psychology and its benefits","ui-ux-psychology alternative design approaches","ui-ux-psychology install and integration tutorial"],"zh":["UI/UX心理学","AIエージェント","用户体验设计","认知偏见","行为触发","知觉法则","情感和社会性因素","暗模式"],"ja":["UI/UX心理学","AIエージェント","ユーザーエクスペリエンス設計","認知バイアス","行動トリガー","知覚法則","感情と社会性要因","ダークパターン"],"ko":["UI/UX 심리학","AI 에이전트","사용자 경험 설계","인지 편향","행동 트리거","지각 법칙","감정과 사회성 요인","다크 패턴"],"es":["psicología de UI/UX","diseño de interfaces de usuario","sesgos cognitivos","desencadenantes de comportamiento","leyes de percepción","patrones oscuros","agentes de inteligencia artificial","herramientas de inteligencia artificial"],"fr":["psychologie UI/UX","conception d''interfaces utilisateur","biais cognitifs","déclencheurs de comportement","lois de perception","modèles sombres","outils d''intelligence artificielle","agents d''intelligence artificielle"],"de":["UI/UX-Psychologie","Benutzeroberflächendesign","kognitive Verzerrungen","Verhaltensauslöser","Wahrnehmungsgesetze","dunkle Muster","künstliche Intelligenz-Tools","künstliche Intelligenz-Agenten"],"pt":["psicologia ui/ux","ferramentas de ia","experiência do usuário","viés cognitivo","gatilhos comportamentais","leis de percepção","elementos emocionais","padrões sombrios"],"ru":["психология ui/ux","ии агенты","пользовательский опыт","когнитивные предубеждения","поведенческие триггеры","законы восприятия","эмоциональные элементы","темные паттерны"],"ar":["علم النفس ui/ux","أدوات الذكاء الاصطناعي","تجربة المستخدم","الانحياز المعرفي","الاستفزازات السلوكية","قوانين الإدراك","العناصر العاطفية","الانماط المظلمة"]}},"owner":"yuki-programmer","repo":"savesmart_app","repoPath":"yuki-programmer/savesmart_app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"ui-ux-psychology","description":"UI/UXデザインにおける心理学的手法・原則の知識ベース。アプリやWebサービスのUI設計、ユーザー行動誘導、コンバージョン最適化、UXライティングなどのタスクで活用。「ユーザーに○○させたい」「離脱を防ぎたい」「課金率を上げたい」「UIの改善案」などの相談時にトリガー。","bodyPreview":"# UI/UX Psychology Skill\n\nUI/UXデザインに活用できる心理学的手法・原則のリファレンス。\n\n## 使い方\n\n1. ユーザーの目的（行動誘導、離脱防止、エンゲージメント向上など）を確認\n2. 該当するカテゴリの原則を参照\n3. 具体的な実装案を提案\n\n## リファレンス\n\n目的に応じて以下を参照：\n\n- [cognitive-biases.md](references/cognitive-biases.md) - 認知バイアス（意思決定への影響）\n- [behavioral-triggers.md](references/behavioral-triggers.md) - 行動誘導・ナッジ\n- [perception-laws.md](references/perception-laws.md) - 知覚・認知法則（UI配置）\n- [emotional-social.md](references/emotional-social.md) - 感情・社会性・信頼\n- [dark-patterns.md](references/dark-patterns.md)","body":"# UI/UX Psychology Skill\n\nUI/UXデザインに活用できる心理学的手法・原則のリファレンス。\n\n## 使い方\n\n1. ユーザーの目的（行動誘導、離脱防止、エンゲージメント向上など）を確認\n2. 該当するカテゴリの原則を参照\n3. 具体的な実装案を提案\n\n## リファレンス\n\n目的に応じて以下を参照：\n\n- [cognitive-biases.md](references/cognitive-biases.md) - 認知バイアス（意思決定への影響）\n- [behavioral-triggers.md](references/behavioral-triggers.md) - 行動誘導・ナッジ\n- [perception-laws.md](references/perception-laws.md) - 知覚・認知法則（UI配置）\n- [emotional-social.md](references/emotional-social.md) - 感情・社会性・信頼\n- [dark-patterns.md](references/dark-patterns.md) - ダークパターン（NG例）\n- [practical-examples.md](references/practical-examples.md) - アプリ種別ごとの実践例\n"},"lastSynced":"2026-03-08T02:01:41.799Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX Design Agents needing psychology-driven design principles and techniques.","zh":"适合需要运用心理学驱动设计原则和技术的 UI/UX 设计代理","ja":"UI/UX デザインエージェントが心理学に基づく設計原則とテクニックを必要とする場合に最適","ko":"사용자 경험 설계 에이전트가 심리학적 설계 원칙과 기술을 필요로 하는 경우 적합","es":"Perfecto para agentes de diseño de UI/UX que necesitan principios y técnicas de diseño impulsados por la psicología.","fr":"Parfait pour les agents de conception UI/UX qui ont besoin de principes et de techniques de conception basés sur la psychologie.","de":"Perfekt für UI/UX-Design-Agenten, die psychologisch gesteuerte Designprinzipien und -techniken benötigen.","pt":"Perfeito para Agentes de Design de UI/UX que precisam de princípios e técnicas de design baseados em psicologia.","ru":"Идеально подходит для агентов дизайна UI/UX, которым необходимы принципы и методы дизайна, основанные на психологии.","ar":"مثالي لوكلاء تصميم UI/UX الذين يحتاجون إلى مبادئ وطرق تصميم مدفوعة bằng علم النفس."},"recommendation":{"en":"Empowers agents to create user-centered and engaging interfaces by applying cognitive biases, behavioral triggers, and perception laws, utilizing references like cognitive-biases.md and behavioral-triggers.md to inform design decisions.","zh":"赋予代理创建以用户为中心和吸引人的接口的能力，通过应用认知偏见、行为触发器和感知法则，利用类似 cognitive-biases.md 和 behavioral-triggers.md 的参考资料来指导设计决策","ja":"エージェントが認知バイアス、行動トリガー、認識法則を適用してユーザー中心で魅力的インターフェイスを作成できるようにし、cognitive-biases.md や behavioral-triggers.md などの参考資料を使用して設計上の決定を下す","ko":"에이전트가 인지 편향, 행동 트리거, 인식 법칙을 적용하여 사용자 중심의 인터페이스를 생성할 수 있도록 하며, cognitive-biases.md 및 behavioral-triggers.md와 같은 참조 자료를 사용하여 디자인 결정을 내림","es":"Habilita a los agentes a crear interfaces centradas en el usuario y atractivas aplicando sesgos cognitivos, desencadenantes del comportamiento y leyes de la percepción, utilizando referencias como cognitive-biases.md y behavioral-triggers.md para informar las decisiones de diseño.","fr":"Permet aux agents de créer des interfaces centrées sur l''utilisateur et engageantes en appliquant des biais cognitifs, des déclencheurs de comportement et des lois de perception, en utilisant des références telles que cognitive-biases.md et behavioral-triggers.md pour éclairer les décisions de conception.","de":"Ermöglicht es Agenten, benutzerzentrierte und ansprechende Schnittstellen zu erstellen, indem sie kognitive Verzerrungen, Verhaltensauslöser und Wahrnehmungsgesetze anwenden, unter Verwendung von Referenzen wie cognitive-biases.md und behavioral-triggers.md, um Designentscheidungen zu treffen.","pt":"Habilita os agentes a criar interfaces centradas no usuário e envolventes, aplicando vieses cognitivos, gatilhos comportamentais e leis de percepção, utilizando referências como cognitive-biases.md e behavioral-triggers.md para informar decisões de design.","ru":"Наделяет агентов возможностью создавать пользовательские и увлекательные интерфейсы, применяя когнитивные предубеждения, поведенческие триггеры и законы восприятия, используя ссылки, такие как cognitive-biases.md и behavioral-triggers.md, для принятия решений по дизайну.","ar":"تمكن الوكلاء من إنشاء واجهات مستخدم مركزة ومثيرة للاهتمام من خلال تطبيق التحيزات المعرفية والملفات البدنية لقوانين الإدراك، استخدام المراجع مثل cognitive-biases.md وbehavioral-triggers.md لإبلاغ قرارات التصميم."},"useCases":{"en":["Applying cognitive biases to improve user decision-making","Designing interfaces with behavioral triggers for increased engagement","Optimizing UI layouts using perception laws for better user experience"],"zh":["应用认知偏见来改善用户决策","使用行为触发器设计接口以提高参与度","使用感知法则优化 UI 布局以获得更好的用户体验"],"ja":["認知バイアスを適用してユーザーの意思決定を改善する","行動トリガーを使用してインターフェイスを設計し、関与度を高める","認識法則を使用して UI レイアウトを最適化し、より良いユーザーエクスペリエンスを実現する"],"ko":["인지 편향을 적용하여 사용자의 의사 결정을 개선하는 것","행동 트리거를 사용하여 인터페이스를 설계하고 참여도를 높이는 것","인식 법칙을 사용하여 UI 레이아웃을 최적화하여 더 나은 사용자 경험을 구현하는 것"],"es":["Aplicar sesgos cognitivos para mejorar la toma de decisiones del usuario","Diseñar interfaces con desencadenantes del comportamiento para aumentar la participación","Optimizar diseños de UI utilizando leyes de la percepción para una mejor experiencia del usuario"],"fr":["Appliquer des biais cognitifs pour améliorer la prise de décision de l''utilisateur","Concevoir des interfaces avec des déclencheurs de comportement pour augmenter l''engagement","Optimiser les conceptions d''interface utilisateur en utilisant des lois de perception pour une meilleure expérience utilisateur"],"de":["Kognitive Verzerrungen anwenden, um die Entscheidungsfindung des Benutzers zu verbessern","Schnittstellen mit Verhaltensauslösern entwerfen, um die Beteiligung zu erhöhen","UI-Layouts mit Wahrnehmungsgesetzen optimieren, um eine bessere Benutzererfahrung zu erzielen"],"pt":["Aplicar vieses cognitivos para melhorar a tomada de decisões do usuário","Projetar interfaces com gatilhos comportamentais para aumento da participação","Otimizar layouts de UI usando leis de percepção para melhor experiência do usuário"],"ru":["Применять когнитивные предубеждения для улучшения принятия решений пользователем","Проектировать интерфейсы с поведенческими триггерами для повышения вовлеченности","Оптимизировать макеты UI, используя законы восприятия для лучшего пользовательского опыта"],"ar":["تطبيق التحيزات المعرفية لتحسين اتخاذ القرارات للمستخدم","تصميم واجهات مع الملفات البدنية لتزيد المشاركة","تحسين تخطيطات UI باستخدام قوانين الإدراك لتحسين تجربة المستخدم"]},"limitations":{"en":["Requires knowledge of psychology-driven design principles","Limited to UI/UX design applications"],"zh":["需要了解心理学驱动的设计原则","仅限于 UI/UX 设计应用"],"ja":["心理学に基づく設計原則の知識が必要","UI/UX デザインアプリケーションに限定される"],"ko":["심리학적 설계 원칙에 대한 지식이 필요","사용자 경험 설계 응용 프로그램에만 제한됨"],"es":["Requiere conocimiento de principios de diseño impulsados por la psicología","Limitado a aplicaciones de diseño de UI/UX"],"fr":["Nécessite des connaissances en principes de conception basés sur la psychologie","Limité aux applications de conception UI/UX"],"de":["Benötigt Kenntnisse in psychologisch gesteuerten Designprinzipien","Begrenzt auf UI/UX-Design-Anwendungen"],"pt":["Requer conhecimento de princípios de design baseados em psicologia","Limitado a aplicações de design de UI/UX"],"ru":["Требует знаний принципов дизайна, основанных на психологии","Ограничен применением в дизайне UI/UX"],"ar":["يتطلب معرفة بمبادئ تصميم مدفوعة bằng علم النفس","محدود بتطبيقات تصميم UI/UX"]},"version":4},"contentHash":"5cc6b3005f5290dd4ccd7de9ddc41921fedd9baed2bce44040ef1442c5e36539","qualityScore":23}');
DELETE FROM skills_fts WHERE id = 'yuki-programmer/savesmart_app/ui-ux-psychology';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yuki-programmer/savesmart_app/ui-ux-psychology', 'ui-ux-psychology', 'yuki-programmer', 'savesmart_app', 'community', 'ui-ux-psychology yuki-programmer savesmart_app community The ui-ux-psychology skill provides a reference for psychology-driven UI/UX design principles and techniques, benefiting developers and designers who want to create user-centered and engaging interfaces. UI/UX心理学是一门研究如何应用心理学原理来改善用户体验的学科，涉及认知偏见、行为触发和知觉法则等方面 UI/UX心理学は、ユーザーエクスペリエンスを向上させるために心理学的原理を適用する方法を研究する学科です UI/UX 심리학은 사용자 경험을 향상시키기 위해 심리학적 원리를 적용하는 방법을 연구하는 학문입니다 La psicología de UI/UX se aplica en el diseño para mejorar la experiencia del usuario mediante principios como los sesgos cognitivos y los desencadenantes de comportamiento La psychologie UI/UX est appliquée dans la conception pour améliorer l''expérience utilisateur via des principes tels que les biais cognitifs et les déclencheurs de comportement Die UI/UX-Psychologie wird im Design angewendet, um die Benutzererfahrung durch Prinzipien wie kognitive Verzerrungen und Verhaltensauslöser zu verbessern A psicologia UI/UX é uma habilidade que ajuda a melhorar a experiência do usuário em ferramentas de IA, utilizando princípios como viés cognitivo e gatilhos comportamentais Психология UI/UX - это навык, который помогает улучшить пользовательский опыт в ИИ Агентах, используя принципы, такие как когнитивные предубеждения и поведенческие триггеры علم النفس UI/UX هو مهارة تساعد على تحسين تجربة المستخدم في أدوات الذكاء الاصطناعي، باستخدام مبادئ مثل الانحياز المعرفي والاستفزازات السلوكية how to use ui-ux-psychology in design ui-ux-psychology vs human-centered design ui-ux-psychology setup guide for developers what is ui-ux-psychology and its benefits ui-ux-psychology alternative design approaches ui-ux-psychology install and integration tutorial UI/UX心理学 AIエージェント 用户体验设计 认知偏见 行为触发 知觉法则 情感和社会性因素 暗模式 References cognitive biases from cognitive-biases.md for informed design decisions Applies behavioral triggers from behavioral-triggers.md to drive user engagement Utilizes perception laws from perception-laws.md for effective UI layout and design Incorporates emotional and social factors from emotional-social.md to build trust and user loyalty Avoids dark patterns from dark-patterns.md to ensure ethical and user-friendly design ui-ux-psychology is a set of principles and techniques that apply psychological insights to UI/UX design, including cognitive biases, behavioral triggers, and perception laws.');
