INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TheBeardedBearSAS/claude-craft/security-reactnative', 'security-reactnative', 'TheBeardedBearSAS', 'claude-craft', 'community', 'security-reactnative TheBeardedBearSAS claude-craft community The security-reactnative skill provides guidelines and best practices for secure React Native development, benefiting developers and projects across multiple technology stacks. 本技能提供React Native安全最佳实践指南，帮助开发者确保应用安全 このスキルは、React Nativeのセキュリティベストプラクティスを提供し、開発者がアプリのセキュリティを確保できるようにします 이 스킬은 React Native 보안 설정 가이드를 제공하여 개발자가 애플리케이션의 보안을 강화할 수 있습니다 Este skill proporciona pautas y mejores prácticas para la seguridad en React Native. Ofrece reglas estandarizadas para el desarrollo asistido por IA. Ce skill fournit des lignes directrices et des bonnes pratiques pour la sécurité dans React Native. Il offre des règles standardisées pour le développement assisté par l''IA. Dieses Skill bietet Richtlinien und Best Practices für die Sicherheit in React Native. Es bietet standardisierte Regeln für die KI-gestützte Entwicklung. O skill security-reactnative fornece diretrizes e melhores práticas para segurança em React Native. Навык security-reactnative предоставляет руководства и лучшие практики для безопасности в React Native. المهارة security-reactnative توفر إرشادات وأفضل الممارسات للأمان في React Native. how to use security-reactnative security-reactnative setup guide react native security best practices security-reactnative alternative security-reactnative vs owasp install security-reactnative what is security-reactnative security-reactnative documentation react native security guidelines security-reactnative tutorial React Native 安全性 AI 辅助开发 标准化规则 安全最佳实践 React Native 开发 AI 工具 Provides guidelines and best practices for secure React Native development Includes standardized rules for multiple technology stacks Offers detailed documentation in ../../rules/11-security-reactnative.md Supports installation of standardized agents and commands for projects Enables AI-assisted development for secure React Native applications Follows expert knowledge for secure coding practices security-reactnative is a comprehensive framework for AI-assisted development, offering standardized rules and agents for secure React Native projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('coakenfold/p-100226/perf', 'community', 'coakenfold', 'p-100226', 'coakenfold/p-100226', 'perf', 0, 0, 23, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:38.906Z', 'c506bf2de8d4026ba01cc3acdeb89a9eadc76cde8496693e9d8ee9045505ba4f', '{"id":"coakenfold/p-100226/perf","name":"perf","description":{"en":"The perf skill helps web performance specialists optimize page load speed, Core Web Vitals, and asset delivery for multipage applications. It benefits developers seeking to improve user experience.","zh":"perf 是一个专注于页面加载速度、Core Web Vitals 和资产交付的性能优化工具","ja":"perf はページロード速度、Core Web Vitals、資産配信に焦点を当てたパフォーマンス最適化ツールです","ko":"perf 는 페이지 로드 속도, Core Web Vitals, 자산 전달에 중점을 둔 성능 최적화 도구입니다","es":"El agente de IA perf es un especialista en rendimiento web que se centra en la velocidad de carga de página y los vitales web centrales","fr":"L''agent de IA perf est un spécialiste des performances web qui se concentre sur la vitesse de chargement de page et les vitals web centraux","de":"Der perf-KI-Agent ist ein Web-Performance-Spezialist, der sich auf die Seitenladezeit und die Kernwebvitals konzentriert","pt":"O Perf é uma ferramenta de otimização de performance web que melhora a velocidade de carregamento de páginas e os principais vitais da web","ru":"ИИ Агент Perf - это инструмент для оптимизации веб-производительности, который улучшает скорость загрузки страниц и основные веб-метрики","ar":"أداة Perf هي أداة لتحسين أداء الويب التي تحسن سرعة تحميل الصفحات والمعايير الأساسية للويب"},"seo":{"title":{"en":"perf: Core Web Vitals Optimization Guide | AI Agent Skill","zh":"perf 性能优化设置指南","ja":"perf パフォーマンス最適化ベストプラクティス","ko":"perf 성능 최적화 설정 가이드","es":"Guía de configuración de perf para optimización de rendim...","fr":"Configurer perf pour améliorer les performances web","de":"Perf-Setup-Leitfaden für bessere Web-Performance","